$activity_graph_guard$;

-- DEVELOPMENT_PRIVATE_PREFIX:

-- Existing protocol tables must remain private, including column-level grants.
-- Public RPC authority is separately frozen by the complete routine guard.
do $activity_private_authority$
declare relation_name text;role_name text;relation_oid oid;
begin
 foreach relation_name in array ARRAY['work_activity_definitions','work_activity_definition_versions','work_capture_menus','work_capture_menu_versions','work_job_menu_selections','work_job_management_grants','personal_activity_state','personal_activity_commands','personal_activity_transitions','work_session_capture_metadata','work_configuration_commands','work_configuration_draft_revisions','work_configuration_draft_pointers','work_unit_fact_revisions','work_unit_fact_current','work_unit_fact_context_epochs','work_activity_observations','work_activity_streams','work_activity_transaction_context','work_activity_expected_mutations','work_setup_sessions','personal_activity_transition_sources'] loop
  relation_oid:=to_regclass('public.'||relation_name);
  if relation_oid is null or not (select relrowsecurity from pg_class where oid=relation_oid) then
   raise exception using errcode='23514',message='Private activity protocol table authority changed.';end if;
  foreach role_name in array array['anon','authenticated'] loop
   if has_table_privilege(role_name,relation_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')
    or has_any_column_privilege(role_name,relation_oid,'SELECT,INSERT,UPDATE,REFERENCES') then
     raise exception using errcode='23514',message='Private activity protocol table authority changed.';end if;
  end loop;
 end loop;
end;
$activity_private_authority$;


-- Protocol primitives are private; none establishes authority or a timing frame.
-- Advisory serialization cannot refresh a REPEATABLE READ transaction's
-- snapshot. New protocol calls require the supported PostgREST isolation.
create function public._work_activity_read_committed() returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
begin
 if current_setting('transaction_isolation') is distinct from 'read committed' then
   raise exception using errcode='25001',message='Activity protocol requires a fresh read-committed transaction.';
 end if;
end; $$;
revoke all on function public._work_activity_read_committed() from public,anon,authenticated;

create function public._work_activity_object(p_value jsonb,p_keys text[]) returns void
language plpgsql immutable set search_path=public,pg_temp as $$
begin
  if p_value is null or jsonb_typeof(p_value) is distinct from 'object'
    or not(p_value ?& p_keys) or exists(select 1 from jsonb_object_keys(p_value) k where k<>all(p_keys)) then
    raise exception using errcode='23514',message='Invalid activity fields.';
  end if;
end; $$;
revoke all on function public._work_activity_object(jsonb,text[]) from public,anon,authenticated;

create function public._work_activity_uuid(p_value jsonb,p_nullable boolean default false) returns uuid
language plpgsql immutable set search_path=public,pg_temp as $$
begin
  if p_nullable and p_value='null'::jsonb then return null; end if;
  if p_value is null or jsonb_typeof(p_value) is distinct from 'string'
    or (p_value#>>'{}') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception using errcode='23514',message='Invalid activity identity.';
  end if;
  return (p_value#>>'{}')::uuid;
end; $$;
revoke all on function public._work_activity_uuid(jsonb,boolean) from public,anon,authenticated;

create function public._work_activity_integer(p_value jsonb,p_min bigint default 0,p_max bigint default 9007199254740991) returns bigint
language plpgsql immutable set search_path=public,pg_temp as $$
declare n numeric;
begin
  if p_value is null or jsonb_typeof(p_value) is distinct from 'number' then
    raise exception using errcode='23514',message='Invalid activity integer.';
  end if;
  n:=(p_value#>>'{}')::numeric;
  if n<p_min or n>p_max or n<>trunc(n) then raise exception using errcode='23514',message='Invalid activity integer.'; end if;
  return n::bigint;
end; $$;
revoke all on function public._work_activity_integer(jsonb,bigint,bigint) from public,anon,authenticated;

create function public._work_activity_instant(p_value jsonb,p_nullable boolean default false) returns timestamptz
language plpgsql immutable set search_path=public,pg_temp as $$
declare t timestamptz;
begin
  if p_nullable and p_value='null'::jsonb then return null; end if;
  if p_value is null or jsonb_typeof(p_value) is distinct from 'string'
    or (p_value#>>'{}') !~ '^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12][0-9]|3[01])T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.\d{1,6})?(Z|[+-]([01][0-9]|2[0-3]):[0-5][0-9])$' then
    raise exception using errcode='23514',message='Invalid activity timestamp.';
  end if;
  begin t:=(p_value#>>'{}')::timestamptz;
  exception when invalid_datetime_format or datetime_field_overflow then
    raise exception using errcode='23514',message='Invalid activity timestamp.';
  end;
  if not isfinite(t) or t<'0001-01-01T00:00:00Z'::timestamptz or t>='10000-01-01T00:00:00Z'::timestamptz then
    raise exception using errcode='23514',message='Invalid activity timestamp.';
  end if;
  return t;
end; $$;
revoke all on function public._work_activity_instant(jsonb,boolean) from public,anon,authenticated;

create function public._work_activity_iso(p_value timestamptz) returns text
language sql immutable set search_path=public,pg_temp as $$
 select to_char(p_value at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
$$;
revoke all on function public._work_activity_iso(timestamptz) from public,anon,authenticated;

create function public._work_activity_answers(p_schema jsonb,p_values jsonb) returns jsonb
language plpgsql set search_path=public,pg_temp as $$
declare f jsonb; a jsonb; option_value jsonb; field_id text; known text[]:='{}'; seen text[]; n numeric;
 -- Exactly ECMAScript TrimString whitespace, not a locale-dependent SQL regex.
 whitespace text:=chr(9)||chr(10)||chr(11)||chr(12)||chr(13)||chr(32)||chr(160)||chr(5760)
   ||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)
   ||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279);
begin
  perform public._work_config_validate_typed_fields(p_schema);
  if p_values is null or jsonb_typeof(p_values) is distinct from 'object' or octet_length(p_values::text)>20000 then
    raise exception using errcode='23514',message='Invalid activity answers.';
  end if;
  for f in select value from jsonb_array_elements(p_schema) loop
    field_id:=f->>'id'; known:=array_append(known,field_id);
    if not(p_values ? field_id) then
      if (f->>'required')::boolean then raise exception using errcode='23514',message='A required activity answer is missing.'; end if;
      continue;
    end if;
    a:=p_values->field_id;
    case f->>'type'
    when 'text' then
      if jsonb_typeof(a) is distinct from 'string' or length(a#>>'{}')>500
        or ((f->>'required')::boolean and length(btrim(a#>>'{}',whitespace))=0) then
        raise exception using errcode='23514',message='Invalid activity text answer.';
      end if;
    when 'boolean' then
      if jsonb_typeof(a) is distinct from 'boolean' then raise exception using errcode='23514',message='Invalid activity Boolean answer.'; end if;
    when 'number' then
      if jsonb_typeof(a) is distinct from 'number' then raise exception using errcode='23514',message='Invalid activity number answer.'; end if;
      n:=(a#>>'{}')::numeric;
      if abs(n)>1.7976931348623157e308::numeric
        or (f ? 'min' and n<(f->>'min')::numeric) or (f ? 'max' and n>(f->>'max')::numeric)
        or (f->>'unit'='count' and (n<0 or n>9007199254740991 or n<>trunc(n))) then
        raise exception using errcode='23514',message='Activity number is outside its published bounds.';
      end if;
    when 'single_select' then
      if jsonb_typeof(a) is distinct from 'string' or not exists(select 1 from jsonb_array_elements(f->'options') o where o->'id'=a) then
        raise exception using errcode='23514',message='Invalid activity selection.';
      end if;
    when 'multi_select' then
      if jsonb_typeof(a) is distinct from 'array' or jsonb_array_length(a)>50
        or ((f->>'required')::boolean and jsonb_array_length(a)=0) then
        raise exception using errcode='23514',message='Invalid activity selections.';
      end if;
      seen:='{}';
      for option_value in select value from jsonb_array_elements(a) loop
        if jsonb_typeof(option_value) is distinct from 'string' or (option_value#>>'{}')=any(seen)
          or not exists(select 1 from jsonb_array_elements(f->'options') o where o->'id'=option_value) then
          raise exception using errcode='23514',message='Invalid activity selections.';
        end if;
        seen:=array_append(seen,option_value#>>'{}');
      end loop;
    else raise exception using errcode='23514',message='Invalid activity field type.';
    end case;
  end loop;
  if exists(select 1 from jsonb_object_keys(p_values) k where k<>all(known)) then
    raise exception using errcode='23514',message='Unknown activity answer.';
  end if;
  return p_values;
end; $$;
revoke all on function public._work_activity_answers(jsonb,jsonb) from public,anon,authenticated;

-- Exact current+original authority precedes identifiers, epochs and fact values.
-- This private projection is shared by the future public basis read and switch.
create function public._work_activity_unit_basis(p_unit_id uuid,p_actor uuid) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare u public.custom_work_units; f public.work_unit_fact_revisions; eligible boolean; reason text; dimensions jsonb;
begin
  if p_actor is distinct from auth.uid() or not public._work_config_internal(p_actor) then return null; end if;
  select * into u from public.custom_work_units where id=p_unit_id;
  if u.id is null or not public._work_unit_fact_context_visible(p_actor,
      case when u.project_id is null then 'unassigned' else 'job' end,u.project_id,u.opening_id,u.created_by,public.is_test_profile(u.created_by),false) then return null; end if;
  select r.* into f from public.work_unit_fact_revisions r join public.work_unit_fact_current c on c.current_revision_id=r.id where c.unit_id=u.id;
  if f.id is not null and (f.unit_incarnation_epoch is distinct from public._work_unit_fact_peek_epoch('unit_incarnation',u.id)
    or not public._work_unit_fact_context_visible(p_actor,f.origin_kind,f.origin_project_id,f.origin_opening_id,f.origin_author_id,f.origin_is_test,true)) then return null; end if;
  eligible:=u.project_id is not null and f.id is not null and f.raw_observation is not null
    and f.width_in>0 and f.width_in<=100000 and f.height_in>0 and f.height_in<=100000 and f.measurement_source in ('measured','plans','estimated');
  eligible:=coalesce(eligible,false);
  reason:=case when u.project_id is null then 'unassigned' when f.event_kind in ('incomplete','cleared') then 'incomplete_dimensions' when f.id is null or f.raw_observation is null then 'missing_observation'
    when not eligible then 'incomplete_dimensions' else null end;
  dimensions:=case when f.width_in is not null and f.height_in is not null and f.measurement_source is not null then
    jsonb_build_object('widthIn',f.width_in,'heightIn',f.height_in,'source',f.measurement_source,
      'original',case when f.raw_observation is not null then jsonb_build_object('width',f.raw_observation->'width','height',f.raw_observation->'height',
        'unit',f.measurement_unit,'source',f.measurement_source,'sourceReference',f.source_reference) else 'null'::jsonb end)
    else 'null'::jsonb end;
  return jsonb_build_object('id',u.id,'projectId',u.project_id,'openingId',u.opening_id,'operationalRevision',u.revision,
    'incarnationEpoch',public._work_unit_fact_peek_epoch('unit_incarnation',u.id),'bindingEpoch',public._work_unit_fact_peek_epoch('unit_binding',u.id),
    'projectEpoch',case when u.project_id is not null then public._work_unit_fact_peek_epoch('project',u.project_id) end,
    'openingEpoch',case when u.opening_id is not null then public._work_unit_fact_peek_epoch('opening',u.opening_id) end,
    'fact',case when f.id is not null then jsonb_build_object('id',f.id,'revision',f.revision,'eventKind',f.event_kind,
      'originProjectEpoch',case when f.origin_project_id is not null then public._work_unit_fact_peek_epoch('project',f.origin_project_id) end,
      'originOpeningEpoch',case when f.origin_opening_id is not null then public._work_unit_fact_peek_epoch('opening',f.origin_opening_id) end,
      'dimensions',dimensions,'estimated',f.estimated) else 'null'::jsonb end,
    'eligibleForCapture',eligible,'ineligibleReason',reason);
end; $$;
revoke all on function public._work_activity_unit_basis(uuid,uuid) from public,anon,authenticated;

-- All normalized payloads have one immutable spelling before hashing.
create function public._work_activity_payload(p_data jsonb) returns jsonb
language plpgsql set search_path=public,pg_temp as $$
declare v jsonb; i jsonb; u jsonb; k text; seq bigint; pred uuid; sr jsonb; kind text;
begin
  perform public._work_activity_object(p_data,array['deviceId','clientGeneration','clientSequence','predecessorCommandId','expectedRevision','basis','shiftRef','tappedAt','clockCheckedAt','clockSkewMs','intent']);
  if octet_length(p_data::text)>20000 then raise exception using errcode='23514',message='Activity request is too large.'; end if;
  perform public._work_activity_instant(p_data->'tappedAt');
  perform public._work_activity_instant(p_data->'clockCheckedAt',true);
  if jsonb_typeof(p_data->'intent') is distinct from 'object' or jsonb_typeof(p_data#>'{intent,kind}') is distinct from 'string' then
    raise exception using errcode='23514',message='Invalid activity intent.';
  end if;
  kind:=p_data#>>'{intent,kind}';
  if kind='establish_stream' then return public._work_activity_establish_payload(p_data); end if;
  seq:=public._work_activity_integer(p_data->'clientSequence',1);
  pred:=public._work_activity_uuid(p_data->'predecessorCommandId');
  perform public._work_activity_object(p_data->'shiftRef',array['kind','id']);
  if jsonb_typeof(p_data#>'{shiftRef,kind}') is distinct from 'string' or p_data#>>'{shiftRef,kind}' not in ('shift','clock_command') then raise exception using errcode='23514',message='Invalid activity shift reference.'; end if;
  sr:=jsonb_build_object('kind',p_data#>>'{shiftRef,kind}','id',public._work_activity_uuid(p_data#>'{shiftRef,id}'));
  -- Reuse the independently tested exact common envelope normalizer. This
  -- synthetic establishment is local validation only: never saved or executed.
  v:=public._work_activity_establish_payload(p_data||jsonb_build_object('clientSequence',0,'predecessorCommandId',null,
    'shiftRef',jsonb_build_object('kind','shift','id',sr->'id'),
    'intent',jsonb_build_object('kind','establish_stream','previousGeneration',null,'previousHeadCommandId',null)));
  i:=p_data->'intent';
  if kind='stop' then perform public._work_activity_object(i,array['kind']);
  elsif kind='finish_setup' then
    perform public._work_activity_object(i,array['kind','projectId','costCodeId']);
    i:=jsonb_build_object('kind',kind,'projectId',public._work_activity_uuid(i->'projectId'),'costCodeId',public._work_activity_uuid(i->'costCodeId',true));
  elsif kind='switch' then
    perform public._work_activity_object(i,array['kind','projectId','selectionId','selectionRevision','menuVersionId','definitionVersionId','scope','unit','machineKind','values']);
    foreach k in array array['projectId','selectionId','menuVersionId','definitionVersionId'] loop
      i:=jsonb_set(i,array[k],to_jsonb(public._work_activity_uuid(i->k)));
    end loop;
    i:=jsonb_set(i,'{selectionRevision}',to_jsonb(public._work_activity_integer(i->'selectionRevision',1)));
    if i->>'scope' not in ('general','specific') or jsonb_typeof(i->'scope') is distinct from 'string'
      or jsonb_typeof(i->'values') is distinct from 'object'
      or (i->'machineKind'<>'null'::jsonb and (jsonb_typeof(i->'machineKind') is distinct from 'string' or i->>'machineKind' not in ('forklift','tele_handler','scissor_lift','spider_suction')))
      or (i->>'scope'='general' and (i->'unit'<>'null'::jsonb or i->>'machineKind' in ('scissor_lift','spider_suction'))) then
      raise exception using errcode='23514',message='Invalid activity switch.';
    end if;
    if i->>'scope'='specific' then
      u:=i->'unit';
      perform public._work_activity_object(u,array['id','operationalRevision','factId','factRevision','incarnationEpoch','bindingEpoch','projectEpoch','openingEpoch','originProjectEpoch','originOpeningEpoch']);
      u:=jsonb_set(u,'{id}',to_jsonb(public._work_activity_uuid(u->'id')));
      u:=jsonb_set(u,'{factId}',to_jsonb(public._work_activity_uuid(u->'factId')));
      foreach k in array array['operationalRevision','factRevision','incarnationEpoch','bindingEpoch','projectEpoch','openingEpoch','originProjectEpoch','originOpeningEpoch'] loop
        if k in ('openingEpoch','originProjectEpoch','originOpeningEpoch') and u->k='null'::jsonb then continue; end if;
        u:=jsonb_set(u,array[k],to_jsonb(public._work_activity_integer(u->k,case when k='factRevision' then 1 else 0 end)));
      end loop;
      i:=jsonb_set(i,'{unit}',u);
    end if;
  else raise exception using errcode='23514',message='Invalid activity intent.';
  end if;
  v:=v||jsonb_build_object('clientSequence',seq,'predecessorCommandId',pred,'shiftRef',sr,'intent',i);
  if octet_length(v::text)>20000 then raise exception using errcode='23514',message='Activity request is too large.'; end if;
  return v;
end; $$;
revoke all on function public._work_activity_payload(jsonb) from public,anon,authenticated;

-- One post-G arrival, passed explicitly through payroll. This does not change
-- accepted-tap policy or audit timestamps elsewhere. A corrupt future stored
-- boundary is a needs-finish case, not an invented payable finish.
create function public._clock_pick_time_at(p_tapped_at timestamptz,p_clock_checked_at timestamptz,p_clock_skew_ms integer,p_not_before timestamptz,p_arrived_at timestamptz)
returns public.clock_time_pick language plpgsql stable set search_path=public,pg_temp as $$
declare v_corrected timestamptz;
begin
  if p_arrived_at is null or not isfinite(p_arrived_at) then raise exception using errcode='23514',message='Invalid clock arrival.'; end if;
  if p_not_before is not null and (not isfinite(p_not_before) or p_not_before>p_arrived_at) then
    return (null,false,'stored_punch_after_arrival')::public.clock_time_pick;
  end if;
  if p_tapped_at is null then return (p_arrived_at,false,null)::public.clock_time_pick; end if;
  if p_clock_checked_at is null or p_arrived_at-p_clock_checked_at>interval '24 hours' or p_clock_checked_at>p_arrived_at+interval '2 minutes' then
    return (p_arrived_at,false,'clock_unchecked')::public.clock_time_pick;
  end if;
  if p_clock_skew_ms is null or abs(p_clock_skew_ms::bigint)>120000 then return (p_arrived_at,false,'clock_off')::public.clock_time_pick; end if;
  v_corrected:=p_tapped_at-make_interval(secs=>p_clock_skew_ms/1000.0);
  if v_corrected>p_arrived_at then return (p_arrived_at,false,'tap_after_arrival')::public.clock_time_pick; end if;
  if p_arrived_at-v_corrected>make_interval(hours=>public.shift_cap_hours()) then return (p_arrived_at,false,'tap_too_old')::public.clock_time_pick; end if;
  if p_not_before is not null and v_corrected<p_not_before then return (p_arrived_at,false,'tap_out_of_order')::public.clock_time_pick; end if;
  return (v_corrected,true,null)::public.clock_time_pick;
end; $$;
revoke all on function public._clock_pick_time_at(timestamptz,timestamptz,integer,timestamptz,timestamptz) from public,anon,authenticated;

-- Ephemeral operation bookkeeping. These are not employee work history and
-- cannot survive commit. Identities come only from actual backend/transaction
-- metadata and installed entry/statement helpers; no client context token.
create table public.work_activity_operations (
 id uuid primary key default gen_random_uuid(),top_xid xid8 not null,backend_pid integer not null,
 actor_id uuid,route text not null check(route ~ '^[a-z_][a-z0-9_]{0,119}$'),
 arrival_at timestamptz not null check(isfinite(arrival_at)),request_id uuid,command_id uuid,
 clock_entry_claimed boolean not null default false,
 arguments jsonb not null check(jsonb_typeof(arguments)='object' and octet_length(arguments::text)<=4000),
 unique(top_xid,backend_pid)
);
create table public.work_activity_operation_people (
 id uuid primary key default gen_random_uuid(),operation_id uuid not null references public.work_activity_operations(id),
 profile_id uuid not null,transition_id uuid not null default gen_random_uuid(),
 before_state jsonb not null check(jsonb_typeof(before_state)='object' and octet_length(before_state::text)<=20000),
 unique(operation_id,profile_id)
);
create table public.work_activity_operation_events (
 id uuid primary key default gen_random_uuid(),operation_id uuid not null references public.work_activity_operations(id),
 profile_id uuid not null,event_order integer not null,source_kind text not null check(source_kind in ('custom','unit','task','service','phase','setup','shift','helper')),
 source_id uuid not null,operation text not null check(operation in ('INSERT','UPDATE','DELETE')),
 selected_at timestamptz not null check(isfinite(selected_at)),cause text not null,
 before_value jsonb not null check(jsonb_typeof(before_value)='object' and octet_length(before_value::text)<=8192),
 after_value jsonb not null check(jsonb_typeof(after_value)='object' and octet_length(after_value::text)<=8192),
 unique(operation_id,event_order)
);
create index work_activity_operation_events_subject on public.work_activity_operation_events(operation_id,profile_id);
create table public.work_activity_statement_frames (
 id uuid primary key default gen_random_uuid(),operation_id uuid not null references public.work_activity_operations(id),
 top_xid xid8 not null,backend_pid integer not null,depth integer not null check(depth between 1 and 64),
 table_oid oid not null,operation text not null check(operation in ('INSERT','UPDATE','DELETE')),
 owns_operation boolean not null,unique(top_xid,backend_pid,depth)
);
