create function public._work_activity_ephemeral_commit_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare remains boolean;
begin
  if tg_table_name<>all(array['work_activity_operations','work_activity_operation_people','work_activity_operation_events','work_activity_statement_frames']) then
    raise exception using errcode='23514',message='Unsupported activity bookkeeping.';
  end if;
  execute format('select exists(select 1 from public.%I where id=$1)',tg_table_name) into remains using new.id;
  if remains then raise exception using errcode='23514',message='Unfinished activity bookkeeping cannot commit.'; end if;
  return null;
end; $$;
revoke all on function public._work_activity_ephemeral_commit_guard() from public,anon,authenticated;
