create function public._work_activity_operation() returns public.work_activity_operations
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare r public.work_activity_operations;
begin
 select * into r from public.work_activity_operations where top_xid=pg_current_xact_id() and backend_pid=pg_backend_pid() and actor_id is not distinct from auth.uid();
 return r;
end; $$;
revoke all on function public._work_activity_operation() from public,anon,authenticated;

create function public._work_activity_operation_enter(p_route text,p_arguments jsonb default '{}'::jsonb,p_request_id uuid default null,p_command_id uuid default null) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare existing public.work_activity_operations; result uuid;
begin
 perform public._work_activity_gate();
 existing:=public._work_activity_operation();
 if existing.id is not null then return null; end if;
 if auth.uid() is null then
   -- Built-in SET ROLE identity, never a JWT/custom-GUC assertion or the
   -- definer's current_user. Supported PostgREST authenticators are trusted
   -- server sessions. Installed source/caller closure must prove that no
   -- authenticated invoker RPC can SET ROLE before entering this factory.
   if not ((session_user in ('postgres','supabase_admin') and current_setting('role') in ('none','postgres','supabase_admin','service_role'))
     or (session_user='authenticator' and current_setting('role')='service_role')
     or (session_user='service_role' and current_setting('role') in ('none','service_role'))) then
     raise exception using errcode='42501',message='An identified activity actor is required.';
   end if;
 elsif not exists(select 1 from public.profiles where id=auth.uid()) then
   raise exception using errcode='42501',message='An identified activity actor is required.';
 end if;
 insert into public.work_activity_operations(top_xid,backend_pid,actor_id,route,arrival_at,request_id,command_id,arguments)
 values(pg_current_xact_id(),pg_backend_pid(),auth.uid(),p_route,clock_timestamp(),p_request_id,p_command_id,p_arguments) returning id into result;
 return result;
end; $$;
revoke all on function public._work_activity_operation_enter(text,jsonb,uuid,uuid) from public,anon,authenticated;

