 selected_effective_at timestamptz not null check(isfinite(selected_effective_at)), cause text not null,
 before_state jsonb not null check(jsonb_typeof(before_state)='object' and octet_length(before_state::text)<=20000),
 after_state jsonb not null check(jsonb_typeof(after_state)='object' and octet_length(after_state::text)<=20000),
 before_evidence jsonb not null check(jsonb_typeof(before_evidence)='object' and octet_length(before_evidence::text)<=8192),
 after_evidence jsonb not null check(jsonb_typeof(after_evidence)='object' and octet_length(after_evidence::text)<=8192),
 recorded_at timestamptz not null default clock_timestamp(), unique(operation_id,profile_id,source_kind,source_id)
);
