   and ((end_transition_id is not null and end_safety_event_id is null) or (end_transition_id is null and end_safety_event_id is not null))));

create function public._work_activity_bookkeeping_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations;
begin
 if tg_table_name='work_activity_operations' then
   if tg_op='UPDATE' and not (old.route='clock_in_setup' and not old.clock_entry_claimed and new.clock_entry_claimed
     and (to_jsonb(new)-'clock_entry_claimed')=(to_jsonb(old)-'clock_entry_claimed')) then
     raise exception using errcode='23514',message='Activity operation identity is immutable.';
   end if;
   if tg_op='INSERT' then o:=new; else o:=old; end if;
 else
   select * into o from public.work_activity_operations where id=case when tg_op='DELETE' then old.operation_id else new.operation_id end;
   if tg_op='UPDATE' then raise exception using errcode='23514',message='Activity bookkeeping is append-only within its operation.'; end if;
 end if;
 if o.id is null or o.top_xid is distinct from pg_current_xact_id() or o.backend_pid is distinct from pg_backend_pid()
   or o.actor_id is distinct from auth.uid() or not exists(select 1 from pg_locks where locktype='advisory' and pid=pg_backend_pid()
      and classid=7712 and objid=0 and objsubid=2 and mode='ExclusiveLock' and granted) then
   raise exception using errcode='42501',message='Activity bookkeeping is not this actor transaction.';
 end if;
 if tg_op='DELETE' then return old; end if;
 return new;
end; $$;
revoke all on function public._work_activity_bookkeeping_guard() from public,anon,authenticated;
create trigger work_activity_operations_identity before insert or update or delete on public.work_activity_operations for each row execute function public._work_activity_bookkeeping_guard();
create trigger work_activity_people_identity before insert or update or delete on public.work_activity_operation_people for each row execute function public._work_activity_bookkeeping_guard();
create trigger work_activity_events_identity before insert or update or delete on public.work_activity_operation_events for each row execute function public._work_activity_bookkeeping_guard();
create trigger work_activity_statements_identity before insert or update or delete on public.work_activity_statement_frames for each row execute function public._work_activity_bookkeeping_guard();

-- Open shift identity is derived only when unambiguous. No timestamp/UUID wins
-- an old conflict. Old off-task/break rows remain evidence, not personal work.
create function public._work_activity_live_sources(p_profile uuid)
returns table(source_kind text,source_id uuid,shift_id uuid,started_at timestamptz,project_id uuid,opening_id uuid,unit_id uuid)
language sql stable security definer set search_path=public,pg_temp as $$
 with open_shift as(select case when count(*)=1 then min(id::text)::uuid end id from public.time_shifts where profile_id=p_profile and status='open' and clock_out_at is null)
 select 'custom',s.id,s.shift_id,s.started_at,s.project_id,u.opening_id,s.unit_id from public.custom_work_sessions s left join public.custom_work_units u on u.id=s.unit_id where s.profile_id=p_profile and s.ended_at is null
 union all select 'unit',s.id,h.id,s.started_at,o.project_id,s.opening_id,null::uuid from public.unit_sessions s cross join open_shift h left join public.project_openings o on o.id=s.opening_id where s.profile_id=p_profile and s.ended_at is null
 union all select 'task',s.id,h.id,s.started_at,s.project_id,s.opening_id,null::uuid from public.task_sessions s cross join open_shift h where s.profile_id=p_profile and s.ended_at is null and s.state='on_task'
 union all select 'service',s.id,s.shift_id,s.started_at,s.project_id,u.opening_id,u.work_unit_id from public.service_time_sessions s left join public.service_visit_units u on u.id=s.unit_id where s.profile_id=p_profile and s.ended_at is null
 union all select 'phase',s.id,h.id,s.started_at,o.project_id,s.opening_id,null::uuid from public.opening_phases s cross join open_shift h left join public.project_openings o on o.id=s.opening_id where s.started_by=p_profile and s.status='active' and s.paused_at is null
  and (exists(select 1 from public.personal_activity_state ps where ps.profile_id=p_profile and ps.active_source_kind='phase' and ps.active_source_id=s.id)
    or exists(select 1 from public.work_activity_operation_events e join public.work_activity_operations op on op.id=e.operation_id
      where op.top_xid=pg_current_xact_id() and op.backend_pid=pg_backend_pid() and op.actor_id=p_profile
       and e.profile_id=p_profile and e.source_kind='phase' and e.source_id=s.id
       and e.after_value->>'status'='active' and e.after_value->'paused_at'='null'::jsonb
       and (e.operation='INSERT' or e.before_value->'paused_at'<>'null'::jsonb)
       and exists(select 1 from public.time_shifts sh where sh.id=h.id and sh.break_started_at is null)))
 union all select 'setup',s.id,s.shift_id,s.started_at,null::uuid,null::uuid,null::uuid from public.work_setup_sessions s where s.profile_id=p_profile and s.ended_at is null
$$;
revoke all on function public._work_activity_live_sources(uuid) from public,anon,authenticated;

create function public._work_activity_refresh_state(p_profile uuid) returns public.personal_activity_state
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare s public.personal_activity_state; h public.time_shifts; source_row record; shift_count bigint; source_count bigint; clean boolean; effective_start timestamptz; phase_event timestamptz;
begin
 perform public._work_activity_gate();
 insert into public.personal_activity_state(profile_id) values(p_profile) on conflict(profile_id) do nothing;
 select * into s from public.personal_activity_state where profile_id=p_profile for update;
 select count(*) into shift_count from public.time_shifts where profile_id=p_profile and status='open' and clock_out_at is null;
 if shift_count=1 then select * into h from public.time_shifts where profile_id=p_profile and status='open' and clock_out_at is null; end if;
 select count(*) into source_count from public._work_activity_live_sources(p_profile);
 select * into source_row from public._work_activity_live_sources(p_profile) limit 1;
 effective_start:=source_row.started_at;
 if source_count=1 and source_row.source_kind='phase' then
   -- A phase keeps its original lifetime row. The current work interval begins
   -- at an actual unpause event, never at yesterday's original started_at.
   select e.selected_at into phase_event from public.work_activity_operation_events e
    join public.work_activity_operations o on o.id=e.operation_id
    where o.top_xid=pg_current_xact_id() and o.backend_pid=pg_backend_pid()
      and e.profile_id=p_profile and e.source_kind='phase' and e.source_id=source_row.source_id
      and e.after_value->>'status'='active' and e.after_value->'paused_at'='null'::jsonb
      and (e.operation='INSERT' or e.before_value->'paused_at'<>'null'::jsonb)
    order by e.event_order desc limit 1;
   effective_start:=coalesce(phase_event,case when s.active_source_kind='phase' and s.active_source_id=source_row.source_id then s.effective_since end,source_row.started_at);
 end if;
 clean:=shift_count<=1 and source_count<=1;
 if source_count=1 then clean:=clean and h.id is not null and h.break_started_at is null and source_row.shift_id=h.id
   and effective_start>=h.clock_in_at; end if;
 update public.personal_activity_state set shift_id=h.id,
   active_source_kind=case when clean and source_count=1 then source_row.source_kind end,
   active_source_id=case when clean and source_count=1 then source_row.source_id end,
   effective_since=case when clean and source_count=1 then effective_start end,
   active_definition_version_id=case when clean and source_count=1 and source_row.source_kind='custom' then (select definition_version_id from public.work_session_capture_metadata where session_id=source_row.source_id) end,
   integrity_state=case when clean then 'clean' when shift_count>1 or source_count>1 then 'legacy_conflict' else 'review' end,
   choice_required=case when h.id is not null and h.break_started_at is null then not(clean and source_count=1) else false end,
   resume_token=case when h.id is not null and h.break_started_at is not null then resume_token end,
   resume_source_kind=case when h.id is not null and h.break_started_at is not null then resume_source_kind end,
   resume_source_id=case when h.id is not null and h.break_started_at is not null then resume_source_id end,
   resume_definition_version_id=case when h.id is not null and h.break_started_at is not null then resume_definition_version_id end,
   resume_shift_id=case when h.id is not null and h.break_started_at is not null then resume_shift_id end,
   resume_from_revision=case when h.id is not null and h.break_started_at is not null then resume_from_revision end,
   resume_after_break_transition_id=case when h.id is not null and h.break_started_at is not null then resume_after_break_transition_id end,
   resume_authority_revision=case when h.id is not null and h.break_started_at is not null then resume_authority_revision end,
   updated_at=clock_timestamp()
 where profile_id=p_profile returning * into s;
 return s;
end; $$;
revoke all on function public._work_activity_refresh_state(uuid) from public,anon,authenticated;

create function public._work_activity_touch(p_profile uuid) returns public.work_activity_operation_people
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; s public.personal_activity_state; result public.work_activity_operation_people;
begin
 o:=public._work_activity_operation();
 if o.id is null or p_profile is null then raise exception using errcode='23514',message='Activity change lacks its operation.'; end if;
 select * into result from public.work_activity_operation_people where operation_id=o.id and profile_id=p_profile;
 if result.id is not null then return result; end if;
 select * into s from public.personal_activity_state where profile_id=p_profile for update;
 if s.profile_id is null then s:=public._work_activity_refresh_state(p_profile); end if;
 insert into public.work_activity_operation_people(operation_id,profile_id,before_state) values(o.id,p_profile,to_jsonb(s)) returning * into result;
 return result;
end; $$;
revoke all on function public._work_activity_touch(uuid) from public,anon,authenticated;

create function public._work_activity_event(p_profile uuid,p_kind text,p_id uuid,p_operation text,p_selected_at timestamptz,p_cause text,p_before jsonb,p_after jsonb) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; person public.work_activity_operation_people; result uuid;
begin
 o:=public._work_activity_operation();person:=public._work_activity_touch(p_profile);
 insert into public.work_activity_operation_events(operation_id,profile_id,event_order,source_kind,source_id,operation,selected_at,cause,before_value,after_value)
 values(o.id,p_profile,(select coalesce(max(event_order),0)+1 from public.work_activity_operation_events where operation_id=o.id),p_kind,p_id,p_operation,p_selected_at,p_cause,coalesce(p_before,'{}'::jsonb),coalesce(p_after,'{}'::jsonb)) returning id into result;
 return result;
end; $$;
revoke all on function public._work_activity_event(uuid,text,uuid,text,timestamptz,text,jsonb,jsonb) from public,anon,authenticated;

alter table public.personal_activity_transition_sources drop constraint personal_activity_transition_sources_source_kind_check;
alter table public.personal_activity_transition_sources add constraint personal_activity_transition_sources_source_kind_check check(source_kind in ('custom','unit','task','service','phase','setup','shift','helper'));
alter table public.personal_activity_transition_sources drop constraint personal_activity_transition_sources_cause_check;
alter table public.personal_activity_transition_sources add constraint personal_activity_transition_sources_cause_check check(cause in ('switch','stop','pause','break_start','break_end','clock_out','clock_in','correction','void','restore','import','legacy_transition'));
alter table public.personal_activity_transition_sources drop constraint personal_activity_transition_sources_relation_check;
alter table public.personal_activity_transition_sources add constraint personal_activity_transition_sources_relation_check check(relation in ('effective','companion','conflict','phase_participation','payroll','attribution'));

create function public._work_activity_authority_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' then raise exception using errcode='23514',message='Activity authority generation is retained.'; end if;
 if tg_op='UPDATE' and (new.singleton is distinct from old.singleton or new.revision<old.revision
   or (new.capture_enabled is distinct from old.capture_enabled and new.revision<=old.revision
     and not(old.revision=9007199254740991 and old.capture_enabled and not new.capture_enabled))) then
   raise exception using errcode='23514',message='Activity authority cannot move backward.';
 end if;
 if tg_op='UPDATE' and not exists(select 1 from pg_locks where locktype='advisory' and pid=pg_backend_pid() and classid=7712 and objid=0 and objsubid=2 and mode='ExclusiveLock' and granted) then
   raise exception using errcode='23514',message='Activity authority change requires the first gate.';
 end if;
 new.updated_at:=clock_timestamp();return new;
end; $$;
revoke all on function public._work_activity_authority_guard() from public,anon,authenticated;
create trigger work_activity_authority_guard before insert or update or delete on public.work_activity_authority_generation for each row execute function public._work_activity_authority_guard();

create function public._work_activity_operation_exit(p_operation uuid) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; person public.work_activity_operation_people; s public.personal_activity_state;
 before_s public.personal_activity_state; last_event public.work_activity_operation_events; event_row record;
 selected_time timestamptz; selected_cause text; shift_source uuid; relation_kind text; before_count bigint;
begin
 if p_operation is null then return; end if;
 o:=public._work_activity_operation();
 if o.id is distinct from p_operation then raise exception using errcode='42501',message='Activity operation is unavailable.'; end if;
 if exists(select 1 from public.work_activity_statement_frames where operation_id=o.id)
   or exists(select 1 from public.work_activity_transaction_context where top_xid=o.top_xid and backend_pid=o.backend_pid) then
   raise exception using errcode='23514',message='Activity statements and mutations must finish before their operation.';
 end if;
 for person in select * from public.work_activity_operation_people where operation_id=o.id order by profile_id loop
   before_s:=jsonb_populate_record(null::public.personal_activity_state,person.before_state);
   s:=public._work_activity_refresh_state(person.profile_id);
   select * into last_event from public.work_activity_operation_events where operation_id=o.id and profile_id=person.profile_id order by event_order desc limit 1;
   if last_event.id is null and (to_jsonb(s)-'updated_at')=(person.before_state-'updated_at') then continue; end if;
   selected_time:=coalesce(last_event.selected_at,o.arrival_at);
   selected_cause:=coalesce(last_event.cause,'legacy_transition');
   -- A payroll transition owns the root boundary even when its callback
   -- emits subsequent per-source rows at the same selected time.
   select source_id,selected_at,cause into shift_source,selected_time,selected_cause from public.work_activity_operation_events
     where operation_id=o.id and profile_id=person.profile_id and source_kind='shift' order by event_order desc limit 1;
   if not found then selected_time:=coalesce(last_event.selected_at,o.arrival_at);selected_cause:=coalesce(last_event.cause,'legacy_transition');shift_source:=coalesce(s.shift_id,before_s.shift_id); end if;
   if o.command_id is not null then selected_cause:=case o.arguments->>'kind' when 'switch' then 'switch' else 'stop' end; end if;
   if before_s.revision>=9007199254740991 or exists(select 1 from public.work_activity_safety_events where profile_id=person.profile_id) then
     perform public._work_activity_safety_exit(o.id,person.profile_id,case when before_s.revision>=9007199254740991 then 'revision_exhausted' else 'prior_safety_event' end);
     continue;
   end if;
   insert into public.personal_activity_transitions(id,profile_id,revision_before,revision_after,command_id,legacy_source_route,source_request_id,actor_id,cause,
     received_at,selected_effective_at,time_selection_reason,source_shift_id,before_evidence,after_evidence,protocol_version)
   values(person.transition_id,person.profile_id,before_s.revision,before_s.revision+1,o.command_id,case when o.command_id is null then o.route end,o.request_id,o.actor_id,
     selected_cause,o.arrival_at,selected_time,case when o.command_id is null then 'legacy_selected_boundary' else 'validated_activity_boundary' end,shift_source,
     jsonb_build_object('state',person.before_state),jsonb_build_object('state',(to_jsonb(s)-'updated_at')||jsonb_build_object('revision',before_s.revision+1,'last_transition_id',person.transition_id)),1);
   -- Multiple writes to one source in one logical operation are one typed
   -- immutable child: exact first-before and last-after, never copied notes.
   for event_row in
     select source_kind,source_id,(array_agg(before_value order by event_order))[1] first_before,
       (array_agg(after_value order by event_order desc))[1] last_after,
       (array_agg(selected_at order by event_order desc))[1] boundary,
       (array_agg(cause order by event_order desc))[1] event_cause
     from public.work_activity_operation_events where operation_id=o.id and profile_id=person.profile_id group by source_kind,source_id
   loop
     relation_kind:=case event_row.source_kind when 'shift' then 'payroll' when 'helper' then 'attribution'
       when 'phase' then case when (before_s.active_source_kind='phase' and before_s.active_source_id=event_row.source_id)
         or (s.active_source_kind='phase' and s.active_source_id=event_row.source_id) then 'phase_participation' else 'attribution' end else 'effective' end;
     insert into public.personal_activity_transition_sources(transition_id,profile_id,source_kind,source_id,relation,source_shift_id,
       selected_effective_at,cause,before_revision,after_revision,before_evidence,after_evidence)
     values(person.transition_id,person.profile_id,event_row.source_kind,event_row.source_id,relation_kind,
       case when event_row.source_kind='shift' then event_row.source_id else coalesce((event_row.last_after->>'shift_id')::uuid,(event_row.first_before->>'shift_id')::uuid,shift_source) end,
       event_row.boundary,event_row.event_cause,(event_row.first_before->>'revision')::bigint,(event_row.last_after->>'revision')::bigint,event_row.first_before,event_row.last_after);
   end loop;
   update public.personal_activity_state set revision=before_s.revision+1,last_transition_id=person.transition_id,
     resume_after_break_transition_id=case when resume_token is not null and selected_cause='break_start' then person.transition_id else resume_after_break_transition_id end,
     updated_at=clock_timestamp() where profile_id=person.profile_id;
   -- A source's narrow integer counter may be exhausted while the personal
   -- counter remains usable. Keep the normal lifecycle transition AND exact
   -- exceptional evidence; do not wrap a source revision or block payroll.
   if exists(select 1 from public.work_activity_operation_events e where e.operation_id=o.id and e.profile_id=person.profile_id
      and ((e.source_kind='custom' and (e.before_value->>'revision')::bigint>=2147483647 and e.before_value is distinct from e.after_value)
        or e.after_value->'exhaustedVisitCounter' is not null)) then
     perform public._work_activity_safety_exit(o.id,person.profile_id,'source_revision_exhausted');
   end if;
 end loop;
 delete from public.work_activity_operation_events where operation_id=o.id;
 delete from public.work_activity_operation_people where operation_id=o.id;
 delete from public.work_activity_operations where id=o.id;
end; $$;
revoke all on function public._work_activity_operation_exit(uuid) from public,anon,authenticated;

create function public._work_activity_evidence(p_table text,p_row jsonb) returns jsonb
language plpgsql immutable set search_path=public,pg_temp as $$
declare columns text[];
begin
 if p_row is null then return '{}'::jsonb; end if;
 columns:=case p_table
 when 'time_shifts' then array['id','profile_id','project_id','cost_code_id','clock_in_at','clock_out_at','break_started_at','break_type','break_seconds','last_punch_at','status','client_id']
 when 'custom_work_sessions' then array['id','profile_id','shift_id','project_id','unit_id','kind','participation','stage','started_at','ended_at','end_reason','revision','review_required','shift_status']
 when 'unit_sessions' then array['id','profile_id','opening_id','role','is_rework','started_at','ended_at','end_reason','block_issue_id']
 when 'task_sessions' then array['id','profile_id','project_id','opening_id','state','started_at','ended_at']
 when 'service_time_sessions' then array['id','profile_id','shift_id','project_id','visit_id','unit_id','kind','stage','started_at','ended_at','end_reason','review_required']
 when 'opening_phases' then array['id','started_by','opening_id','kind','status','started_at','paused_at','paused_seconds','submitted_at']
 when 'work_setup_sessions' then array['id','profile_id','shift_id','clock_client_id','resumed_from_id','start_transition_id','started_at','ended_at','selected_end_at','end_reason','end_transition_id','end_safety_event_id']
 when 'summon_helpers' then array['id','profile_id','summon_id','joined_at','completed_at','canceled_at','minutes']
 else null end;
 if columns is null then raise exception using errcode='23514',message='Unsupported activity source.'; end if;
 return coalesce((select jsonb_object_agg(key,value) from jsonb_each(p_row) where key=any(columns)),'{}'::jsonb);
end; $$;
revoke all on function public._work_activity_evidence(text,jsonb) from public,anon,authenticated;

-- The later privileged multi-person factories are bounded by a live operation
-- and actual affected-person record. No new public helper grant is introduced.
alter table public.work_activity_transaction_context drop constraint work_activity_transaction_context_check1;
alter table public.work_activity_transaction_context drop constraint work_activity_transaction_context_route_check;
alter table public.work_activity_transaction_context add constraint work_activity_transaction_context_route_check check(route ~ '^[a-z_][a-z0-9_]{0,119}$');
alter table public.work_activity_transaction_context alter column actor_id drop not null;
create or replace function public._work_activity_context_assert(p_frame_id uuid) returns public.work_activity_transaction_context
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare v public.work_activity_transaction_context;
begin
 select * into v from public.work_activity_transaction_context where id=p_frame_id and top_xid=pg_current_xact_id() and backend_pid=pg_backend_pid() and actor_id is not distinct from auth.uid();
 if v.id is null then raise exception using errcode='42501',message='Activity frame is unavailable.'; end if;
 if exists(select 1 from public.work_activity_transaction_context where parent_id=v.id) then raise exception using errcode='23514',message='Finish the nested activity frame first.'; end if;
 return v;
end; $$;
revoke all on function public._work_activity_context_assert(uuid) from public,anon,authenticated;
create function public._work_activity_context_for(p_profile uuid,p_cause text,p_selected_at timestamptz) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; parent uuid; result uuid;
begin
 o:=public._work_activity_operation();
 if o.id is null or not exists(select 1 from public.work_activity_operation_people where operation_id=o.id and profile_id=p_profile) then
   raise exception using errcode='42501',message='Activity subject is not part of this operation.';
 end if;
 select c.id into parent from public.work_activity_transaction_context c where c.top_xid=o.top_xid and c.backend_pid=o.backend_pid
   and not exists(select 1 from public.work_activity_transaction_context child where child.parent_id=c.id);
 if (select count(*) from public.work_activity_transaction_context where top_xid=o.top_xid and backend_pid=o.backend_pid)>=16 then
   raise exception using errcode='54000',message='Activity context nesting is too deep.';
 end if;
 if parent is not null then perform public._work_activity_context_assert(parent); end if;
 insert into public.work_activity_transaction_context(top_xid,backend_pid,parent_id,actor_id,subject_profile_id,route,cause,selected_effective_at)
 values(o.top_xid,o.backend_pid,parent,o.actor_id,p_profile,o.route,p_cause,p_selected_at) returning id into result;
 return result;
end; $$;
revoke all on function public._work_activity_context_for(uuid,text,timestamptz) from public,anon,authenticated;

-- Service review revisions are legacy integer counters. Exhaustion must not
-- roll back a paid break/out. The exact visit mutation is retained beside each
-- affected source, and new capture refuses instead of using this exception.
create function public._work_activity_review_visit(p_visit uuid,p_at timestamptz,p_cause text) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare prior public.service_visits; after_visit public.service_visits; r public.service_time_sessions;
 o public.work_activity_operations; before_e jsonb; after_e jsonb;
begin
 o:=public._work_activity_operation();
 if o.id is null then raise exception using errcode='42501',message='Service review requires its activity operation.';end if;
 select * into prior from public.service_visits where id=p_visit for update;
 if prior.id is null then return;end if;
 if prior.revision>=2147483647 and o.command_id is not null then
   raise exception using errcode='P0001',message='Activity source revision requires reconciliation.';
 end if;
 update public.service_visits set revision=least(prior.revision::bigint+1,2147483647),reviewed_at=null,reviewed_by=null,updated_at=clock_timestamp()
  where id=p_visit returning * into after_visit;
 if prior.revision>=2147483647 then
   for r in select * from public.service_time_sessions where visit_id=p_visit order by profile_id,id loop
     perform public._work_activity_touch(r.profile_id);
     before_e:=public._work_activity_evidence('service_time_sessions',to_jsonb(r));
     after_e:=before_e||jsonb_build_object('exhaustedVisitCounter',jsonb_build_object('id',prior.id,
       'before',jsonb_build_object('revision',prior.revision,'reviewed_at',prior.reviewed_at,'reviewed_by',prior.reviewed_by),
       'after',jsonb_build_object('revision',after_visit.revision,'reviewed_at',after_visit.reviewed_at,'reviewed_by',after_visit.reviewed_by)));
     perform public._work_activity_event(r.profile_id,'service',r.id,'UPDATE',p_at,p_cause,before_e,after_e);
   end loop;
 end if;
end; $$;
revoke all on function public._work_activity_review_visit(uuid,timestamptz,text) from public,anon,authenticated;

create function public._work_activity_close_source(p_profile uuid,p_kind text,p_id uuid,p_at timestamptz,p_cause text) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare table_name text; old_row jsonb; new_row jsonb; changes jsonb; columns text[]; frame uuid; allowance uuid;
 person public.work_activity_operation_people; reason text; safety boolean;
begin
 person:=public._work_activity_touch(p_profile);
 safety:=(person.before_state->>'revision')::bigint>=9007199254740991 or exists(select 1 from public.work_activity_safety_events where profile_id=p_profile);
 table_name:=case p_kind when 'custom' then 'custom_work_sessions' when 'unit' then 'unit_sessions' when 'task' then 'task_sessions'
   when 'service' then 'service_time_sessions' when 'phase' then 'opening_phases' when 'setup' then 'work_setup_sessions' end;
 if table_name is null then raise exception using errcode='23514',message='Unsupported activity close.'; end if;
 execute format('select to_jsonb(s) from public.%I s where id=$1 for update',table_name) into old_row using p_id;
 if old_row is null then return; end if;
 if (case when p_kind='phase' then old_row->>'started_by' else old_row->>'profile_id' end) is distinct from p_profile::text then
   raise exception using errcode='23514',message='Activity close changed its subject.';
 end if;
 if (p_kind='phase' and (old_row->>'status'<>'active' or old_row->'paused_at'<>'null'::jsonb))
   or (p_kind<>'phase' and old_row->'ended_at'<>'null'::jsonb) then return; end if;
 if p_kind='phase' then
   changes:=jsonb_build_object('paused_at',greatest((old_row->>'started_at')::timestamptz,p_at));
 elsif p_kind='setup' then
   reason:=case p_cause when 'break_start' then 'break' when 'clock_out' then 'clock_out' when 'switch' then 'switch' when 'stop' then 'setup_complete' when 'void' then 'void' when 'correction' then 'correction' else 'legacy_transition' end;
   changes:=jsonb_build_object('ended_at',greatest((old_row->>'started_at')::timestamptz,p_at),'selected_end_at',p_at,'end_reason',reason,'end_transition_id',case when not safety then person.transition_id end,'end_safety_event_id',case when safety then gen_random_uuid() end);
 else
   reason:=case p_cause when 'break_start' then 'break' when 'clock_out' then 'clock_out' when 'switch' then 'handoff' when 'stop' then 'complete' else 'auto_closed' end;
   changes:=jsonb_build_object('ended_at',greatest((old_row->>'started_at')::timestamptz,p_at));
   if p_kind<>'task' then changes:=changes||jsonb_build_object('end_reason',case when p_kind='custom' and p_cause='switch' then 'switch' when p_kind='custom' and p_cause='stop' then 'stop' else reason end); end if;
   if p_kind='custom' then
     if (old_row->>'revision')::bigint>=2147483647 and (public._work_activity_operation()).command_id is not null then
       raise exception using errcode='P0001',message='Activity source revision requires reconciliation.';
     end if;
     changes:=changes||jsonb_build_object('revision',least((old_row->>'revision')::bigint+1,2147483647),
       'review_required',coalesce((old_row->>'review_required')::boolean,false) or (old_row->>'started_at')::timestamptz>p_at or (old_row->>'revision')::bigint>=2147483647);
   end if;
   if p_kind='service' then changes:=changes||jsonb_build_object('review_required',coalesce((old_row->>'review_required')::boolean,false) or (old_row->>'started_at')::timestamptz>p_at); end if;
 end if;
 new_row:=old_row||changes;select array_agg(k order by k) into columns from jsonb_object_keys(changes) k;
 frame:=public._work_activity_context_for(p_profile,p_cause,p_at);
 -- Legacy notes can be arbitrarily larger than the allowance budget. Bind
 -- identities and every changed column; consume still compares ALL actual
 -- row columns and refuses any change outside this exact mask.
 allowance:=public._work_activity_expect(frame,('public.'||table_name)::regclass,'UPDATE',p_id,columns,
   (select jsonb_object_agg(key,value) from jsonb_each(old_row) where key=any(columns||array['id',case when p_kind='phase' then 'started_by' else 'profile_id' end])),
   (select jsonb_object_agg(key,value) from jsonb_each(new_row) where key=any(columns||array['id',case when p_kind='phase' then 'started_by' else 'profile_id' end])));
 execute format('update public.%I target set %s from jsonb_populate_record(null::public.%I,$1) proposed where target.id=$2',table_name,
   (select string_agg(format('%I=proposed.%I',c,c),',') from unnest(columns) c),table_name) using new_row,p_id;
 perform public._work_activity_context_close(frame);
 if p_kind='service' and p_cause in ('switch','stop','legacy_transition') then
   perform public._work_activity_review_visit((old_row->>'visit_id')::uuid,p_at,p_cause);
 end if;
end; $$;
revoke all on function public._work_activity_close_source(uuid,text,uuid,timestamptz,text) from public,anon,authenticated;

create function public._work_activity_close_all(p_profile uuid,p_at timestamptz,p_cause text,p_except_kind text default null,p_except_id uuid default null) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare r record;
begin
 perform public._work_activity_touch(p_profile);
 for r in select source_kind,source_id from public._work_activity_live_sources(p_profile)
   union select 'phase',id from public.opening_phases where started_by=p_profile and status='active' and paused_at is null
   order by source_kind,source_id loop
   if r.source_kind is not distinct from p_except_kind and r.source_id is not distinct from p_except_id then continue; end if;
   perform public._work_activity_close_source(p_profile,r.source_kind,r.source_id,p_at,p_cause);
 end loop;
end; $$;
revoke all on function public._work_activity_close_all(uuid,timestamptz,text,text,uuid) from public,anon,authenticated;

-- Statement ownership is proved by private transaction rows, not trigger depth
-- or a caller-set setting. A root RPC can own several nested statements; a
-- legacy invoker/REST statement owns only its own operation.
create function public._work_activity_statement_begin() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare owned uuid; o public.work_activity_operations; depth integer; partner boolean;
begin
 perform public._work_activity_gate();
 owned:=public._work_activity_operation_enter('direct_'||tg_table_name);
 -- The outer REST/invoker DML snapshot can predate its wait at G. Read the
 -- exact existing direct-write RLS predicate in a fresh inner SQL command.
 -- An already-authorized definer root keeps its own source authorization;
 -- this does not invent a new job/role policy for those legacy operations.
 if owned is not null and tg_table_name in ('time_shifts','task_sessions')
   and (current_setting('role') in ('authenticated','anon')
     or (current_setting('role')='none' and session_user in ('authenticated','anon'))) then
   select public.is_partner_user() into partner;
   if partner is distinct from false then
     raise exception using errcode='42501',message='A crew login is required for this timing change.';
   end if;
 end if;
 o:=public._work_activity_operation();
 select coalesce(max(s.depth),0)+1 into depth from public.work_activity_statement_frames s where s.top_xid=o.top_xid and s.backend_pid=o.backend_pid;
 if depth>64 then raise exception using errcode='54000',message='Activity statement nesting is too deep.'; end if;
 insert into public.work_activity_statement_frames(operation_id,top_xid,backend_pid,depth,table_oid,operation,owns_operation)
 values(o.id,o.top_xid,o.backend_pid,depth,tg_relid,tg_op,owned is not null or exists(
   select 1 from public.work_activity_statement_frames where operation_id=o.id and owns_operation));
 return null;
end; $$;
revoke all on function public._work_activity_statement_begin() from public,anon,authenticated;

create function public._work_activity_statement_end() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; s public.work_activity_statement_frames;
begin
 o:=public._work_activity_operation();
 -- FK cascades can complete AFTER STATEMENT callbacks in a different table
 -- order from their BEFORE callbacks. Match the actual statement relation and
 -- operation, and retain direct-root ownership on every descendant frame.
 select * into s from public.work_activity_statement_frames where operation_id=o.id and table_oid=tg_relid and operation=tg_op order by depth desc limit 1;
 if s.id is null or s.table_oid<>tg_relid or s.operation<>tg_op then
   raise exception using errcode='23514',message='Activity statement ownership does not match.';
 end if;
 delete from public.work_activity_statement_frames where id=s.id;
 if s.owns_operation and not exists(select 1 from public.work_activity_statement_frames where operation_id=o.id) then
   perform public._work_activity_operation_exit(o.id);
 end if;
 return null;
end; $$;
revoke all on function public._work_activity_statement_end() from public,anon,authenticated;

-- TRUNCATE has no row images and bypasses RLS. Refuse it throughout the
-- runtime graph; reviewed offline maintenance must use its explicit procedure.
create function public._work_activity_no_truncate() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
begin raise exception using errcode='23514',message='Activity source history cannot be truncated.';end; $$;
revoke all on function public._work_activity_no_truncate() from public,anon,authenticated;

create function public._work_activity_parent_gate() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
begin perform public._work_activity_gate();return null;end; $$;
revoke all on function public._work_activity_parent_gate() from public,anon,authenticated;

create function public._work_activity_row_allowance(p_table oid,p_operation text,p_before jsonb,p_after jsonb) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare allowance uuid; v_source_id uuid;
begin
 v_source_id:=coalesce((p_after->>'id')::uuid,(p_before->>'id')::uuid);
 select m.id into allowance from public.work_activity_expected_mutations m
 join public.work_activity_transaction_context c on c.id=m.frame_id
 where c.top_xid=pg_current_xact_id() and c.backend_pid=pg_backend_pid() and c.actor_id is not distinct from auth.uid()
   and m.table_oid=p_table and m.operation=p_operation and m.source_id=v_source_id and not m.consumed;
 if allowance is not null then perform public._work_activity_consume(allowance,p_table::regclass,p_operation,p_before,p_after);end if;
 return allowance;
end; $$;
revoke all on function public._work_activity_row_allowance(oid,text,jsonb,jsonb) from public,anon,authenticated;

create function public._work_activity_row_before() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare oldj jsonb; newj jsonb; who uuid; oldwho uuid; kind text; o public.work_activity_operations;
 allowance uuid; new_live boolean; old_live boolean; boundary timestamptz;
begin
 o:=public._work_activity_operation();
 if o.id is null then raise exception using errcode='23514',message='Activity source write lacks its statement.';end if;
 oldj:=case when tg_op<>'INSERT' then to_jsonb(old) end;
 newj:=case when tg_op<>'DELETE' then to_jsonb(new) end;
 who:=(coalesce(newj,oldj)->>case when tg_table_name='opening_phases' then 'started_by' else 'profile_id' end)::uuid;
 oldwho:=(oldj->>case when tg_table_name='opening_phases' then 'started_by' else 'profile_id' end)::uuid;
 if oldwho is not null then perform public._work_activity_touch(oldwho);end if;
 if who is not null then perform public._work_activity_touch(who);end if;
 -- Setup has its stronger exact-once private guard. Do not consume its
 -- allowance twice; its row guard remains installed and authoritative.
 if tg_table_name<>'work_setup_sessions' then allowance:=public._work_activity_row_allowance(tg_relid,tg_op,oldj,newj);end if;
 if allowance is not null or tg_op='DELETE' or tg_table_name in ('time_shifts','summon_helpers','work_setup_sessions') then
   if tg_op='DELETE' then return old;else return new;end if;
 end if;
 kind:=case tg_table_name when 'custom_work_sessions' then 'custom' when 'unit_sessions' then 'unit' when 'task_sessions' then 'task' when 'service_time_sessions' then 'service' when 'opening_phases' then 'phase' end;
 new_live:=case when kind='phase' then newj->>'status'='active' and newj->'paused_at'='null'::jsonb
   when kind='task' then newj->>'state'='on_task' and newj->'ended_at'='null'::jsonb else newj->'ended_at'='null'::jsonb end;
 old_live:=coalesce(case when kind='phase' then oldj->>'status'='active' and oldj->'paused_at'='null'::jsonb
   when kind='task' then oldj->>'state'='on_task' and oldj->'ended_at'='null'::jsonb else oldj->'ended_at'='null'::jsonb end,false);
 -- Shared progress may be resumed by another authorized worker, or by a
 -- starter off the clock. It is then untimed progress, never a transfer of
 -- that starter's personal claim or a closure of their unrelated activity.
 if kind='phase' and (who is distinct from o.actor_id or (select count(*) from public.time_shifts where profile_id=who and status='open' and clock_out_at is null and break_started_at is null)<>1) then return new;end if;
 if who is not null and new_live and (not old_live or oldwho is distinct from who) then
   boundary:=case when kind='phase' and tg_op='UPDATE' then o.arrival_at else (newj->>'started_at')::timestamptz end;
   if boundary is null or not isfinite(boundary) then raise exception using errcode='23514',message='A finite activity boundary is required.';end if;
   if exists(select 1 from public.time_shifts where profile_id=who and status='open' and clock_out_at is null and break_started_at is not null) then
     raise exception using errcode='23514',message='Resume the job clock before starting work.';
   end if;
   if kind<>'service' and exists(select 1 from public.service_time_sessions where profile_id=who and (started_at>boundary or ended_at>boundary)) then
     raise exception using errcode='23514',message='Newer service time requires timeline review.';
   end if;
   perform public._work_activity_close_all(who,boundary,'legacy_transition',kind,(newj->>'id')::uuid);
 elsif kind='task' and tg_op='INSERT' and newj->>'state'='off_task' then
   perform public._work_activity_close_all(who,(newj->>'started_at')::timestamptz,'stop');
 end if;
 return new;
end; $$;
revoke all on function public._work_activity_row_before() from public,anon,authenticated;

create function public._work_activity_row_event() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare oldj jsonb; newj jsonb; before_value jsonb; after_value jsonb; who uuid; oldwho uuid; kind text;
 boundary timestamptz; cause text; frame public.work_activity_transaction_context; o public.work_activity_operations;
begin
 o:=public._work_activity_operation();
 oldj:=case when tg_op<>'INSERT' then to_jsonb(old) end;newj:=case when tg_op<>'DELETE' then to_jsonb(new) end;
 before_value:=public._work_activity_evidence(tg_table_name,oldj);after_value:=public._work_activity_evidence(tg_table_name,newj);
 if before_value=after_value then return null;end if;
 who:=(coalesce(newj,oldj)->>case when tg_table_name='opening_phases' then 'started_by' else 'profile_id' end)::uuid;
 oldwho:=(oldj->>case when tg_table_name='opening_phases' then 'started_by' else 'profile_id' end)::uuid;
 kind:=case tg_table_name when 'time_shifts' then 'shift' when 'custom_work_sessions' then 'custom' when 'unit_sessions' then 'unit' when 'task_sessions' then 'task' when 'service_time_sessions' then 'service' when 'opening_phases' then 'phase' when 'work_setup_sessions' then 'setup' when 'summon_helpers' then 'helper' end;
 select c.* into frame from public.work_activity_transaction_context c where c.top_xid=o.top_xid and c.backend_pid=o.backend_pid
   and c.subject_profile_id=who and not exists(select 1 from public.work_activity_transaction_context child where child.parent_id=c.id);
 boundary:=coalesce(frame.selected_effective_at,o.arrival_at);cause:=coalesce(frame.cause,'legacy_transition');
 if frame.id is null then
   if tg_op='DELETE' then cause:='correction';
   elsif kind='shift' then
     if tg_op='INSERT' then boundary:=(newj->>'clock_in_at')::timestamptz;cause:=case when newj->'source_import' is not null and newj->'source_import'<>'null'::jsonb then 'import' else 'clock_in' end;
     elsif newj->>'status'='voided' and oldj->>'status'<>'voided' then cause:='void';
     elsif oldj->>'status'='voided' and newj->>'status'<>'voided' then cause:='restore';
     elsif newj->'clock_out_at'<>'null'::jsonb and oldj->'clock_out_at'='null'::jsonb then boundary:=(newj->>'clock_out_at')::timestamptz;cause:='clock_out';
     elsif newj->'break_started_at'<>'null'::jsonb and oldj->'break_started_at'='null'::jsonb then boundary:=(newj->>'break_started_at')::timestamptz;cause:='break_start';
     elsif newj->'break_started_at'='null'::jsonb and oldj->'break_started_at'<>'null'::jsonb then boundary:=coalesce((newj->>'last_punch_at')::timestamptz,o.arrival_at);cause:='break_end';
     else cause:='correction';end if;
   elsif kind='phase' then boundary:=coalesce((newj->>'paused_at')::timestamptz,(newj->>'submitted_at')::timestamptz,case when tg_op='INSERT' then (newj->>'started_at')::timestamptz else o.arrival_at end);
   elsif kind='helper' then boundary:=coalesce((newj->>'completed_at')::timestamptz,(newj->>'canceled_at')::timestamptz,(newj->>'joined_at')::timestamptz);
   else boundary:=coalesce((newj->>'selected_end_at')::timestamptz,(newj->>'ended_at')::timestamptz,(newj->>'started_at')::timestamptz,o.arrival_at);end if;
 end if;
 if oldwho is not null and oldwho is distinct from who then
   perform public._work_activity_event(oldwho,kind,(oldj->>'id')::uuid,tg_op,boundary,'correction',before_value,'{}');
   before_value:='{}';
 end if;
 if who is not null then perform public._work_activity_event(who,kind,(coalesce(newj,oldj)->>'id')::uuid,tg_op,boundary,cause,before_value,after_value);end if;
 return null;
end; $$;
revoke all on function public._work_activity_row_event() from public,anon,authenticated;

create or replace function public._work_activity_setup_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare v_expected uuid; v_cause text; v_boundary timestamptz;
begin
  if tg_op='DELETE' then raise exception using errcode='23514',message='Setup evidence is retained.'; end if;
  if tg_op='INSERT' and not public._work_config_internal(new.profile_id) then
    raise exception using errcode='42501',message='An eligible Forge account is required for new setup.';
  end if;
  if tg_op='INSERT' and (new.ended_at is not null or new.selected_end_at is not null or new.end_reason is not null or new.end_transition_id is not null or new.end_safety_event_id is not null) then
    raise exception using errcode='23514',message='A setup segment must begin open.';
  end if;
  if tg_op='UPDATE' and (old.ended_at is not null or new.ended_at is null
    or (to_jsonb(new)-array['ended_at','selected_end_at','end_reason','end_transition_id','end_safety_event_id']) is distinct from (to_jsonb(old)-array['ended_at','selected_end_at','end_reason','end_transition_id','end_safety_event_id'])) then
    raise exception using errcode='23514',message='Only an open setup interval can close once.';
  end if;
  select m.id,c.cause,c.selected_effective_at into v_expected,v_cause,v_boundary from public.work_activity_expected_mutations m
    join public.work_activity_transaction_context c on c.id=m.frame_id
    where c.top_xid=pg_current_xact_id() and c.backend_pid=pg_backend_pid() and c.actor_id is not distinct from auth.uid()
      and m.table_oid=tg_relid and m.operation=tg_op and m.source_id=new.id and m.subject_profile_id=new.profile_id and not m.consumed;
  if v_expected is null then raise exception using errcode='42501',message='Setup requires an exact private activity frame.'; end if;
  if (tg_op='INSERT' and (new.started_at is distinct from v_boundary or v_cause<>(case when new.resumed_from_id is null then 'clock_in' else 'break_end' end)))
    or (tg_op='UPDATE' and (new.selected_end_at is distinct from v_boundary or new.ended_at is distinct from greatest(new.started_at,v_boundary)
      or v_cause<>(case new.end_reason when 'setup_complete' then 'stop' when 'switch' then 'switch' when 'break' then 'break_start' when 'clock_out' then 'clock_out' when 'correction' then 'correction' when 'void' then 'void' else 'legacy_transition' end))) then
    raise exception using errcode='23514',message='Setup mutation does not match the frame boundary and cause.';
  end if;
  perform public._work_activity_consume(v_expected,tg_relid::regclass,tg_op,case when tg_op='UPDATE' then to_jsonb(old) end,to_jsonb(new));
  return new;
end; $$;
revoke all on function public._work_activity_setup_guard() from public,anon,authenticated;

create or replace function public._work_activity_setup_ledger_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare v public.work_setup_sessions; t public.personal_activity_transitions; prior public.work_setup_sessions;
begin
  select * into strict v from public.work_setup_sessions where id=new.id;
  select * into t from public.personal_activity_transitions where id=v.start_transition_id;
  if t.id is null or t.profile_id is distinct from v.profile_id or t.source_shift_id is distinct from v.shift_id
    or t.selected_effective_at is distinct from v.started_at or t.cause<>(case when v.resumed_from_id is null then 'clock_in' else 'break_end' end)
    or (v.resumed_from_id is null and (t.source_request_id is distinct from v.clock_client_id or t.actor_id is distinct from v.profile_id))
    or (tg_op='INSERT' and v.resumed_from_id is null and not exists(select 1 from public.time_shifts ts where ts.id=v.shift_id and ts.profile_id=v.profile_id and ts.clock_in_at=v.started_at))
    or (tg_op='INSERT' and not exists(select 1 from public.time_clock_actions where client_id=v.clock_client_id and profile_id=v.profile_id and shift_id=v.shift_id and action='clock_in')) then
    raise exception using errcode='23514',message='Setup lacks its actual clock and lifecycle identity.';
  end if;
  if v.resumed_from_id is not null then
    select * into prior from public.work_setup_sessions where id=v.resumed_from_id;
    if prior.profile_id is distinct from v.profile_id or prior.shift_id is distinct from v.shift_id or prior.clock_client_id is distinct from v.clock_client_id
      or prior.end_reason is distinct from 'break' or prior.ended_at is null or prior.ended_at>v.started_at then
      raise exception using errcode='23514',message='Setup resume does not match its prior segment.';
    end if;
  end if;
  if v.end_safety_event_id is not null then
    if v.ended_at is distinct from greatest(v.started_at,v.selected_end_at) or not exists(
      select 1 from public.work_activity_safety_events e where e.id=v.end_safety_event_id and e.profile_id=v.profile_id
       and e.source_kind='setup' and e.source_id=v.id and e.source_shift_id=v.shift_id and e.selected_effective_at=v.selected_end_at
       and e.after_evidence->>'end_safety_event_id'=v.end_safety_event_id::text
       and e.cause=(case v.end_reason when 'setup_complete' then 'stop' when 'switch' then 'switch' when 'break' then 'break_start'
         when 'clock_out' then 'clock_out' when 'correction' then 'correction' when 'void' then 'void' else 'legacy_transition' end)) then
      raise exception using errcode='23514',message='Setup safety close lacks its exact retained boundary.';
    end if;
  elsif v.ended_at is not null then
    select * into t from public.personal_activity_transitions where id=v.end_transition_id;
    -- A single root clock-in can close an OLD shift and start a NEW one.
    -- Preserve that one revision; its typed child event owns the old source's
    -- exact shift/cause/boundary, which need not equal the root transition.
    if t.id is null or t.profile_id is distinct from v.profile_id
      or v.ended_at is distinct from greatest(v.started_at,v.selected_end_at)
      or not exists(select 1 from public.personal_activity_transition_sources e
        where e.transition_id=v.end_transition_id and e.profile_id=v.profile_id
          and e.source_kind='setup' and e.source_id=v.id and e.relation='effective'
          and e.source_shift_id=v.shift_id and e.selected_effective_at=v.selected_end_at
          and e.cause=(case v.end_reason when 'setup_complete' then 'stop' when 'switch' then 'switch' when 'break' then 'break_start'
            when 'clock_out' then 'clock_out' when 'correction' then 'correction' when 'void' then 'void' else 'legacy_transition' end)) then
      raise exception using errcode='23514',message='Setup end lacks its exact per-source lifecycle boundary.';
    end if;
  end if;
  return null;
end; $$;
revoke all on function public._work_activity_setup_ledger_guard() from public,anon,authenticated;

create function public._work_activity_safety_exit(p_operation uuid,p_profile uuid,p_reason text) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations; person public.work_activity_operation_people; s public.personal_activity_state; e record; emitted boolean:=false;
begin
 o:=public._work_activity_operation();
 select * into person from public.work_activity_operation_people where operation_id=o.id and profile_id=p_profile;
 if o.id is distinct from p_operation or person.id is null or o.command_id is not null then
   raise exception using errcode='23514',message='Safety evidence requires an actual legacy payroll operation.';
 end if;
 update public.personal_activity_state set integrity_state='review',resume_token=null,resume_source_kind=null,resume_source_id=null,
  resume_definition_version_id=null,resume_shift_id=null,resume_from_revision=null,resume_after_break_transition_id=null,resume_authority_revision=null,
  updated_at=clock_timestamp() where profile_id=p_profile returning * into s;
 for e in select source_kind,source_id,(array_agg(operation order by event_order desc))[1] source_operation,
   (array_agg(before_value order by event_order))[1] first_before,(array_agg(after_value order by event_order desc))[1] last_after,
   (array_agg(after_value->'exhaustedVisitCounter' order by event_order) filter(where after_value->'exhaustedVisitCounter' is not null))[1] exhausted_counter,
   (array_agg(selected_at order by event_order desc))[1] boundary,(array_agg(cause order by event_order desc))[1] event_cause
   from public.work_activity_operation_events where operation_id=o.id and profile_id=p_profile group by source_kind,source_id
 loop
   insert into public.work_activity_safety_events(id,operation_id,profile_id,actor_id,source_kind,source_id,source_shift_id,source_operation,
     reason,selected_effective_at,cause,before_state,after_state,before_evidence,after_evidence)
   values(coalesce((e.last_after->>'end_safety_event_id')::uuid,gen_random_uuid()),o.id,p_profile,o.actor_id,e.source_kind,e.source_id,
     case when e.source_kind='shift' then e.source_id else coalesce((e.last_after->>'shift_id')::uuid,(e.first_before->>'shift_id')::uuid,s.shift_id,(person.before_state->>'shift_id')::uuid) end,
     e.source_operation,p_reason,e.boundary,e.event_cause,person.before_state,to_jsonb(s),e.first_before,e.last_after||case when e.exhausted_counter is not null then jsonb_build_object('exhaustedVisitCounter',e.exhausted_counter) else '{}'::jsonb end);
   emitted:=true;
 end loop;
 if not emitted then
   insert into public.work_activity_safety_events(operation_id,profile_id,actor_id,source_kind,source_id,source_shift_id,source_operation,
     reason,selected_effective_at,cause,before_state,after_state,before_evidence,after_evidence)
   values(o.id,p_profile,o.actor_id,'state',p_profile,s.shift_id,'STATE',p_reason,o.arrival_at,'correction',person.before_state,to_jsonb(s),'{}','{}');
 end if;
end; $$;
revoke all on function public._work_activity_safety_exit(uuid,uuid,text) from public,anon,authenticated;

create function public._work_activity_safety_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations;
begin
 o:=public._work_activity_operation();
 if o.id is distinct from new.operation_id or o.actor_id is distinct from new.actor_id
   or not exists(select 1 from public.work_activity_operation_people where operation_id=o.id and profile_id=new.profile_id)
   or (new.before_state->>'profile_id') is distinct from new.profile_id::text or (new.after_state->>'profile_id') is distinct from new.profile_id::text then
   raise exception using errcode='23514',message='Safety evidence lacks its actual subject and operation.';
 end if;
 return new;
end; $$;
revoke all on function public._work_activity_safety_guard() from public,anon,authenticated;
create trigger work_activity_safety_guard before insert on public.work_activity_safety_events for each row execute function public._work_activity_safety_guard();

create function public._work_activity_project_view(p_project uuid,p_actor uuid) returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
declare p jsonb;
begin
 if p_project is null then return jsonb_build_object('visibility','unassigned','id',null,'name',null,'jobCode',null);end if;
 if not public._ai_job_visible(p_project,p_actor) then return jsonb_build_object('visibility','unavailable','id',null,'name',null,'jobCode',null);end if;
 select to_jsonb(x) into p from public.projects x where id=p_project;
 return jsonb_build_object('visibility','available','id',p_project,'name',coalesce(p->>'name',p->>'job_code','Job'),'jobCode',p->>'job_code');
end; $$;
revoke all on function public._work_activity_project_view(uuid,uuid) from public,anon,authenticated;

create function public._work_activity_command_basis(p_basis jsonb) returns jsonb
language sql immutable set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_basis->'id','operationalRevision',p_basis->'operationalRevision',
  'factId',p_basis#>'{fact,id}','factRevision',p_basis#>'{fact,revision}','incarnationEpoch',p_basis->'incarnationEpoch',
  'bindingEpoch',p_basis->'bindingEpoch','projectEpoch',p_basis->'projectEpoch','openingEpoch',p_basis->'openingEpoch',
  'originProjectEpoch',p_basis#>'{fact,originProjectEpoch}','originOpeningEpoch',p_basis#>'{fact,originOpeningEpoch}')
$$;
revoke all on function public._work_activity_command_basis(jsonb) from public,anon,authenticated;

-- Every known original/current link is checked before projecting any source
-- identity, label, selected answers or fact token. This function never chooses
-- between competing claims and never enumerates another person's sources.
create function public._work_activity_source_view(p_state public.personal_activity_state) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare table_name text; r jsonb; h public.time_shifts; u jsonb; project uuid; opening uuid; work_unit uuid;
 v public.service_visits; su public.service_visit_units; meta public.work_session_capture_metadata;
 definition public.work_activity_definition_versions; capture jsonb; unavailable constant jsonb:='{"visibility":"unavailable"}';
begin
 if p_state.profile_id is distinct from auth.uid() or not public._work_config_internal(p_state.profile_id) then return unavailable;end if;
 if p_state.active_source_id is null then return null;end if;
 table_name:=case p_state.active_source_kind when 'custom' then 'custom_work_sessions' when 'unit' then 'unit_sessions' when 'task' then 'task_sessions'
  when 'service' then 'service_time_sessions' when 'phase' then 'opening_phases' when 'setup' then 'work_setup_sessions' end;
 if table_name is null then return unavailable;end if;
 execute format('select to_jsonb(s) from public.%I s where id=$1',table_name) into r using p_state.active_source_id;
 if r is null or (r->>case when p_state.active_source_kind='phase' then 'started_by' else 'profile_id' end) is distinct from p_state.profile_id::text then return unavailable;end if;
 select * into h from public.time_shifts where id=p_state.shift_id and profile_id=p_state.profile_id;
 if h.id is null or (h.project_id is not null and not public._ai_job_visible(h.project_id,p_state.profile_id)) then return unavailable;end if;
 if r ? 'shift_id' and (r->>'shift_id')::uuid is distinct from h.id then return unavailable;end if;
 project:=(r->>'project_id')::uuid;opening:=(r->>'opening_id')::uuid;
 if project is not null and not public._ai_job_visible(project,p_state.profile_id) then return unavailable;end if;
 if p_state.active_source_kind='custom' then work_unit:=(r->>'unit_id')::uuid;
 elsif p_state.active_source_kind='service' then
   select * into v from public.service_visits where id=(r->>'visit_id')::uuid;
   if v.id is null or not public.service_job_access(project) or not public.service_job_access(v.project_id)
     or not public._ai_job_visible(v.project_id,p_state.profile_id) then return unavailable;end if;
   if r->>'unit_id' is not null then
     select * into su from public.service_visit_units where id=(r->>'unit_id')::uuid;
     if su.id is null or su.visit_id is distinct from v.id or not public.service_job_access(su.project_id)
       or not public._ai_job_visible(su.project_id,p_state.profile_id) then return unavailable;end if;
     work_unit:=su.work_unit_id;opening:=su.opening_id;
   end if;
 end if;
 if opening is not null then
   if not exists(select 1 from public.project_openings x where x.id=opening and x.removed_at is null and public._ai_job_visible(x.project_id,p_state.profile_id)) then return unavailable;end if;
   if project is null then select project_id into project from public.project_openings where id=opening;end if;
 end if;
 if work_unit is not null then
   u:=public._work_activity_unit_basis(work_unit,p_state.profile_id);
   if u is null then return unavailable;end if;
 end if;
 if p_state.active_source_kind='custom' then
   select * into meta from public.work_session_capture_metadata where session_id=p_state.active_source_id;
   if meta.session_id is not null then
     if meta.profile_id is distinct from p_state.profile_id or not public._ai_job_visible(meta.project_id,p_state.profile_id)
       or meta.selection_id is null or meta.answers is null or meta.unit_id is distinct from work_unit then return unavailable;end if;
     if not exists(select 1 from public.work_job_menu_selections x where x.id=meta.selection_id and x.project_id=meta.project_id and x.revision=meta.selection_revision and x.menu_version_id=meta.menu_version_id) then return unavailable;end if;
     select * into definition from public.work_activity_definition_versions where id=meta.definition_version_id;
     if definition.id is null then return unavailable;end if;
     capture:=jsonb_build_object('definitionVersionId',meta.definition_version_id,'menuVersionId',meta.menu_version_id,
       'selectionId',meta.selection_id,'selectionRevision',meta.selection_revision,'scope',meta.scope,'labelEn',definition.label_en,'labelEs',definition.label_es,
       'machineKind',meta.machine_kind,'values',meta.answers,'unitAtStart',meta.unit_basis);
   end if;
 end if;
 return jsonb_build_object('visibility','available','source',jsonb_build_object('kind',p_state.active_source_kind,'id',p_state.active_source_id),
  'startedAt',public._work_activity_iso(p_state.effective_since),'project',public._work_activity_project_view(project,p_state.profile_id),'capture',capture,'unit',u);
end; $$;
revoke all on function public._work_activity_source_view(public.personal_activity_state) from public,anon,authenticated;

create function public._work_activity_validate_switch(p_intent jsonb,p_actor uuid) returns text
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare selected public.work_job_menu_selections; menu public.work_capture_menu_versions;
 definition public.work_activity_definition_versions; u jsonb; at_time timestamptz:=clock_timestamp();
begin
 if p_actor is distinct from auth.uid() or not public._work_config_internal(p_actor)
   or not public._ai_job_visible((p_intent->>'projectId')::uuid,p_actor) then return 'source_unavailable';end if;
 -- Source authorization precedes revision/version comparisons.
 if p_intent->>'scope'='specific' then
   u:=public._work_activity_unit_basis((p_intent#>>'{unit,id}')::uuid,p_actor);
   if u is null then return 'source_unavailable';end if;
 end if;
 select * into selected from public.work_job_menu_selections where project_id=(p_intent->>'projectId')::uuid order by revision desc limit 1;
 if selected.id is null or selected.id is distinct from (p_intent->>'selectionId')::uuid or selected.revision is distinct from (p_intent->>'selectionRevision')::bigint
  or selected.menu_version_id is distinct from (p_intent->>'menuVersionId')::uuid then return 'selection_changed';end if;
 select mv.* into menu from public.work_capture_menu_versions mv join public.work_capture_menus m on m.id=mv.menu_id
  where mv.id=selected.menu_version_id and m.retired_at is null and coalesce(mv.effective_from,mv.published_at)<=at_time;
 if menu.id is null or exists(select 1 from jsonb_array_elements(menu.items) it join public.work_activity_definition_versions dv on dv.id=(it->>'versionId')::uuid
   join public.work_activity_definitions d on d.id=dv.definition_id where (it->>'enabled')::boolean and (d.retired_at is not null or coalesce(dv.effective_from,dv.published_at)>at_time)) then return 'selection_changed';end if;
 select dv.* into definition from public.work_activity_definition_versions dv join public.work_activity_definitions d on d.id=dv.definition_id
  where dv.id=(p_intent->>'definitionVersionId')::uuid and d.retired_at is null and coalesce(dv.effective_from,dv.published_at)<=at_time
   and dv.scope=p_intent->>'scope' and exists(select 1 from jsonb_array_elements(menu.items) it where (it->>'versionId')::uuid=dv.id and (it->>'definitionId')::uuid=dv.definition_id and (it->>'enabled')::boolean);
 if definition.id is null then return 'selection_changed';end if;
 if u is not null and (not (u->>'eligibleForCapture')::boolean or u->>'projectId' is distinct from p_intent->>'projectId'
   or public._work_activity_command_basis(u) is distinct from p_intent->'unit') then return 'unit_changed';end if;
 if definition.machine_selection is distinct from (p_intent->'machineKind'<>'null'::jsonb) then return 'answers_invalid';end if;
 begin perform public._work_activity_answers(definition.typed_fields,p_intent->'values');
 exception when check_violation then return 'answers_invalid';end;
 return null;
end; $$;
revoke all on function public._work_activity_validate_switch(jsonb,uuid) from public,anon,authenticated;

create function public.work_activity_unit_basis(p_unit_id uuid) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid; u jsonb; result jsonb;
begin
 perform public._work_activity_read_committed();
 perform public._work_activity_gate();actor:=public._work_activity_actor();
 if p_unit_id is null then raise exception using errcode='23514',message='A unit identity is required.';end if;
 perform pg_advisory_xact_lock(7710,0);
 actor:=public._work_activity_actor();u:=public._work_activity_unit_basis(p_unit_id,actor);
 result:=jsonb_build_object('protocolVersion',1,'asOf',public._work_activity_iso(clock_timestamp()),'availability',case when u is null then 'unavailable' else 'available' end,'unit',u);
 if octet_length(result::text)>100000 then raise exception using errcode='54000',message='Activity projection is too large.';end if;
 return result;
end; $$;
revoke all on function public.work_activity_unit_basis(uuid) from public,anon;
grant execute on function public.work_activity_unit_basis(uuid) to authenticated;

create function public.work_activity_command_receipt(p_command_id uuid) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid; receipt jsonb;
begin
 perform public._work_activity_read_committed();
 perform public._work_activity_gate();actor:=public._work_activity_actor();
 if p_command_id is null then raise exception using errcode='23514',message='A command identity is required.';end if;
 select result into receipt from public.personal_activity_commands where command_id=p_command_id and actor_id=actor and subject_profile_id=actor;
 return jsonb_build_object('protocolVersion',1,'availability',case when receipt is null then 'unavailable' else 'available' end,'receipt',receipt);
end; $$;
revoke all on function public.work_activity_command_receipt(uuid) from public,anon;
grant execute on function public.work_activity_command_receipt(uuid) to authenticated;

create function public.work_activity_snapshot(p_device_id uuid) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid; s public.personal_activity_state; h public.time_shifts; stream public.work_activity_streams; observation public.work_activity_observations;
 result jsonb; state_view jsonb; stream_view jsonb; observation_view jsonb; shift_view jsonb; enabled boolean; ready boolean; personal_status text; state_actions jsonb; as_of timestamptz;
begin
 perform public._work_activity_read_committed();
 perform public._work_activity_gate();actor:=public._work_activity_actor();
 if p_device_id is null then raise exception using errcode='23514',message='A device identity is required.';end if;
 perform pg_advisory_xact_lock(7710,0);actor:=public._work_activity_actor();as_of:=clock_timestamp();
 if exists(select 1 from public.work_activity_safety_events where profile_id=actor) then
   return jsonb_build_object('protocolVersion',1,'asOf',public._work_activity_iso(as_of),'deviceId',p_device_id,
     'capability',jsonb_build_object('mode','unavailable','reasonCode','not_ready'),'observation',null,'stream',null,'state',null);
 end if;
 select capture_enabled into enabled from public.work_activity_authority_generation where singleton;
 select * into s from public.personal_activity_state where profile_id=actor;
 if s.profile_id is null then s:=public._work_activity_refresh_state(actor);end if;
 select * into h from public.time_shifts where id=s.shift_id and profile_id=actor and status='open' and clock_out_at is null;
 ready:=s.integrity_state='clean' and s.revision<9007199254740991 and ((s.shift_id is null and not exists(select 1 from public._work_activity_live_sources(actor)))
   or (h.id is not null and isfinite(h.clock_in_at) and h.clock_in_at<=as_of and h.clock_in_at+make_interval(hours=>public.shift_cap_hours())>as_of));
 if ready then observation:=public._work_activity_observe(p_device_id);end if;
 select * into stream from public.work_activity_streams where actor_id=actor and device_id=p_device_id and status in ('active','blocked');
 if stream.id is not null then stream_view:=jsonb_build_object('clientGeneration',stream.client_generation,'headSequence',stream.head_sequence,'headCommandId',stream.head_command_id,
  'headAfterRevision',(select after_revision from public.personal_activity_commands where command_id=stream.head_command_id),'status',stream.status);end if;
 if observation.id is not null then observation_view:=jsonb_build_object('id',observation.id,'revision',observation.revision,'lastTransitionId',observation.last_transition_id,
  'issuedAt',public._work_activity_iso(observation.issued_at),'expiresAt',public._work_activity_iso(observation.expires_at),
  'shiftRef',case when observation.shift_id is not null then jsonb_build_object('kind','shift','id',observation.shift_id) end,
  'currentGeneration',observation.current_generation,'currentHeadCommandId',observation.current_head_command_id);end if;
 if h.id is not null then shift_view:=jsonb_build_object('id',h.id,'clockInCommandId',h.client_id,'clockInAt',public._work_activity_iso(h.clock_in_at),
  'breakStartedAt',public._work_activity_iso(h.break_started_at),'breakType',h.break_type,'status','open','project',public._work_activity_project_view(h.project_id,actor));end if;
 personal_status:=case when s.integrity_state<>'clean' then 'review' when h.id is null then 'off_clock' when h.break_started_at is not null then 'on_break'
  when s.active_source_kind='setup' then 'setup' when s.active_source_id is not null then 'running' else 'unclassified' end;
 state_actions:=jsonb_build_object('canEstablishStream',ready,'canSwitch',ready and enabled and h.id is not null and h.break_started_at is null and s.active_source_kind is distinct from 'setup',
  'canFinishSetup',coalesce(ready and enabled and h.id is not null and h.break_started_at is null and s.active_source_kind='setup',false),
  'canStop',ready and h.id is not null and h.break_started_at is null and s.active_source_id is not null);
 state_view:=jsonb_build_object('revision',s.revision,'lastTransitionId',s.last_transition_id,'integrity',s.integrity_state,'status',personal_status,'choiceRequired',s.choice_required,
  'actions',state_actions,'shift',shift_view,'activity',case when h.id is not null and h.break_started_at is null then public._work_activity_source_view(s) end);
 result:=jsonb_build_object('protocolVersion',1,'asOf',public._work_activity_iso(as_of),'deviceId',p_device_id,
  'capability',jsonb_build_object('mode',case when enabled then 'active' else 'closing_only' end,'reasonCode',case when not enabled then 'starts_disabled' end),
  'observation',observation_view,'stream',stream_view,'state',state_view);
 if octet_length(result::text)>100000 then raise exception using errcode='54000',message='Activity projection is too large.';end if;
 return result;
end; $$;
revoke all on function public.work_activity_snapshot(uuid) from public,anon;
grant execute on function public.work_activity_snapshot(uuid) to authenticated;

create function public._work_activity_insert_source(p_profile uuid,p_kind text,p_data jsonb,p_at timestamptz,p_cause text) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare table_name text; columns text[]; frame uuid; new_id uuid; data jsonb; allowance uuid;
begin
 perform public._work_activity_touch(p_profile);
 table_name:=case p_kind when 'unit' then 'unit_sessions' when 'task' then 'task_sessions' when 'service' then 'service_time_sessions' when 'setup' then 'work_setup_sessions' end;
 if table_name is null or jsonb_typeof(p_data) is distinct from 'object' or p_data->>'profile_id' is distinct from p_profile::text
   or (p_data->>'started_at')::timestamptz is distinct from p_at then raise exception using errcode='23514',message='Invalid source insertion frame.';end if;
 new_id:=(p_data->>'id')::uuid;
 select array_agg(key order by key) into columns from jsonb_object_keys(p_data) key;
 frame:=public._work_activity_context_for(p_profile,p_cause,p_at);
 allowance:=public._work_activity_expect(frame,('public.'||table_name)::regclass,'INSERT',new_id,columns,null,public._work_activity_evidence(table_name,p_data));
 execute format('insert into public.%I(%s) select %s from jsonb_populate_record(null::public.%I,$1) proposed',table_name,
   (select string_agg(format('%I',c),',') from unnest(columns) c),
   (select string_agg(format('proposed.%I',c),',') from unnest(columns) c),table_name) using p_data;
 perform public._work_activity_context_close(frame);
 return new_id;
end; $$;
revoke all on function public._work_activity_insert_source(uuid,text,jsonb,timestamptz,text) from public,anon,authenticated;

create function public._work_activity_start_setup(p_shift public.time_shifts,p_clock_client uuid,p_prior uuid default null) returns uuid
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare person public.work_activity_operation_people; o public.work_activity_operations; at_time timestamptz;
begin
 o:=public._work_activity_operation();person:=public._work_activity_touch(p_shift.profile_id);
 if o.actor_id is distinct from p_shift.profile_id or not public._work_config_internal(p_shift.profile_id)
   or (person.before_state->>'revision')::bigint>=9007199254740991
   or exists(select 1 from public.work_activity_safety_events where profile_id=p_shift.profile_id) then return null;end if;
 if p_prior is null and (o.route<>'clock_in_setup' or o.request_id is distinct from p_clock_client) then
   raise exception using errcode='23514',message='Initial setup requires the explicit clock adapter.';
 end if;
 at_time:=case when p_prior is null then p_shift.clock_in_at else coalesce(p_shift.last_punch_at,o.arrival_at) end;
 return public._work_activity_insert_source(p_shift.profile_id,'setup',jsonb_build_object('id',gen_random_uuid(),'profile_id',p_shift.profile_id,
   'shift_id',p_shift.id,'clock_client_id',p_clock_client,'resumed_from_id',p_prior,'started_at',at_time,'start_transition_id',person.transition_id),
   at_time,case when p_prior is null then 'clock_in' else 'break_end' end);
end; $$;
revoke all on function public._work_activity_start_setup(public.time_shifts,uuid,uuid) from public,anon,authenticated;

create function public._work_activity_fact_snapshot(p_unit uuid) returns jsonb
language sql stable security definer set search_path=public,pg_temp as $$
 select jsonb_build_object('factId',r.id,'factRevision',r.revision,'width_in',r.width_in,'height_in',r.height_in,
  'measurement_source',r.measurement_source,'estimated',r.estimated,'raw_observation',r.raw_observation)
 from public.work_unit_fact_current c join public.work_unit_fact_revisions r on r.id=c.current_revision_id where c.unit_id=p_unit
$$;
revoke all on function public._work_activity_fact_snapshot(uuid) from public,anon,authenticated;

-- Only the payroll break-return callback may call this private composer. A
-- failed eligibility check means choiceRequired; it never guesses a last row.
create function public._work_activity_resume(p_state public.personal_activity_state,p_shift public.time_shifts,p_at timestamptz) returns boolean
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare view_state public.personal_activity_state; r jsonb; table_name text; prior_meta public.work_session_capture_metadata;
 intent jsonb; new_id uuid; frame uuid; config_enabled boolean; source_basis jsonb; changes jsonb; columns text[]; before_values jsonb; after_values jsonb; paused_total numeric;
begin
 if p_state.profile_id is distinct from auth.uid() or not public._work_config_internal(p_state.profile_id)
   or p_state.resume_token is null or p_state.resume_shift_id is distinct from p_shift.id
   or p_state.resume_after_break_transition_id is distinct from p_state.last_transition_id
   or p_state.resume_authority_revision is distinct from public._work_activity_authority_revision()
   or p_state.resume_authority_revision>=9007199254740991 or p_shift.status<>'open' or p_shift.clock_out_at is not null or p_shift.break_started_at is not null
   or exists(select 1 from public.work_activity_safety_events where profile_id=p_state.profile_id)
   or exists(select 1 from public._work_activity_live_sources(p_state.profile_id)) then return false;end if;
 if not pg_try_advisory_xact_lock(7710,0) then return false;end if;
 -- Recheck after any domain-lock acquisition. G excludes installed writers;
 -- the check remains explicit so a future adapter cannot rely on old state.
 if p_state.resume_authority_revision is distinct from public._work_activity_authority_revision() then return false;end if;
 view_state:=p_state;view_state.active_source_kind:=p_state.resume_source_kind;view_state.active_source_id:=p_state.resume_source_id;
 view_state.active_definition_version_id:=p_state.resume_definition_version_id;view_state.effective_since:=p_at;
 if public._work_activity_source_view(view_state)->>'visibility' is distinct from 'available' then return false;end if;
 table_name:=case p_state.resume_source_kind when 'custom' then 'custom_work_sessions' when 'unit' then 'unit_sessions' when 'task' then 'task_sessions'
   when 'service' then 'service_time_sessions' when 'phase' then 'opening_phases' when 'setup' then 'work_setup_sessions' end;
 execute format('select to_jsonb(s) from public.%I s where id=$1 for update',table_name) into r using p_state.resume_source_id;
 if p_state.resume_source_kind<>'phase' and ((r->>'ended_at')::timestamptz is null or (r->>'ended_at')::timestamptz>p_at) then return false;end if;
 if p_state.resume_source_kind='setup' then
   if r->>'end_reason'<>'break' then return false;end if;
   select capture_enabled into config_enabled from public.work_activity_authority_generation where singleton;
   if not config_enabled then return false;end if;
   new_id:=public._work_activity_start_setup(p_shift,(r->>'clock_client_id')::uuid,p_state.resume_source_id);
   return new_id is not null;
 end if;
 -- A toolbox refusal is an eligibility outcome for auto-resume. Do not turn
 -- an expired signature into a failed paid break return.
 if p_state.resume_source_kind='custom' and r->>'unit_id' is null then perform public._prep_time_gate(p_state.profile_id);
 else perform public._unit_work_gate(p_state.profile_id);end if;
 if p_state.resume_source_kind in ('unit','task','phase') and not exists(
   select 1 from public.project_openings where id=(r->>'opening_id')::uuid and removed_at is null and status<>'installed' and public._ai_job_visible(project_id,p_state.profile_id)) then return false;end if;
 if p_state.resume_source_kind='custom' then
   if r->>'end_reason'<>'break' or exists(select 1 from public.custom_work_units where id=(r->>'unit_id')::uuid and facts->>'installation_complete'='Yes') then return false;end if;
   select * into prior_meta from public.work_session_capture_metadata where session_id=p_state.resume_source_id;
   if prior_meta.session_id is not null then
     select capture_enabled into config_enabled from public.work_activity_authority_generation where singleton;
     if not config_enabled then return false;end if;
     intent:=jsonb_build_object('kind','switch','projectId',prior_meta.project_id,'selectionId',prior_meta.selection_id,'selectionRevision',prior_meta.selection_revision,
      'menuVersionId',prior_meta.menu_version_id,'definitionVersionId',prior_meta.definition_version_id,'scope',prior_meta.scope,
      'unit',prior_meta.continuation_unit_basis,'machineKind',prior_meta.machine_kind,'values',prior_meta.answers);
     if public._work_activity_validate_switch(intent,p_state.profile_id) is not null then return false;end if;
   end if;
   frame:=public._work_activity_context_for(p_state.profile_id,'break_end',p_at);
   new_id:=gen_random_uuid();
   perform public.custom_work_command(gen_random_uuid(),'start',jsonb_build_object('id',new_id,'shift_id',p_shift.id,'unit_id',r->'unit_id',
    'expected_session_id',null,'at',p_at,'participation',r->'participation','stage',r->'stage','description',r->'description'));
   perform public._work_activity_context_close(frame);
   if prior_meta.session_id is not null then
     source_basis:=case when prior_meta.unit_id is not null then public._work_activity_command_basis(public._work_activity_unit_basis(prior_meta.unit_id,p_state.profile_id)) end;
     insert into public.work_session_capture_metadata(session_id,profile_id,project_id,definition_version_id,menu_version_id,scope,unit_id,fact_revision,unit_facts,machine_kind,
       selection_id,selection_revision,answers,unit_basis,continuation_unit_basis)
     values(new_id,p_state.profile_id,prior_meta.project_id,prior_meta.definition_version_id,prior_meta.menu_version_id,prior_meta.scope,prior_meta.unit_id,
       prior_meta.fact_revision,prior_meta.unit_facts,prior_meta.machine_kind,prior_meta.selection_id,prior_meta.selection_revision,prior_meta.answers,
       prior_meta.continuation_unit_basis,source_basis);
   end if;
 elsif p_state.resume_source_kind='unit' then
   -- Old helper intervals lack an exact summon foreign key. Never infer a
   -- continuation from another helper's or yesterday's similarly named call.
   if r->>'end_reason'<>'break' or r->>'role'='helper' then return false;end if;
   new_id:=public._work_activity_insert_source(p_state.profile_id,'unit',jsonb_build_object('id',gen_random_uuid(),'profile_id',p_state.profile_id,
     'opening_id',r->'opening_id','role',r->'role','is_rework',public._has_open_redo((r->>'opening_id')::uuid),'started_at',p_at),p_at,'break_end');
 elsif p_state.resume_source_kind='task' then
   if r->>'state'<>'on_task' then return false;end if;
   new_id:=public._work_activity_insert_source(p_state.profile_id,'task',jsonb_build_object('id',gen_random_uuid(),'profile_id',p_state.profile_id,
     'opening_id',r->'opening_id','project_id',r->'project_id','state','on_task','started_at',p_at),p_at,'break_end');
 elsif p_state.resume_source_kind='service' then
   if r->>'end_reason'<>'break' or not exists(select 1 from public.service_visits where id=(r->>'visit_id')::uuid and status='active') then return false;end if;
   new_id:=public._work_activity_insert_source(p_state.profile_id,'service',jsonb_build_object('id',gen_random_uuid(),'profile_id',p_state.profile_id,
    'visit_id',r->'visit_id','project_id',r->'project_id','unit_id',r->'unit_id','shift_id',p_shift.id,'kind',r->'kind','stage',r->'stage','description',r->'description','started_at',p_at),p_at,'break_end');
 elsif p_state.resume_source_kind='phase' then
   if r->>'status'<>'active' or r->>'paused_at' is null or (r->>'paused_at')::timestamptz>p_at then return false;end if;
   -- A corrupt/exhausted activity duration must never reject paid break return.
   -- Compute before the integer cast so the eligibility path is deterministic.
   paused_total:=(r->>'paused_seconds')::numeric+greatest(0,round(extract(epoch from p_at-(r->>'paused_at')::timestamptz)));
   if paused_total is null or paused_total<0 or paused_total>2147483647 then return false;end if;
   changes:=jsonb_build_object('paused_at',null,'paused_seconds',paused_total::integer);
   frame:=public._work_activity_context_for(p_state.profile_id,'break_end',p_at);
   columns:=array['paused_at','paused_seconds'];
   select jsonb_object_agg(key,value) into before_values from jsonb_each(r) where key=any(columns||array['id','started_by']);after_values:=before_values||changes;
   perform public._work_activity_expect(frame,'public.opening_phases'::regclass,'UPDATE',p_state.resume_source_id,columns,before_values,after_values);
   update public.opening_phases set paused_at=null,paused_seconds=(changes->>'paused_seconds')::integer where id=p_state.resume_source_id;
   perform public._work_activity_context_close(frame);new_id:=p_state.resume_source_id;
 end if;
 return new_id is not null;
exception when raise_exception or check_violation or foreign_key_violation or unique_violation or insufficient_privilege or numeric_value_out_of_range then
 -- This subtransaction rolls back a partially constructed resume, including
 -- all private frames/events. The outer paid break return stays successful.
 return false;
end; $$;
revoke all on function public._work_activity_resume(public.personal_activity_state,public.time_shifts,timestamptz) from public,anon,authenticated;

create function public._work_activity_shift_lifecycle() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare person public.work_activity_operation_people; s public.personal_activity_state; o public.work_activity_operations; boundary timestamptz; cause text; saved boolean; resumed boolean;
begin
 o:=public._work_activity_operation();person:=public._work_activity_touch(case when tg_op='DELETE' then old.profile_id else new.profile_id end);
 select * into s from public.personal_activity_state where profile_id=person.profile_id;
 if tg_op='DELETE' then
   if s.shift_id=old.id then perform public._work_activity_close_all(old.profile_id,o.arrival_at,'correction');end if;
   return old;
 end if;
 if tg_op='INSERT' then
   -- Historical imports never start/close today's activity. Ordinary new
   -- clock-ins clear stale claims before explicit setup can be opened.
   if new.source_import is null and new.status='open' and new.clock_out_at is null then
     perform public._work_activity_close_all(new.profile_id,new.clock_in_at,'clock_in');
   end if;
   return new;
 end if;
 if new.clock_out_at is not null and old.clock_out_at is null then boundary:=new.clock_out_at;cause:='clock_out';
 elsif new.status<>'open' and old.status='open' then boundary:=coalesce(new.clock_out_at,o.arrival_at);cause:=case when new.status='voided' then 'void' else 'correction' end;
 elsif new.break_started_at is not null and old.break_started_at is null then boundary:=new.break_started_at;cause:='break_start';
 elsif new.break_started_at is null and old.break_started_at is not null and new.clock_out_at is null and new.status='open' then
   boundary:=coalesce(new.last_punch_at,o.arrival_at);
   resumed:=false;
   if o.route='end_break' and o.actor_id=new.profile_id then resumed:=public._work_activity_resume(s,new,boundary);end if;
   update public.personal_activity_state set resume_token=null,resume_source_kind=null,resume_source_id=null,resume_definition_version_id=null,
    resume_shift_id=null,resume_from_revision=null,resume_after_break_transition_id=null,resume_authority_revision=null,
    choice_required=not resumed where profile_id=new.profile_id;
   return new;
 else return new;end if;
 -- A historical correction to another shift cannot end today's timer.
 if s.shift_id is distinct from new.id then return new;end if;
 saved:=cause='break_start' and s.integrity_state='clean' and s.active_source_id is not null and s.revision<9007199254740991
   and not exists(select 1 from public.work_activity_safety_events where profile_id=new.profile_id);
 perform public._work_activity_close_all(new.profile_id,boundary,cause);
 update public.personal_activity_state set active_source_kind=null,active_source_id=null,active_definition_version_id=null,effective_since=null,
  resume_token=case when saved then gen_random_uuid() end,resume_source_kind=case when saved then s.active_source_kind end,
  resume_source_id=case when saved then s.active_source_id end,resume_definition_version_id=case when saved then s.active_definition_version_id end,
  resume_shift_id=case when saved then new.id end,resume_from_revision=case when saved then s.revision end,
  resume_after_break_transition_id=case when saved then person.transition_id end,
  resume_authority_revision=case when saved then public._work_activity_authority_revision() end,choice_required=false where profile_id=new.profile_id;
 return new;
end; $$;
revoke all on function public._work_activity_shift_lifecycle() from public,anon,authenticated;

-- The coordinator is the only lifecycle closer/resumer. Existing callbacks
-- retain their non-timing review/attribution effects and their original OIDs.
create or replace function public.custom_work_follow_legacy() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 update public.custom_work_units set legacy_time_present=true where opening_id=new.opening_id and not legacy_time_present;
 return new;
end; $$;
create or replace function public.custom_work_follow_phase() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin return new;end; $$;
create or replace function public.service_follow_work() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin return new;end; $$;
create or replace function public.unit_sessions_follow_shift() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin return new;end; $$;
create or replace function public.unit_sessions_on_clock_in() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin return new;end; $$;
create or replace function public.custom_work_follow_shift() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin
 update public.custom_work_sessions set shift_status=new.status,
   review_required=review_required or new.status in ('needs_finish','rejected','voided') or project_id is distinct from new.project_id
    or started_at<new.clock_in_at or (ended_at is not null and new.clock_out_at is not null and ended_at>new.clock_out_at)
   where shift_id=new.id;
 return new;
end; $$;
create or replace function public.service_follow_shift() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare visit_id uuid;
begin
 update public.service_time_sessions set review_required=review_required or new.status in ('needs_finish','rejected','voided') or project_id is distinct from new.project_id
   or started_at<new.clock_in_at or (ended_at is not null and new.clock_out_at is not null and ended_at>new.clock_out_at)
   or (new.break_seconds is distinct from old.break_seconds and old.break_started_at is null) where shift_id=new.id;
 for visit_id in select distinct s.visit_id from public.service_time_sessions s where s.shift_id=new.id order by s.visit_id loop
   perform public._work_activity_review_visit(visit_id,(public._work_activity_operation()).arrival_at,'correction');
 end loop;
 return new;
end; $$;
-- No grants are added to the preserved trigger functions.

create or replace function public.unit_sessions_follow_summon_helpers() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare opening uuid; r record; boundary timestamptz; o public.work_activity_operations; begins boolean;
begin
 o:=public._work_activity_operation();
 select opening_id into opening from public.summons where id=new.summon_id;
 if opening is null then return new;end if;
 begins:=new.completed_at is null and new.canceled_at is null and (tg_op='INSERT' or (tg_op='UPDATE' and old.canceled_at is not null));
 if begins then
   -- The public summon entry retains its source/toolbox checks; the private
   -- callback additionally refuses to invent an unpaid or on-break timer.
   if (select count(*) from public.time_shifts where profile_id=new.profile_id and status='open' and clock_out_at is null and break_started_at is null)<>1 then return new;end if;
   boundary:=case when tg_op='INSERT' then new.joined_at else o.arrival_at end;
   perform public._work_activity_close_all(new.profile_id,boundary,'legacy_transition');
   perform public._work_activity_insert_source(new.profile_id,'unit',jsonb_build_object('id',gen_random_uuid(),'profile_id',new.profile_id,
     'opening_id',opening,'role','helper','is_rework',public._has_open_redo(opening),'started_at',boundary),boundary,'legacy_transition');
 elsif tg_op='UPDATE' and ((new.completed_at is not null and old.completed_at is null) or (new.canceled_at is not null and old.canceled_at is null)) then
   boundary:=case when new.completed_at is not null and old.completed_at is null then new.completed_at else new.canceled_at end;
   for r in select id from public.unit_sessions where profile_id=new.profile_id and ended_at is null and role='helper' and opening_id=opening loop
     perform public._work_activity_close_source(new.profile_id,'unit',r.id,boundary,case when new.completed_at is not null then 'stop' else 'legacy_transition' end);
   end loop;
 end if;
 return new;
end; $$;

-- One public write surface. The existing source command remains the canonical
-- custom-session writer; this coordinator owns admission and atomic lifecycle.
create function public.work_activity_command(p_command_id uuid,p_protocol_version integer,p_payload jsonb) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid; payload jsonb; hash text; prior public.personal_activity_commands; head public.personal_activity_commands;
 s public.personal_activity_state; after_s public.personal_activity_state; h public.time_shifts; obs public.work_activity_observations;
 stream public.work_activity_streams; anchor public.work_activity_observations; clock_action public.time_clock_actions;
 clock_transition public.personal_activity_transitions; definition public.work_activity_definition_versions;
 device uuid; generation uuid; expected bigint; sequence_number bigint; predecessor uuid; kind text; intent jsonb;
 v_status text:='noop'; reason text; source_reason text; result jsonb; arrival timestamptz; selected_at timestamptz;
 pick public.clock_time_pick; not_before timestamptz; operation uuid; frame uuid; nested_request uuid; session_id uuid; person public.work_activity_operation_people;
 enabled boolean; admitted boolean:=false; clock_bridge boolean:=false; observation_lineage boolean:=false; unit_basis jsonb; before_shift jsonb; after_shift jsonb;
begin
 perform public._work_activity_read_committed();
 perform public._work_activity_gate();
 actor:=public._work_activity_actor();
 if p_command_id is null or p_protocol_version is distinct from 1 then raise exception using errcode='23514',message='Invalid activity protocol or command identity.';end if;
 payload:=public._work_activity_payload(p_payload);hash:=encode(sha256(convert_to(payload::text,'UTF8')),'hex');
 select * into prior from public.personal_activity_commands where command_id=p_command_id;
 if prior.command_id is not null then
   if prior.actor_id is distinct from actor or prior.subject_profile_id is distinct from actor or prior.protocol_version is distinct from 1
    or prior.payload_hash is distinct from hash or prior.normalized_payload is distinct from payload then
     return jsonb_build_object('protocolVersion',1,'availability','unavailable','receipt',null);
   end if;
   return jsonb_build_object('protocolVersion',1,'availability','available','receipt',prior.result);
 end if;
 -- G is first. Configuration/source authority is read again after its domain
 -- lock; no before-wait account or menu decision is reused.
 perform pg_advisory_xact_lock(7710,0);actor:=public._work_activity_actor();arrival:=clock_timestamp();
 device:=(payload->>'deviceId')::uuid;generation:=(payload->>'clientGeneration')::uuid;
 expected:=(payload->>'expectedRevision')::bigint;sequence_number:=(payload->>'clientSequence')::bigint;
 predecessor:=(payload->>'predecessorCommandId')::uuid;intent:=payload->'intent';kind:=intent->>'kind';
 if exists(select 1 from public.personal_activity_commands where actor_id=actor and device_id=device and client_generation=generation and client_sequence=sequence_number) then
   return jsonb_build_object('protocolVersion',1,'availability','unavailable','receipt',null);
 end if;
 select * into s from public.personal_activity_state where profile_id=actor for update;
 if s.profile_id is null then s:=public._work_activity_refresh_state(actor);end if;
 select * into obs from public.work_activity_observations where id=(payload#>>'{basis,observationId}')::uuid and actor_id=actor and device_id=device;
 select * into stream from public.work_activity_streams where actor_id=actor and device_id=device and status in ('active','blocked') for update;
 select capture_enabled into enabled from public.work_activity_authority_generation where singleton;
 -- Permission comes before any referenced source's eligibility/revision reason.
 if kind='switch' then source_reason:=public._work_activity_validate_switch(intent,actor);
 elsif kind='finish_setup' and not public._ai_job_visible((intent->>'projectId')::uuid,actor) then source_reason:='source_unavailable';end if;
 if source_reason='source_unavailable' then v_status:='refused';reason:=source_reason;
 elsif s.integrity_state<>'clean' or s.revision>=9007199254740991 or exists(select 1 from public.work_activity_safety_events where profile_id=actor) then
   v_status:='refused';reason:='reconciliation_required';
 elsif obs.id is null then v_status:='refused';reason:='observation_unavailable';
 elsif kind<>'stop' and obs.expires_at<=arrival then v_status:='refused';reason:='observation_expired';
 elsif kind<>'stop' and (obs.authority_revision is distinct from public._work_activity_authority_revision() or obs.authority_revision>=9007199254740991) then
   v_status:='conflict';reason:='state_changed';
 elsif s.revision<>expected then v_status:='conflict';reason:='state_changed';end if;
 if kind='establish_stream' then
   if reason is null and (obs.revision<>expected or obs.last_transition_id is distinct from s.last_transition_id
     or obs.shift_id is distinct from s.shift_id or obs.shift_id is distinct from (payload#>>'{shiftRef,id}')::uuid) then
     v_status:='conflict';reason:='state_changed';
   elsif reason is null and (stream.client_generation is distinct from (intent->>'previousGeneration')::uuid
     or stream.head_command_id is distinct from (intent->>'previousHeadCommandId')::uuid
     or obs.current_generation is distinct from (intent->>'previousGeneration')::uuid
     or obs.current_head_command_id is distinct from (intent->>'previousHeadCommandId')::uuid
     or exists(select 1 from public.work_activity_streams where actor_id=actor and device_id=device and client_generation=generation)) then
     v_status:='conflict';reason:='stream_changed';
   end if;
 else
   select * into head from public.personal_activity_commands where command_id=predecessor and actor_id=actor and device_id=device and client_generation=generation;
   admitted:=stream.id is not null and stream.status='active' and stream.client_generation=generation and stream.head_sequence<9007199254740991
     and sequence_number=stream.head_sequence+1 and predecessor=stream.head_command_id and head.status in ('applied','noop');
   if reason is null and not admitted then v_status:='conflict';reason:='stream_changed';end if;
   if payload#>>'{shiftRef,kind}'='clock_command' then
     select * into clock_action from public.time_clock_actions where client_id=(payload#>>'{shiftRef,id}')::uuid and profile_id=actor and action='clock_in';
     select * into h from public.time_shifts where id=clock_action.shift_id and profile_id=actor for update;
     select * into clock_transition from public.personal_activity_transitions where id=s.last_transition_id and profile_id=actor
      and cause='clock_in' and source_request_id=clock_action.client_id and source_shift_id=h.id;
     clock_bridge:=obs.shift_id is null and obs.revision=head.after_revision and obs.last_transition_id is not distinct from
       (select id from public.personal_activity_transitions where profile_id=actor and revision_after=obs.revision)
       and clock_transition.revision_before=obs.revision and clock_transition.revision_after=expected
       and clock_transition.id is not null and head.after_revision+1=expected;
   else select * into h from public.time_shifts where id=(payload#>>'{shiftRef,id}')::uuid and profile_id=actor for update;end if;
   if reason is null and (h.id is null or h.id is distinct from s.shift_id or h.status<>'open' or h.clock_out_at is not null) then v_status:='refused';reason:='shift_unavailable';end if;
   if reason is null and h.break_started_at is not null then v_status:='refused';reason:='on_break';end if;
   if reason is null and head.after_revision<>expected and not coalesce(clock_bridge,false) then v_status:='conflict';reason:='state_changed';end if;
   if stream.id is not null then select * into anchor from public.work_activity_observations where id=stream.anchor_observation_id;end if;
   observation_lineage:=obs.id=stream.anchor_observation_id or (obs.current_generation=generation and exists(
     select 1 from public.personal_activity_commands c where c.command_id=obs.current_head_command_id and c.actor_id=actor and c.device_id=device
       and c.client_generation=generation and c.client_sequence<=head.client_sequence and c.status in ('applied','noop') and c.after_revision=obs.revision));
   if reason is null and (not coalesce(observation_lineage,false) or obs.revision>expected or obs.revision<anchor.revision
     or (not coalesce(clock_bridge,false) and (obs.shift_id is distinct from h.id or obs.shift_clock_in_at is distinct from h.clock_in_at))) then
     v_status:='conflict';reason:='state_changed';end if;
   if reason is null and kind<>'stop' and (not enabled or h.clock_in_at+make_interval(hours=>public.shift_cap_hours())<=arrival) then
     v_status:='refused';reason:=case when not enabled then 'starts_disabled' else 'observation_expired' end;end if;
   if reason is null and source_reason is not null then v_status:='conflict';reason:=source_reason;end if;
   if reason is null and kind='switch' and ((intent->>'projectId')::uuid is distinct from h.project_id or s.active_source_kind='setup') then
     v_status:='refused';reason:='shift_unavailable';end if;
   if reason is null and kind='finish_setup' then
     if s.active_source_kind is distinct from 'setup' then v_status:='conflict';reason:='state_changed';
     elsif intent->>'costCodeId' is not null and not exists(select 1 from public.cost_codes where id=(intent->>'costCodeId')::uuid) then
       v_status:='refused';reason:='source_unavailable';end if;
   end if;
   if reason is null and kind in ('switch','finish_setup') and not public._toolbox_signed_today(actor) then v_status:='refused';reason:='toolbox_required';end if;
   if reason is null then
     select greatest(h.clock_in_at,h.last_punch_at,s.effective_since,(select selected_effective_at from public.personal_activity_transitions where id=s.last_transition_id)) into not_before;
     pick:=public._clock_pick_time_at((payload->>'tappedAt')::timestamptz,(payload->>'clockCheckedAt')::timestamptz,(payload->>'clockSkewMs')::integer,not_before,arrival);
     if pick.pay_at is null or pick.reason in ('tap_out_of_order','tap_too_old') then v_status:='refused';reason:='time_out_of_order';else selected_at:=pick.pay_at;end if;
   end if;
   if reason is null and not(kind='stop' and s.active_source_id is null) then
     -- Only the expected legacy business refusal is converted. Integrity,
     -- schema, timeout and deadlock exceptions roll back the entire command.
     begin
       nested_request:=case when kind='switch' then gen_random_uuid() end;
       operation:=public._work_activity_operation_enter('work_activity_command',jsonb_build_object('kind',kind),nested_request,p_command_id);
       if operation is null then raise exception using errcode='23514',message='Activity command cannot nest in another source operation.';end if;
       person:=public._work_activity_touch(actor);
       perform public._work_activity_close_all(actor,selected_at,case when kind='switch' then 'switch' else 'stop' end);
       if kind='switch' then
         select * into definition from public.work_activity_definition_versions where id=(intent->>'definitionVersionId')::uuid;
         session_id:=gen_random_uuid();frame:=public._work_activity_context_for(actor,'switch',selected_at);
         -- Classic's stage is a bounded display projection (100 characters).
         -- Preserve the complete published label in description and the exact
         -- immutable definition version in private metadata; identity never
         -- depends on this shortened legacy display.
         perform public.custom_work_command(nested_request,'start',jsonb_build_object('id',session_id,'shift_id',h.id,'unit_id',intent#>'{unit,id}',
           'expected_session_id',null,'at',selected_at,'participation','install','stage',left(definition.label_en,100),'description',definition.label_en));
         perform public._work_activity_context_close(frame);
         if intent->>'scope'='specific' then unit_basis:=public._work_activity_command_basis(public._work_activity_unit_basis((intent#>>'{unit,id}')::uuid,actor));end if;
         insert into public.work_session_capture_metadata(session_id,profile_id,project_id,definition_version_id,menu_version_id,scope,unit_id,fact_revision,unit_facts,machine_kind,
           selection_id,selection_revision,answers,unit_basis,continuation_unit_basis)
         values(session_id,actor,(intent->>'projectId')::uuid,definition.id,(intent->>'menuVersionId')::uuid,intent->>'scope',(intent#>>'{unit,id}')::uuid,
           (intent#>>'{unit,factRevision}')::bigint,case when intent->>'scope'='specific' then public._work_activity_fact_snapshot((intent#>>'{unit,id}')::uuid) end,
           intent->>'machineKind',(intent->>'selectionId')::uuid,(intent->>'selectionRevision')::bigint,intent->'values',nullif(intent->'unit','null'::jsonb),unit_basis);
       elsif kind='finish_setup' then
         before_shift:=public._work_activity_evidence('time_shifts',to_jsonb(h));
         after_shift:=before_shift||jsonb_build_object('project_id',intent->'projectId','cost_code_id',intent->'costCodeId');
         frame:=public._work_activity_context_for(actor,'stop',selected_at);
         perform public._work_activity_expect(frame,'public.time_shifts'::regclass,'UPDATE',h.id,array['project_id','cost_code_id'],before_shift,after_shift);
         update public.time_shifts set project_id=(intent->>'projectId')::uuid,cost_code_id=(intent->>'costCodeId')::uuid where id=h.id;
         perform public._work_activity_context_close(frame);
       end if;
       perform public._work_activity_operation_exit(operation);
       select * into after_s from public.personal_activity_state where profile_id=actor;
       if after_s.revision is distinct from s.revision+1 or after_s.last_transition_id is distinct from person.transition_id then
         raise exception using errcode='23514',message='Activity command lacks its one actual transition.';end if;
       v_status:='applied';
     exception when raise_exception then v_status:='refused';reason:='reconciliation_required';selected_at:=null;person.transition_id:=null;
     end;
   end if;
 end if;
 result:=jsonb_build_object('protocolVersion',1,'commandId',p_command_id,'status',v_status,'reasonCode',reason,
   'beforeRevision',s.revision,'afterRevision',case when v_status='applied' then after_s.revision else s.revision end,
   'transitionId',case when v_status='applied' then person.transition_id end,'effectiveAt',case when v_status='applied' then public._work_activity_iso(selected_at) end);
 insert into public.personal_activity_commands(command_id,actor_id,subject_profile_id,protocol_version,normalized_payload,payload_hash,received_at,
   device_id,client_generation,client_sequence,predecessor_command_id,expected_revision,status,reason_code,before_revision,after_revision,transition_id,effective_at,result)
 values(p_command_id,actor,actor,1,payload,hash,arrival,device,generation,sequence_number,predecessor,expected,v_status,reason,s.revision,
   case when v_status='applied' then after_s.revision else s.revision end,case when v_status='applied' then person.transition_id end,case when v_status='applied' then selected_at end,result);
 if kind='establish_stream' and v_status='noop' then
   if stream.id is not null then update public.work_activity_streams set status='retired',retired_at=clock_timestamp() where id=stream.id;end if;
   insert into public.work_activity_streams(actor_id,device_id,client_generation,head_sequence,head_command_id,anchor_observation_id,status)
   values(actor,device,generation,0,p_command_id,obs.id,'active');
 elsif kind<>'establish_stream' and admitted then
   update public.work_activity_streams set head_command_id=p_command_id,head_sequence=sequence_number,status=case when v_status in ('applied','noop') then 'active' else 'blocked' end where id=stream.id;
 end if;
 return jsonb_build_object('protocolVersion',1,'availability','available','receipt',result);
end; $$;
revoke all on function public.work_activity_command(uuid,integer,jsonb) from public,anon;
grant execute on function public.work_activity_command(uuid,integer,jsonb) to authenticated;

-- Any grant/source-visibility revocation followed by restoration fences prior
-- observations and resume contexts. Exhaustion disables starts; a permission
-- revocation itself is never blocked by an exhausted capture counter.
create function public._work_activity_authority_changed() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare before_value jsonb;after_value jsonb;columns text[];
begin
 columns:=case tg_table_name
  when 'profiles' then array['id','role','retired_at','access_revoked_at','is_partner','is_test']
  when 'projects' then array['id','deleted_at','is_test']
  when 'project_openings' then array['id','project_id','removed_at','status']
  when 'custom_work_units' then array['id','created_by','project_id','opening_id']
  when 'sandbox_projects' then array['project_id']
  when 'company_settings' then array['id','paid_time_from_start_day_on']
  when 'toolbox_completions' then array['id','profile_id','signed_at']
  when 'work_job_management_grants' then array['id','project_id','profile_id','capability','revoked_at','revoked_by']
  when 'work_job_menu_selections' then array['id','project_id','revision','menu_version_id']
  when 'work_activity_definitions' then array['id','retired_at']
  when 'work_capture_menus' then array['id','retired_at']
  when 'service_visits' then array['id','project_id','status']
  when 'service_visit_units' then array['id','visit_id','project_id','opening_id','work_unit_id']
 end;
 if columns is null then raise exception using errcode='23514',message='Unsupported activity authority source.';end if;
 if tg_op<>'INSERT' then select jsonb_object_agg(key,value) into before_value from jsonb_each(to_jsonb(old)) where key=any(columns);end if;
 if tg_op<>'DELETE' then select jsonb_object_agg(key,value) into after_value from jsonb_each(to_jsonb(new)) where key=any(columns);end if;
 if before_value is distinct from after_value then
   update public.work_activity_authority_generation set revision=least(revision+1,9007199254740991),
     capture_enabled=capture_enabled and revision<9007199254740990 where singleton;
 end if;
 return null;
end; $$;
revoke all on function public._work_activity_authority_changed() from public,anon,authenticated;

-- A polymorphic return seam evaluates the original result expression before
-- finalizing the root. It is private and never authorizes a source operation.
create function public._work_activity_finish(p_operation uuid,p_value anyelement) returns anyelement
language plpgsql volatile security definer set search_path=public,pg_temp as $$
begin perform public._work_activity_operation_exit(p_operation);return p_value;end; $$;
revoke all on function public._work_activity_finish(uuid,anyelement) from public,anon,authenticated;

-- A corrupt future stored punch cannot manufacture an end or break duration.
-- Keep every original timestamp/total, save the submitted keyed request as a
-- requires_review outcome, and move the existing shift to needs_finish.
create function public._work_activity_clock_review(p_shift_id uuid,p_client_id uuid,p_action text,p_tapped_at timestamptz,p_checked_at timestamptz,p_skew integer)
returns public.time_shifts language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations;h public.time_shifts;
begin
 o:=public._work_activity_operation();
 if o.id is null or o.actor_id is distinct from auth.uid() or auth.uid() is null
   or p_action not in ('clock_out','break_start','break_end') or p_action is null
   or o.route is distinct from (case p_action when 'break_start' then 'start_break' when 'break_end' then 'end_break' else 'clock_out' end) then
   raise exception using errcode='42501',message='Clock review requires its original payroll route.';end if;
 select * into h from public.time_shifts where id=p_shift_id and profile_id=auth.uid() for update;
 if h.id is null then raise exception using errcode='42501',message='Clock review source is unavailable.';end if;
 update public.time_shifts set status='needs_finish' where id=h.id;
 perform public._flag_shift_for_review(h.id,'stored_punch_after_arrival','An existing clock or break time is later than this request reached Forge. The original times and break total were preserved; a foreman must record the actual finish.');
 if p_client_id is not null then
   insert into public.time_clock_actions(client_id,shift_id,profile_id,action,outcome,tapped_at,arrived_at,clock_checked_at,clock_skew_ms,used_tap_time,review_reason)
   values(p_client_id,h.id,h.profile_id,p_action,'requires_review',p_tapped_at,o.arrival_at,p_checked_at,p_skew,false,'stored_punch_after_arrival');
 end if;
 select * into h from public.time_shifts where id=p_shift_id;
 return h;
end; $$;
revoke all on function public._work_activity_clock_review(uuid,uuid,text,timestamptz,timestamptz,integer) from public,anon,authenticated;

-- This is an additive code; none of the existing punch dispositions changes.
alter table public.time_shifts drop constraint if exists time_shifts_review_reason_check;
alter table public.time_shifts add constraint time_shifts_review_reason_check check(review_reason is null or review_reason in (
 'clock_unchecked','clock_off','tap_after_arrival','tap_too_old','tap_out_of_order','overlaps_previous_shift','previous_shift_open','break_end_without_break','stored_punch_after_arrival'));


-- Retain only receipts newly inserted by an actual keyed payroll root. Original
-- time_clock_actions purge semantics stay intact; no history is backfilled.
create table public.work_activity_clock_receipts (
 client_id uuid primary key,profile_id uuid not null,shift_id uuid not null,
 action text not null check(action in ('clock_in','clock_out','break_start','break_end')),
 outcome text not null check(length(outcome) between 1 and 40),tapped_at timestamptz,arrived_at timestamptz not null,
 clock_checked_at timestamptz,clock_skew_ms integer,used_tap_time boolean not null,
 review_reason text check(review_reason is null or length(review_reason)<=80),source_created_at timestamptz not null,
 receipt_protocol text not null check(receipt_protocol in ('legacy','setup_v1')),
 setup_payload_digest text check(setup_payload_digest ~ '^[a-f0-9]{64}$'),
 recorded_at timestamptz not null default clock_timestamp(),
 check((receipt_protocol='setup_v1' and setup_payload_digest is not null and action='clock_in')
    or (receipt_protocol='legacy' and setup_payload_digest is null))
);
alter table public.work_activity_clock_receipts enable row level security;
revoke all on table public.work_activity_clock_receipts from public,anon,authenticated;
create trigger work_activity_clock_receipt_immutable before update or delete on public.work_activity_clock_receipts for each row execute function public.work_capture_immutable_record();

create function public._work_activity_keep_clock_receipt() returns trigger
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations;protocol text;
begin
 o:=public._work_activity_operation();
 -- This is not an importer or backfill. Administrator/direct ledger changes
 -- outside a real keyed payroll root keep their original legacy semantics.
 if o.id is null or o.route<>all(array['clock_in_setup','clock_in','clock_out','start_break','end_break']) then return new;end if;
 if o.actor_id is null or o.actor_id is distinct from new.profile_id or o.request_id is distinct from new.client_id
   or new.action is distinct from (case o.route when 'clock_in_setup' then 'clock_in' when 'start_break' then 'break_start' when 'end_break' then 'break_end' else o.route end) then
   raise exception using errcode='42501',message='The keyed payroll receipt does not belong to its actual root.';
 end if;
 if o.route='clock_in_setup' and not o.clock_entry_claimed then
   raise exception using errcode='42501',message='Paid setup receipt lacks its claimed payroll entry.';
 end if;
 protocol:=case when o.route='clock_in_setup' then 'setup_v1' else 'legacy' end;
 insert into public.work_activity_clock_receipts(client_id,profile_id,shift_id,action,outcome,tapped_at,arrived_at,clock_checked_at,clock_skew_ms,used_tap_time,review_reason,source_created_at,receipt_protocol,setup_payload_digest)
 values(new.client_id,new.profile_id,new.shift_id,new.action,new.outcome,new.tapped_at,new.arrived_at,new.clock_checked_at,new.clock_skew_ms,new.used_tap_time,new.review_reason,new.created_at,protocol,
  case when protocol='setup_v1' then o.arguments->>'clockPayloadDigest' end);
 return new;
end; $$;
revoke all on function public._work_activity_keep_clock_receipt() from public,anon,authenticated;

create function public._work_activity_clock_replay_guard(p_client uuid,p_action text,p_shift uuid default null) returns void
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare r public.work_activity_clock_receipts;o public.work_activity_operations;
begin
 if p_client is null then return;end if;
 o:=public._work_activity_operation();
 if o.id is null or o.actor_id is null or o.actor_id is distinct from auth.uid() then raise exception using errcode='42501',message='Clock receipt unavailable.';end if;
 select * into r from public.work_activity_clock_receipts where client_id=p_client;
 if r.client_id is null then return;end if;
 if r.profile_id is distinct from o.actor_id then raise exception using errcode='42501',message='Clock receipt unavailable.';end if;
 if r.action is distinct from p_action or (p_shift is not null and r.shift_id is distinct from p_shift) then raise exception using errcode='23514',message='Clock command identity conflicts.';end if;
 if o.route='clock_in_setup' and (r.receipt_protocol<>'setup_v1' or r.setup_payload_digest is distinct from o.arguments->>'clockPayloadDigest') then
   raise exception using errcode='23514',message='Clock command identity conflicts.';end if;
 -- A retained acknowledgement survives source deletion. Never reapply the
 -- original command after its mutable/cascading legacy lookup disappeared.
 if not exists(select 1 from public.time_clock_actions where client_id=r.client_id and profile_id=r.profile_id and shift_id=r.shift_id and action=r.action)
    or not exists(select 1 from public.time_shifts where id=r.shift_id and profile_id=r.profile_id) then
   raise exception using errcode='42501',message='Clock receipt unavailable.';
 end if;
end; $$;
revoke all on function public._work_activity_clock_replay_guard(uuid,text,uuid) from public,anon,authenticated;

create function public.work_activity_clock_receipt(p_client_id uuid) returns jsonb
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid;r record;t record;retention text;protocol text;present boolean;
 missing constant jsonb:='{"protocolVersion":1,"availability":"unavailable","receipt":null}'::jsonb;
begin
 perform public._work_activity_read_committed();perform public._work_activity_gate();actor:=public._work_activity_actor();
 if p_client_id is null then raise exception using errcode='23514',message='A clock command identity is required.';end if;
 select x.client_id,x.profile_id,x.shift_id,x.action,x.outcome,x.tapped_at,x.arrived_at,x.clock_checked_at,x.clock_skew_ms,x.used_tap_time,x.review_reason,x.receipt_protocol
 into r from public.work_activity_clock_receipts x where x.client_id=p_client_id and x.profile_id=actor;
 if found then retention:='retained';protocol:=r.receipt_protocol;
 else
  select x.client_id,x.profile_id,x.shift_id,x.action,x.outcome,x.tapped_at,x.arrived_at,x.clock_checked_at,x.clock_skew_ms,x.used_tap_time,x.review_reason,'legacy'::text receipt_protocol
  into r from public.time_clock_actions x where x.client_id=p_client_id and x.profile_id=actor;
  if not found then return missing;end if;retention:='legacy';protocol:='legacy';
 end if;
 -- Unsupported historical evidence remains unavailable rather than coercing
 -- a nonfinite time or an unknown disposition into a truthful completion.
 if (r.review_reason is not null and length(r.review_reason)>80) or not isfinite(r.arrived_at) or (r.tapped_at is not null and not isfinite(r.tapped_at))
   or (r.clock_checked_at is not null and not isfinite(r.clock_checked_at))
   or r.outcome<>all(case r.action when 'clock_in' then array['clocked_in'] when 'clock_out' then array['clocked_out','requires_review']
      when 'break_start' then array['started','already_on_break','requires_review'] when 'break_end' then array['ended','no_break_running','shift_closed','requires_review'] else array[]::text[] end)
 then return missing;end if;
 select x.id,x.revision_before,x.revision_after into t from public.personal_activity_transitions x
 where x.profile_id=actor and x.source_request_id=p_client_id and x.actor_id=actor and x.source_shift_id=r.shift_id;
 present:=exists(select 1 from public.time_shifts where id=r.shift_id and profile_id=actor)
   and exists(select 1 from public.time_clock_actions where client_id=p_client_id and profile_id=actor and shift_id=r.shift_id);
 return jsonb_build_object('protocolVersion',1,'availability','available','receipt',jsonb_build_object(
  'clientId',r.client_id,'action',r.action,'outcome',r.outcome,'shiftId',r.shift_id,'tappedAt',public._work_activity_iso(r.tapped_at),
  'arrivedAt',public._work_activity_iso(r.arrived_at),'clockCheckedAt',public._work_activity_iso(r.clock_checked_at),'clockSkewMs',r.clock_skew_ms,
  'usedTapTime',r.used_tap_time,'reviewReason',r.review_reason,'receiptProtocol',protocol,'retention',retention,'sourcePresent',present,
  'activityTransition',case when t.id is not null then jsonb_build_object('id',t.id,'beforeRevision',t.revision_before,'afterRevision',t.revision_after) else 'null'::jsonb end));
end; $$;
revoke all on function public.work_activity_clock_receipt(uuid) from public,anon;
grant execute on function public.work_activity_clock_receipt(uuid) to authenticated;

-- Protocol admission is proved by the private root, never a client flag/GUC.
-- One exact spelling is shared by the adapter and the existing keyed payroll
-- body. The gate is consumed once, before that body can write a fresh punch.
create function public._work_activity_clock_setup_digest(p_project_id uuid,p_cost_code_id uuid,p_photo text,p_lat double precision,p_lng double precision,
 p_note text,p_mode text,p_client_id uuid,p_tapped_at timestamptz,p_clock_checked_at timestamptz,p_clock_skew_ms integer) returns text
language sql stable set search_path=public,pg_temp as $$
 select encode(sha256(convert_to(jsonb_build_object('projectId',p_project_id,'costCodeId',p_cost_code_id,'photo',p_photo,'lat',p_lat,'lng',p_lng,'note',p_note,'mode',p_mode,'clientId',p_client_id,'tappedAt',public._work_activity_iso(p_tapped_at),'clockCheckedAt',public._work_activity_iso(p_clock_checked_at),'clockSkewMs',p_clock_skew_ms,'setupVersion',1)::text,'UTF8')),'hex')
$$;
revoke all on function public._work_activity_clock_setup_digest(uuid,uuid,text,double precision,double precision,text,text,uuid,timestamptz,timestamptz,integer) from public,anon,authenticated,service_role;

create function public._work_activity_claim_clock_setup(p_project_id uuid,p_cost_code_id uuid,p_photo text,p_lat double precision,p_lng double precision,
 p_note text,p_mode text,p_client_id uuid,p_tapped_at timestamptz,p_clock_checked_at timestamptz,p_clock_skew_ms integer) returns boolean
language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare o public.work_activity_operations;actor uuid;enabled boolean;generation bigint;s public.personal_activity_state;
begin
 o:=public._work_activity_operation();
 -- All retained direct overloads keep their original admission policy.
 if o.id is null or o.route is distinct from 'clock_in_setup' then return false;end if;
 actor:=auth.uid();
 if actor is null or not public._work_config_internal(actor)
  or o.actor_id is distinct from actor or o.top_xid is distinct from pg_current_xact_id() or o.backend_pid is distinct from pg_backend_pid()
  or p_client_id is null or o.request_id is distinct from p_client_id or o.command_id is not null or o.clock_entry_claimed
  or o.arguments is distinct from jsonb_build_object('setupVersion',1,'clockPayloadDigest',public._work_activity_clock_setup_digest(p_project_id,p_cost_code_id,p_photo,p_lat,p_lng,p_note,p_mode,p_client_id,p_tapped_at,p_clock_checked_at,p_clock_skew_ms)) then
   raise exception using errcode='42501',message='Paid setup does not match its original clock entry.';
 end if;
 -- An ordinary caller cannot create this private row, consume this helper,
 -- or relabel a different root. Replays return before reaching this claim.
 update public.work_activity_operations set clock_entry_claimed=true where id=o.id;
 select capture_enabled,revision into enabled,generation from public.work_activity_authority_generation where singleton;
 select * into s from public.personal_activity_state where profile_id=actor;
 -- Closing-only retains existing payroll/replay policy, but cannot grant a
 -- NEW unsigned-start exemption. No setup counter/state is initialized here.
 return coalesce(enabled,false) and generation<9007199254740991
  and (s.profile_id is null or (s.integrity_state='clean' and s.revision<9007199254740991))
  and not exists(select 1 from public.work_activity_safety_events where profile_id=actor);
end; $$;
revoke all on function public._work_activity_claim_clock_setup(uuid,uuid,text,double precision,double precision,text,text,uuid,timestamptz,timestamptz,integer) from public,anon,authenticated,service_role;

-- Explicit protocol opt-in. All twelve arguments are required. Old overloads
-- retain their original meaning; a replay never retroactively creates setup.
create function public.clock_in(
 p_project_id uuid,p_cost_code_id uuid,p_photo text,p_lat double precision,p_lng double precision,
 p_note text,p_mode text,p_client_id uuid,p_tapped_at timestamptz,p_clock_checked_at timestamptz,p_clock_skew_ms integer,p_setup_version integer
) returns public.time_shifts language plpgsql volatile security definer set search_path=public,pg_temp as $$
declare actor uuid;operation uuid;h public.time_shifts;prior boolean;enabled boolean;digest text;
begin
 perform public._work_activity_read_committed();
 perform public._work_activity_gate();actor:=public._work_activity_actor();
 if p_setup_version is distinct from 1 then raise exception using errcode='23514',message='Unsupported paid setup protocol.';end if;
 if p_project_id is not null and not public._ai_job_visible(p_project_id,actor) then raise exception using errcode='42501',message='The clock source is unavailable.';end if;
 if p_client_id is null or p_tapped_at is null or not isfinite(p_tapped_at) or (p_clock_checked_at is not null and not isfinite(p_clock_checked_at)) then
   raise exception using errcode='23514',message='Paid setup requires its original keyed clock stamp.';end if;
 digest:=public._work_activity_clock_setup_digest(p_project_id,p_cost_code_id,p_photo,p_lat,p_lng,p_note,p_mode,p_client_id,p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
 operation:=public._work_activity_operation_enter('clock_in_setup',jsonb_build_object('setupVersion',1,'clockPayloadDigest',digest),p_client_id);
 if operation is null then raise exception using errcode='23514',message='Paid setup requires its original clock root.';end if;
 perform public._work_activity_clock_replay_guard(p_client_id,'clock_in');
 prior:=exists(select 1 from public.time_clock_actions where client_id=p_client_id and profile_id=actor)
   or exists(select 1 from public.time_shifts where client_id=p_client_id and profile_id=actor);
 h:=public.clock_in(p_project_id,p_cost_code_id,p_photo,p_lat,p_lng,p_note,p_mode,p_client_id,p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
 select capture_enabled into enabled from public.work_activity_authority_generation where singleton;
 if not prior and enabled and h.profile_id=actor and h.status='open' and h.clock_out_at is null and h.break_started_at is null
  -- A reviewed/fallback payroll arrival remains paid under the original route,
  -- but cannot resurrect automatic capture from an untrusted/delayed tap.
  and exists(select 1 from public.time_clock_actions where client_id=p_client_id and profile_id=actor and shift_id=h.id and action='clock_in' and outcome='clocked_in' and used_tap_time and review_reason is null) then
   perform public._work_activity_start_setup(h,p_client_id);
 end if;
 perform public._work_activity_operation_exit(operation);
 return h;
end; $$;
revoke all on function public.clock_in(uuid,uuid,text,double precision,double precision,text,text,uuid,timestamptz,timestamptz,integer,integer) from public,anon;
grant execute on function public.clock_in(uuid,uuid,text,double precision,double precision,text,text,uuid,timestamptz,timestamptz,integer,integer) to authenticated;


