$$;
revoke all on function public.person_record_counts(uuid) from public,anon,authenticated;
grant execute on function public.person_record_counts(uuid) to service_role;
create function public._work_activity_profile_delete_guard() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare counts jsonb;
begin
 perform public._work_activity_gate();
 counts:=public.person_record_counts(old.id);
 if counts is null or exists(select 1 from jsonb_each(counts) x where jsonb_typeof(x.value)<>'number' or (x.value::text)::numeric<>0) then
   raise exception using errcode='23514',message='This person has retained work history. Revoke or retire access instead of deleting the account.';
 end if;
 return old;
end; $$;
revoke all on function public._work_activity_profile_delete_guard() from public,anon,authenticated;

-- INSTALLED_ENTRY_ASSEMBLY: exact reviewed bodies with G-first entry seams.
do $activity_entries$
declare item jsonb;definition text;delimiter text;start_at integer;original_acl aclitem[];original_owner oid;function_oid oid;
begin
 for item in select jsonb_build_object('identity',v.identity,'body',v.body,'convertInvokerPayroll',v.convert_invoker,
   'expectedBodySha256',v.old_sha,'newBodySha256',v.new_sha,'name',v.routine_name,'arguments',v.arguments) from (values
-- ENTRY_VALUES_BEGIN
('receive_window(uuid, uuid, text)'::text,$activity_body_0$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_window windows;
begin
  loop
    begin
      insert into windows (window_id, short_code, window_type_id, status, project_id)
      values (issue_window_id(p_type_id), issue_window_short_code(), p_type_id, 'inbound', p_project_id)
      returning * into v_window;
      exit;
    exception when unique_violation then
      null;
    end;
  end loop;

  insert into movements (window_id, event, project_id, actor)
  values (v_window.id, 'received', p_project_id, p_actor);

  return v_window;
end;

end;
$activity_body_0$::text,false,'99eaf8319a73ee54a504d408b3980fa6952348669fc040cf0cf0f92895eacd04'::text,'f16aa8f212c1b9ed40e7e59a19f3efe641d4e459ed280d48536230803a0d17f9'::text,'receive_window'::text,'p_type_id uuid, p_project_id uuid, p_actor text'::text),
('move_window(uuid, uuid, text, text)'::text,$activity_body_1$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_window windows;
  v_zone text;
  v_from uuid;
  v_status text;
  v_event text;
begin
  select zone into v_zone from locations where id = p_location_id;
  if v_zone is null then
    raise exception 'unknown location %', p_location_id;
  end if;

  select location_id into v_from from windows where id = p_window_id;

  v_status := case v_zone
    when 'J' then 'staged'
    when 'D' then 'damaged'
    else 'in_warehouse'
  end;
  v_event := case
    when v_from is null then 'putaway'
    when v_zone = 'J' then 'staged'
    when v_zone = 'D' then 'damaged'
    else 'moved'
  end;

  update windows
  set location_id = p_location_id, status = v_status
  where id = p_window_id
  returning * into v_window;

  insert into movements (window_id, event, from_location_id, to_location_id, actor, reason)
  values (p_window_id, v_event, v_from, p_location_id, p_actor, p_reason);

  return v_window;
end;

end;
$activity_body_1$::text,false,'23255e667139943ddb909cc22bb478b568d739e3e399c179b1a9e9c4cfef8106'::text,'67ca6583a93ee920087b214c10f94337519c53b7ec858266bc3862f929ae4f2c'::text,'move_window'::text,'p_window_id uuid, p_location_id uuid, p_actor text, p_reason text'::text),
('load_window(uuid, text)'::text,$activity_body_2$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_window windows;
  v_from uuid;
  v_status text;
begin
  select location_id, status into v_from, v_status from windows where id = p_window_id;
  if v_status is null then
    raise exception 'unknown window %', p_window_id;
  end if;
  if v_status not in ('in_warehouse', 'staged') then
    raise exception 'unit is not warehouse-ready to load (status %)', v_status;
  end if;

  update windows
  set status = 'loaded', location_id = null
  where id = p_window_id
  returning * into v_window;

  insert into movements (window_id, event, from_location_id, project_id, actor)
  values (p_window_id, 'loaded', v_from, v_window.project_id, p_actor);

  return v_window;
end;

end;
$activity_body_2$::text,false,'1161290269e35931ddbb6da38d7d34330bc0ab2fd201de669ac3664d8c1ec3e5'::text,'388bc3dbf2148713a33b5526ac7f2f22653a90cc968dbd3cd3c3b3e9136d212c'::text,'load_window'::text,'p_window_id uuid, p_actor text'::text),
('install_window(uuid, text)'::text,$activity_body_3$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_window windows;
begin
  update windows
  set status = 'installed', installed_at = now()
  where id = p_window_id
  returning * into v_window;

  insert into movements (window_id, event, project_id, actor)
  values (p_window_id, 'installed', v_window.project_id, p_actor);

  return v_window;
end;

end;
$activity_body_3$::text,false,'6581b8a24eef7dd9fbe7f0e67fe8e00c9c76ed330255a8d3f2b6e49714e5d0b5'::text,'469b833ef40e83c1b27686c88ca428d08c136949eca98cb4c9ad3003a2a5bd3f'::text,'install_window'::text,'p_window_id uuid, p_actor text'::text),
('assign_window_to_opening(uuid, uuid, text)'::text,$activity_body_4$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_opening project_openings;
  v_window windows;
begin
  select * into v_opening from project_openings where id = p_opening_id;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;
  if v_opening.status = 'installed' then
    raise exception 'opening % is already installed', v_opening.opening_code;
  end if;

  select * into v_window from windows where id = p_window_id;
  if v_window is null then
    raise exception 'unknown window %', p_window_id;
  end if;
  if v_window.status = 'installed' then
    raise exception '% is already installed', v_window.window_id;
  end if;
  if v_opening.window_type_id is not null
     and v_window.window_type_id <> v_opening.window_type_id then
    raise exception 'type mismatch: % is not the type planned for opening %',
      v_window.window_id, v_opening.opening_code;
  end if;

  update windows
  set project_id = v_opening.project_id
  where id = v_window.id
    and (project_id is distinct from v_opening.project_id);

  update project_openings
  set assigned_window_id = v_window.id,
      window_type_id = coalesce(window_type_id, v_window.window_type_id),
      status = 'assigned'
  where id = p_opening_id
  returning * into v_opening;

  insert into movements (window_id, event, project_id, actor, reason)
  values (
    v_window.id,
    'assigned',
    v_opening.project_id,
    p_actor,
    'assigned to opening ' || v_opening.opening_code
  );

  return v_opening;
end;

end;
$activity_body_4$::text,false,'a5d33b05bec1e8e72f0cc2d763db0f7f992e390da9b8994ec4b30503d41b76e3'::text,'668fbd6d99a7e9053a15e3fe9c979bb1343f7ebc41b6030de80f6ed5d07f5521'::text,'assign_window_to_opening'::text,'p_opening_id uuid, p_window_id uuid, p_actor text'::text),
