$activity_body_12$::text,false,'d6296509af795129aaf0fe526a19d2173099499740cbd1cc7c0e16cccbd11a45'::text,'ba78bfb9ad2f79e0a2fba680fde0dbffbc66a166d6a6849ce575fc42219dbf63'::text,'submit_install_event'::text,'p_opening_id uuid, p_installer text, p_minutes integer, p_quality_grade integer, p_difficulty text, p_went_well text, p_went_poorly text, p_obstacles text, p_tools_helped text, p_time_vs_estimate text, p_safety_notes text, p_do_again text, p_transcript_raw text, p_started_at timestamp with time zone, p_installer_id uuid, p_estimate_minutes integer'::text),
('pick_golden_install(uuid)'::text,$activity_body_13$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare v_locked boolean; v_golden uuid;
begin
  select golden_locked into v_locked from window_types where id = p_type_id;
  if v_locked then return; end if;

  select e.id into v_golden
  from install_events e
  where e.window_type_id = p_type_id
    and not public.is_test_profile(coalesce(e.credited_to, e.installer_id))
  order by
    coalesce(e.quality_grade, 0) desc,
    (e.transcript_raw is not null) desc,
    (exists (select 1 from attachments a
             where a.install_event_id = e.id and a.kind = 'photo')) desc,
    e.created_at desc
  limit 1;

  update window_types set golden_install_event_id = v_golden where id = p_type_id;
end;

end;
