$activity_body_15$::text,false,'73bc3ac7261f6f126f473f355c8a4cb97d6af93aa2884781854bcca9789da36c'::text,'1ddf1380efaa09d08c1a63441315f596d0ddb15471190bb0f4a821f8120801be'::text,'flag_opening'::text,'p_opening_id uuid, p_note text'::text),
('set_my_pin(text)'::text,$activity_body_16$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_my_pin','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v text := coalesce(trim(p_pin), '');
begin
  if auth.uid() is null then
    raise exception 'sign in before setting a PIN' using errcode = '42501';
  end if;

  -- Empty means "clear my PIN", which the Roster screen offers explicitly.
  if v = '' then
    update public.profiles
       set pin_hash = null, updated_at = now()
     where id = auth.uid();
    perform public._work_activity_operation_exit(__work_activity_root_id); return;
  end if;

  -- Mirrors validateNewPin() in supabase/functions/_shared/pin.ts.
  if length(v) < 4 or length(v) > 10 or v !~ '^[A-Za-z0-9]+$' then
    raise exception 'PIN must be 4-10 letters or numbers' using errcode = '22023';
  end if;

  update public.profiles
     set pin_hash = extensions.crypt(v, extensions.gen_salt('bf', 10)),
         updated_at = now()
   where id = auth.uid();
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_16$::text,false,'e347d8692324f0a88559b11f5d96a6647fcc8923c2b327eedf0174f14e60577d'::text,'6c20b1a10b8350804fddef64575b2025bfe73ad739f20784101d04180929cc9b'::text,'set_my_pin'::text,'p_pin text'::text),
('trg_qc_recompute()'::text,$activity_body_17$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare v_type uuid;
begin
  select window_type_id into v_type from project_openings
  where id = coalesce(new.project_opening_id, old.project_opening_id);
  if v_type is not null then
    perform recompute_window_type_rollups(v_type);
  end if;
  return coalesce(new, old);
end;

end;
$activity_body_17$::text,false,'d045c7ffe9d76ca68942b92164aaa2602702db901584c0baf60652096e133fdf'::text,'4c1638088f3caa3dc166dc47cee8cf92db212dd9e03cf79756db8faf5bfa8804'::text,'trg_qc_recompute'::text,''::text),
('end_break(uuid)'::text,$activity_body_18$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
if current_setting('role') in ('authenticated','anon') and exists(select 1 from public.time_shifts where id=p_shift_id and profile_id=auth.uid() and status='approved') then raise exception 'Use the timecard editor to change approved time.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('end_break','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v public.time_shifts;
begin
 if exists(select 1 from public.time_shifts where id=p_shift_id and profile_id=auth.uid() and clock_out_at is null and status='open' and greatest(clock_in_at,last_punch_at,break_started_at)>__work_activity_arrival) then
   return public._work_activity_finish(__work_activity_root_id,(public._work_activity_clock_review(p_shift_id,null,'break_end',null,null,null))::public.time_shifts);
 end if;

  update public.time_shifts
  set break_seconds = break_seconds
        + greatest(0, extract(epoch from (__work_activity_arrival - break_started_at))::int),
      break_started_at = null,
      break_type = null,
      last_punch_at = __work_activity_arrival
  where id = p_shift_id and profile_id = auth.uid() and break_started_at is not null
  returning * into v;
  if v is null then
    if exists (select 1 from public.time_shifts where id = p_shift_id and profile_id = auth.uid()) then
      raise exception 'We couldn''t find the start of that break, so it wasn''t ended. Your foreman will check your breaks.';
    end if;
    raise exception 'no open shift %', p_shift_id;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_18$::text,true,'6b007126a2c72e254b1932257e30ce0afc7c0e52938bb63b41e059b4e72fb256'::text,'f930e2e95a4d59e547eea6e7ee30135bfe39a13b002c76abfe6f72d1451c1ada'::text,'end_break'::text,'p_shift_id uuid'::text),
('undo_install(uuid, text)'::text,$activity_body_19$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('undo_install','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_caller_role text;
  v_opening project_openings;
  v_voided_id uuid;
begin
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null then
    raise exception 'only a signed-in crew member can undo an install';
  end if;

  -- Foreman+ can undo any install. An installer can UN-SUBMIT only their own:
  -- the latest non-voided event must be theirs and less than 24 hours old.
  -- Older than that, the points may be confirmed and the record settled - a
  -- foreman makes that call.
  -- The check is on the LATEST non-voided event (the one this undo voids),
  -- not "any event of mine": undoing over someone else's later re-install
  -- must stay a foreman call.
  if v_caller_role = 'installer' then
    if not exists (
      select 1 from (
        select installer_id, created_at
        from install_events
        where project_opening_id = p_opening_id
          and voided_at is null
        order by created_at desc
        limit 1
      ) latest
      where latest.installer_id = auth.uid()
        and latest.created_at > now() - interval '24 hours'
    ) then
      raise exception 'you can only un-submit your own install within 24 hours; ask a foreman otherwise';
    end if;
  end if;

  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required to undo an install';
  end if;

  select * into v_opening from project_openings where id = p_opening_id;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  -- Void (never delete) the most recent non-voided install event, remembering
  -- whether we actually voided one.
  update install_events
  set voided_at = now(),
      voided_by = auth.uid(),
      void_reason = btrim(p_reason)
  where id = (
    select id from install_events
    where project_opening_id = p_opening_id
      and voided_at is null
    order by created_at desc
    limit 1
  )
  returning id into v_voided_id;

  -- Revert the opening to its pre-install state. Clear BOTH work_started_at and
  -- work_ended_at so the phantom "in progress" and any elapsed task-time clear.
  update project_openings
  set status = case when assigned_window_id is not null then 'assigned' else 'planned' end,
      confirmed = false,
      work_started_at = null,
      work_ended_at = null
  where id = p_opening_id;

  -- Stop task-time: close any still-open session tied to this opening.
  update task_sessions
  set ended_at = now()
  where opening_id = p_opening_id and ended_at is null;

  -- Return the physical unit to the truck. Only append the reverse movement when
  -- an install event was actually voided (guards a spurious repeat undo).
  if v_opening.assigned_window_id is not null then
    update windows
    set status = 'loaded', installed_at = null
    where id = v_opening.assigned_window_id;

    if v_voided_id is not null then
      insert into movements (window_id, event, project_id, actor, reason)
      values (
        v_opening.assigned_window_id,
        'uninstalled',
        v_opening.project_id,
        auth.uid()::text,
        btrim(p_reason)
      );
    end if;
  end if;

  -- Void any points earned for this install (ref stores the opening UUID as text).
  update points_ledger
  set status = 'void'
  where ref = p_opening_id::text
    and status in ('pending', 'confirmed');

  -- Open a failed-install issue (deduped on an open one for this opening).
  if not exists (
    select 1 from issues
    where opening_id = p_opening_id and kind = 'failed_install' and status = 'open'
  ) then
    insert into issues (project_id, opening_id, kind, urgency, note, created_by)
    values (v_opening.project_id, p_opening_id, 'failed_install', 'urgent', btrim(p_reason), auth.uid());
  end if;

  -- Refresh learned rollups for this type (best-effort; skip if absent).
  if v_opening.window_type_id is not null then
    begin
      perform recompute_window_type_rollups(v_opening.window_type_id);
    exception when undefined_function then
      null;
    end;
  end if;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_19$::text,false,'66c5de18ec77be26c35aa14c44a3999c395c3e33b4302487b4aacfb9e87ead1d'::text,'0053149e8ad901d1e341863d2ca5d3e5a6269298aa5333544ae2506caef8d186'::text,'undo_install'::text,'p_opening_id uuid, p_reason text'::text),
