$activity_body_24$::text,false,'b35578374596ae42785ea44af82891fc4e9d72227f07b37c0533a81b8c948742'::text,'45d871827f1f23d4753ad9b626a4a034bba640f07f5bb0e01f5033401a04ae50'::text,'start_off_task'::text,'p_project uuid'::text),
('preissue_project_units(uuid)'::text,$activity_body_25$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('preissue_project_units','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_caller_role text;
  v_need record;
  v_existing int;
  v_to_create int;
  i int;
  v_window windows;
begin
  -- Guard: only a foreman-level user or above may pre-issue. Only a plain
  -- installer is explicitly blocked, so this holds for both legacy role names
  -- (lead/foreman/admin/big_boss) and any new role above installer.
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can pre-issue unit IDs';
  end if;

  for v_need in
    select window_type_id, quantity
    from project_windows
    where project_id = p_project_id
  loop
    -- Count units that already exist for this (project, type) in ANY status so
    -- re-running never exceeds the planned quantity.
    select count(*) into v_existing
    from windows
    where project_id = p_project_id
      and window_type_id = v_need.window_type_id;

    v_to_create := v_need.quantity - v_existing;

    if v_to_create > 0 then
      for i in 1..v_to_create loop
        -- Retry on the rare short_code unique collision.
        loop
          begin
            insert into windows (
              window_id, short_code, window_type_id, status, project_id, location_id
            )
            values (
              issue_window_id(v_need.window_type_id),
              issue_window_short_code(),
              v_need.window_type_id,
              'pre_issued',
              p_project_id,
              null
            )
            returning * into v_window;
            exit;
          exception when unique_violation then
            -- extremely rare short_code collision; try again
          end;
        end loop;

        insert into movements (window_id, event, project_id, actor)
        values (v_window.id, 'preissued', p_project_id, auth.uid()::text);

        return next v_window;
      end loop;
    end if;
  end loop;

  perform public._work_activity_operation_exit(__work_activity_root_id); return;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_25$::text,false,'038a01f6d6af3304d42f3f438f4113fcbf1d590266e7c03f22fdb8de01bd065d'::text,'716bbb8f5edebf0a6758b2bced8307456562691cb5b30f31a490be7d27c2bd34'::text,'preissue_project_units'::text,'p_project_id uuid'::text),
('clock_in(uuid, uuid, text, double precision, double precision)'::text,$activity_body_26$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('clock_in','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_shift time_shifts;
begin
  if not public._toolbox_gate_open(auth.uid()) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  if exists(select 1 from public.time_shifts where profile_id=auth.uid() and status<>'voided' and greatest(clock_in_at,clock_out_at,last_punch_at,break_started_at)>__work_activity_arrival) then raise exception 'Existing clock times need foreman review before a new shift can start.';end if;
  perform _close_dangling_shift(auth.uid());

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng, clock_in_at, last_punch_at)
  values (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng, __work_activity_arrival, __work_activity_arrival)
  returning * into v_shift;
  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_26$::text,true,'6503402b2d140b967019f6137afe423969855e7012aa683ee93bad758031b4a1'::text,'c062f0c38a76f236bd2e4e459b2cdb39b99547865599717261334092d18d01e8'::text,'clock_in'::text,'p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision'::text),
('start_break(uuid, text)'::text,$activity_body_27$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('start_break','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v public.time_shifts;
begin
 if exists(select 1 from public.time_shifts where id=p_shift_id and profile_id=auth.uid() and clock_out_at is null and status='open' and greatest(clock_in_at,last_punch_at,break_started_at)>__work_activity_arrival) then
   return public._work_activity_finish(__work_activity_root_id,(public._work_activity_clock_review(p_shift_id,null,'break_start',null,null,null))::public.time_shifts);
 end if;

  update public.time_shifts
  set break_started_at = coalesce(break_started_at, __work_activity_arrival),
      break_type = coalesce(break_type, p_break_type),
      last_punch_at = case when break_started_at is null then __work_activity_arrival else last_punch_at end
  where id = p_shift_id and profile_id = auth.uid()
    and status = 'open' and clock_out_at is null
  returning * into v;
  if v is null then
    if exists (select 1 from public.time_shifts where id = p_shift_id and profile_id = auth.uid()) then
      raise exception 'This shift is already clocked out, so a break can''t start on it.';
    end if;
    raise exception 'no open shift %', p_shift_id;
  end if;

  update public.opening_phases
     set paused_at = coalesce(paused_at, __work_activity_arrival)
   where status = 'active' and started_by = auth.uid();

  return public._work_activity_finish(__work_activity_root_id,(v)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_27$::text,true,'22e89428eca668880c9cf14693ef9f9acec7db17fd08f3e250009658c14c7ab5'::text,'4f12f25fc5d7060f59ad7cbe9d717c6a23de4a6ba860301200815063a1d24b06'::text,'start_break'::text,'p_shift_id uuid, p_break_type text'::text),
('activate_preissued_unit(text, uuid, boolean, text)'::text,$activity_body_28$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('activate_preissued_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_caller_role text;
  v_unit windows;
  v_new_status text;
begin
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can receive against the plan';
  end if;

  select * into v_unit from find_window_by_code(p_code);
  if v_unit.id is null then
    raise exception 'unknown code % — no unit matches that code or serial', p_code;
  end if;
  if v_unit.status <> 'pre_issued' then
    raise exception
      'window % is not awaiting delivery (status %) — it may already be received',
      v_unit.window_id, v_unit.status;
  end if;

  v_new_status := case when p_damaged then 'damaged' else 'in_warehouse' end;

  update windows
  set status = v_new_status,
      location_id = coalesce(p_location_id, location_id),
      received_at = now()
  where id = v_unit.id
  returning * into v_unit;

  insert into movements (window_id, event, to_location_id, project_id, actor, reason)
  values (
    v_unit.id,
    'received',
    p_location_id,
    v_unit.project_id,
    coalesce(p_actor, auth.uid()::text),
    case when p_damaged then 'received damaged on arrival' else null end
  );

  if p_damaged then
    if not exists (
      select 1 from issues
      where kind = 'damage' and status = 'open'
        and (
          window_id = v_unit.id
          or opening_id = (
            select id from project_openings
            where assigned_window_id = v_unit.id
            limit 1
          )
        )
    ) then
      insert into issues (project_id, opening_id, window_id, kind, urgency, note, created_by)
      values (v_unit.project_id, null, v_unit.id, 'damage', 'urgent',
              'damaged on arrival', auth.uid());
    end if;
  else
    update issues
    set status = 'resolved', resolved_at = now(), resolved_by = auth.uid()
    where window_id = v_unit.id and kind = 'missing' and status = 'open';
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_unit)::windows);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_28$::text,false,'791f2a02763b7fba07eb7c79fecab7701d9e04e88d18606dd75087630a75e928'::text,'bdbb0e2cfe1f905b9256853352f79a9434773597a217a2cdc68b0bf3e0beb1a3'::text,'activate_preissued_unit'::text,'p_code text, p_location_id uuid, p_damaged boolean, p_actor text'::text),
('reconcile_project_deliveries(uuid)'::text,$activity_body_29$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('reconcile_project_deliveries','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_caller_role text;
  v_unit windows;
  v_issue issues;
begin
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can reconcile deliveries';
  end if;

  for v_unit in
    select * from windows
    where project_id = p_project_id and status = 'pre_issued'
  loop
    if not exists (
      select 1 from issues
      where window_id = v_unit.id and kind = 'missing' and status = 'open'
    ) then
      insert into issues (project_id, opening_id, window_id, kind, urgency, note, created_by)
      values (
        p_project_id, null, v_unit.id, 'missing', 'urgent',
        'delivery missing: ' || v_unit.window_id ||
          coalesce(' (' || v_unit.short_code || ')', ''),
        auth.uid()
      )
      returning * into v_issue;
      return next v_issue;
    end if;
  end loop;

  perform public._work_activity_operation_exit(__work_activity_root_id); return;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_29$::text,false,'c60ebe797f1d98a0bed0f3becbe281e099c8c0c4546086dac366deaf754908cf'::text,'4264cf7d2dd80a5e16a69f96c63b0c2e9380ce17422a820103cb7f21aef7d608'::text,'reconcile_project_deliveries'::text,'p_project_id uuid'::text),
('load_units(uuid[], uuid, text)'::text,$activity_body_30$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('load_units','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_id uuid;
  v_from uuid;
  v_window windows;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can load units for a run';
  end if;

  foreach v_id in array coalesce(p_window_ids, array[]::uuid[])
  loop
    -- Only load a unit that belongs to this job and is warehouse-ready.
    select location_id into v_from
    from windows
    where id = v_id
      and project_id = p_project_id
      and status in ('in_warehouse', 'staged');
    if not found then
      continue;
    end if;

    update windows
    set status = 'loaded', location_id = null
    where id = v_id
    returning * into v_window;

    insert into movements (window_id, event, from_location_id, project_id, actor)
    values (v_id, 'loaded', v_from, p_project_id, coalesce(p_actor, auth.uid()::text));

    return next v_window;
  end loop;

  perform public._work_activity_operation_exit(__work_activity_root_id); return;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_30$::text,false,'195e994e94d32f50374e2bd1d989f59eb8ea7410770dabcd58ab696fa472986a'::text,'9abb5c277da52bad02e4af0370426f8528a69f00643f80e3043cb88cc6113a60'::text,'load_units'::text,'p_window_ids uuid[], p_project_id uuid, p_actor text'::text),
('unload_units(uuid[], uuid[], uuid, text, text)'::text,$activity_body_31$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('unload_units','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_id uuid;
  v_actor text;
  v_note text;
  v_unloaded int := 0;
  v_damaged int := 0;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can unload a run';
  end if;

  v_actor := coalesce(p_actor, auth.uid()::text);
  v_note := nullif(trim(coalesce(p_location_note, '')), '');

  foreach v_id in array coalesce(p_ok_ids, array[]::uuid[])
  loop
    update windows
    set status = 'on_site'
    where id = v_id and project_id = p_project_id and status = 'loaded';
    if found then
      insert into movements (window_id, event, project_id, actor, reason)
      values (
        v_id, 'unloaded', p_project_id, v_actor,
        'unloaded on site' ||
          case when v_note is not null then ' — ' || v_note else '' end
      );
      v_unloaded := v_unloaded + 1;
    end if;
  end loop;

  foreach v_id in array coalesce(p_damaged_ids, array[]::uuid[])
  loop
    update windows
    set status = 'damaged'
    where id = v_id and project_id = p_project_id and status = 'loaded';
    if found then
      insert into movements (window_id, event, project_id, actor, reason)
      values (v_id, 'unloaded', p_project_id, v_actor, 'damaged in transit/unload');

      if not exists (
        select 1 from issues
        where kind = 'damage' and status = 'open'
          and (
            window_id = v_id
            or opening_id = (
              select id from project_openings
              where assigned_window_id = v_id
              limit 1
            )
          )
      ) then
        insert into issues (project_id, opening_id, window_id, kind, urgency, note, created_by)
        values (p_project_id, null, v_id, 'damage', 'urgent',
                'damaged in transit/unload', auth.uid());
      end if;
      v_damaged := v_damaged + 1;
    end if;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('unloaded', v_unloaded, 'damaged', v_damaged))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_31$::text,false,'725d8d56b58255fd015da781f65272ca9c96e86b67ff64c2966ad876becdf2c7'::text,'27f0e4d0fa2c23304f1896a1b40179fb204a77fba7cf0769d0847eda7518e530'::text,'unload_units'::text,'p_ok_ids uuid[], p_damaged_ids uuid[], p_project_id uuid, p_location_note text, p_actor text'::text),
('open_service_case(uuid, text, text, text)'::text,$activity_body_32$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('open_service_case','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_window windows;
  v_event install_events;
  v_case service_cases;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can open a service case';
  end if;

  select * into v_window from windows where id = p_window_id;
  if v_window is null then
    raise exception 'unknown window %', p_window_id;
  end if;

  -- Idempotent: one open case per unit. Return the existing open case if any.
  select * into v_case
  from service_cases
  where window_id = p_window_id and status = 'open'
  order by created_at desc
  limit 1;
  if v_case.id is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_case)::service_cases);
  end if;

  -- Latest non-voided install event for this unit gives us the opening,
  -- installer, and the exact event the failure traces back to.
  select * into v_event
  from install_events
  where window_id = p_window_id and voided_at is null
  order by created_at desc
  limit 1;

  insert into service_cases (
    window_id, install_event_id, project_id, opening_id, window_type_id,
    installer_id, status, reason, fail_point, description, reported_by
  ) values (
    p_window_id,
    v_event.id,
    v_window.project_id,
    v_event.project_opening_id,
    v_window.window_type_id,
    coalesce(v_event.credited_to, v_event.installer_id),
    'open',
    p_reason,
    p_fail_point,
    p_description,
    auth.uid()
  )
  returning * into v_case;

  return public._work_activity_finish(__work_activity_root_id,(v_case)::service_cases);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_32$::text,false,'ec9b3be406f9477c14fc7e279f9a1dee7f0f668b49c3d44f6d930adbe43826e3'::text,'b417e91670fd4bc29b4c104773697eff77f59c5e9eb31552a89015aed12af7b9'::text,'open_service_case'::text,'p_window_id uuid, p_reason text, p_fail_point text, p_description text'::text),
