('clock_in(uuid, uuid, text, double precision, double precision, uuid)'::text,$activity_body_39$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('clock_in','{}'::jsonb,p_client_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 perform public._work_activity_clock_replay_guard(p_client_id,'clock_in',null);

declare v_shift time_shifts;
begin
  if p_client_id is not null then
    select * into v_shift from time_shifts
      where client_id = p_client_id and profile_id = auth.uid();
    if v_shift.id is not null then
      return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
    end if;
  end if;

  if not public._toolbox_gate_open(auth.uid()) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

