declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('undo_opening_pin_move','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_move project_opening_pin_moves;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can undo a mark move';
  end if;

  select * into v_move from project_opening_pin_moves where id = p_move_id;
  if v_move.id is null then
    raise exception 'That move is no longer on record';
  end if;
  if v_move.undone_at is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_move)::project_opening_pin_moves);
  end if;

  perform set_config('app.pin_undo', 'on', true);
  update project_openings
  set pin_x = v_move.from_pin_x,
      pin_y = v_move.from_pin_y,
      page_number = coalesce(v_move.from_page_number, page_number)
  where id = v_move.opening_id;
  perform set_config('app.pin_undo', 'off', true);

  update project_opening_pin_moves
  set undone_at = now(),
      undone_by = auth.uid()
  where id = p_move_id
  returning * into v_move;

  return public._work_activity_finish(__work_activity_root_id,(v_move)::project_opening_pin_moves);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_51$::text,false,'ac5651a91456eaa76d7ac8fc3f40b0bd753a8317c90664afa176edfd8fbd3277'::text,'61722603d0b033a33eba7a03d63318fba468d03dfb5131e4c1f18ee5a8bb0a12'::text,'undo_opening_pin_move'::text,'p_move_id uuid'::text),
