begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('reset_project_pins_to_extracted','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_count integer;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can reset a job''s marks';
  end if;

  perform set_config('app.pin_undo', 'on', true);
  with restored as (
    update project_openings
    set pin_x = origin_pin_x,
        pin_y = origin_pin_y,
        page_number = coalesce(origin_page_number, page_number)
    where project_id = p_project_id
      and origin_pin_x is not null
      and pin_x is not null
      and (pin_x <> origin_pin_x or pin_y <> origin_pin_y)
    returning 1
  )
  select count(*) into v_count from restored;
  perform set_config('app.pin_undo', 'off', true);

  update project_opening_pin_moves
  set undone_at = now(),
      undone_by = auth.uid()
  where project_id = p_project_id
    and undone_at is null;

  return public._work_activity_finish(__work_activity_root_id,(v_count)::integer);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
