$activity_body_53$::text,false,'ecc51fc775abbbada34e84d8b80addfb792204e8e4a04965f2a735279412769f'::text,'e2ac98fc75ecb346d1af7aece89655896a426cda9ca3ac548c44b2d206cfbf86'::text,'reset_opening_pin_to_extracted'::text,'p_opening_id uuid'::text),
('remove_opening(uuid, text)'::text,$activity_body_54$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('remove_opening','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row project_openings;
begin
  -- Byte-identical to the sentence the create/delete guard raises, so the app
  -- shows one wording for "you may not remove a window" however it is reached.
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can remove a window or door from a job.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;

  -- Already hidden. Replaying this is a no-op rather than an error, so a second
  -- tap or a retried request cannot turn into a scary red message.
  if v_row.removed_at is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
  end if;

  if v_row.status = 'installed' then
    raise exception 'That window or door is already installed, so it can''t be removed. Undo the install first.'
      using errcode = '42501';
  end if;

  -- A removed opening must not go on holding a physical unit: the warehouse
  -- would have it reserved for something nobody can see, and the damage-issue
  -- dedup in unload_units/activate_preissued_unit finds an opening BY its
  -- assigned unit. Refusing here keeps both correct without touching either.
  if v_row.assigned_window_id is not null then
    raise exception 'That window or door has a unit from the warehouse against it. Take the unit off it first.'
      using errcode = '42501';
  end if;

  perform set_config('app.opening_removal', 'on', true);
  update project_openings
     set removed_at = now(),
         removed_by = auth.uid(),
         removed_reason = nullif(trim(coalesce(p_reason, '')), '')
   where id = p_opening_id
   returning * into v_row;
  perform set_config('app.opening_removal', 'off', true);

  return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_54$::text,false,'a97a56e94f2a221b15911402e76593bcb806539a2e3db32b2610c0e1d8a691a4'::text,'9f018c5507d9dde0d9fef0e90008a9c1f888380f350513835f980b5f51b42ad0'::text,'remove_opening'::text,'p_opening_id uuid, p_reason text'::text),
('restore_opening(uuid)'::text,$activity_body_55$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('restore_opening','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row project_openings;
  v_clash text;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can put a window or door back on a job.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;

  if v_row.removed_at is null then
    return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
  end if;

  -- Somebody added the code back, or a re-extract found it on the plan again.
  -- The live one wins; this one stays hidden and the foreman is told why in the
  -- words they would use themselves.
  select opening_code into v_clash
    from project_openings
   where project_id = v_row.project_id
     and opening_code = v_row.opening_code
     and removed_at is null
   limit 1;
  if v_clash is not null then
    raise exception 'There is already a #% on this job, so this one cannot come back under that name. Remove or rename the one that is there first.', v_clash
      using errcode = '23505';
  end if;

  perform set_config('app.opening_removal', 'on', true);
  update project_openings
     set removed_at = null,
         removed_by = null,
         removed_reason = null
   where id = p_opening_id
   returning * into v_row;
  perform set_config('app.opening_removal', 'off', true);

  return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_55$::text,false,'3c9d2d883a2d6450cb9e649946fe702596496436709b54092d142a17ca31d3aa'::text,'bf01e293099fd8289838ed04caa2d4f4eec9d2402a496518cfc1e901726e54a0'::text,'restore_opening'::text,'p_opening_id uuid'::text),
('_close_dangling_shift(uuid)'::text,$activity_body_56$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_close_dangling_shift','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 if auth.uid() is not null and p_profile is distinct from auth.uid() and (public._work_activity_operation()).route<>'clock_in_for' then raise exception using errcode='42501',message='This legacy timing helper is available only for your own activity.';end if;

declare v_cap interval := make_interval(hours => shift_cap_hours());
begin
 if exists(select 1 from public.time_shifts where profile_id=p_profile and status='open' and clock_out_at is null and greatest(clock_in_at,last_punch_at,break_started_at)>__work_activity_arrival) then raise exception 'Existing clock times need foreman review before a new shift can start.';end if;

  -- Believable: a forgotten punch inside the day, or a job/phase switch. The
  -- elapsed time is still evidence, so close it exactly as before — now
  -- also naming WHY, so this row never reads as a punch the person closed
  -- themselves.
  update time_shifts
     set clock_out_at = __work_activity_arrival,
         status = 'submitted',
         closed_reason = 'auto-closed by next clock-in'
   where profile_id = p_profile
     and status = 'open'
     and clock_out_at is null
     and __work_activity_arrival - clock_in_at <= v_cap;

  -- Not believable. Refuse to name a finish time; say so on the row instead.
  update time_shifts
     set status = 'needs_finish',
         break_started_at = null,
         break_type = null,
         edited_note = left(
           coalesce(edited_note || ' | ', '') ||
           'Ran past ' || shift_cap_hours() || 'h without a clock-out, so the app '
           || 'stopped counting instead of guessing an end time. Needs the real '
           || 'finish time from the crew member or the office.',
           2000)
   where profile_id = p_profile
     and status = 'open'
     and clock_out_at is null
     and __work_activity_arrival - clock_in_at > v_cap;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_56$::text,false,'43a1d739ef5e6a0739fa4b50d3e540707dd911f0a3f4d3f237f3b738a3a20477'::text,'0fbad26efe7f7b7e9fedf62b0efd5e01391c81bb67e9382257ec8d69b2877a91'::text,'_close_dangling_shift'::text,'p_profile uuid'::text),
('finish_shift_at(uuid, timestamp with time zone, boolean, integer)'::text,$activity_body_57$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('finish_shift_at','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_shift time_shifts;
  v_lead boolean := _is_lead(auth.uid());
begin
  select * into v_shift from time_shifts where id = p_shift_id;
  if v_shift.id is null then
    raise exception 'no shift %', p_shift_id;
  end if;
  if v_shift.profile_id <> auth.uid() and not v_lead then
    raise exception 'that is not your shift';
  end if;
  if v_shift.clock_out_at is not null then
    raise exception 'that shift already has a finish time';
  end if;
  if p_clock_out_at is null then
    raise exception 'a finish time is required';
  end if;
  if p_clock_out_at <= v_shift.clock_in_at then
    raise exception 'the finish time must be after the clock-in time';
  end if;
  -- Two minutes of tolerance for a phone whose clock runs fast. Anything
  -- further ahead would be recording work that has not happened yet.
  if p_clock_out_at > now() + interval '2 minutes' then
    raise exception 'the finish time cannot be in the future';
  end if;

  update time_shifts
     set clock_out_at = p_clock_out_at,
         injured = coalesce(p_injured, injured),
         break_seconds = coalesce(p_break_seconds, break_seconds),
         break_started_at = null,
         break_type = null,
         time_confirmed = true,
         signed_at = now(),
         status = 'submitted',
         edited_by = auth.uid(),
         edited_at = now(),
         edited_note = left(
           coalesce(edited_note || ' | ', '') ||
           'Finish time entered by hand because the shift ran past '
           || shift_cap_hours() || 'h and the app would not guess one.',
           2000)
   where id = p_shift_id
  returning * into v_shift;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_57$::text,false,'496b9f8a4db452c44d87aedd77cef714901fc3351c94a091d4ee8ea71802ea98'::text,'6a1ff32ebf97dcdb31cdd03e6bbc37d4afa0f2e765dad0a249cec6d214d5b8c6'::text,'finish_shift_at'::text,'p_shift_id uuid, p_clock_out_at timestamp with time zone, p_injured boolean, p_break_seconds integer'::text),
('close_shift_as_no_work(uuid, text)'::text,$activity_body_58$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('close_shift_as_no_work','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_shift time_shifts;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can write a shift off to zero';
  end if;

  select * into v_shift from time_shifts where id = p_shift_id;
  if v_shift.id is null then
    raise exception 'no shift %', p_shift_id;
  end if;
  if v_shift.clock_out_at is not null then
    raise exception 'that shift is already closed';
  end if;

  update time_shifts
     set clock_out_at  = clock_in_at,
         break_seconds = 0,
         break_started_at = null,
         break_type    = null,
         -- The worker never signed off on this, a supervisor decided it.
         time_confirmed = false,
         injured       = coalesce(injured, false),
         signed_at     = now(),
         status        = 'approved',
         edited_by     = auth.uid(),
         edited_at     = now(),
         approved_by   = auth.uid(),
         approved_at   = now(),
         edited_note   = left(
           coalesce(edited_note || ' | ', '') ||
           'Recorded as zero hours — no work was done on this punch.' ||
           coalesce(' Reason: ' || nullif(btrim(p_reason), ''), ''),
           2000)
   where id = p_shift_id
  returning * into v_shift;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_58$::text,false,'d1e5f257ec4512dba6486ba77720b853cfa0bd133de92dbec6521933f7392f86'::text,'b3b6790de9ed9e795f02798f2ada9310a3bad21a069c35265a20700bda26c3e9'::text,'close_shift_as_no_work'::text,'p_shift_id uuid, p_reason text'::text),
('start_opening_phase(uuid, text)'::text,$activity_body_59$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('start_opening_phase','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_phase opening_phases;
begin
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before starting a task';
  end if;
  perform public._unit_work_gate(v_uid);

  insert into opening_phases (opening_id, kind, started_by)
  values (p_opening_id, p_kind, v_uid)
  on conflict (opening_id, kind) do update
    -- Re-starting an unfinished phase is fine (a second person joining, or a
    -- resume); a submitted phase stays submitted.
    set started_by = coalesce(opening_phases.started_by, excluded.started_by)
  returning * into v_phase;

  if v_phase.status = 'submitted' then
    raise exception 'this % is already submitted', p_kind;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_phase)::opening_phases);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_59$::text,false,'85e1a758ba4b3323d0272f4f9faafe1cebeee101f06fcd19dc5696117bee08a7'::text,'bfef4d9ab759d5b385108e36934698c6630bc9dd4e3009cd5a08dd15b8ccccfb'::text,'start_opening_phase'::text,'p_opening_id uuid, p_kind text'::text),
('submit_opening_phase(uuid, text, text)'::text,$activity_body_60$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('submit_opening_phase','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_phase opening_phases;
begin
  if p_photo_path is null or btrim(p_photo_path) = '' then
    raise exception 'a finished-work photo is required to submit %', p_kind;
  end if;

  update opening_phases
     set status = 'submitted',
         submitted_at = now(),
         submitted_by = v_uid,
         photo_path = p_photo_path,
         minutes = least(
           greatest(0,
             floor((
               extract(epoch from now() - started_at)
               - paused_seconds
               - coalesce(extract(epoch from now() - paused_at), 0)
             ) / 60)::int
           ),
           install_timer_cap_minutes()
         ),
         paused_at = null
   where opening_id = p_opening_id and kind = p_kind and status = 'active'
   returning * into v_phase;

  if v_phase is null then
    raise exception 'no active % to submit on this opening', p_kind;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_phase)::opening_phases);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_60$::text,false,'d540a99e3e234a22e40d08856f59c3dc151767c10ede2d614f002c78feb85e0a'::text,'dd6699cbf76a99f9b1fa51fba835c4f5c69dfea0d3412201a6d9e159cd339852'::text,'submit_opening_phase'::text,'p_opening_id uuid, p_kind text, p_photo_path text'::text),
('set_opening_needs_flashing(uuid, boolean)'::text,$activity_body_61$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_opening_needs_flashing','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_opening project_openings;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can change flashing requirements';
  end if;
  update project_openings set needs_flashing = p_needs
  where id = p_opening_id returning * into v_opening;
  if v_opening is null then raise exception 'unknown opening %', p_opening_id; end if;
  return public._work_activity_finish(__work_activity_root_id,(v_opening)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_61$::text,false,'fb11061192e550f0a3cb08fc1d393cd77226e90f3626db911380b7a732cf04e3'::text,'502582d58f4953dab884200efda3f4384ae903d60c9d65d05e431f8d9623cc03'::text,'set_opening_needs_flashing'::text,'p_opening_id uuid, p_needs boolean'::text),
('set_project_needs_flashing(uuid, boolean)'::text,$activity_body_62$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_project_needs_flashing','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_count int;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can change flashing requirements';
  end if;
  update project_openings set needs_flashing = p_needs
  where project_id = p_project_id and needs_flashing is distinct from p_needs;
  get diagnostics v_count = row_count;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_62$::text,false,'90d738ae796ed3aaeb8556dbd05548e89aa33d58f3d3ba7df4fa71d98da081cd'::text,'74f7f18e1ae5c1848af74c3b0521f3fe1091b70fc2c8b0d673253adab6d1214e'::text,'set_project_needs_flashing'::text,'p_project_id uuid, p_needs boolean'::text),
('pause_opening_phase(uuid, text)'::text,$activity_body_63$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('pause_opening_phase','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v opening_phases;
begin
  update opening_phases
     set paused_at = coalesce(paused_at, now())
   where opening_id = p_opening_id and kind = p_kind and status = 'active'
   returning * into v;
  if v is null then raise exception 'no active % on this opening', p_kind; end if;
  return public._work_activity_finish(__work_activity_root_id,(v)::opening_phases);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_63$::text,false,'dcbae698473765e81e601ddae738926548d8c29a50d1344ea4b215f4fc44609e'::text,'28aaa3e35e5701e2fd9112d8221dec22b9768dc45dbc6234e2c0cddb3d7aec2f'::text,'pause_opening_phase'::text,'p_opening_id uuid, p_kind text'::text),
('resume_opening_phase(uuid, text)'::text,$activity_body_64$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('resume_opening_phase','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v opening_phases;
begin
  -- A phase paused yesterday must not run today on an unsigned talk: for the
  -- signature's purposes, resuming is starting. (This RPC never checked the
  -- shift; that is unchanged.)
  perform public._unit_work_gate(auth.uid());
  update opening_phases
     set paused_seconds = paused_seconds
           + greatest(0, extract(epoch from (now() - paused_at))::int),
         paused_at = null
   where opening_id = p_opening_id and kind = p_kind
     and status = 'active' and paused_at is not null
   returning * into v;
  if v is null then
    -- Already running (or never paused) — return the row as it stands.
    select * into v from opening_phases
    where opening_id = p_opening_id and kind = p_kind and status = 'active';
    if v is null then raise exception 'no active % on this opening', p_kind; end if;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v)::opening_phases);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
