declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('lead_void_shift','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_old time_shifts;
  v_shift time_shifts;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a lead-level user can delete crew time';
  end if;
  if p_note is null or btrim(p_note) = '' then
    raise exception 'deleting a punch needs a reason note';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status = 'voided' then
    raise exception 'this punch is already deleted';
  end if;

  update time_shifts
     set status      = 'voided',
         edited_note = btrim(p_note),
         edited_by   = auth.uid(),
         edited_at   = now(),
         approved_by = null,
         approved_at = null
   where id = p_shift_id
   returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', v_old.status, 'voided', btrim(p_note));

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_67$::text,false,'19aa93bdc32e49282fe54aac149a31c730b57b0ec947303823aabde085b9215d'::text,'09c5dd4a44e948668c52c63c4b83232f4d6f3ad626f1903347a8ae5094087732'::text,'lead_void_shift'::text,'p_shift_id uuid, p_note text'::text),
('get_or_create_toolbox_talk_for_date(date)'::text,$activity_body_68$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('get_or_create_toolbox_talk_for_date','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_talk safety_talks;
  v_lib toolbox_talk_library;
  v_body text;
begin
  -- One writer per date; readers queue briefly instead of double-inserting.
  perform pg_advisory_xact_lock(hashtext('toolbox_talk_' || p_date::text));

  select * into v_talk from safety_talks
    where talk_date = p_date
    order by created_at desc limit 1;
  if v_talk.id is not null then return public._work_activity_finish(__work_activity_root_id,(v_talk)::safety_talks); end if;

  v_lib := _toolbox_library_for_date(p_date);
  if v_lib.id is null then
    -- Empty library: leave the app on its legacy newest-talk fallback.
    return public._work_activity_finish(__work_activity_root_id,(null)::safety_talks);
  end if;

  -- Plain-text body so every legacy reader (snapshot, PDF, old cards)
  -- keeps working without knowing about the structured fields.
  v_body := v_lib.briefing || E'\n\nKey points:\n' ||
    (select string_agg('• ' || x, E'\n') from jsonb_array_elements_text(v_lib.key_points) x) ||
    case when v_lib.stop_work_line is not null
      then E'\n\nStop work: ' || v_lib.stop_work_line else '' end;

  insert into safety_talks
    (title, body, talk_date, library_slug, category, citation,
     key_points, watch_for, stop_work_line, pledge)
  values
    (v_lib.title, v_body, p_date, v_lib.slug, v_lib.category, v_lib.citation,
     v_lib.key_points, v_lib.watch_for, v_lib.stop_work_line, v_lib.pledge)
  returning * into v_talk;
  return public._work_activity_finish(__work_activity_root_id,(v_talk)::safety_talks);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
