$activity_body_71$::text,false,'6b11870ecd83bd84f50d57bfa12bd2cd86747354a70010c1ecc46acaca2ea9c6'::text,'259036217ac78dafddd039d320d0c32813b19df0be996ff2ce3e4bbb21bdd993'::text,'ensure_package_delivery'::text,'p_label text'::text),
('store_packages(uuid[], uuid)'::text,$activity_body_72$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('store_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_prev uuid;
  v_prev_loc uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id, location_id into v_prev, v_prev_loc
    from packages
    where id = v_id and status in ('received', 'stored', 'checked_out');
    if not found then
      continue; -- blank stickers can't be stored
    end if;

    update packages
    set status = 'stored', container_id = p_container, location_id = null
    where id = v_id;

    -- from_location_id carries the shelf it came off, so a package moving from
    -- a job's bay into a conex leaves a trail that says where it was. Without
    -- it the bay simply vanishes from the history.
    insert into movements (
      package_id, event, from_container_id, from_location_id, to_container_id, actor
    )
    values (
      v_id,
      case when v_prev is null and v_prev_loc is null then 'stored' else 'moved' end,
      v_prev,
      v_prev_loc,
      p_container,
      auth.uid()::text
    );
    v_count := v_count + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_72$::text,false,'2af2b7465dc7056fec5b17a5be1249d98ff2dbeef02c595a49cdfca0ad298d3d'::text,'1299e65fb6263fa688806c0a46ebbdcdee142bfb499996a1e085ca83287d9fa5'::text,'store_packages'::text,'p_packages uuid[], p_container uuid'::text),
('checkout_packages(uuid[], text, uuid)'::text,$activity_body_73$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('checkout_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_from uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_reason is null or length(trim(p_reason)) = 0 then
    raise exception 'pick a reason for taking the material';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is going to';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id into v_from
    from packages
    where id = v_id and status in ('received', 'stored');
    if not found then
      continue;
    end if;

    update packages
    set status = 'checked_out', container_id = null
    where id = v_id;

    insert into movements (package_id, event, from_container_id, project_id, reason, actor)
    values (v_id, 'checked_out', v_from, p_project, trim(p_reason), auth.uid()::text);
    v_count := v_count + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_73$::text,false,'4ce9e08e28b48a9a2be0a3ab847fa8fdf16ebbd78266b7fa396a7a79e65faa8b'::text,'9967e3e0f8d52dee0ea7dbe1e2812a9ecf7b80add77516b870727dee08b0a4bb'::text,'checkout_packages'::text,'p_packages uuid[], p_reason text, p_project uuid'::text),
('save_studio_project(uuid, text, uuid, jsonb, boolean)'::text,$activity_body_74$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('save_studio_project','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_row studio_projects;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role in ('installer', 'foreman') then
    raise exception 'only a supervisor or above can author Studio projects';
  end if;
  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'a Studio project needs a name';
  end if;

  if p_id is null then
    insert into studio_projects (name, project_id, model, archived, created_by)
    values (trim(p_name), p_project, p_model, coalesce(p_archived, false), auth.uid()::text)
    returning * into v_row;
  else
    update studio_projects
    set name = trim(p_name),
        project_id = p_project,
        -- Passing null model on a rename/link must not erase the drawing.
        model = coalesce(p_model, model),
        archived = coalesce(p_archived, false),
        updated_at = now()
    where id = p_id
    returning * into v_row;
    if not found then
      raise exception 'Studio project not found';
    end if;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::studio_projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_74$::text,false,'7d8910bfeebde7ece228c05a0c451c898d07e5411d90bee8da01390f5d0b3e56'::text,'429a074ffbbb0c41cd0a75e7e87b858c69b33adc25e546d13d9f10e3b0ba83a0'::text,'save_studio_project'::text,'p_id uuid, p_name text, p_project uuid, p_model jsonb, p_archived boolean'::text),
