$activity_body_75$::text,false,'59edf9e8a6a8a6965dcd3982aa58c6b7c5ba471191e3091a4b119e20f722404a'::text,'47a293d20b243006e7e54b1a3cab4038f184c4ed2cf8c5678ad4c48ea0154ff5'::text,'set_issue_fault_trade'::text,'p_id uuid, p_trade text'::text),
('answer_summon(uuid)'::text,$activity_body_76$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('answer_summon','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_summon summons;
  v_row summon_helpers;
  v_count int;
begin
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before answering a summon';
  end if;
  -- Answering opens a helper unit session (unit_sessions_follow_summon_helpers,
  -- 20260963000000) — unit work, so it waits for today's signature too.
  perform public._unit_work_gate(v_uid);
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.status = 'closed' then
    raise exception 'this summon has ended';
  end if;
  -- Expired but not yet swept: a day-old call is over whatever the row says.
  if v_summon.created_at < now() - interval '1 day' then
    raise exception 'this summon has ended';
  end if;
  if v_summon.requested_by = v_uid then
    raise exception 'you called this summon — no answering yourself';
  end if;
  select count(*) into v_count
  from summon_helpers
  where summon_id = p_summon_id and canceled_at is null;
  if v_count >= v_summon.needed then
    raise exception 'this summon is covered — thanks anyway';
  end if;

  -- Re-answer after a cancel revives the old row; first answer inserts.
  update summon_helpers
  set canceled_at = null, joined_at = now(), completed_at = null, minutes = null
  where summon_id = p_summon_id and profile_id = v_uid and canceled_at is not null
  returning * into v_row;
  if v_row.id is null then
    insert into summon_helpers (summon_id, profile_id)
    values (p_summon_id, v_uid)
    returning * into v_row;
  end if;

  if v_count + 1 >= v_summon.needed then
    update summons set status = 'covered' where id = p_summon_id;
  end if;

  insert into points_ledger (profile_id, kind, points, ref, status)
  values (v_uid, 'summon_answer', 10, p_summon_id::text, 'confirmed');

  -- You answered — any earlier "can't help" no longer applies.
  delete from summon_declines where summon_id = p_summon_id and profile_id = v_uid;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::summon_helpers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_76$::text,false,'4044d2b6839800f5a4e8c5a8f040b71d1b6e8f804cc80483e3dead1411da18b8'::text,'da366d5f1b759c838a074e4ba4626f4d21a10b1198d8394bbe9f1dd02733c783'::text,'answer_summon'::text,'p_summon_id uuid'::text),
('complete_summon_help(uuid)'::text,$activity_body_77$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('complete_summon_help','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_row summon_helpers;
begin
  update summon_helpers
  set completed_at = now(),
      minutes = least(480, greatest(0, floor(extract(epoch from now() - joined_at) / 60))::int)
  where summon_id = p_summon_id and profile_id = v_uid and completed_at is null and canceled_at is null
  returning * into v_row;
  if v_row.id is null then
    raise exception 'no open help of yours on this summon';
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::summon_helpers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_77$::text,false,'dcce01f06c1dbe85a747648bb9ea6c0b6358c62d966244058baeec08ca281439'::text,'c2d3859c665a7c735a8c898727db1956f20c0b50fac043cfe1fc8fc8d100c3e1'::text,'complete_summon_help'::text,'p_summon_id uuid'::text),
('close_summon(uuid)'::text,$activity_body_78$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('close_summon','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_summon summons;
begin
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.requested_by <> v_uid and not _is_lead(v_uid) then
    raise exception 'only the caller or a foreman can end a summon';
  end if;
  update summon_helpers
  set completed_at = now(),
      minutes = least(480, greatest(0, floor(extract(epoch from now() - joined_at) / 60))::int)
  where summon_id = p_summon_id and completed_at is null and canceled_at is null;
  update summons
  set status = 'closed', closed_at = now()
  where id = p_summon_id
  returning * into v_summon;
  return public._work_activity_finish(__work_activity_root_id,(v_summon)::summons);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_78$::text,false,'8585fff6740b6c3b11e60e0d33e4a5e270323565aad3d69584cca6fc689bb14a'::text,'7ece47a6e3d58f12ca99d12781e090fb9ffcf7e542faf2439961a0c77bc312a7'::text,'close_summon'::text,'p_summon_id uuid'::text),
('set_unit_signature(uuid, jsonb)'::text,$activity_body_79$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_unit_signature','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_key text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  -- v1 shape gates: versioned, computed, categorical — never free text.
  if (p_signature ->> 'v') is distinct from '1' then
    raise exception 'unknown signature version';
  end if;
  if (p_signature ->> 'kind') not in ('window', 'door') then
    raise exception 'kind must be window or door';
  end if;
  if (p_signature ->> 'corner') not in ('none', 'corner') then
    raise exception 'corner must be none or corner';
  end if;
  if jsonb_typeof(p_signature -> 'tiers') is distinct from 'array'
     or jsonb_array_length(p_signature -> 'tiers') < 1 then
    raise exception 'signature needs at least one tier';
  end if;
  if (p_signature ->> 'insetOutset') is not null
     and (p_signature ->> 'insetOutset') not in ('inset', 'outset') then
    raise exception 'insetOutset must be inset, outset or null';
  end if;
  if jsonb_typeof(p_signature -> 'panelCount') is distinct from 'number'
     or jsonb_typeof(p_signature -> 'movingCount') is distinct from 'number' then
    raise exception 'panelCount and movingCount must be numbers';
  end if;

  v_key := canonical_jsonb(p_signature);

  update project_openings
  set signature = p_signature,
      sig_key = v_key,
      sig_computed_at = now()
  where id = p_opening_id;
  if not found then
    raise exception 'opening not found';
  end if;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
