begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_close_stale_sessions','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 if auth.uid() is not null and p_profile is distinct from auth.uid() then raise exception using errcode='42501',message='This legacy timing helper is available only for your own activity.';end if;

