$activity_body_81$::text,false,'8a71296dca4f3ed31ebb4358eb570f6416e8cd9712ad0e3e7d3eb631d6e2e4f1'::text,'3b41048114f0cf27058a7c83cfd8df7cebb1762ffa1995158a3e76480f9e9d0d'::text,'_close_stale_sessions'::text,'p_profile uuid'::text),
('start_unit_session(uuid, text)'::text,$activity_body_82$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('start_unit_session','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_row unit_sessions;
begin
  if p_role not in ('install', 'helper') then
    raise exception 'role must be install or helper';
  end if;
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in before starting a task';
  end if;
  perform public._unit_work_gate(v_uid);
  if p_role = 'install' and _flashing_outstanding(p_opening_id) then
    raise exception 'this opening needs flashing before the install starts';
  end if;

  perform _close_stale_sessions(v_uid);
  perform _end_open_session(v_uid, 'handoff');

  insert into unit_sessions (opening_id, profile_id, role, is_rework)
  values (p_opening_id, v_uid, p_role, _has_open_redo(p_opening_id))
  returning * into v_row;

  -- Keep the map/Heartbeat read-model true: first touch stamps the unit.
  update project_openings
  set work_started_at = coalesce(work_started_at, now())
  where id = p_opening_id;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::unit_sessions);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_82$::text,false,'537ffcd3ff1aa6d5302d6cf212046bfbc80c7d0370e55dbf1a43db59b2e51392'::text,'123ee4820b5b5c5b990061efe2fb7c70b1b2a16151c891c35c8cc0af79d87fb6'::text,'start_unit_session'::text,'p_opening_id uuid, p_role text'::text),
('reattribute_session(uuid)'::text,$activity_body_83$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('reattribute_session','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_row unit_sessions;
begin
  update unit_sessions
  set opening_id = p_opening_id,
      is_rework = _has_open_redo(p_opening_id)
  where profile_id = v_uid and ended_at is null
    and started_at > now() - interval '5 minutes'
  returning * into v_row;
  if v_row.id is null then
    raise exception 'nothing to move — no open session younger than 5 minutes';
  end if;
  update project_openings
  set work_started_at = coalesce(work_started_at, now())
  where id = p_opening_id;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::unit_sessions);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
