('block_unit(uuid, text, uuid, uuid)'::text,$activity_body_85$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('block_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_issue uuid := p_issue_id;
  v_project uuid;
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required to block a unit';
  end if;
  select project_id into v_project from project_openings where id = p_opening_id;
  if v_project is null then
    raise exception 'opening not found';
  end if;
  if v_issue is null then
    insert into issues (project_id, opening_id, kind, note, created_by)
    values (v_project, p_opening_id, 'blocker', p_reason, v_uid)
    returning id into v_issue;
  end if;

  update unit_sessions
  set ended_at = now(), end_reason = 'block',
      block_reason = p_reason, block_issue_id = v_issue
  where profile_id = v_uid and ended_at is null and opening_id = p_opening_id;

  if p_next_opening_id is not null then
    begin
      perform start_unit_session(p_next_opening_id, 'install');
    exception when others then
      null;
    end;
  end if;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_85$::text,false,'8ed2fc9507b84fccb83d8e02cfed0c940e22ac83a9409662987203a359c42176'::text,'5e45470f2b66eddf3fa76fccac3c092943535b694442bf534821c66bd55ad27b'::text,'block_unit'::text,'p_opening_id uuid, p_reason text, p_issue_id uuid, p_next_opening_id uuid'::text),
