declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('press_redo','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_row unit_redos;
begin
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'a reason is required to redo a unit';
  end if;
  if exists (
    select 1 from unit_redos where opening_id = p_opening_id and resolved_at is null
  ) then
    raise exception 'a redo is already open on this unit';
  end if;

  insert into unit_redos (opening_id, pressed_by, reason)
  values (p_opening_id, v_uid, p_reason)
  returning * into v_row;

  -- Back in play, visibly. The install_events row is NOT touched.
  update project_openings
  set status = case when assigned_to is not null then 'assigned' else 'planned' end,
      confirmed = false,
      work_ended_at = null
  where id = p_opening_id;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::unit_redos);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_86$::text,false,'1af62172881b9ecc761c660f0c9d182940f3b32ba9964259566cc499f0aa5958'::text,'af9af79350077e3fd4dbbe9ef118fab11eb36bb16d907c8950fc05a6238701e4'::text,'press_redo'::text,'p_opening_id uuid, p_reason text'::text),
('move_container(uuid, uuid, uuid)'::text,$activity_body_87$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('move_container','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row storage_containers;
  v_old_parent uuid;
  v_old_location uuid;
  v_kind text;
  v_parent_kind text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_parent is not null and p_location is not null then
    raise exception 'pick one destination — inside a container or at a spot, not both';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  select kind into v_kind from storage_containers where id = p_container;
  if v_kind = 'building' then
    raise exception 'the building does not move';
  end if;

  if p_parent is not null then
    select kind into v_parent_kind
    from storage_containers where id = p_parent and active;
    if v_parent_kind is null then
      raise exception 'destination container not found or inactive';
    end if;
    if v_parent_kind = 'crate' then
      raise exception 'nothing goes inside a crate — a crate is the smallest box there is';
    end if;
    if v_kind = 'conex' and v_parent_kind <> 'truck' then
      raise exception 'a conex only rides on a truck';
    end if;
    if v_kind = 'truck' then
      raise exception 'a truck does not go inside anything';
    end if;
  end if;

  select parent_container_id, location_id into v_old_parent, v_old_location
  from storage_containers where id = p_container;

  update storage_containers
  set parent_container_id = p_parent,
      location_id = p_location
  where id = p_container
  returning * into v_row;

  insert into movements
    (container_id, event, from_container_id, to_container_id,
     from_location_id, to_location_id, actor)
  values
    (p_container, 'moved', v_old_parent, p_parent, v_old_location, p_location,
     auth.uid()::text);

  insert into movements (package_id, event, to_container_id, actor, reason)
  select p.id, 'moved', p.container_id, auth.uid()::text,
         'rode along — ' || v_row.name || ' moved'
  from packages p
  where p.status = 'stored'
    and (
      p.container_id = p_container
      or p.container_id in (
        select id from storage_containers where parent_container_id = p_container
      )
    );

  return public._work_activity_finish(__work_activity_root_id,(v_row)::storage_containers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_87$::text,false,'b1d2bcdaa2f2e456d95c4759abec76ed992062c5adcf5912916468e0871b0386'::text,'78f7dc79c5156fda4e6851e2284fb9d9a59e10c9cdbdf158a657ba65220487c9'::text,'move_container'::text,'p_container uuid, p_parent uuid, p_location uuid'::text),
('stage_packages(uuid[], uuid)'::text,$activity_body_88$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('stage_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_bay uuid;
  v_id uuid;
  v_prev uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is staged for';
  end if;

  v_bay := public.job_staging_bay(p_project);
  if v_bay is null then
    raise exception 'this job has no staging bay yet'
      using hint = 'no_staging_bay';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select container_id into v_prev
    from packages
    where id = v_id and status in ('received', 'stored');
    if not found then
      continue; -- blank stickers and checked-out packages cannot be staged
    end if;

    update packages
    set status = 'stored', container_id = null, location_id = v_bay
    where id = v_id;

    insert into movements
      (package_id, event, from_container_id, to_location_id, project_id, actor, reason)
    values (v_id, 'staged', v_prev, v_bay, p_project, auth.uid()::text,
            'staged for the job');
    v_count := v_count + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_88$::text,false,'a9a9d417b48de6744a8388f8f38736c774a3c705523e9c54b57dea005eb183d1'::text,'665d32afaa1a69c630cb34ae477c22931ee6e0e6a959bf4a09c006a272e57b90'::text,'stage_packages'::text,'p_packages uuid[], p_project uuid'::text),
('store_packages(uuid[], uuid, jsonb)'::text,$activity_body_89$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('store_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_status text;
  v_container uuid;
  v_location uuid;
  v_serial text;
  v_note jsonb;
  v_exp_status text;
  v_exp_container uuid;
  v_hit int;
  v_stored int := 0;
  v_refused jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    -- `select into` sets every target to null when nothing comes back, and
    -- packages.status is NOT NULL, so a null status here means one thing:
    -- there is no such package. Read that instead of `FOUND`, which several
    -- later statements in this loop would clobber.
    select p.status, p.container_id, p.location_id, p.serial
      into v_status, v_container, v_location, v_serial
    from packages p
    where p.id = v_id;

    -- Already sitting exactly where this check-in was sending it. That is
    -- this same write arriving a second time — the answer to the first one
    -- got lost, or a foreman pressed Try again after another package in the
    -- batch was refused. It is done. Counting it and writing NO movement row
    -- keeps the history honest about how many times the package moved, and
    -- makes the whole call safe to send again.
    if v_status = 'stored' and v_container is not distinct from p_container then
      v_stored := v_stored + 1;
      continue;
    end if;

    v_note := coalesce(p_expected, '{}'::jsonb) -> v_id::text;
    v_exp_status := v_note ->> 'status';
    v_exp_container := nullif(v_note ->> 'container', '')::uuid;

    -- Apply only what the phone can vouch for. Three ways to fall out of this
    -- and every one of them ends up reported rather than skipped:
    --   * there is no such package;
    --   * the note has nothing for it, so we cannot tell whether it is still
    --     true (this is what a check-in queued by an older bundle looks like);
    --   * the note says it was a blank sticker, which was never storable —
    --     the old version skipped that one in silence, which is exactly the
    --     habit this migration exists to break.
    if v_status is not null
       and v_exp_status is not null
       and v_exp_status in ('received', 'stored', 'checked_out')
    then
      -- The compare and the write are ONE statement on purpose. Reading the
      -- row first and updating after leaves a gap another actor fits inside;
      -- putting the note in the WHERE clause makes the database do the
      -- comparing, against the row as it stands at the instant of the write.
      --
      -- location_id is cleared because a package in a container is not also
      -- on a shelf — `packages_one_place_ck` says so, and a package that was
      -- set aside on a job's bay is a real, everyday check-in candidate.
      update packages
      set status = 'stored',
          container_id = p_container,
          location_id = null
      where id = v_id
        and status = v_exp_status
        and container_id is not distinct from v_exp_container;
      get diagnostics v_hit = row_count;

      if v_hit = 1 then
        -- The previous container is v_exp_container and not a fresh read:
        -- the update only touched the row BECAUSE the two matched, so the
        -- note is the proven old value. Same movement row the old version
        -- wrote, so history reads identically for every check-in that lands.
        insert into movements (package_id, event, from_container_id, to_container_id, actor)
        values (
          v_id,
          case when v_exp_container is null then 'stored' else 'moved' end,
          v_exp_container,
          p_container,
          auth.uid()::text
        );
        v_stored := v_stored + 1;
        continue;
      end if;

      -- The note matched a moment ago and does not now: somebody wrote to
      -- this row between the read at the top of the loop and the update.
      -- Re-read so the refusal names what is actually true.
      select p.status, p.container_id, p.location_id, p.serial
        into v_status, v_container, v_location, v_serial
      from packages p
      where p.id = v_id;
    end if;

    -- Refused. Say which package and what beat it, in facts the app can turn
    -- into a sentence: the serial a person reads off the sticker, the state
    -- the package is really in, the container it is really in, and — when it
    -- was checked out — the job it went to.
    v_refused := v_refused || jsonb_build_array(jsonb_build_object(
      'id', v_id,
      'serial', v_serial,
      'status', v_status,
      'container', (
        select c.name from storage_containers c where c.id = v_container
      ),
      -- The shelf, when the package went onto a job's bay instead. Its sibling
      -- (stage_packages) has always sent this, and the app has a sentence
      -- ready for it — "it is on shelf J-BLACK22-A now" — which was
      -- unreachable for check-ins because this key was never here. That is
      -- the very case F3 made likely: set-aside became queueable, so a
      -- check-in now loses to a set-aside far more often than it used to.
      'location', (
        select l.address from locations l where l.id = v_location
      ),
      'job', case when v_status = 'checked_out' then (
        select pr.job_code
        from movements m
        join projects pr on pr.id = m.project_id
        where m.package_id = v_id and m.event = 'checked_out'
        order by m.created_at desc
        limit 1
      ) end
    ));
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object(
    'stored', v_stored,
    'container', (select c.name from storage_containers c where c.id = p_container),
    'refused', v_refused
  ))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_89$::text,false,'0c03e8915581ef19667a13a0102f0db06748be27038af1431acaa405b132a50e'::text,'97bf9b6c6f62fbbe7de839cab2da9cbc52a3c93afb9a76dcb6c84cabc12f228d'::text,'store_packages'::text,'p_packages uuid[], p_container uuid, p_expected jsonb'::text),
('stage_packages(uuid[], uuid, jsonb)'::text,$activity_body_90$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('stage_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_bay uuid;
  v_id uuid;
  v_status text;
  v_container uuid;
  v_location uuid;
  v_serial text;
  v_note jsonb;
  v_exp_status text;
  v_exp_container uuid;
  v_exp_location uuid;
  v_hit int;
  v_staged int := 0;
  v_refused jsonb := '[]'::jsonb;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material is staged for';
  end if;

  v_bay := public.job_bay_box(p_project);

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select p.status, p.container_id, p.location_id, p.serial
      into v_status, v_container, v_location, v_serial
    from packages p
    where p.id = v_id;

    -- Already in the bay: the same write arriving twice. Done, no new line.
    if v_status = 'stored' and v_container is not distinct from v_bay then
      v_staged := v_staged + 1;
      continue;
    end if;

    v_note := coalesce(p_expected, '{}'::jsonb) -> v_id::text;
    v_exp_status := v_note ->> 'status';
    v_exp_container := nullif(v_note ->> 'container', '')::uuid;
    v_exp_location := nullif(v_note ->> 'location', '')::uuid;

    if v_status is not null
       and v_exp_status is not null
       and v_exp_status in ('received', 'stored')
    then
      update packages
      set status = 'stored',
          container_id = v_bay,
          location_id = null
      where id = v_id
        and status = v_exp_status
        and container_id is not distinct from v_exp_container
        and location_id is not distinct from v_exp_location;
      get diagnostics v_hit = row_count;

      if v_hit = 1 then
        insert into movements
          (package_id, event, from_container_id, from_location_id,
           to_container_id, project_id, actor, reason)
        values (v_id, 'staged', v_exp_container, v_exp_location,
                v_bay, p_project, auth.uid()::text, 'set aside in the job''s bay');
        v_staged := v_staged + 1;
        continue;
      end if;

      select p.status, p.container_id, p.location_id, p.serial
        into v_status, v_container, v_location, v_serial
      from packages p
      where p.id = v_id;
    end if;

    v_refused := v_refused || jsonb_build_array(jsonb_build_object(
      'id', v_id,
      'serial', v_serial,
      'status', v_status,
      'container', (
        select c.name from storage_containers c where c.id = v_container
      ),
      'location', (
        select l.address from locations l where l.id = v_location
      ),
      'job', case when v_status = 'checked_out' then (
        select pr.job_code
        from movements m
        join projects pr on pr.id = m.project_id
        where m.package_id = v_id and m.event = 'checked_out'
        order by m.created_at desc
        limit 1
      ) end
    ));
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object(
    'staged', v_staged,
    'job', (select pr.job_code from projects pr where pr.id = p_project),
    -- Was the slot's address; the bay is a box now, so its name.
    'bay', (select c.name from storage_containers c where c.id = v_bay),
    'refused', v_refused
  ))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_90$::text,false,'ff3e1449d07d30d0b82428cb1ac73a11e00b1ec8f660ca839c7ee0b5d529ba87'::text,'59d390428a62109ecad364807febd9eb884f771b891ffc778ae3159cc597405a'::text,'stage_packages'::text,'p_packages uuid[], p_project uuid, p_expected jsonb'::text),
('save_storage_container(uuid, text, text, text, text, boolean, text, numeric, numeric, numeric, numeric)'::text,$activity_body_91$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('save_storage_container','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row storage_containers;
  v_old_address text;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'a container needs a name';
  end if;

  if p_id is null then
    if coalesce(p_kind, 'conex') = 'building'
       and exists (select 1 from storage_containers where kind = 'building') then
      raise exception 'there is already a building — the main warehouse is one of a kind';
    end if;
    insert into storage_containers
      (name, address, access_code, notes, active, kind,
       length_cm, width_cm, height_cm, weight_kg)
    values
      (trim(p_name), p_address, p_access_code, p_notes, coalesce(p_active, true),
       coalesce(p_kind, 'conex'),
       p_length_cm, p_width_cm, p_height_cm, p_weight_kg)
    returning * into v_row;
  else
    select address into v_old_address from storage_containers where id = p_id;
    if not found then
      raise exception 'container not found';
    end if;

    update storage_containers
    set name = trim(p_name), address = p_address, access_code = p_access_code,
        notes = p_notes, active = coalesce(p_active, true),
        length_cm = p_length_cm, width_cm = p_width_cm,
        height_cm = p_height_cm, weight_kg = p_weight_kg
    where id = p_id
    returning * into v_row;

    -- The trail. Whitespace-insensitive so a stray space is not a "move", and
    -- written AFTER the update so a failed update writes no phantom line.
    if nullif(trim(coalesce(v_old_address, '')), '')
       is distinct from nullif(trim(coalesce(p_address, '')), '') then
      insert into movements (container_id, event, actor, reason)
      values (
        p_id,
        'moved',
        auth.uid()::text,
        case
          when nullif(trim(coalesce(v_old_address, '')), '') is null
            then 'address set: ' || trim(p_address)
          when nullif(trim(coalesce(p_address, '')), '') is null
            then 'address cleared — was ' || trim(v_old_address)
          else 'address changed: ' || trim(v_old_address) || ' → ' || trim(p_address)
        end
      );
    end if;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::storage_containers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_91$::text,false,'4efb9b428db04e13a0778e781f4571bcacc483321b9f95ab0b44064dcb90b8c8'::text,'155d29fc3179819f012f0d4b589e74d55ffcee5e26efe33d8ceb08c8e450553b'::text,'save_storage_container'::text,'p_id uuid, p_name text, p_address text, p_access_code text, p_notes text, p_active boolean, p_kind text, p_length_cm numeric, p_width_cm numeric, p_height_cm numeric, p_weight_kg numeric'::text),
('set_package_area(uuid, text)'::text,$activity_body_92$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_package_area','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_kind text;
  v_allowed text[];
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;

  select p.* into v_row from packages p where p.id = p_package;
  if not found then
    raise exception 'package not found';
  end if;

  if p_area is not null then
    if v_row.container_id is null then
      raise exception 'put it in a box first — an area is where inside the box it sits';
    end if;
    select kind into v_kind from storage_containers where id = v_row.container_id;
    if coalesce(v_kind, 'conex') = 'building' then
      v_allowed := array['north','northeast','east','southeast',
                         'south','southwest','west','northwest','middle'];
    else
      -- Anything that moves: the compass would lie the day the box is
      -- re-parked facing the other way, so it only gets the door-relative
      -- three plus their six finer zones (ADR-0006, owner call).
      v_allowed := array['front','middle','back',
                         'front-left','front-right','middle-left','middle-right',
                         'back-left','back-right'];
    end if;
    if not (p_area = any(v_allowed)) then
      raise exception 'that area does not fit this kind of box';
    end if;
  end if;

  update packages set area = p_area where id = p_package
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_92$::text,false,'c11eeca95dbd4254d99f96bdd375ae05fa1dd02f9604133b96395a27e90979c8'::text,'0925fd7a334afa0b58fecce9b386ed781c5967d9ff34261002adac93d0554112'::text,'set_package_area'::text,'p_package uuid, p_area text'::text),
('mint_mark_packages(uuid, text, integer, text)'::text,$activity_body_93$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('mint_mark_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_mark uuid;
  v_mark_code text;
  v_existing_total int;
  v_have int[];
  i int;
  v_row packages;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_total is null or p_total < 1 or p_total > 20 then
    raise exception 'a window arrives as 1 to 20 packages';
  end if;

  v_mark_code := upper(trim(coalesce(p_mark, '')));
  select id into v_mark
  from project_marks
  where project_id = p_project and mark_code = v_mark_code;
  if v_mark is null then
    raise exception 'mark % is not on this job''s schedule', v_mark_code;
  end if;

  -- Every package already carrying this mark, whatever its stage. A label
  -- that disagrees about the total is a contradiction, not a top-up.
  select array_agg(distinct p.part_index) filter (where p.part_index is not null),
         max(p.part_total)
    into v_have, v_existing_total
  from packages p
  join package_marks pm on pm.package_id = p.id
  where pm.mark_id = v_mark;

  if v_existing_total is not null and v_existing_total <> p_total then
    raise exception
      'window % already has labels saying "of %" — burn those first if the count is really %',
      v_mark_code, v_existing_total, p_total;
  end if;

  for i in 1..p_total loop
    if v_have is not null and i = any(v_have) then
      continue; -- that part slot already has its label
    end if;
    insert into packages
      (status, project_id, category, part_index, part_total,
       short_code, bound_at, bound_by)
    values
      ('minted', p_project, p_category, i, p_total,
       issue_package_short_code(), now(), auth.uid()::text)
    returning * into v_row;

    insert into package_marks (package_id, mark_id)
    values (v_row.id, v_mark)
    on conflict do nothing;

    -- 'preissued' is already in movements_event_ck — the unit chain put it
    -- there, and this is its idea living on. The constraint stays untouched.
    insert into movements (package_id, event, project_id, actor, reason)
    values (v_row.id, 'preissued', p_project, auth.uid()::text,
            'label minted — part ' || i || ' of ' || p_total);

    return next v_row;
  end loop;
  perform public._work_activity_operation_exit(__work_activity_root_id); return;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_93$::text,false,'a75a14a9308af39c03056ffe34c58e8d9147125ee8720deaf920f14ca3b65632'::text,'b7775b1a89089d54300864c70bad23e116808ca40dcf1bfce6e9e50b2fa77144'::text,'mint_mark_packages'::text,'p_project uuid, p_mark text, p_total integer, p_category text'::text),
('receive_minted_packages(uuid[])'::text,$activity_body_94$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('receive_minted_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_status text;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select status into v_status from packages where id = v_id;
    if v_status is null then
      continue; -- no such package; nothing honest to do with it here
    end if;
    if v_status = 'minted' then
      update packages set status = 'received' where id = v_id;
      insert into movements (package_id, event, project_id, actor, reason)
      select v_id, 'received', p.project_id, auth.uid()::text,
             'came off the truck — pre-labeled'
      from packages p where p.id = v_id;
      v_count := v_count + 1;
    elsif v_status in ('received', 'stored', 'checked_out') then
      v_count := v_count + 1; -- already arrived; a resend is not a second truck
    end if;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_94$::text,false,'45e46642f46a136371fad1539265cf6224e169390c9a7a7ff2702863d3d45d12'::text,'88fade071ab1a60fa12ad327664dea5aef59d7609fa9e5038ecc9fd8d2aec676'::text,'receive_minted_packages'::text,'p_packages uuid[]'::text),
('burn_packages(uuid[])'::text,$activity_body_95$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('burn_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_row packages;
  v_mark text;
  v_count int := 0;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'only a foreman-level user or above can burn labels';
  end if;

  -- Refuse the whole batch before touching anything.
  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select p.* into v_row from packages p where p.id = v_id;
    if not found then
      continue; -- already gone — a resend is not a second burn
    end if;
    if v_row.status <> 'minted' then
      raise exception
        '% has a life behind it — reprint the sticker instead of burning it',
        v_row.serial;
    end if;
  end loop;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select p.* into v_row from packages p where p.id = v_id;
    if not found then
      continue;
    end if;

    select pm2.mark_code into v_mark
    from package_marks pm
    join project_marks pm2 on pm2.id = pm.mark_id
    where pm.package_id = v_id
    limit 1;

    insert into movements (event, project_id, actor, reason)
    values (
      'override',
      v_row.project_id,
      auth.uid()::text,
      'burned label ' || v_row.serial ||
        coalesce(' — window ' || v_mark, '') ||
        coalesce(', part ' || v_row.part_index || ' of ' || v_row.part_total, '') ||
        ' — never arrived, paper destroyed'
    );

    delete from packages where id = v_id;
    v_count := v_count + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_95$::text,false,'1830998a4797170c2e99f6a55e549c6ed682f4f6774942f74d24a42e535b3d3b'::text,'19025856c43bfef4bd838cb452940c2596f4cb767599aa1d9262a87544c8a721'::text,'burn_packages'::text,'p_packages uuid[]'::text),
('bind_package(uuid, uuid, text, text, text[], uuid, integer, integer, text, text, boolean)'::text,$activity_body_96$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('bind_package','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_mark uuid;
  m text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if coalesce(p_boneyard, false) then
    if p_project is not null then
      raise exception 'boneyard stock has no job — pick one or the other';
    end if;
    if p_marks is not null and array_length(p_marks, 1) > 0 then
      raise exception 'a window number is a position on one job''s plans — boneyard stock has none';
    end if;
  elsif p_project is null then
    raise exception 'every package binds to a job — or to the Boneyard, said on purpose';
  end if;
  if (p_part_index is null) <> (p_part_total is null) then
    raise exception 'a part number needs both halves — "2 of 3", not just one';
  end if;
  if p_part_index is not null and p_part_index > p_part_total then
    raise exception 'part % of % — the first number can''t be bigger than the second', p_part_index, p_part_total;
  end if;

  foreach m in array coalesce(p_marks, array[]::text[])
  loop
    select id into v_mark
    from project_marks
    where project_id = p_project and mark_code = upper(trim(m));
    if v_mark is null then
      raise exception 'mark % is not on this job''s schedule', m;
    end if;
  end loop;

  update packages
  set status = 'received',
      project_id = p_project,
      category = p_category,
      note = nullif(trim(coalesce(p_note, '')), ''),
      delivery_id = p_delivery,
      part_index = p_part_index,
      part_total = p_part_total,
      part_type = p_part_type,
      mfr_mark = nullif(upper(trim(coalesce(p_mfr_mark, ''))), ''),
      bound_at = now(),
      bound_by = auth.uid()::text
  where id = p_package and status = 'blank'
  returning * into v_row;
  if not found then
    raise exception 'that sticker is already assigned — a package ID never moves to another package';
  end if;

  foreach m in array coalesce(p_marks, array[]::text[])
  loop
    select id into v_mark
    from project_marks
    where project_id = p_project and mark_code = upper(trim(m));
    insert into package_marks (package_id, mark_id)
    values (p_package, v_mark)
    on conflict do nothing;
  end loop;

  insert into movements (package_id, event, project_id, actor, reason)
  values (p_package, 'bound', p_project, auth.uid()::text,
          case when coalesce(p_boneyard, false) then 'tagged into the Boneyard — company stock' end);

  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_96$::text,false,'59f8c4b38be203b278f465447289d7ee54e16aa9d055e5d554a9dca4b6c3a767'::text,'c6b2ebfb5f93fc49607e014732e4f148d84eb78927577856fd9ad39edd437890'::text,'bind_package'::text,'p_package uuid, p_project uuid, p_category text, p_note text, p_marks text[], p_delivery uuid, p_part_index integer, p_part_total integer, p_part_type text, p_mfr_mark text, p_boneyard boolean'::text),
('assign_package_to_job(uuid, uuid, text)'::text,$activity_body_97$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('assign_package_to_job','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_mark uuid;
  v_mark_code text;
  v_job text;
  v_issue uuid;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_project is null then
    raise exception 'pick the job this package is going on';
  end if;

  select p.* into v_row from packages p where p.id = p_package;
  if not found then
    raise exception 'package not found';
  end if;
  if v_row.status = 'blank' then
    raise exception 'that sticker is not on a package yet — tag it first';
  end if;
  if v_row.project_id is not null then
    raise exception 'this package already belongs to a job — only Boneyard stock can be assigned';
  end if;

  v_issue := v_row.pending_issue_id;

  v_mark_code := upper(trim(coalesce(p_mark, '')));
  if v_mark_code = '' then
    raise exception 'pick the window this package becomes part of';
  end if;
  select id into v_mark
  from project_marks
  where project_id = p_project and mark_code = v_mark_code;
  if v_mark is null then
    raise exception 'mark % is not on this job''s schedule', v_mark_code;
  end if;

  update packages
  set project_id = p_project,
      pending_job_name = null,
      pending_issue_id = null
  where id = p_package
  returning * into v_row;

  insert into package_marks (package_id, mark_id)
  values (p_package, v_mark)
  on conflict do nothing;

  select job_code into v_job from projects where id = p_project;
  insert into movements (package_id, event, project_id, actor, reason)
  values (
    p_package, 'assigned', p_project, auth.uid()::text,
    'assigned from the Boneyard to ' || coalesce(v_job, 'a job') ||
      ' as window ' || v_mark_code
  );

  -- The missing_job issue resolves when its last waiting package files —
  -- byte-for-byte the rule file_pending_packages follows.
  if v_issue is not null and not exists (
    select 1 from packages
    where pending_issue_id = v_issue and project_id is null
  ) then
    update issues
       set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
     where id = v_issue and status = 'open';
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_97$::text,false,'4d7e76a43fd6828ad343807c705bb8d5423f7a5883740397da17bad307d140ad'::text,'94e14ec8726381498b84179d2c52e888a393f4dbef93937b069f219252431b42'::text,'assign_package_to_job'::text,'p_package uuid, p_project uuid, p_mark text'::text),
('report_maker_count(uuid, integer)'::text,$activity_body_98$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('report_maker_count','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_total is not null and p_total < 1 then
    raise exception 'a package count starts at 1';
  end if;

  update packages set mfr_part_total = p_total
  where id = p_package and status <> 'blank'
  returning * into v_row;
  if not found then
    raise exception 'that sticker is not on a package yet';
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_98$::text,false,'d49583433abbd62e530092ecc2d1b9becebf6edc4fcc4febc937561fa0e1360b'::text,'96639fc373c8f47f10215ac4b34ab12eb5d5eed02533c5e2741bb27b4fa5ad74'::text,'report_maker_count'::text,'p_package uuid, p_total integer'::text),
('set_mark_part_total(uuid, text, integer)'::text,$activity_body_99$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_mark_part_total','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_mark uuid;
  v_mark_code text;
  v_max_index int;
  v_count int;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_total is null or p_total < 1 or p_total > 20 then
    raise exception 'a window arrives as 1 to 20 packages';
  end if;

  v_mark_code := upper(trim(coalesce(p_mark, '')));
  select id into v_mark
  from project_marks
  where project_id = p_project and mark_code = v_mark_code;
  if v_mark is null then
    raise exception 'mark % is not on this job''s schedule', v_mark_code;
  end if;

  select max(p.part_index), count(*)
    into v_max_index, v_count
  from packages p
  join package_marks pm on pm.package_id = p.id
  where pm.mark_id = v_mark and p.status <> 'blank';

  if v_count = 0 then
    raise exception 'window % has no packages yet — nothing to renumber', v_mark_code;
  end if;
  -- Shrinking below an existing part number would orphan real paper: a
  -- package printed "4 of 4" cannot live under "of 3".
  if v_max_index is not null and p_total < v_max_index then
    raise exception
      'window % already has a part numbered % — the count cannot be smaller than that',
      v_mark_code, v_max_index;
  end if;

  update packages p
  set part_total = p_total
  from package_marks pm
  where pm.package_id = p.id
    and pm.mark_id = v_mark
    and p.status <> 'blank'
    and p.part_total is distinct from p_total;

  insert into movements (event, project_id, actor, reason)
  values (
    'override', p_project, auth.uid()::text,
    'window ' || v_mark_code || ' package count set to ' || p_total ||
      ' — every part label now reads "of ' || p_total || '"'
  );

  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_99$::text,false,'f83d69089ed9faa146b51efe6859ed80487dd8130e6e6df701f71584e61ea6e4'::text,'83ff3cce62da514b66bd92c72787b7a086556ecf74c54f9d261dc257a50886d6'::text,'set_mark_part_total'::text,'p_project uuid, p_mark text, p_total integer'::text),
('set_container_model(uuid, uuid)'::text,$activity_body_100$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_container_model','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_row storage_containers;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role not in ('supervisor', 'owner') then
    raise exception 'only a supervisor or above can link a container to a model';
  end if;
  if p_studio is not null
     and not exists (select 1 from studio_projects where id = p_studio) then
    raise exception 'that Studio project does not exist';
  end if;

  update storage_containers
  set studio_project_id = p_studio
  where id = p_container
  returning * into v_row;
  if not found then
    raise exception 'container not found';
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::storage_containers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_100$::text,false,'9322171b043169b6d0579df59865b2991f8c00ddb9ce190827e52575e01109f9'::text,'0b9a6d502ca618bcf2f609a62e1594e9c1a562cc463226674e8fa2364a1af9e3'::text,'set_container_model'::text,'p_container uuid, p_studio uuid'::text),
('cancel_summon_help(uuid)'::text,$activity_body_101$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('cancel_summon_help','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_summon summons;
  v_row summon_helpers;
begin
  select * into v_summon from summons where id = p_summon_id for update;
  if v_summon.id is null then
    raise exception 'summon not found';
  end if;
  if v_summon.status = 'closed' then
    raise exception 'this summon already ended';
  end if;

  update summon_helpers
  set canceled_at = now(), minutes = 0
  where summon_id = p_summon_id and profile_id = v_uid
    and completed_at is null and canceled_at is null
  returning * into v_row;
  if v_row.id is null then
    raise exception 'no open help of yours on this summon';
  end if;

  -- The 10 answer points come back off — a matching negative entry, so the
  -- ledger reads as the story actually went.
  insert into points_ledger (profile_id, kind, points, ref, status)
  values (v_uid, 'summon_answer_canceled', -10, p_summon_id::text, 'confirmed');

  -- A covered summon with a freed seat is open again.
  if v_summon.status = 'covered' then
    update summons set status = 'open' where id = p_summon_id;
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::summon_helpers);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_101$::text,false,'e2fe46fb16901def9276fb59273ba92058b195dd2cba05d8122ad209cf634eb3'::text,'ecf6caab78edde39e6fbfc3ba14c5b198fa7b567d9cfa81bc400c098fc8f6d22'::text,'cancel_summon_help'::text,'p_summon_id uuid'::text),
('create_summon(uuid, integer, integer, text)'::text,$activity_body_102$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('create_summon','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_project uuid;
  v_row summons;
begin
  if p_needed is null or p_needed < 1 or p_needed > 8 then
    raise exception 'ask for between 1 and 8 helpers';
  end if;
  if p_lead_minutes is not null and (p_lead_minutes < 5 or p_lead_minutes > 480) then
    raise exception 'lead time must be between 5 minutes and 8 hours';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'keep the note under 500 characters';
  end if;
  select project_id into v_project from project_openings where id = p_opening_id;
  if v_project is null then
    raise exception 'opening not found';
  end if;
  if exists (
    select 1 from summons
    where opening_id = p_opening_id
      and status in ('open', 'covered')
      and created_at >= now() - interval '1 day'
  ) then
    raise exception 'a summon is already live on this window';
  end if;
  insert into summons (project_id, opening_id, requested_by, needed, needed_at, note)
  values (
    v_project, p_opening_id, v_uid, p_needed,
    case when p_lead_minutes is null then null
         else now() + make_interval(mins => p_lead_minutes) end,
    nullif(trim(p_note), '')
  )
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::summons);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_102$::text,false,'e67eb2063a40e9d9cb093217d097a59219a104c17621572e4cb2d4578faf1d3c'::text,'e91e1710849127d4702ce6a13c993b5e7bc4ec3cf0193e62667c09acb13cde1e'::text,'create_summon'::text,'p_opening_id uuid, p_needed integer, p_lead_minutes integer, p_note text'::text),
('clock_out(uuid, text, boolean, boolean, integer, double precision, double precision, text)'::text,$activity_body_103$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('clock_out','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_shift public.time_shifts;
begin
 if exists(select 1 from public.time_shifts where id=p_shift_id and profile_id=auth.uid() and clock_out_at is null and status='open' and greatest(clock_in_at,last_punch_at,break_started_at)>__work_activity_arrival) then
   return public._work_activity_finish(__work_activity_root_id,(public._work_activity_clock_review(p_shift_id,null,'clock_out',null,null,null))::public.time_shifts);
 end if;

  update public.time_shifts
  set clock_out_at = __work_activity_arrival,
      last_punch_at = __work_activity_arrival,
      clock_out_photo = coalesce(p_photo, clock_out_photo),
      injured = p_injured,
      injury_note = case when p_injured then nullif(trim(coalesce(p_injury_note, '')), '') else null end,
      time_confirmed = p_time_confirmed,
      break_seconds = coalesce(p_break_seconds, break_seconds),
      break_started_at = null,
      break_type = null,
      clock_out_lat = coalesce(p_lat, clock_out_lat),
      clock_out_lng = coalesce(p_lng, clock_out_lng),
      signed_at = __work_activity_arrival,
      status = 'submitted'
  where id = p_shift_id and profile_id = auth.uid()
    and status = 'open' and clock_out_at is null
  returning * into v_shift;
  if v_shift is null then
    if exists (select 1 from public.time_shifts where id = p_shift_id and profile_id = auth.uid()) then
      raise exception 'This shift was already clocked out. Nothing was changed.';
    end if;
    raise exception 'no open shift %', p_shift_id;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_103$::text,true,'7baa1ba7a4d7d6d86aafca48df557a600c8d5f7c8794299d64c2cf345fd18056'::text,'085e2e0382392ee105bf5dfb1322e786cb464f3dad2a43d981f1359ec562d1b4'::text,'clock_out'::text,'p_shift_id uuid, p_photo text, p_injured boolean, p_time_confirmed boolean, p_break_seconds integer, p_lat double precision, p_lng double precision, p_injury_note text'::text),
('arrive_packages(uuid[], uuid[], uuid, text, jsonb)'::text,$activity_body_104$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('arrive_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_note text;
  v_serial text;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if p_project is null then
    raise exception 'pick the job this material arrived at';
  end if;
  v_note := nullif(trim(coalesce(p_note, '')), '');

  foreach v_id in array coalesce(p_ok, array[]::uuid[])
  loop
    if not exists (
      select 1 from packages where id = v_id and status = 'checked_out'
    ) then
      continue;
    end if;
    insert into movements (package_id, event, project_id, actor, reason)
    values (v_id, 'unloaded', p_project, auth.uid()::text,
            coalesce('arrived on site — ' || v_note, 'arrived on site'));
    v_count := v_count + 1;
  end loop;

  foreach v_id in array coalesce(p_damaged, array[]::uuid[])
  loop
    select serial into v_serial from packages where id = v_id and status = 'checked_out';
    if v_serial is null then
      continue;
    end if;

    insert into movements (package_id, event, project_id, actor, reason)
    values (v_id, 'damaged', p_project, auth.uid()::text,
            coalesce('damaged on arrival — ' || v_note, 'damaged on arrival'));

    -- Deduped per package, mirroring the unit-side rule: a second report on
    -- the same package while the first is still open is the same problem.
    -- The photo follows the same rule the note already did — a repeat report
    -- on a package that already has an open issue does not retro-fit either
    -- one onto history it didn't carry when that issue was opened.
    if not exists (
      select 1 from issues
      where package_id = v_id and kind = 'damage' and status = 'open'
    ) then
      insert into issues (project_id, package_id, kind, urgency, note, created_by, photo_path)
      values (
        p_project, v_id, 'damage', 'urgent',
        coalesce('Package ' || v_serial || ' damaged on arrival — ' || v_note,
                 'Package ' || v_serial || ' damaged on arrival'),
        auth.uid(),
        p_photos ->> v_id::text
      );
    end if;
    v_count := v_count + 1;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_104$::text,false,'eb996d8b477fc26fbf29431b8a86d7821e237bf302df1d48d20d2cfd68cb0501'::text,'008573cd480b0e3da7e7ae180712a2932af2e34dab02f8e04e0861d1ee937cee'::text,'arrive_packages'::text,'p_ok uuid[], p_damaged uuid[], p_project uuid, p_note text, p_photos jsonb'::text),
('set_package_note(uuid, text)'::text,$activity_body_105$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_package_note','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_note text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  v_note := nullif(trim(coalesce(p_note, '')), '');
  if v_note is not null and char_length(v_note) > 1000 then
    raise exception 'that note is too long — 1000 characters, max';
  end if;

  update packages set note = v_note
  where id = p_package and status <> 'blank'
  returning * into v_row;
  if not found then
    raise exception 'that sticker is not on a package yet';
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_105$::text,false,'b18d144c8e9d0fe89f5d338349a0119d3028a35612e11b10654a11bf1cdae47c'::text,'5e0a2a535b7cc50b9bc3e2e69ee6010ae4194101e3eec9d38e1a646d43064059'::text,'set_package_note'::text,'p_package uuid, p_note text'::text),
('delete_packages(uuid[])'::text,$activity_body_106$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('delete_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_refused jsonb := '[]'::jsonb;
  v_deleted int := 0;
  v_row record;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can delete packages.'
      using errcode = '42501';
  end if;
  if p_package_ids is null or array_length(p_package_ids, 1) is null then
    return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('deleted', 0, 'refused', v_refused))::jsonb);
  end if;
  if array_length(p_package_ids, 1) > 200 then
    raise exception 'Delete at most 200 packages in one sweep.';
  end if;

  for v_row in
    select p.id, p.serial, p.status
    from packages p
    where p.id = any (p_package_ids)
  loop
    if v_row.status = 'checked_out' then
      v_refused := v_refused || jsonb_build_object(
        'serial', v_row.serial,
        'reason', 'checked out — it is on a truck or jobsite, bring it back first'
      );
      continue;
    end if;
    delete from packages where id = v_row.id;
    v_deleted := v_deleted + 1;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('deleted', v_deleted, 'refused', v_refused))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_106$::text,false,'13cfd2edc0117ff13b79b8f80be5e58590b2521a793021731d1063821fb1108b'::text,'e415693eb00a948185d7e262bfa2b667c26082465f89b394e2cd336be814efad'::text,'delete_packages'::text,'p_package_ids uuid[]'::text),
('create_manual_delivery(text, jsonb)'::text,$activity_body_107$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('create_manual_delivery','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_delivery uuid;
  v_entry jsonb;
  v_set jsonb;
  v_project uuid;
  v_job_name text;
  v_issue uuid;
  v_crate_name text;
  v_created int := 0;
  v_unfiled int := 0;
  v_entry_count int := 0;
  v_set_count int;
  v_n int;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_entries is null or jsonb_typeof(p_entries) <> 'array'
     or jsonb_array_length(p_entries) < 1 then
    raise exception 'Log at least one job''s material.';
  end if;
  if jsonb_array_length(p_entries) > 17 then
    raise exception 'A delivery covers at most 17 jobs.';
  end if;

  insert into package_deliveries (label, arrived_on, created_by)
  values (
    coalesce(nullif(trim(p_label), ''), 'Hand-logged delivery'),
    current_date,
    auth.uid()::text
  )
  returning id into v_delivery;

  for v_entry in select * from jsonb_array_elements(p_entries) loop
    v_entry_count := v_entry_count + 1;
    v_project := nullif(v_entry->>'project_id', '')::uuid;
    v_job_name := nullif(trim(coalesce(v_entry->>'job_name', '')), '');
    if v_project is null and v_job_name is null then
      raise exception 'Entry % names no job.', v_entry_count;
    end if;
    if jsonb_typeof(v_entry->'sets') <> 'array'
       or jsonb_array_length(v_entry->'sets') < 1 then
      raise exception 'Job % has no sets.', v_entry_count;
    end if;
    v_set_count := jsonb_array_length(v_entry->'sets');
    if v_set_count > 50 then
      raise exception 'A job takes at most 50 sets in one delivery.';
    end if;

    v_issue := null;
    if v_project is null then
      insert into issues (project_id, kind, urgency, note, created_by)
      values (
        null, 'missing_job', 'normal',
        'Build the job "' || v_job_name || '" — ' || v_set_count ||
        ' set(s) from the delivery "' ||
        coalesce(nullif(trim(p_label), ''), 'Hand-logged delivery') ||
        '" arrived under that name and are waiting to be filed.',
        auth.uid()
      )
      returning id into v_issue;
    end if;

    for v_set in select * from jsonb_array_elements(v_entry->'sets') loop
      v_n := public.create_delivery_set(
        v_delivery, v_project,
        v_set->>'mark',
        coalesce(v_set->>'kind', 'window'),
        (v_set->>'package_count')::int,
        v_set#>>'{crate,name}',
        (v_set#>>'{crate,pieces}')::int,
        v_set#>>'{crate,part_type}',
        coalesce((v_set->>'quantity')::int, 1),
        v_job_name,
        v_issue
      );
      v_created := v_created + v_n;
      if v_project is null then
        v_unfiled := v_unfiled + v_n;
      end if;
    end loop;

    -- One sealed crate per distinct name this entry mentioned.
    for v_crate_name in
      select distinct upper(trim(s#>>'{crate,name}'))
      from jsonb_array_elements(v_entry->'sets') s
      where nullif(trim(coalesce(s#>>'{crate,name}', '')), '') is not null
    loop
      insert into packages
        (status, project_id, category, part_type, mfr_mark,
         pending_job_name, pending_issue_id,
         delivery_id, short_code, bound_at, bound_by)
      values
        ('minted', v_project, 'other', 'crate', v_crate_name,
         case when v_project is null then v_job_name end,
         case when v_project is null then v_issue end,
         v_delivery, issue_package_short_code(), now(), auth.uid()::text);
      v_created := v_created + 1;
      if v_project is null then
        v_unfiled := v_unfiled + 1;
      end if;
    end loop;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object(
    'delivery_id', v_delivery,
    'created', v_created,
    'unfiled', v_unfiled,
    'pending', 0
  ))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_107$::text,false,'b6d65e351d5fce7d40f519dd0fcd7c5cf50e99820a0fee3e4df798d58cbe1332'::text,'dd51dea94e548eff679438aa8e97b558f1f707983bf63b20ce006eb29643734e'::text,'create_manual_delivery'::text,'p_label text, p_entries jsonb'::text),
('set_package_part(uuid, integer, integer, text, boolean)'::text,$activity_body_108$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_package_part','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_type text := lower(nullif(trim(coalesce(p_part_type, '')), ''));
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if (p_part_index is null) <> (p_part_total is null) then
    raise exception 'a part number needs both halves — "2 of 3", not just one';
  end if;
  if p_part_index is not null and p_part_index > p_part_total then
    raise exception 'part % of % — the first number can''t be bigger than the second', p_part_index, p_part_total;
  end if;
  if p_part_type is not null and length(trim(p_part_type)) not between 1 and 40 then
    raise exception 'A part label is 1 to 40 characters.';
  end if;

  update packages
  set part_index = p_part_index,
      part_total = p_part_total,
      part_type = v_type
  where id = p_package and status <> 'blank'
  returning * into v_row;
  if not found then
    raise exception 'That package is a blank sticker — tag it first.';
  end if;

  if p_apply_to_siblings and v_type is not null
     and v_row.part_index is not null and v_row.project_id is not null then
    update packages p
    set part_type = v_type
    where p.id <> v_row.id
      and p.status <> 'blank'
      and p.project_id = v_row.project_id
      and p.part_index = v_row.part_index
      and p.part_total = v_row.part_total
      and exists (
        select 1
        from package_marks pm
        join package_marks pm2 on pm2.mark_id = pm.mark_id
        where pm.package_id = p.id and pm2.package_id = v_row.id
      );
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_108$::text,false,'69ce0a236215d17a98fa1bfe5a55c5157e739cdde64d7614b3a6d748db8ed9bd'::text,'57e47e0b9ba04fb5e112730cc81243edbbf76f107b876df2ba79bc6807a0ec13'::text,'set_package_part'::text,'p_package uuid, p_part_index integer, p_part_total integer, p_part_type text, p_apply_to_siblings boolean'::text),
('create_delivery_set(uuid, uuid, text, text, integer, text, integer, text, integer, text, uuid)'::text,$activity_body_109$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('create_delivery_set','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_mark_code text := upper(regexp_replace(trim(coalesce(p_mark, '')), '^#', ''));
  v_mark uuid;
  v_category text := case when p_kind = 'door' then 'doors' else 'windows' end;
  v_row packages;
  v_created int := 0;
  v_qty int := coalesce(p_quantity, 1);
  i int;
  u int;
begin
  if length(v_mark_code) < 1 then
    raise exception 'Every set needs a mark, like 16 or 13A.';
  end if;
  if p_package_count is null or p_package_count < 1 or p_package_count > 20 then
    raise exception 'A set arrives as 1 to 20 packages.';
  end if;
  if v_qty < 1 or v_qty > 20 then
    raise exception 'Identical clones go 1 to 20 at a time.';
  end if;
  if p_project is null and nullif(trim(coalesce(p_job_name, '')), '') is null then
    raise exception 'A set needs a job — picked, or at least named.';
  end if;
  if p_crate_name is not null and trim(p_crate_name) <> ''
     and (p_crate_pieces is null or p_crate_pieces < 1 or p_crate_pieces > 99) then
    raise exception 'Say how many pieces of #% ride in the crates (1-99).', v_mark_code;
  end if;

  if p_project is not null then
    insert into project_marks (project_id, mark_code)
    values (p_project, v_mark_code)
    on conflict (project_id, mark_code) do nothing;
    select id into v_mark from project_marks
    where project_id = p_project and mark_code = v_mark_code;
  end if;

  for u in 1..v_qty loop
    for i in 1..p_package_count loop
      insert into packages
        (status, project_id, category, part_index, part_total, mfr_mark,
         pending_job_name, pending_issue_id,
         delivery_id, short_code, bound_at, bound_by)
      values
        ('minted', p_project, v_category, i, p_package_count, v_mark_code,
         case when p_project is null then trim(p_job_name) end,
         case when p_project is null then p_issue end,
         p_delivery, issue_package_short_code(), now(), auth.uid()::text)
      returning * into v_row;
      if v_mark is not null then
        insert into package_marks (package_id, mark_id)
        values (v_row.id, v_mark) on conflict do nothing;
      end if;
      insert into movements (package_id, event, project_id, actor, reason)
      values (v_row.id, 'preissued', p_project, auth.uid()::text,
              'expected off the truck — part ' || i || ' of ' || p_package_count
              || case when v_qty > 1 then ' (unit ' || u || ' of ' || v_qty || ' identical)' else '' end);
      v_created := v_created + 1;
    end loop;

    if p_crate_name is not null and trim(p_crate_name) <> '' then
      -- The POOL: pieces belong to the job's crates collectively.
      insert into packages
        (status, project_id, category, part_type, piece_count, mfr_mark,
         pending_job_name, pending_issue_id,
         delivery_id, short_code, bound_at, bound_by)
      values
        ('minted', p_project, v_category,
         lower(trim(coalesce(nullif(p_crate_part_type, ''), 'glass'))), p_crate_pieces, v_mark_code,
         case when p_project is null then trim(p_job_name) end,
         case when p_project is null then p_issue end,
         p_delivery, issue_package_short_code(), now(), auth.uid()::text)
      returning * into v_row;
      if v_mark is not null then
        insert into package_marks (package_id, mark_id)
        values (v_row.id, v_mark) on conflict do nothing;
      end if;
      insert into movements (package_id, event, project_id, actor, reason)
      values (v_row.id, 'preissued', p_project, auth.uid()::text,
              'expected off the truck — ' || p_crate_pieces || ' piece(s) riding in the job''s crates'
              || case when v_qty > 1 then ' (unit ' || u || ' of ' || v_qty || ' identical)' else '' end);
      v_created := v_created + 1;
    end if;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(v_created)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_109$::text,false,'ca2e38b61cc708039e54fabfe48f800ac2b227bc8fcc3cd1b176054dd124c668'::text,'4d51b12ef9580b6c2b1f5605ede3270adb3c4a2b217e9c343d0b71425c19099b'::text,'create_delivery_set'::text,'p_delivery uuid, p_project uuid, p_mark text, p_kind text, p_package_count integer, p_crate_name text, p_crate_pieces integer, p_crate_part_type text, p_quantity integer, p_job_name text, p_issue uuid'::text),
('file_pending_packages(uuid[], uuid)'::text,$activity_body_110$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('file_pending_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_mark uuid;
  v_id uuid;
  v_issue uuid;
  v_count int := 0;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  foreach v_id in array coalesce(p_package_ids, array[]::uuid[])
  loop
    select * into v_row from packages
    where id = v_id and project_id is null and pending_job_name is not null;
    if not found then
      continue;
    end if;

    v_issue := v_row.pending_issue_id;

    update packages
    set project_id = p_project,
        pending_job_name = null,
        pending_issue_id = null
    where id = v_id;

    if v_row.mfr_mark is not null and coalesce(v_row.part_type, '') <> 'crate' then
      insert into project_marks (project_id, mark_code)
      values (p_project, v_row.mfr_mark)
      on conflict (project_id, mark_code) do nothing;
      select id into v_mark from project_marks
      where project_id = p_project and mark_code = v_row.mfr_mark;
      insert into package_marks (package_id, mark_id)
      values (v_id, v_mark) on conflict do nothing;
    end if;

    insert into movements (package_id, event, project_id, actor, reason)
    values (v_id, 'assigned', p_project, auth.uid()::text,
            'filed onto the job — was waiting as "' || v_row.pending_job_name || '"');
    v_count := v_count + 1;

    if v_issue is not null and not exists (
      select 1 from packages
      where pending_issue_id = v_issue and project_id is null
    ) then
      update issues
         set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
       where id = v_issue and status = 'open';
    end if;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_110$::text,false,'04e2e22be2a79196c4438f9d13d029f807e9e19c6b33f11b0f49068e8392e23c'::text,'6bfd338d8111dd1c27e0973fc50519e0c433728bfc97527dc244623ba4497cdf'::text,'file_pending_packages'::text,'p_package_ids uuid[], p_project uuid'::text),
('unreceive_packages(uuid[])'::text,$activity_body_111$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('unreceive_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages%rowtype;
  v_id uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;

  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select * into v_row from packages where id = v_id;
    if not found then
      continue;
    end if;
    if v_row.status = 'received'
       or (v_row.status = 'stored' and v_row.piece_count is not null) then
      update packages set status = 'minted' where id = v_id;
      insert into movements (package_id, event, project_id, actor, reason)
      values (v_id, 'override', v_row.project_id, auth.uid()::text,
              'arrival tap undone — back to expected');
      v_count := v_count + 1;
    end if;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_111$::text,false,'f8d6aed87e1eed065c9cc6bc5b74cfc0777a0d7bc9403cc600648cfd36015b96'::text,'6d5cad8de86d9d396ac4054c690bdf9cc03082246d12e3228f03f0deeb095813'::text,'unreceive_packages'::text,'p_packages uuid[]'::text),
('custom_checkin(uuid, uuid, text, text, text, integer)'::text,$activity_body_112$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('custom_checkin','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_mark_code text := upper(regexp_replace(trim(coalesce(p_mark, '')), '^#', ''));
  v_mark uuid;
  v_type text := lower(nullif(trim(coalesce(p_part_type, '')), ''));
  v_category text := 'other';
  v_row packages;
  v_count int := coalesce(p_count, 1);
  i int;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if not exists (select 1 from storage_containers where id = p_container and active) then
    raise exception 'container not found or inactive';
  end if;
  if v_count < 1 or v_count > 20 then
    raise exception 'Check in 1 to 20 at a time.';
  end if;
  if v_type is not null and length(v_type) not between 1 and 40 then
    raise exception 'A part label is 1 to 40 characters.';
  end if;
  if p_project is not null
     and not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  if p_project is not null and v_mark_code <> '' then
    insert into project_marks (project_id, mark_code)
    values (p_project, v_mark_code)
    on conflict (project_id, mark_code) do nothing;
    select id into v_mark from project_marks
    where project_id = p_project and mark_code = v_mark_code;
    -- Borrow the set's own category so the new piece counts with its unit.
    select p2.category into v_category
    from packages p2
    join package_marks pm on pm.package_id = p2.id
    where pm.mark_id = v_mark and p2.category in ('windows', 'doors')
    limit 1;
    v_category := coalesce(v_category, 'other');
  end if;

  for i in 1..v_count loop
    insert into packages
      (status, project_id, category, part_type, mfr_mark, note,
       container_id, short_code, bound_at, bound_by)
    values
      ('stored', p_project, v_category, v_type,
       nullif(v_mark_code, ''),
       nullif(trim(coalesce(p_note, '')), ''),
       p_container, issue_package_short_code(), now(), auth.uid()::text)
    returning * into v_row;
    if v_mark is not null then
      insert into package_marks (package_id, mark_id)
      values (v_row.id, v_mark) on conflict do nothing;
    end if;
    insert into movements (package_id, event, project_id, actor, to_container_id, reason)
    values (v_row.id, 'received', p_project, auth.uid()::text, p_container,
            'custom check-in' || case when v_type is not null then ' — ' || v_type else '' end);
    insert into movements (package_id, event, project_id, actor, to_container_id, reason)
    values (v_row.id, 'stored', p_project, auth.uid()::text, p_container,
            'checked in on the spot');
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_112$::text,false,'37121396659e904f7e299e0f9c00c2b6212390c31f2fcb62ea979fa4adc171a7'::text,'324381764d78a2761bbd3d5deed1b049c59785d66a77d4e05fadb73839377b26'::text,'custom_checkin'::text,'p_container uuid, p_project uuid, p_mark text, p_part_type text, p_note text, p_count integer'::text),
('unstore_packages(uuid[])'::text,$activity_body_113$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('unstore_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages%rowtype;
  v_id uuid;
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  foreach v_id in array coalesce(p_packages, array[]::uuid[])
  loop
    select * into v_row from packages where id = v_id;
    if not found or v_row.status <> 'stored' then
      continue;
    end if;
    update packages
    set status = 'received', container_id = null, area = null
    where id = v_id;
    insert into movements (package_id, event, project_id, actor, from_container_id, reason)
    values (v_id, 'override', v_row.project_id, auth.uid()::text, v_row.container_id,
            'put-away undone at the tailgate — back to loose');
    v_count := v_count + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_113$::text,false,'b2c66b26d5b9023714850400beb3f898d5e7619839db30f1a6b6068b7c50cf7e'::text,'a2b225c46e76f26c5aa4cf1bedea083e8858c586a4997a7c4f2c9d59739af0cc'::text,'unstore_packages'::text,'p_packages uuid[]'::text),
('label_packages(uuid[], text)'::text,$activity_body_114$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('label_packages','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_type text := lower(nullif(trim(coalesce(p_part_type, '')), ''));
  v_count int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if v_type is null or length(v_type) not between 1 and 40 then
    raise exception 'A part label is 1 to 40 characters.';
  end if;
  update packages
  set part_type = v_type
  where id = any (coalesce(p_packages, array[]::uuid[]))
    and status <> 'blank';
  get diagnostics v_count = row_count;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

