declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('update_delivery','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_row package_deliveries;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  update package_deliveries
  set label = coalesce(nullif(trim(coalesce(p_label, '')), ''), label),
      expected_at = coalesce(p_expected_at, expected_at)
  where id = p_delivery
  returning * into v_row;
  if not found then
    raise exception 'That delivery is gone.';
  end if;
  -- The schedule entry follows the truck's new time.
  if p_expected_at is not null then
    update schedule_assignments
    set start_date = p_expected_at::date,
        end_date = p_expected_at::date,
        start_time = p_expected_at::time
    where delivery_id = p_delivery;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::package_deliveries);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_117$::text,false,'2ff1b60c3bcbb61fbff0d429c934a40bd0c22cd05d896f192c69dfe076ad1cd1'::text,'ad80043a3cebc840a286c36d91181de6588cac25542065e24444ac766c36bd06'::text,'update_delivery'::text,'p_delivery uuid, p_label text, p_expected_at timestamp with time zone'::text),
