declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('delete_delivery','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_killed int;
  v_kept int;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can delete a delivery.'
      using errcode = '42501';
  end if;
  select count(*) filter (where status = 'minted'),
         count(*) filter (where status <> 'minted')
    into v_killed, v_kept
  from packages where delivery_id = p_delivery;

  delete from packages where delivery_id = p_delivery and status = 'minted';
  delete from package_deliveries where id = p_delivery;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('killed', coalesce(v_killed, 0), 'kept', coalesce(v_kept, 0)))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_118$::text,false,'5b8b7f7d61931e2e174e1566517b6a525d4239d6a566624c7e2c9876b6850606'::text,'bf4d7addfecd7e45f0d678fa53be71bbabb9ffea7b567fb14dc3736f3191f9cf'::text,'delete_delivery'::text,'p_delivery uuid'::text),
('schedule_delivery(uuid, timestamp with time zone, uuid[])'::text,$activity_body_119$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('schedule_delivery','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_role text;
  v_label text;
  v_assignment uuid;
  v_member uuid;
begin
  select role into v_role from profiles where id = auth.uid();
  if public.is_partner_user() or v_role is null or v_role not in ('supervisor', 'owner', 'admin', 'big_boss') then
    raise exception 'Only a supervisor or above can put a delivery on the schedule.'
      using errcode = '42501';
  end if;
  if p_when is null then
    raise exception 'Pick the date and time the truck comes.';
  end if;
  select label into v_label from package_deliveries where id = p_delivery;
  if v_label is null then
    raise exception 'That delivery is gone.';
  end if;

  update package_deliveries set expected_at = p_when where id = p_delivery;

  select id into v_assignment from schedule_assignments
  where delivery_id = p_delivery;

  if v_assignment is null then
    insert into schedule_assignments
      (kind, delivery_id, project_id, start_date, end_date, start_time,
       status, note, created_by, published_at)
    values
      ('delivery', p_delivery, null, p_when::date, p_when::date, p_when::time,
       'published', 'Meet the truck — ' || v_label, auth.uid(), now())
    returning id into v_assignment;
  else
    update schedule_assignments
    set start_date = p_when::date,
        end_date = p_when::date,
        start_time = p_when::time,
        status = 'published',
        note = 'Meet the truck — ' || v_label,
        published_at = coalesce(published_at, now())
    where id = v_assignment;
  end if;

  delete from schedule_assignment_members where assignment_id = v_assignment;
  foreach v_member in array coalesce(p_member_ids, array[]::uuid[])
  loop
    insert into schedule_assignment_members (assignment_id, profile_id, role)
    values (v_assignment, v_member, 'installer')
    on conflict do nothing;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(v_assignment)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_119$::text,false,'19af25f68929c6a4468dcb02a0d0003931d05138043891aa8648916b29e77823'::text,'34335d0f18d91e3350129fd8d6850487120e5770febe866524062ff7f9b543fb'::text,'schedule_delivery'::text,'p_delivery uuid, p_when timestamp with time zone, p_member_ids uuid[]'::text),
('set_project_test(uuid, boolean)'::text,$activity_body_120$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_project_test','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_zztest_id uuid;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can flag a job as a testing project';
  end if;

  update projects set is_test = p_is_test where id = p_project;
  if not found then
    raise exception 'that job does not exist';
  end if;

  if p_is_test then
    insert into sandbox_projects (project_id, note)
    values (p_project, 'Testing project — flagged in-app')
    on conflict (project_id) do nothing;
  else
    -- Never remove the dedicated automation-sandbox job (ZZTEST, seeded by
    -- 20260730220000) from this list even if somebody toggles the testing
    -- flag off on it by mistake — that would silently cut off the QA test
    -- login's only writable project. Every OTHER project this RPC ever
    -- added to sandbox_projects, it may also remove.
    select id into v_zztest_id from projects where job_code = 'ZZTEST';
    if v_zztest_id is null or p_project <> v_zztest_id then
      delete from sandbox_projects where project_id = p_project;
    end if;
  end if;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
