$activity_body_122$::text,false,'6982f346f7476a0de9317bf7f954802648cdc0e53106dc0fd6b984eb9a81b3ef'::text,'dec1dbf5ab5e5a9f31206b517231c3402d59a06e09c7408c68c6dd559f000fb4'::text,'add_delivery_set'::text,'p_delivery uuid, p_project uuid, p_job_name text, p_mark text, p_kind text, p_package_count integer, p_crate_name text, p_crate_pieces integer, p_crate_part_type text'::text),
('add_crate_supplies(uuid, text, text, integer)'::text,$activity_body_123$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('add_crate_supplies','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_type text := lower(nullif(trim(coalesce(p_part_type, '')), ''));
  v_name text := nullif(trim(coalesce(p_job_name, '')), '');
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if v_type is null or length(v_type) not between 1 and 40 then
    raise exception 'Say what the supply is — 1 to 40 characters.';
  end if;
  if p_pieces is null or p_pieces < 1 or p_pieces > 99 then
    raise exception 'How many pieces ride in the crates? 1 to 99.';
  end if;
  if p_project is null and v_name is null then
    raise exception 'Crate supplies belong to a job — picked, or at least named.';
  end if;
  if p_project is not null and not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  insert into packages
    (status, project_id, pending_job_name, category, part_type, piece_count,
     short_code, bound_at, bound_by)
  values
    ('received', p_project,
     case when p_project is null then v_name end,
     'other', v_type, p_pieces,
     issue_package_short_code(), now(), auth.uid()::text)
  returning * into v_row;

  insert into movements (package_id, event, project_id, actor, reason)
  values (v_row.id, 'received', p_project, auth.uid()::text,
          'supply logged into the crates — ' || p_pieces || ' × ' || v_type);

  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
