('set_project_status(uuid, text)'::text,$activity_body_124$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_project_status','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or owner can finish, cancel, or reopen a job.'
      using errcode = '42501';
  end if;
  if p_status not in ('active', 'completed', 'cancelled') then
    raise exception 'A job is active, completed, or cancelled — nothing else.';
  end if;

  update projects
     set status = p_status,
         status_changed_at = now()
   where id = p_project
  returning * into v_row;
  if v_row.id is null then
    raise exception 'That job does not exist.';
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_124$::text,false,'de0ae17cf953fafd331b8fb8650563fbea42f9f99837c34a15df60a4b8d12829'::text,'280d41fdeca2d6c1a1439379aca218bed242c300c129efd2f396c09a024a1734'::text,'set_project_status'::text,'p_project uuid, p_status text'::text),
('delete_project(uuid)'::text,$activity_body_125$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('delete_project','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_n int;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can delete a job.' using errcode = '42501';
  end if;
  if not exists (select 1 from projects where id = p_project) then
    raise exception 'That job does not exist.';
  end if;

  select count(*) into v_n from packages where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % tracked package%. Complete or cancel it instead — deleting would erase where material went.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;
  select count(*) into v_n from project_openings where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % opening% on its plans. Complete or cancel it instead.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;
  select count(*) into v_n from time_shifts where project_id = p_project;
  if v_n > 0 then
    raise exception 'This job has % clocked shift%. Complete or cancel it instead — hours are payroll.',
      v_n, case when v_n = 1 then '' else 's' end;
  end if;

  delete from project_marks where project_id = p_project;
  delete from sandbox_projects where project_id = p_project;
  delete from projects where id = p_project;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_125$::text,false,'4e5a9545476d09612ff65b618d6b303ba932566f3d202973d9ee3718ad075ded'::text,'78723067fe396ed1325803c8ba9605763e345fdce21dd31de6cdd4f45c252225'::text,'delete_project'::text,'p_project uuid'::text),
('edit_shift(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, text)'::text,$activity_body_126$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('edit_shift','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_old time_shifts;
  v_shift time_shifts;
  v_signed boolean;
  v_changed boolean;
begin
  if auth.uid() is null or public.is_partner_user() then
    raise exception 'A crew login is required.';
  end if;
  if p_note is null or btrim(p_note) = '' then
    raise exception 'an edit needs a reason note';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;

  if not public.can_edit_timecard(v_old.profile_id) then
    raise exception 'Foremen may edit their own time and installers; supervisor time requires a supervisor.';
  end if;
  if v_old.status = 'voided' then
    raise exception 'Restore this removed punch before editing it.';
  end if;
  v_changed := (coalesce(p_project_id,v_old.project_id) is distinct from v_old.project_id)
    or (coalesce(p_cost_code_id,v_old.cost_code_id) is distinct from v_old.cost_code_id)
    or (coalesce(p_clock_in_at,v_old.clock_in_at) is distinct from v_old.clock_in_at)
    or (coalesce(p_clock_out_at,v_old.clock_out_at) is distinct from v_old.clock_out_at)
    or (coalesce(p_break_seconds,v_old.break_seconds) is distinct from v_old.break_seconds);
  v_signed := exists (
    select 1 from timecard_periods
    where profile_id = v_old.profile_id
      and employee_signed_at is not null
      and period_start <= v_old.clock_in_at
      and v_old.clock_in_at < period_start + interval '14 days'
  );

  update time_shifts
     set project_id    = coalesce(p_project_id, project_id),
         cost_code_id  = coalesce(p_cost_code_id, cost_code_id),
         clock_in_at   = coalesce(p_clock_in_at, clock_in_at),
         clock_out_at  = coalesce(p_clock_out_at, clock_out_at),
         break_seconds = coalesce(p_break_seconds, break_seconds),
         edited_note   = p_note,
         edited_by     = auth.uid(),
         edited_at     = now(),
         edited_after_signing = edited_after_signing or v_signed,
         status        = case
                           when v_old.status = 'approved' and v_changed
                             then 'submitted'
                           when v_old.status = 'rejected'
                             then 'submitted'
                           when p_clock_out_at is not null
                                and v_old.status in ('open', 'needs_finish')
                             then 'submitted'
                           else v_old.status
                         end,
         approved_by   = case
                           when v_old.status = 'approved' and v_changed
                             then null
                           else approved_by
                         end,
         approved_at   = case
                           when v_old.status = 'approved' and v_changed
                             then null
                           else approved_at
                         end
   where id = p_shift_id
   returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  select p_shift_id, auth.uid(), d.field, d.old_value, d.new_value, btrim(p_note)
  from (values
    ('project_id',    v_old.project_id::text,    v_shift.project_id::text),
    ('cost_code_id',  v_old.cost_code_id::text,  v_shift.cost_code_id::text),
    ('clock_in_at',   v_old.clock_in_at::text,   v_shift.clock_in_at::text),
    ('clock_out_at',  v_old.clock_out_at::text,  v_shift.clock_out_at::text),
    ('break_seconds', v_old.break_seconds::text, v_shift.break_seconds::text),
    ('status',        v_old.status,              v_shift.status)
  ) as d(field, old_value, new_value)
  where d.old_value is distinct from d.new_value;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_126$::text,false,'be6b9a953394d52ffbe1b3c37829b1a986704283c72184096576c90c01a78022'::text,'ead903a4ce9d781aceb1d53a419ad8f21f73e137f2c7fb968ee08307e487623b'::text,'edit_shift'::text,'p_shift_id uuid, p_project_id uuid, p_cost_code_id uuid, p_clock_in_at timestamp with time zone, p_clock_out_at timestamp with time zone, p_break_seconds integer, p_note text'::text),
('void_shift(uuid, text)'::text,$activity_body_127$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('void_shift','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_old time_shifts;
  v_shift time_shifts;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can delete crew time';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'deleting a punch needs a reason';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status = 'voided' then
    raise exception 'this punch is already deleted';
  end if;

  update time_shifts
     set status        = 'voided',
         voided_at     = now(),
         voided_by     = auth.uid(),
         voided_reason = btrim(p_reason),
         approved_by   = null,
         approved_at   = null
   where id = p_shift_id
   returning * into v_shift;

  -- The Horizon fake-success lesson, cited per the spec: an UPDATE that
  -- matches nothing (RLS silently excluded the row, or it moved under us)
  -- must never be reported back as though the void happened. Belt-and-
  -- suspenders alongside the `for update` row lock above, which already
  -- makes this unreachable today — kept explicit so a future refactor that
  -- drops the lock still fails loudly instead of lying. (This exact phrase
  -- isn't written down anywhere else in this repo that a search could find;
  -- recording the reasoning here rather than a citation I can't verify.)
  if v_shift.id is null then
    raise exception 'void did not apply to shift % — no row was updated', p_shift_id;
  end if;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', v_old.status, 'voided', btrim(p_reason));

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_127$::text,false,'50a4d4b880693ae8308daf6e1f121acac7b898168f14bc273b6a6fc60a4a9ece'::text,'779a735583c0d0cb82486ff81eb9d56c910314498997a9f79b8b2888438fd7b8'::text,'void_shift'::text,'p_shift_id uuid, p_reason text'::text),
('restore_shift(uuid)'::text,$activity_body_128$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('restore_shift','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_old time_shifts;
  v_shift time_shifts;
  v_restored_status text;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'only a supervisor or above can restore crew time';
  end if;

  select * into v_old from time_shifts where id = p_shift_id for update;
  if v_old is null then raise exception 'no shift %', p_shift_id; end if;
  if v_old.status <> 'voided' then
    raise exception 'this punch is not deleted';
  end if;

  v_restored_status := case when v_old.clock_out_at is not null then 'submitted' else 'open' end;

  update time_shifts
     set status        = v_restored_status,
         voided_at     = null,
         voided_by     = null,
         voided_reason = null,
         approved_by   = null,
         approved_at   = null
   where id = p_shift_id
   returning * into v_shift;

  if v_shift.id is null then
    raise exception 'restore did not apply to shift % — no row was updated', p_shift_id;
  end if;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'status', 'voided', v_restored_status, 'restored');

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_128$::text,false,'1a50d5e25bcb3113ddfc9fb194fadb78f3d7c5a2ab3c9286af1b4a868c19aa56'::text,'9747e683b93529f2f052de5595e7b3fafaf382df8e270caccbbe5ec008155a16'::text,'restore_shift'::text,'p_shift_id uuid'::text),
('rename_package(uuid, text, text, text)'::text,$activity_body_129$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('rename_package','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages%rowtype;
  v_pending text := nullif(trim(coalesce(p_pending_job_name, '')), '');
  v_mark text := nullif(trim(coalesce(p_mark, '')), '');
  v_category text := nullif(trim(coalesce(p_category, '')), '');
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if v_pending is not null and length(v_pending) > 120 then
    raise exception 'A waiting-job name is at most 120 characters.';
  end if;
  if v_mark is not null and length(v_mark) > 40 then
    raise exception 'A mark is at most 40 characters.';
  end if;
  if v_category is not null and v_category not in ('windows', 'doors') then
    raise exception 'A set is windows or doors.';
  end if;

  select * into v_row from packages where id = p_package;
  if not found then
    raise exception 'That package does not exist.';
  end if;
  if v_row.status = 'blank' then
    raise exception 'That package is a blank sticker — tag it first.';
  end if;
  if v_row.project_id is not null and v_pending is not null then
    raise exception 'This piece belongs to a job already — its name comes from the job.';
  end if;
  if v_mark is distinct from v_row.mfr_mark
     and exists (select 1 from package_marks where package_id = p_package) then
    raise exception 'This piece is tied to a real window — reassign it instead of renaming the mark.';
  end if;

  update packages
  set pending_job_name = case when project_id is null then v_pending else pending_job_name end,
      mfr_mark = v_mark,
      category = coalesce(v_category, category)
  where id = p_package
  returning * into v_row;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::packages);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_129$::text,false,'fe611427ccc0b5888648e6596f9b8766f6bb5a9df1433510dc9a3f3e5deb4261'::text,'0823b147d81ccb04c82aab2c5176a680bf56ded5bcc59d79cb739427584fedbc'::text,'rename_package'::text,'p_package uuid, p_pending_job_name text, p_mark text, p_category text'::text),
('rewrite_set(uuid, text, text, jsonb, text)'::text,$activity_body_130$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('rewrite_set','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_mark text := upper(regexp_replace(trim(coalesce(p_mark, '')), '^#', ''));
  v_pending text := nullif(trim(coalesce(p_pending_job_name, '')), '');
  v_category text := case when p_kind = 'door' then 'doors' else 'windows' end;
  v_existing_category text;
  v_project_mark uuid;
  v_removed_count int;
  v_candidate_count int;
  v_removed_part_type text;
  v_removed_packaging text;
  v_removed_arrived int;
  v_refit_from_type text;
  v_refit_from_packaging text;
  v_refit_to_type text;
  v_refit_to_packaging text;
  v_parts text;
  v_row record;
  v_key_type text;
  v_key_packaging text;
  v_old_arrived int;
  v_old_expected int;
  v_old_arrived_ids uuid[];
  v_old_expected_ids uuid[];
  v_target_count int;
  v_target_expected int;
  v_mint int;
  v_release int;
  v_minted int := 0;
  v_deleted int := 0;
  v_delivery uuid;
begin
  -- Warehouse work is crew work (ADR-0007, owner call 2026-09-04). The rank
  -- check that stood here is gone; signed in, and not a builder login, is
  -- the whole door now. Every other line of this function is byte-for-byte
  -- what it was.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;

  if (p_project_id is null) = (v_pending is null) then
    raise exception 'That set does not exist.';
  end if;
  if p_project_id is not null and not exists (select 1 from projects where id = p_project_id) then
    raise exception 'That set does not exist.';
  end if;
  if length(v_mark) < 1 then
    raise exception 'That set does not exist.';
  end if;
  if p_lines is null or jsonb_typeof(p_lines) <> 'array' then
    raise exception 'That set does not exist.';
  end if;
  if jsonb_array_length(p_lines) > 12 then
    raise exception 'A set holds at most 12 lines — split it if it needs more.';
  end if;

  -- Register the mark on the job's schedule (create_delivery_set's own
  -- precedent) — a real job's mark may not be on it yet: the whole point of
  -- this screen is fixing material that never matched the manifest.
  if p_project_id is not null then
    insert into project_marks (project_id, mark_code)
    values (p_project_id, v_mark)
    on conflict (project_id, mark_code) do nothing;
    select id into v_project_mark from project_marks
    where project_id = p_project_id and mark_code = v_mark;
  end if;

  -- ---------------------------------------------------- normalize the ask

  drop table if exists _rw_new;
  create temp table _rw_new (
    part_type text not null default '',
    packaging text not null,
    count int not null
  ) on commit drop;

  insert into _rw_new (part_type, packaging, count)
  select coalesce(nullif(trim(lower(x.part_type)), ''), ''), x.packaging, sum(x.count)::int
  from jsonb_to_recordset(p_lines) as x(part_type text, packaging text, count int)
  where x.packaging in ('package', 'crate_pool') and x.count is not null and x.count > 0
  group by 1, 2;

  if exists (select 1 from _rw_new where packaging = 'package' and count > 20) then
    raise exception 'A line of packages holds at most 20.';
  end if;
  if exists (select 1 from _rw_new where packaging = 'crate_pool' and count > 99) then
    raise exception 'A line of pieces in a crate holds at most 99.';
  end if;

  -- ---------------------------------------------------- current reality

  drop table if exists _rw_old;
  create temp table _rw_old (
    part_type text not null default '',
    packaging text not null,
    arrived int not null default 0,
    expected int not null default 0,
    arrived_ids uuid[] not null default array[]::uuid[],
    expected_ids uuid[] not null default array[]::uuid[]
  ) on commit drop;

  insert into _rw_old (part_type, packaging, arrived, expected, arrived_ids, expected_ids)
  with scope as (
    select p.*
    from packages p
    where coalesce(p.part_type, '') <> 'crate'
      and (
        (p_project_id is not null and p.project_id = p_project_id and exists (
          select 1 from package_marks pm
          join project_marks pmk on pmk.id = pm.mark_id
          where pm.package_id = p.id and pmk.mark_code = v_mark
        ))
        or
        (v_pending is not null and p.project_id is null
           and p.pending_job_name = v_pending and p.mfr_mark = v_mark)
      )
  )
  select coalesce(nullif(trim(lower(part_type)), ''), ''),
         'package',
         coalesce(count(*) filter (where status in ('received', 'stored', 'checked_out')), 0)::int,
         coalesce(count(*) filter (where status = 'minted'), 0)::int,
         coalesce(array_agg(id order by part_index nulls last) filter (where status in ('received', 'stored', 'checked_out')), array[]::uuid[]),
         coalesce(array_agg(id order by part_index nulls last) filter (where status = 'minted'), array[]::uuid[])
  from scope where piece_count is null
  group by 1
  union all
  select coalesce(nullif(trim(lower(part_type)), ''), ''),
         'crate_pool',
         coalesce(sum(piece_count) filter (where status in ('received', 'stored', 'checked_out')), 0)::int,
         coalesce(sum(piece_count) filter (where status = 'minted'), 0)::int,
         coalesce(array_agg(id) filter (where status in ('received', 'stored', 'checked_out')), array[]::uuid[]),
         coalesce(array_agg(id) filter (where status = 'minted'), array[]::uuid[])
  from scope where piece_count is not null
  group by 1;

  select category into v_existing_category from packages p
  where coalesce(p.part_type, '') <> 'crate' and p.category is not null
    and (
      (p_project_id is not null and p.project_id = p_project_id and exists (
        select 1 from package_marks pm join project_marks pmk on pmk.id = pm.mark_id
        where pm.package_id = p.id and pmk.mark_code = v_mark
      ))
      or
      (v_pending is not null and p.project_id is null
         and p.pending_job_name = v_pending and p.mfr_mark = v_mark)
    )
  limit 1;
  if v_existing_category is not null then
    v_category := v_existing_category;
  end if;

  -- The tailgate lists a delivery's packages by delivery_id, and the whole
  -- point of this screen is fixing a set WHILE unloading — so replacements
  -- minted here inherit the delivery the set's existing packages rode in on
  -- (latest first when a set somehow spans two trucks). Captured BEFORE the
  -- apply loop deletes anything. Declaring from scratch has no truck to
  -- inherit; those mint delivery-less, same as the ledger's own additions.
  select p.delivery_id into v_delivery from packages p
  where p.delivery_id is not null
    and coalesce(p.part_type, '') <> 'crate'
    and (
      (p_project_id is not null and p.project_id = p_project_id and exists (
        select 1 from package_marks pm join project_marks pmk on pmk.id = pm.mark_id
        where pm.package_id = p.id and pmk.mark_code = v_mark
      ))
      or
      (v_pending is not null and p.project_id is null
         and p.pending_job_name = v_pending and p.mfr_mark = v_mark)
    )
  order by p.bound_at desc nulls last
  limit 1;

  -- --------------------------------------- ambiguity / re-fit resolution
  -- A "removed" line: an old group with arrived material whose (type,
  -- packaging) is absent from the new declaration entirely — the line
  -- vanished, not merely shrank. Re-fit is allowed ONLY when exactly one
  -- such line exists and exactly one brand-new line (same packaging) can
  -- hold its arrived count; anything less clear-cut refuses rather than
  -- guess with real material.

  drop table if exists _rw_removed;
  create temp table _rw_removed on commit drop as
  select o.* from _rw_old o
  left join _rw_new n on n.part_type = o.part_type and n.packaging = o.packaging
  where n.part_type is null and o.arrived > 0;

  drop table if exists _rw_new_only;
  create temp table _rw_new_only on commit drop as
  select n.* from _rw_new n
  left join _rw_old o on o.part_type = n.part_type and o.packaging = n.packaging
  where o.part_type is null;

  select count(*) into v_removed_count from _rw_removed;

  if v_removed_count = 1 then
    select part_type, packaging, arrived into v_removed_part_type, v_removed_packaging, v_removed_arrived
    from _rw_removed;
    select count(*) into v_candidate_count from _rw_new_only
    where packaging = v_removed_packaging and count >= v_removed_arrived;
  else
    v_candidate_count := null;
  end if;

  if v_removed_count = 1 and v_candidate_count = 1 then
    select v_removed_part_type, v_removed_packaging, part_type, packaging
      into v_refit_from_type, v_refit_from_packaging, v_refit_to_type, v_refit_to_packaging
    from _rw_new_only
    where packaging = v_removed_packaging and count >= v_removed_arrived;
  elsif v_removed_count > 0 then
    select string_agg(
      arrived || ' ' || coalesce(nullif(part_type, ''), 'untyped') || ' ' ||
      (case when packaging = 'crate_pool' then 'piece' else 'package' end) ||
      (case when arrived = 1 then '' else 's' end),
      ', ' order by part_type
    ) into v_parts
    from _rw_removed;
    raise exception '%', 'Some arrived material doesn''t clearly fit the new plan: ' || v_parts ||
      '. Retype it one at a time first.';
  end if;

  -- ------------------------------------------------------- apply, per line

  for v_row in
    select part_type, packaging from _rw_old
    union
    select part_type, packaging from _rw_new
  loop
    v_key_type := v_row.part_type;
    v_key_packaging := v_row.packaging;

    select coalesce(arrived, 0), coalesce(expected, 0),
           coalesce(arrived_ids, array[]::uuid[]), coalesce(expected_ids, array[]::uuid[])
      into v_old_arrived, v_old_expected, v_old_arrived_ids, v_old_expected_ids
    from _rw_old where part_type = v_key_type and packaging = v_key_packaging;
    v_old_arrived := coalesce(v_old_arrived, 0);
    v_old_expected := coalesce(v_old_expected, 0);
    v_old_arrived_ids := coalesce(v_old_arrived_ids, array[]::uuid[]);
    v_old_expected_ids := coalesce(v_old_expected_ids, array[]::uuid[]);

    if v_refit_from_type is not null
       and v_key_type = v_refit_from_type and v_key_packaging = v_refit_from_packaging then
      -- This line's arrived material moved on; only its never-arrived
      -- placeholders remain, and those are simply released below.
      v_old_arrived := 0;
      v_old_arrived_ids := array[]::uuid[];
    elsif v_refit_to_type is not null
       and v_key_type = v_refit_to_type and v_key_packaging = v_refit_to_packaging then
      declare
        v_src_arrived int;
        v_src_ids uuid[];
      begin
        select coalesce(arrived, 0), coalesce(arrived_ids, array[]::uuid[])
          into v_src_arrived, v_src_ids
        from _rw_old where part_type = v_refit_from_type and packaging = v_refit_from_packaging;
        v_old_arrived := v_old_arrived + coalesce(v_src_arrived, 0);
        v_old_arrived_ids := v_old_arrived_ids || coalesce(v_src_ids, array[]::uuid[]);
      end;
    end if;

    select count into v_target_count from _rw_new
    where part_type = v_key_type and packaging = v_key_packaging;
    v_target_count := coalesce(v_target_count, 0);

    if v_target_count < v_old_arrived then
      raise exception '%',
        v_old_arrived::text || ' ' || coalesce(nullif(v_key_type, ''), 'untyped') ||
        (case when v_key_packaging = 'crate_pool'
              then ' piece' || (case when v_old_arrived = 1 then '' else 's' end)
              else '' end) ||
        ' already arrived — the new plan only holds ' || v_target_count::text ||
        '. Un-arrive or delete pieces first, so nothing real disappears.';
    end if;

    if v_target_count = 0 and v_old_arrived = 0 and v_old_expected = 0 then
      continue; -- nothing here at all — not a line, before or after
    end if;

    v_target_expected := v_target_count - v_old_arrived;
    v_mint := greatest(0, v_target_expected - v_old_expected);
    v_release := greatest(0, v_old_expected - v_target_expected);

    if v_key_packaging = 'package' then
      declare
        v_release_ids uuid[];
        v_keep_expected_ids uuid[];
        v_new_minted_ids uuid[] := array[]::uuid[];
        v_final_ids uuid[];
        v_idx int;
        v_mint_i int;
        v_id uuid;
        v_len int := coalesce(array_length(v_old_expected_ids, 1), 0);
      begin
        if v_release > 0 then
          v_release_ids := v_old_expected_ids[(v_len - v_release + 1):v_len];
          v_keep_expected_ids := v_old_expected_ids[1:(v_len - v_release)];
        else
          v_release_ids := array[]::uuid[];
          v_keep_expected_ids := v_old_expected_ids;
        end if;

        if coalesce(array_length(v_release_ids, 1), 0) > 0 then
          delete from packages where id = any (v_release_ids);
          v_deleted := v_deleted + array_length(v_release_ids, 1);
        end if;

        if v_mint > 0 then
          for v_mint_i in 1..v_mint loop
            insert into packages
              (status, project_id, category, part_type, pending_job_name,
               short_code, bound_at, bound_by, mfr_mark, delivery_id)
            values
              ('minted', p_project_id, v_category, nullif(v_key_type, ''),
               case when p_project_id is null then v_pending end,
               issue_package_short_code(), now(), auth.uid()::text, v_mark, v_delivery)
            returning id into v_id;
            v_new_minted_ids := v_new_minted_ids || v_id;
            if p_project_id is not null then
              insert into package_marks (package_id, mark_id)
              values (v_id, v_project_mark) on conflict do nothing;
            end if;
            insert into movements (package_id, event, project_id, actor, reason)
            values (v_id, 'preissued', p_project_id, auth.uid()::text,
                    'rewrite: mark #' || v_mark || ' declared to hold ' || v_target_count::text ||
                    ' ' || coalesce(nullif(v_key_type, ''), 'untyped'));
          end loop;
          v_minted := v_minted + v_mint;
        end if;

        v_final_ids := v_old_arrived_ids || v_keep_expected_ids || v_new_minted_ids;
        v_idx := 0;
        foreach v_id in array v_final_ids loop
          v_idx := v_idx + 1;
          update packages
          set part_index = v_idx, part_total = v_target_count, part_type = nullif(v_key_type, '')
          where id = v_id;
        end loop;
      end;
    else -- crate_pool
      declare
        v_id uuid;
      begin
        if coalesce(array_length(v_old_expected_ids, 1), 0) > 0 then
          delete from packages where id = any (v_old_expected_ids);
          v_deleted := v_deleted + array_length(v_old_expected_ids, 1);
        end if;

        if v_target_expected > 0 then
          insert into packages
            (status, project_id, category, part_type, piece_count, mfr_mark,
             pending_job_name, short_code, bound_at, bound_by, delivery_id)
          values
            ('minted', p_project_id, v_category, nullif(v_key_type, ''), v_target_expected, v_mark,
             case when p_project_id is null then v_pending end,
             issue_package_short_code(), now(), auth.uid()::text, v_delivery)
          returning id into v_id;
          if p_project_id is not null then
            insert into package_marks (package_id, mark_id)
            values (v_id, v_project_mark) on conflict do nothing;
          end if;
          insert into movements (package_id, event, project_id, actor, reason)
          values (v_id, 'preissued', p_project_id, auth.uid()::text,
                  'rewrite: mark #' || v_mark || ' declared to hold ' || v_target_expected::text ||
                  ' piece(s) of ' || coalesce(nullif(v_key_type, ''), 'untyped') || ' in the crates');
          v_minted := v_minted + 1;
        end if;

        if coalesce(array_length(v_old_arrived_ids, 1), 0) > 0 then
          update packages set part_type = nullif(v_key_type, '')
          where id = any (v_old_arrived_ids);
        end if;
      end;
    end if;
  end loop;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('minted', v_minted, 'deleted', v_deleted))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_130$::text,false,'40032639d40c3f032a65ba2fcfbc2c29aed80a50e2e836ef50802906c27e67a2'::text,'146c0bdb37feb13c23e3dbf4978b614306e9d94d73106aecc97738223a029d17'::text,'rewrite_set'::text,'p_project_id uuid, p_pending_job_name text, p_mark text, p_lines jsonb, p_kind text'::text),
('restore_project(uuid)'::text,$activity_body_131$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('restore_project','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or above can undo a deleted job.' using errcode = '42501';
  end if;

  select * into v_row from projects where id = p_project_id for update;
  if v_row.id is null then
    raise exception 'That job does not exist.';
  end if;
  if v_row.deleted_at is null then
    raise exception 'That job is not in the trash.';
  end if;
  -- Past the deadline refuses even if the nightly sweep has not swept this
  -- row yet, so the 30-day promise is exact regardless of cron timing.
  if now() >= v_row.deleted_at + interval '30 days' then
    raise exception 'The 30 days are up — this job is gone for good.';
  end if;

  update projects
     set deleted_at = null, deleted_by = null, deleted_reason = null
   where id = p_project_id
  returning * into v_row;

  if v_row.id is null then
    raise exception 'restore did not apply to job % — no row was updated', p_project_id;
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_131$::text,false,'6b47bb7c029a131a1dfc33e5ab4257d477374b8cc67dc948583e9dc928256dd4'::text,'3caf164ad5ef3c5c8fda5102a7a4cc9cfb06c4f7093970593109011d429fb951'::text,'restore_project'::text,'p_project_id uuid'::text),
('purge_project(uuid)'::text,$activity_body_132$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('purge_project','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_project projects;
  v_job_name text;
  v_install_media_paths text[];
  v_issue_photo_paths text[];
begin
  if auth.uid() is not null and not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or above can permanently delete a job.' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(639024,1);

  select * into v_project from projects where id = p_project_id for update;
  if v_project.id is null then
    raise exception 'That job does not exist.';
  end if;
  if v_project.deleted_at is null then
    raise exception 'That job is not in the trash.';
  end if;
  v_job_name := v_project.name;

  -- ---------------------------------------------------------------------
  -- STEP 0 — every detach runs first, inside this one transaction, so no
  -- FK can block a delete below (movements' FK carries NO on-delete rule
  -- at all — it would abort the whole purge if it still pointed at this
  -- job when the projects row goes).
  -- ---------------------------------------------------------------------
  -- Retain plan/revision history with the surviving travel instructions, but
  -- release live links before Schedule rows are purged. No queued notice for
  -- a purged job is claimable (workflow_claim_notices requires project_id).
  delete from workflow_plan_assignments where plan_id in (select id from workflow_plans where project_id=p_project_id);
  delete from workflow_plan_trips where plan_id in (select id from workflow_plans where project_id=p_project_id);
  update workflow_plans set project_id=null,state='canceled',updated_at=now() where project_id=p_project_id;

  update movements set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update windows set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update packages set project_id = null, pending_job_name = coalesce(pending_job_name, v_job_name)
   where project_id = p_project_id;
  update time_shifts set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update task_sessions set project_id = null
   where project_id = p_project_id;
  update incidents set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update service_cases set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update trips set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update receipts set project_id = null, pending_job_name = coalesce(pending_job_name, v_job_name)
   where project_id = p_project_id;
  update studio_projects set project_id = null
   where project_id = p_project_id;
  update monday_jobs set project_id = null
   where project_id = p_project_id;
  update job_costs set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update change_orders set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;
  update daily_logs set project_id = null, job_name = coalesce(job_name, v_job_name)
   where project_id = p_project_id;

  -- OPEN Q4: a damage report on a package that survives detaches WITH the
  -- package (project_id nulled, row and photo kept); every other issue on
  -- this job purges below.
  update issues
     set project_id = null
   where project_id = p_project_id
     and kind = 'damage' and package_id is not null;

  -- AUDIT HOLES 3+4: attachments dual-anchored to a surviving physical thing
  -- (window, package, or service case) detach — unlink install_event_id and
  -- project_id, keep the row and its storage file untouched. Two passes:
  -- rows already carrying this project's id, and (defense in depth, in case
  -- a row was ever written without project_id set) rows reached only via
  -- install_event_id whose event belongs to one of this job's openings.
  update attachments
     set install_event_id = null, project_id = null
   where project_id = p_project_id
     and (window_id is not null or package_id is not null or service_case_id is not null);

  update attachments a
     set install_event_id = null, project_id = null
    from install_events ie, project_openings po
   where a.install_event_id = ie.id
     and ie.project_opening_id = po.id
     and po.project_id = p_project_id
     and (a.window_id is not null or a.package_id is not null or a.service_case_id is not null);

  -- OPEN Q3 / ADR-0004: snapshot the mark's text onto every package_marks
  -- row still pointing at one of this job's marks, THEN unlink — must
  -- happen before project_marks purges below, or the RESTRICT FK aborts.
  update package_marks pm
     set mark_code = coalesce(pm.mark_code, pmk.mark_code)
    from project_marks pmk
   where pm.mark_id = pmk.id and pmk.project_id = p_project_id;

  update package_marks
     set mark_id = null
   where mark_id in (select id from project_marks where project_id = p_project_id);

  -- ---------------------------------------------------------------------
  -- The purge order. summon_helpers/summon_declines cascade from summons;
  -- install_events/qc_checks/opening_phases/opening_notes/unit_redos/
  -- unit_sessions/project_opening_pin_moves/install_event_time_repairs all
  -- cascade from project_openings (verified against each table's own
  -- migration) — one delete of the parent takes the whole branch.
  -- project_planset_pages cascades from project_plansets the same way.
  -- ---------------------------------------------------------------------
  delete from summons where project_id = p_project_id;

  -- Gather storage paths BEFORE deleting the rows that name them: install
  -- photos anchored only to this job's install_events (no surviving window/
  -- package/service_case — the survivors above already lost that link), and
  -- opening_phases' finished-work photos, which carry no attachments row of
  -- their own and are about to cascade away with project_openings below.
  select coalesce(array_agg(path), '{}') into v_install_media_paths
    from (
      select a.storage_path as path
        from attachments a
        join install_events ie on ie.id = a.install_event_id
        join project_openings po on po.id = ie.project_opening_id
       where po.project_id = p_project_id
      union all
      select op.photo_path
        from opening_phases op
        join project_openings po on po.id = op.opening_id
       where po.project_id = p_project_id and op.photo_path is not null
    ) paths;

  delete from attachments a
   using install_events ie, project_openings po
   where a.install_event_id = ie.id
     and ie.project_opening_id = po.id
     and po.project_id = p_project_id;

  -- Issues: gather photo paths of what purges (the surviving package-damage
  -- carve-out above already left this project, so it is excluded here).
  select coalesce(array_agg(photo_path), '{}') into v_issue_photo_paths
    from issues where project_id = p_project_id and photo_path is not null;

  delete from issues where project_id = p_project_id;

  -- Takes install_events, qc_checks, opening_phases, opening_notes,
  -- unit_redos, unit_sessions, project_opening_pin_moves and
  -- install_event_time_repairs with it.
  delete from project_openings where project_id = p_project_id;

  -- Takes project_planset_pages with it.
  delete from project_mark_elevation_views where project_id = p_project_id;
  delete from project_plan_outlines where project_id = p_project_id;
  delete from project_plansets where project_id = p_project_id;
  delete from project_spec_discrepancies where project_id = p_project_id;
  delete from project_mark_specs where project_id = p_project_id;
  -- package_marks already unlinked above, so this can never hit RESTRICT.
  delete from project_marks where project_id = p_project_id;
  delete from project_windows where project_id = p_project_id;
  delete from job_notes where project_id = p_project_id;
  delete from supply_orders where project_id = p_project_id;
  delete from flash_run_assignments where project_id = p_project_id;
  delete from schedule_assignments where project_id = p_project_id;
  delete from vehicle_project_assignments where project_id = p_project_id;
  delete from takeoffs where project_id = p_project_id;
  delete from project_message_reads where project_id = p_project_id;
  delete from project_messages where project_id = p_project_id;
  delete from project_cost_codes where project_id = p_project_id;
  delete from sandbox_projects where project_id = p_project_id;
  delete from partner_job_grants where project_id = p_project_id;

  -- Storage cleanup: SQL DELETE against storage.objects — the bytes become
  -- unreachable in the bucket, there is no separate "delete the file" step
  -- this migration can call from SQL. Files go second-to-last, right before
  -- the projects row, so a crash mid-purge leaves harmless orphan files in
  -- the bucket, never a row pointing at a file that is already gone.
  delete from storage.objects
   where bucket_id = 'plansets' and name like p_project_id::text || '/%';

  delete from storage.objects
   where bucket_id = 'install-media' and name = any (v_install_media_paths);

  delete from storage.objects
   where bucket_id = 'issue-photos' and name = any (v_issue_photo_paths);

  delete from projects where id = p_project_id;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_132$::text,false,'0ccdfadea041d7f7657f2f26709d94ed40df5f71d8e6b044d04bd1a8514f350f'::text,'bd372ef4bd2ad9ab2190b87e6dcd093a596b4c34841b325314ecc6cafd4d086a'::text,'purge_project'::text,'p_project_id uuid'::text),
('purge_expired_projects()'::text,$activity_body_133$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('purge_expired_projects','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
begin
  for v_id in
    select id from projects
     where deleted_at is not null and deleted_at < now() - interval '30 days'
  loop
    -- A nested block, not a bare call: it gives each project its own
    -- implicit savepoint, so one job hitting an unexpected error doesn't
    -- roll back and silently skip every OTHER already-expired job in the
    -- same nightly run. The failure still surfaces (RAISE WARNING reaches
    -- the Postgres log Supabase exposes) rather than being swallowed.
    begin
      perform public.purge_project(v_id);
    exception when others then
      raise warning 'purge_expired_projects: job % failed to purge: %', v_id, sqlerrm;
    end;
  end loop;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_133$::text,false,'756c98634c8005bd4d877eecc3fd51e52c1a73d685478c529e5cf2b5a35c784d'::text,'edb0f59d33c60407814ff94e280299629b2200c60129e6447417084b52986168'::text,'purge_expired_projects'::text,''::text),
('apply_placement_suggestions(uuid, jsonb)'::text,$activity_body_134$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('apply_placement_suggestions','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_applied int := 0;
begin
  if public.my_role_rank() < 1 then
    raise exception 'Only a foreman or above can place windows on the plan.'
      using errcode = '42501';
  end if;

  with incoming as (
    select
      (rec ->> 'opening_id')::uuid as opening_id,
      (rec ->> 'x')::numeric as x,
      (rec ->> 'y')::numeric as y,
      (rec ->> 'page')::int as page,
      nullif(rec ->> 'confidence', '')::numeric as confidence
    from jsonb_array_elements(coalesce(p_suggestions, '[]'::jsonb)) as rec
  )
  update project_openings o
  set suggested_pin_x = i.x,
      suggested_pin_y = i.y,
      suggested_page_number = i.page,
      suggested_at = now(),
      suggested_confidence = i.confidence
  from incoming i
  where o.id = i.opening_id
    and o.project_id = p_project_id
    and o.pin_x is null; -- THE LAW: a mark with a real pin is never touched

  get diagnostics v_applied = row_count;
  return public._work_activity_finish(__work_activity_root_id,(v_applied)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_134$::text,false,'0d5f22af60ce83ceea18ba548f77de3d7d1e4cf4416d6c9ac26ce7cd829e5ce7'::text,'5ec5f52dabe6f4e9259f7d1a72cb217549adad4ae6e101dcfd88e94f320ac1c4'::text,'apply_placement_suggestions'::text,'p_project_id uuid, p_suggestions jsonb'::text),
('expire_summons()'::text,$activity_body_135$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('expire_summons','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_closed int;
begin
  update summon_helpers h
  set completed_at = now(),
      minutes = least(480, greatest(0, floor(extract(epoch from now() - h.joined_at) / 60))::int)
  where h.completed_at is null
    and h.canceled_at is null
    and h.summon_id in (
      select s.id from summons s
      where s.status in ('open', 'covered')
        and s.created_at < now() - interval '1 day'
    );

  with expired as (
    update summons
    set status = 'closed', closed_at = now()
    where status in ('open', 'covered')
      and created_at < now() - interval '1 day'
    returning 1
  )
  select count(*) into v_closed from expired;

  return public._work_activity_finish(__work_activity_root_id,(v_closed)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_135$::text,false,'864ad00a80e674c1c55a3f15bf3c5b937c7ab74c24b5b03fa005f290ff3c9923'::text,'0b1785b621d1c89bd9a174df1b46c009c6b8171de3168b40687aaa5ee86da246'::text,'expire_summons'::text,''::text),
('quick_check_rough_opening(uuid, text)'::text,$activity_body_136$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_opening project_openings;
begin
  -- Numbers win, and the server is the only place that can say so.
  --
  -- The screen hides this button once numbers are on file, but a phone can be
  -- holding the pre-measurement row for a long time — bad signal, PWA cache —
  -- and go on drawing "Quick check: all good" after somebody else ran a tape
  -- over that window. One tap would then overwrite the measurer's name and the
  -- minute they took it, and leave a row carrying numbers AND a quick check,
  -- the one combination the column comment above says cannot exist. The fit
  -- verdict reads the tape either way, so nothing would look wrong on any
  -- screen: the loss would be silent. The same tap is a plain POST to
  -- /rest/v1/rpc/quick_check_rough_opening for any authenticated crew member,
  -- which is the other reason this cannot live in the UI alone.
  update project_openings
  set ro_quick_ok = true,
      ro_measured_by = p_actor,
      ro_measured_at = now()
  where id = p_opening_id
    and ro_width_in is null
    and ro_height_in is null
  returning * into v_opening;

  if v_opening is null then
    -- Two different misses, and an installer can act on only one of them, so
    -- they get different sentences. The numbers are named again rather than
    -- just the id, because the update also misses a soft-removed opening and a
    -- row this login may not write — those are still "unknown opening", not
    -- "somebody measured it". `exists` runs under the caller's own row
    -- policies for the same reason.
    if exists (
      select 1
      from project_openings
      where id = p_opening_id
        and (ro_width_in is not null or ro_height_in is not null)
    ) then
      raise exception
        'Somebody measured this rough opening already. Reload the sheet to see the numbers.';
    end if;
    raise exception 'unknown opening %', p_opening_id;
  end if;
  return v_opening;
end;

end;
$activity_body_136$::text,false,'b306426c1ef97ad0c5e97c9404669f97acfcb8ed2a2106545babb7ed49285a4a'::text,'262b479514311e76ca1aa89587c7c6d76c75723b162f8518959f45ad79db9aff'::text,'quick_check_rough_opening'::text,'p_opening_id uuid, p_actor text'::text),
('attach_sandbox_guards()'::text,$activity_body_137$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('attach_sandbox_guards','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  r      record;
  v_def  text;
  v_type smallint;
  v_on   boolean;
begin
  for r in select * from public.sandbox_scoped_tables()
  loop
    select pg_get_triggerdef(tg.oid), tg.tgtype, tg.tgenabled in ('O', 'A')
      into v_def, v_type, v_on
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    join pg_trigger tg on tg.tgrelid = c.oid
    where n.nspname = 'public'
      and c.relname::text = r.table_name
      and tg.tgname = 'guard_test_account_sandbox_only'
      and tg.tgfoid = 'public.guard_test_account_sandbox_only()'::regprocedure
      and not tg.tgisinternal;

    if v_def is not null
       and coalesce(v_on, false)
       and v_type = 31
       and position(quote_literal(r.link_column) in v_def) > 0
       and position(quote_literal(r.link_kind) in v_def) > 0
    then
      table_name  := r.table_name;
      link_column := r.link_column;
      link_kind   := r.link_kind;
      action      := 'already armed';
      return next;
      continue;
    end if;

    execute format(
      'drop trigger if exists guard_test_account_sandbox_only on public.%I',
      r.table_name);
    execute format(
      'create trigger guard_test_account_sandbox_only '
      'before insert or update or delete on public.%I '
      'for each row execute function public.guard_test_account_sandbox_only(%L, %L)',
      r.table_name, r.link_column, r.link_kind);

    table_name  := r.table_name;
    link_column := r.link_column;
    link_kind   := r.link_kind;
    action      := case when v_def is null then 'attached' else 're-attached' end;
    return next;
  end loop;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_137$::text,false,'3dc63c5e39126dba0dffcf89c0dbc42ac28acd12b99a1db0acfc850e06c31f3b'::text,'4c01d307ba603e2006d843287edc17caea227ca2ae9eb037a76cfec6a7429bbf'::text,'attach_sandbox_guards'::text,''::text),
('set_my_language(text)'::text,$activity_body_138$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_my_language','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v text := lower(coalesce(trim(p_lang), ''));
begin
  if auth.uid() is null then
    raise exception 'sign in before choosing a language' using errcode = '42501';
  end if;

  if v not in ('en', 'es') then
    raise exception 'language must be en or es' using errcode = '22023';
  end if;

  update public.profiles
     set language = v, updated_at = now()
   where id = auth.uid();
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_138$::text,false,'b1a6300b1a1bbf0d25759774c983edd8fdcaba2db9d68cc7cdd460132cd20b6b'::text,'ae2ba1309ea1c4e792cd8d0ab43baeefb32d21730162b55c14e1bc2f9c9631fc'::text,'set_my_language'::text,'p_lang text'::text),
('set_project_modes(uuid, text[])'::text,$activity_body_139$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_project_modes','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_clean text[];
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a foreman or above can change a job''s modes';
  end if;

  -- Normalise the request to distinct, known modes only. Anything unrecognised
  -- is dropped rather than trusted; an empty result means the caller sent
  -- nothing usable, which is not a legal job.
  select array_agg(distinct m order by m) into v_clean
  from unnest(p_modes) as m
  where m in ('data', 'tracking');

  if v_clean is null or cardinality(v_clean) = 0 then
    raise exception 'a job must allow at least one of: data, tracking';
  end if;

  update projects set allowed_modes = v_clean where id = p_project_id;
  if not found then
    raise exception 'that job does not exist';
  end if;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_139$::text,false,'9011f41fffb3c4320a1eb14e0cc560f9d9d655e25a3c3c12c47e746091994aa8'::text,'86894a1acc708cfe4791f19f3fb62ed4c55c7d922df4f9fe297a3d6f58d19e7c'::text,'set_project_modes'::text,'p_project_id uuid, p_modes text[]'::text),
('clock_in(uuid, uuid, text, double precision, double precision, text, text)'::text,$activity_body_140$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
 if auth.uid() is null or public.is_partner_user() then raise exception using errcode='42501',message='An identified internal clock actor is required.';end if;
 __work_activity_root_id:=public._work_activity_operation_enter('clock_in','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_shift time_shifts;
begin
  if not public._toolbox_gate_open(auth.uid()) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  if exists(select 1 from public.time_shifts where profile_id=auth.uid() and status<>'voided' and greatest(clock_in_at,clock_out_at,last_punch_at,break_started_at)>__work_activity_arrival) then raise exception 'Existing clock times need foreman review before a new shift can start.';end if;
  perform _close_dangling_shift(auth.uid());

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng,
     note, job_mode, clock_in_at, last_punch_at)
  values
    (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng,
     nullif(btrim(p_note), ''),
     case when p_mode in ('data', 'tracking') then p_mode else null end, __work_activity_arrival, __work_activity_arrival)
  returning * into v_shift;
  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_140$::text,true,'a1bfe895a915f40faa51b9abd47ab299bd6c645f300b85caed6438e51f31aa4a'::text,'c3fe0f2a5111f4d21bf5ef5149c79846ea53ec904f977765d75e5e7117fd5f09'::text,'clock_in'::text,'p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision, p_note text, p_mode text'::text),
('create_job_summon(uuid, integer, integer, text, text)'::text,$activity_body_141$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('create_job_summon','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_row summons;
begin
  if p_needed is null or p_needed < 1 or p_needed > 8 then
    raise exception 'ask for between 1 and 8 helpers';
  end if;
  if p_lead_minutes is not null and (p_lead_minutes < 5 or p_lead_minutes > 480) then
    raise exception 'lead time must be between 5 minutes and 8 hours';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'keep the note under 500 characters';
  end if;
  if p_where_note is not null and length(p_where_note) > 500 then
    raise exception 'keep the location note under 500 characters';
  end if;
  if not exists (select 1 from projects where id = p_project_id) then
    raise exception 'job not found';
  end if;
  -- One live JOB-level call at a time (opening_id is null). A window summon on
  -- the same job is a different row with an opening and does not count here.
  if exists (
    select 1 from summons
    where project_id = p_project_id
      and opening_id is null
      and status in ('open', 'covered')
      and created_at >= now() - interval '1 day'
  ) then
    raise exception 'a call for hands is already live on this job';
  end if;
  insert into summons (project_id, opening_id, requested_by, needed, needed_at, note, where_note)
  values (
    p_project_id, null, v_uid, p_needed,
    case when p_lead_minutes is null then null
         else now() + make_interval(mins => p_lead_minutes) end,
    nullif(trim(p_note), ''),
    nullif(trim(p_where_note), '')
  )
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::summons);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_141$::text,false,'094d88902eec1f58ebe38551db08923d0e30ec965882adc8f59021ddc9ddf295'::text,'e123e9e256f89dd2cf17e62fd5424b4c6da4637addd0c6df8791818eff118512'::text,'create_job_summon'::text,'p_project_id uuid, p_needed integer, p_lead_minutes integer, p_note text, p_where_note text'::text),
('trash_project(uuid, text)'::text,$activity_body_142$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('trash_project','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or above can delete a job.' using errcode = '42501';
  end if;
  if v_reason = '' then
    raise exception 'Give a reason for deleting this job.';
  end if;

  select * into v_row from projects where id = p_project_id for update;
  if v_row.id is null then
    raise exception 'That job does not exist.';
  end if;
  if v_row.deleted_at is not null then
    raise exception 'That job is already in the trash.';
  end if;

  update projects
     set deleted_at = now(), deleted_by = auth.uid(), deleted_reason = v_reason
   where id = p_project_id
  returning * into v_row;

  -- The Horizon fake-success lesson (cited verbatim in void_shift,
  -- 20260944000000): an UPDATE matching nothing must never be reported back
  -- as though the trash happened. Unreachable given the row lock above; kept
  -- explicit so a future refactor that drops the lock still fails loudly.
  if v_row.id is null then
    raise exception 'trash did not apply to job % — no row was updated', p_project_id;
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_142$::text,false,'08b46a272fb7c8e04b50b940139abd27df36acbf3c5ebcd5dab16522f0bb4482'::text,'decb241bb30064f838146cebc6b496938a672061777089d33f4c0f729b69d347'::text,'trash_project'::text,'p_project_id uuid, p_reason text'::text),
('promote_project_to_data(uuid)'::text,$activity_body_143$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('promote_project_to_data','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
  v_current text[];
  v_next text[];
begin
  if not _is_lead(auth.uid()) then
    raise exception 'only a foreman or above can build a job out into a data job';
  end if;

  select allowed_modes into v_current from projects where id = p_project_id;
  if not found then
    raise exception 'that job does not exist';
  end if;

  -- The job's existing (known) modes, plus 'data'. distinct + order keep the
  -- stored array canonical (data before tracking) and make a re-promote a true
  -- no-op: a job that already allows data lands on the identical set. A garbled
  -- or empty current set degrades to data-only rather than to an illegal job.
  select array_agg(distinct m order by m) into v_next
  from (
    select m from unnest(coalesce(v_current, array['data']::text[])) as m
    where m in ('data', 'tracking')
    union
    select 'data'
  ) s;

  update projects set allowed_modes = v_next where id = p_project_id
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_143$::text,false,'17bed18078bd536905d5a7096011be14c8e80e574c4f26b2cebbf86dc097e10f'::text,'8c684971226f4d4567f30152dbdcf16cf3172b6ff2195bb286a3baeda718c373'::text,'promote_project_to_data'::text,'p_project_id uuid'::text),
('touch_shift_location(double precision, double precision, double precision)'::text,$activity_body_144$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('touch_shift_location','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'Sign in before the app can save where you are.';
  end if;

  update time_shifts
     set last_seen_at = now(),
         -- A fix we do not have must not erase the one we do: a foreground
         -- visit with location switched off still updates the TIME (they had
         -- the app open) and leaves the last known point alone.
         last_seen_lat = coalesce(p_lat, last_seen_lat),
         last_seen_lng = coalesce(p_lng, last_seen_lng),
         -- The accuracy moves WITH the point, and only with it. Coalescing it
         -- the way the coordinates are coalesced would pair a brand-new point
         -- with the previous fix's radius, which is a worse lie than storing
         -- nothing: a 3 km fix would inherit "accurate to 20 m" and the
         -- supervisor line would state a distance it has no right to.
         last_seen_accuracy_m = case
           when p_lat is not null and p_lng is not null then p_accuracy_m
           else last_seen_accuracy_m
         end
   where profile_id = v_uid
     and status = 'open'
     and clock_out_at is null
  returning id into v_id;

  return public._work_activity_finish(__work_activity_root_id,(v_id)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_144$::text,false,'2699511b5ca98eb30898b1a669053f3b9a3dc5772122b122b360eeae9f0f0f9f'::text,'f64cd28d56abe070a467b9d293bb3f57d3eaf93058a1983b097ba893dde5acb8'::text,'touch_shift_location'::text,'p_lat double precision, p_lng double precision, p_accuracy_m double precision'::text),
('set_evening_nudge_time(text, boolean)'::text,$activity_body_145$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_evening_nudge_time','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row company_settings;
  v_time time;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'Only a foreman or above can change when the evening reminder goes out.';
  end if;

  begin
    v_time := p_local_time::time;
  exception when others then
    raise exception 'That is not a time of day. Use something like 17:30.';
  end;

  update company_settings
     set evening_nudge_local_time = v_time,
         evening_nudge_enabled = coalesce(p_enabled, evening_nudge_enabled),
         updated_at = now(),
         updated_by = auth.uid()
   where id = 1
  returning * into v_row;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::company_settings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_145$::text,false,'dbc7efebae530354d78b19429702fb9fdb7cca95ce38179ab1d66d6a5e6b9864'::text,'8268ef1a408e759d1d6b64e59b39db559fb9961eb29c50a905e024a862478d76'::text,'set_evening_nudge_time'::text,'p_local_time text, p_enabled boolean'::text),
('claim_still_on_the_job_nudges()'::text,$activity_body_146$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('claim_still_on_the_job_nudges','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_tz constant text := 'America/Denver';
  v_settings company_settings;
  v_now_local timestamp;
  v_nudge_local timestamp;
  v_nudge_moment timestamptz;
  v_local_day date;
begin
  if auth.uid() is not null then
    raise exception 'The evening reminder sends itself — nobody needs to press anything.';
  end if;

  select * into v_settings from company_settings where id = 1;
  if not found or not v_settings.evening_nudge_enabled then
    perform public._work_activity_operation_exit(__work_activity_root_id); return;
  end if;

  v_now_local := (now() at time zone v_tz);
  v_local_day := v_now_local::date;
  v_nudge_local := date_trunc('day', v_now_local) + v_settings.evening_nudge_local_time;
  -- Before the hour: nothing is due. The sweep runs every few minutes and
  -- says nothing all day, which is the point.
  if v_now_local < v_nudge_local then
    perform public._work_activity_operation_exit(__work_activity_root_id); return;
  end if;
  v_nudge_moment := (v_nudge_local at time zone v_tz);

  return query
  update time_shifts ts
     set evening_nudged_on = v_local_day
    from cost_codes cc
   where ts.cost_code_id = cc.id
     and ts.status = 'open'
     and ts.clock_out_at is null
     and cc.code <> '900'
     and ts.clock_in_at < v_nudge_moment
     and ts.evening_nudged_on is distinct from v_local_day
  returning ts.id, ts.profile_id, ts.project_id;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_146$::text,false,'1ce0a763281b98a62bb4424dcd2d84a909d75443fdbadc7a688886a3792c1ec3'::text,'325e1bbe2a53c8191621ba4084046824b75c61522c19cbc1b7b7c9e27640f556'::text,'claim_still_on_the_job_nudges'::text,''::text),
('flag_opening(uuid, text, text)'::text,$activity_body_147$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_opening project_openings;
  v_clean text;
  v_kind text;
begin
  v_clean := nullif(trim(coalesce(p_note, '')), '');
  v_kind := nullif(trim(coalesce(p_kind, '')), '');

  if v_kind is not null
     and v_kind not in ('wrong_size', 'mirrored', 'not_as_drawn', 'not_on_plans', 'other') then
    raise exception 'Pick one of the listed reasons for the data being off.'
      using errcode = '22023';
  end if;

  -- A note with no kind is the old two-argument call's meaning: something is
  -- wrong and nobody was asked to say which kind. A kind with no note is fine
  -- — the reason IS the message.
  if v_clean is null and v_kind is null then
    -- THE RANK LIVES HERE, not only in clear_opening_flag. Both arities and
    -- both call paths end up in this branch, and the two-argument form is
    -- granted to every signed-in account and cannot be revoked without
    -- breaking the callers it exists for — so a check that sat only in
    -- clear_opening_flag was one `flag_opening(id, null)` away from being no
    -- check at all. Only asked when there is something to take down: clearing
    -- nothing is not a claim about anything.
    if not public.is_foreman_plus(auth.uid())
       and exists (
         select 1 from project_openings
          where id = p_opening_id
            and (flag_kind is not null or flag_note is not null)
       ) then
      raise exception 'Only a foreman or above can clear a data-off flag.'
        using errcode = '42501';
    end if;

    update project_openings
       set flag_kind = null, flag_note = null, flagged_by = null, flagged_at = null
     where id = p_opening_id
     returning * into v_opening;
  else
    update project_openings
       set flag_kind = coalesce(v_kind, 'other'),
           flag_note = v_clean,
           flagged_by = auth.uid(),
           flagged_at = now()
     where id = p_opening_id
     returning * into v_opening;
  end if;

  if v_opening is null then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;

  if v_opening.flag_kind is null then
    update issues
       set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
     where opening_id = p_opening_id and kind = 'flag' and status = 'open';
  elsif not exists (
    select 1 from issues
     where opening_id = p_opening_id and kind = 'flag' and status = 'open'
  ) then
    -- The NOTE is only ever what a person typed. It used to fall back to the
    -- reason code, so a flag raised with a reason and no note filed an issue
    -- whose note read `wrong_size` — a column value from this database printed
    -- to a foreman on a phone, which is the thing plain-English copy exists to
    -- stop. The reason is already on the opening; Blockers and the Issues page
    -- read it from there and say it in the reader's own language.
    insert into issues (project_id, opening_id, kind, urgency, note, created_by)
    values (v_opening.project_id, p_opening_id, 'flag', 'normal',
            v_clean, auth.uid());
  end if;

  return v_opening;
end;

end;
$activity_body_147$::text,false,'8a2d4084edac913614503a431da70504ab567c36ebe8a6c1558a83fe10cd8a20'::text,'c2070fedd82dd3f4651669c03f080fa5036ea829bbbcfb823e64fae56a65868f'::text,'flag_opening'::text,'p_opening_id uuid, p_note text, p_kind text'::text),
('clear_opening_flag(uuid)'::text,$activity_body_148$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare v_opening project_openings;
begin
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can clear a data-off flag.'
      using errcode = '42501';
  end if;
  return flag_opening(p_opening_id, null, null);
end;

end;
$activity_body_148$::text,false,'0337644af5dd956d2d4f04e8199c36dd42f8f5e9f7d533035f096a83c6784b11'::text,'8c81fca4e394c5e6909d0ac3c090ed62bd555b37d6b4a60fcb5d958f39305818'::text,'clear_opening_flag'::text,'p_opening_id uuid'::text),
('add_field_unit(uuid, text, numeric, numeric, text, numeric, numeric, text, integer)'::text,$activity_body_149$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('add_field_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row project_openings;
  v_next int;
  v_code text;
  v_style text;
  v_name text;
begin
  if p_kind not in ('window', 'door') then
    raise exception 'Say whether this is a window or a door.' using errcode = '22023';
  end if;

  -- PRESENCE, NOT RANK (wave E): whoever is on the clock on this job can
  -- record a window nobody drew. Anything less and the person looking at the
  -- hole has to phone someone to write it down, which is how it goes unwritten.
  if not exists (
    select 1 from time_shifts
     where profile_id = auth.uid()
       and project_id = p_project_id
       and status = 'open'
       and clock_out_at is null
  ) then
    raise exception 'Clock in on this job before you add a missed window or door.'
      using errcode = '42501';
  end if;

  -- "Missed 1", "Missed 2", … per job. Read off field_unit_seq and not off the
  -- CODE, because the code is renameable and the number must not be: a job
  -- where "Missed 1" has been renamed to "W-14", or removed, must still call
  -- the next one "Missed 2". Every row on the job counts, hidden ones included.
  --
  -- The advisory lock is per project and lasts the transaction: two people
  -- standing in the same house adding a unit in the same second would otherwise
  -- both read the same max and one of them would meet a raw duplicate-key error
  -- from project_openings_live_code_key instead of getting their window
  -- recorded.
  perform pg_advisory_xact_lock(hashtext('field_unit:' || p_project_id::text));
  select coalesce(max(field_unit_seq), 0) + 1
    into v_next
    from project_openings
   where project_id = p_project_id;
  v_code := 'Missed ' || v_next;

  v_style := case when p_kind = 'door'
                  then 'Missed door — field added'
                  else 'Missed window — field added' end;

  perform set_config('app.field_unit_add', 'on', true);
  insert into project_openings (
    project_id, opening_code, label, page_number, pin_x, pin_y,
    status, confirmed, flag_kind, flag_note, flagged_by, flagged_at,
    field_added, field_unit_seq
  ) values (
    p_project_id, v_code, v_style, coalesce(p_page_number, 1),
    p_pin_x, p_pin_y,
    'planned', true, 'not_on_plans',
    nullif(trim(coalesce(p_note, '')), ''), auth.uid(), now(), true, v_next
  )
  returning * into v_row;
  perform set_config('app.field_unit_add', 'off', true);

  -- The spec row is what makes it a real unit everywhere else: the sheet, the
  -- schedule list and the 3D map all read specs by mark code.
  insert into project_mark_specs (
    project_id, mark_code, style, width_in, height_in, source, confirmed,
    unit_kind, door_kind
  ) values (
    p_project_id, v_code, v_style, p_width_in, p_height_in, 'field', false,
    p_kind, case when p_kind = 'door' then 'other' end
  )
  -- AUTHORITATIVE FOR A FIELD ROW. `do nothing` meant a leftover spec under
  -- this code silently became the new unit's size — a second missed unit
  -- showing the first one's width and height, which is what a purchase order
  -- gets cut from. The numbering above should make a collision impossible now;
  -- if one happens anyway, the measurements somebody just took on site win. A
  -- row that is not ours, or that a foreman has confirmed, is never touched.
  on conflict (project_id, mark_code) do update
     set style = excluded.style,
         width_in = excluded.width_in,
         height_in = excluded.height_in,
         source = 'field',
         -- Wave X: the kind follows the style it was written with, or the two
         -- would disagree on a row that used to be a window and is now a door.
         unit_kind = excluded.unit_kind,
         door_kind = excluded.door_kind,
         updated_at = now()
   where project_mark_specs.source = 'field'
     and coalesce(project_mark_specs.confirmed, false) = false;

  if nullif(trim(coalesce(p_photo_path, '')), '') is not null then
    insert into attachments (project_id, project_opening_id, kind, storage_path, created_by)
    select p_project_id, v_row.id, 'photo', p_photo_path,
           (select display_name from profiles where id = auth.uid());
  end if;

  -- It lands on the Issues board like every other field problem, so it is
  -- chased rather than admired.
  select display_name into v_name from profiles where id = auth.uid();
  insert into issues (project_id, opening_id, kind, urgency, note, created_by)
  values (
    p_project_id, v_row.id, 'flag', 'normal',
    coalesce(nullif(trim(coalesce(p_note, '')), ''),
             v_style) || ' (added by ' || coalesce(v_name, 'the crew') || ')',
    auth.uid()
  );

  return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_149$::text,false,'73fdaaaa0937851dbe7e5d1d3bae7863ee82f5c5269a7dead76c9dd93e7bd50a'::text,'866a1bbc972de08d4df56a9bd2fc79e36a8a7e7a4fc0a6c725c96446307a9314'::text,'add_field_unit'::text,'p_project_id uuid, p_kind text, p_width_in numeric, p_height_in numeric, p_photo_path text, p_pin_x numeric, p_pin_y numeric, p_note text, p_page_number integer'::text),
('rename_field_unit(uuid, text)'::text,$activity_body_150$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('rename_field_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row project_openings;
  v_old text;
  v_spec_id uuid;
  v_new_mark text;
  v_code text := nullif(trim(coalesce(p_code, '')), '');
begin
  if public.my_role_rank() < 2 then
    raise exception 'Only a supervisor or above can rename a missed window or door.'
      using errcode = '42501';
  end if;
  if v_code is null then
    raise exception 'Give the window or door a name before saving it.' using errcode = '22023';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found or not v_row.field_added then
    raise exception 'That is not a missed window or door added from the field.'
      using errcode = 'P0002';
  end if;
  v_old := v_row.opening_code;
  if exists (
    select 1 from project_openings
     where project_id = v_row.project_id and opening_code = v_code
       and removed_at is null and id <> p_opening_id
  ) then
    raise exception 'There is already a % on this job. Pick a different name.', v_code
      using errcode = '23505';
  end if;

  update project_openings set opening_code = v_code
   where id = p_opening_id
   returning * into v_row;

  -- The spec row carries the size somebody measured, so it has to end up under
  -- the key the sheet will read it back by — mark_base of the new name, not the
  -- new name. Rename to "1-3" and the sheet looks up mark "1"; a spec left at
  -- "1-3" is a row nothing ever reads, and the measurement is gone from the
  -- screen that orders the glass.
  --
  -- It is found BY ID and only when it is ours (source 'field'), so a rename
  -- can never pick up and move a spec the planset put there.
  v_new_mark := public.mark_base(v_code);
  select id into v_spec_id
    from project_mark_specs
   where project_id = v_row.project_id
     and upper(mark_code) = upper(public.mark_base(v_old))
     and source = 'field'
   limit 1;

  if v_spec_id is not null then
    if exists (
      select 1 from project_mark_specs
       where project_id = v_row.project_id
         and upper(mark_code) = upper(v_new_mark)
         and id <> v_spec_id
    ) then
      -- The paperwork caught up and that row is the better one. DELETE rather
      -- than leave ours behind: an orphan sitting at the freed "Missed N" code
      -- is what the next missed unit on this job would silently inherit its
      -- width and height from.
      delete from project_mark_specs where id = v_spec_id;
    else
      update project_mark_specs
         set mark_code = v_new_mark, updated_at = now()
       where id = v_spec_id;
    end if;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_150$::text,false,'39f3bd85628cf57d387c3b03c4d422cc9d5b805b9d04a57a4a4514c45de3ac84'::text,'61e3316f98ba08cc14236ae0a13624a20ecafb6d503ce656b3ef6a23390b72fc'::text,'rename_field_unit'::text,'p_opening_id uuid, p_code text'::text),
('merge_field_unit(uuid, text)'::text,$activity_body_151$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('merge_field_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row project_openings;
  v_target project_openings;
  v_code text := nullif(trim(coalesce(p_into_code, '')), '');
begin
  if public.my_role_rank() < 2 then
    raise exception 'Only a supervisor or above can merge a missed window or door.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found or not v_row.field_added then
    raise exception 'That is not a missed window or door added from the field.'
      using errcode = 'P0002';
  end if;
  if public.field_unit_has_work(p_opening_id) then
    raise exception 'Somebody has already worked this one, so it cannot be merged away. Keep it and rename it instead.'
      using errcode = '42501';
  end if;

  -- A missed unit that has been renamed answers to a real code of its own, so
  -- "merge into <that code>" would otherwise find ITSELF: attachments repointed
  -- to the same row, a job note reading "W-14 turned out to be W-14", and then
  -- the row and its spec deleted. The list on the sheet never offers it; the
  -- refusal belongs in SQL like every other refusal in this file, because the
  -- RPC is granted to every signed-in account.
  if v_code = v_row.opening_code then
    raise exception 'That is the name this one already has — rename it instead.'
      using errcode = '22023';
  end if;

  select * into v_target from project_openings
   where project_id = v_row.project_id and opening_code = v_code
     and removed_at is null and id <> p_opening_id
   limit 1;
  if not found then
    raise exception 'There is no % on this job to merge it into.', v_code using errcode = 'P0002';
  end if;

  -- The photo is the evidence, so it follows the unit it was really about.
  update attachments set project_opening_id = v_target.id
   where project_opening_id = p_opening_id;

  update issues
     set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
   where opening_id = p_opening_id and status = 'open';

  insert into job_notes (project_id, author_id, author_name, note)
  select v_row.project_id, auth.uid(),
         (select display_name from profiles where id = auth.uid()),
         v_row.opening_code || ' turned out to be ' || v_target.opening_code || ' — merged.';

  -- ONLY THE ROW THIS FEATURE CREATED. A merge used to delete any spec whose
  -- mark_code matched the unit's current code — and after a rename that code is
  -- a REAL mark, whose spec is the manufacturer's: style, glass, size code,
  -- u-factor, the drawing coordinates, possibly confirmed by a foreman, and
  -- read by every other opening of that mark. project_mark_specs has no soft
  -- delete, so it would simply be gone. Three fences: it must be ours
  -- (source 'field'), nobody may have confirmed it, and no other live opening
  -- may still resolve to that mark.
  delete from project_mark_specs s
   where s.project_id = v_row.project_id
     and upper(s.mark_code) = upper(public.mark_base(v_row.opening_code))
     and s.source = 'field'
     and coalesce(s.confirmed, false) = false
     and not exists (
       select 1 from project_openings o
        where o.project_id = v_row.project_id
          and o.id <> p_opening_id
          and o.removed_at is null
          and upper(public.mark_base(o.opening_code))
              = upper(public.mark_base(v_row.opening_code))
     );
  delete from project_openings where id = p_opening_id;

  return public._work_activity_finish(__work_activity_root_id,(v_target)::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_151$::text,false,'f57be2996ffb4bf1987e95df0d8b40e52ea8567e7b6d7048373ac3d982a1e03e'::text,'4c0f72eed0a453c0db4aa6776b0eb3ad69489cdf4a58342e96658becf95d3c37'::text,'merge_field_unit'::text,'p_opening_id uuid, p_into_code text'::text),
('remove_field_unit(uuid, text)'::text,$activity_body_152$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('remove_field_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_row project_openings;
begin
  if public.my_role_rank() < 2 then
    raise exception 'Only a supervisor or above can take a missed window or door back off.'
      using errcode = '42501';
  end if;

  select * into v_row from project_openings where id = p_opening_id;
  if not found or not v_row.field_added then
    raise exception 'That is not a missed window or door added from the field.'
      using errcode = 'P0002';
  end if;
  if public.field_unit_has_work(p_opening_id) then
    raise exception 'Somebody has already worked this one, so it stays on the job. Keep it and rename it instead.'
      using errcode = '42501';
  end if;

  -- The ordinary soft delete: hidden, never destroyed, and restorable from the
  -- removed list like any other window a foreman takes off.
  return public._work_activity_finish(__work_activity_root_id,(public.remove_opening(p_opening_id, coalesce(p_reason, 'Missed unit withdrawn')))::project_openings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_152$::text,false,'51d791569722b0d70a5e99ea6fa47d68b56e3eacef09836f56c5fd42365cb36a'::text,'032ccc06817102316eae7d3c69dfb022cbd797c916fdc05a3790fbc9075c865f'::text,'remove_field_unit'::text,'p_opening_id uuid, p_reason text'::text),
('set_profile_grants(uuid, boolean, boolean)'::text,$activity_body_153$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_profile_grants','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_is_partner boolean;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can change who sees costs.'
      using errcode = '42501';
  end if;

  select p.is_partner into v_is_partner from public.profiles p where p.id = p_profile_id;
  if not found then
    raise exception 'That person is not on the crew list.';
  end if;
  -- THE WALL (20260950000000) already ANDs `not is_partner_user()` into every
  -- money policy, so a granted partner would read nothing anyway. Refusing here
  -- as well means nobody ever has to work that out from two files: a builder's
  -- login cannot be handed the company's books, full stop.
  if coalesce(v_is_partner, false) then
    raise exception 'A builder login can never be given the company''s costs.'
      using errcode = '42501';
  end if;

  return query
  update public.profiles p
     set can_see_costs = coalesce(p_costs, p.can_see_costs),
         can_see_pay   = coalesce(p_pay, p.can_see_pay),
         updated_at    = now()
   where p.id = p_profile_id
  returning p.id, p.can_see_costs, p.can_see_pay;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_153$::text,false,'7c814bf6040068fbeedd97c17dae111415f34abaf0cb98701d25f2fb05236cb4'::text,'7f9f75568c1ccdc9411afbdce850f3082bf6a2c4cff63a93b5e53a11eae13dbc'::text,'set_profile_grants'::text,'p_profile_id uuid, p_costs boolean, p_pay boolean'::text),
('set_projects_order(uuid[])'::text,$activity_body_154$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_projects_order','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
begin
  if not _is_lead(auth.uid()) then
    raise exception 'Only a foreman or above can reorder the jobs list.';
  end if;
  if p_ids is null or array_length(p_ids, 1) is null then
    perform public._work_activity_operation_exit(__work_activity_root_id); return;
  end if;

  update projects p
     set sort_order = o.position
    from (
      select id, ordinality::int as position
      from unnest(p_ids) with ordinality as u(id, ordinality)
    ) as o
   where p.id = o.id;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_154$::text,false,'4709a62175a868b618f448d92c5cbec39b21c95bdd86fbb0ad559ea2a3e4865c'::text,'a58d7f4baa3603ebd670d4de93f9c5282bea51144f07f9e69a9ba46aa4e1c7f1'::text,'set_projects_order'::text,'p_ids uuid[]'::text),
('set_project_gc_brand(uuid, text)'::text,$activity_body_155$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_project_gc_brand','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
begin
  if not _is_lead(auth.uid()) then
    raise exception 'Only a foreman or above can choose which name the GC sees.';
  end if;
  if coalesce(p_brand, '') not in ('stg', 'forge') then
    raise exception 'The GC sees us as STG Windows & Doors or as Forge Windows and Doors — nothing else.';
  end if;

  update projects set gc_brand = p_brand where id = p_project_id
  returning * into v_row;

  if not found then
    raise exception 'That job does not exist.';
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_155$::text,false,'be0f005dfa01cd591d8e1d6083713adae3c83075ac9ea353ecb2c71d63a51f1c'::text,'6e99cdf447abdbceadccb0878ed22a59e3143e505c44099ecb95788c9d5dcf0b'::text,'set_project_gc_brand'::text,'p_project_id uuid, p_brand text'::text),
('submit_install_event(uuid, text, integer, integer, text, text, text, text, text, text, text, text, text, timestamp with time zone, uuid, integer, uuid)'::text,$activity_body_156$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_opening project_openings;
  v_event install_events;
  v_actor uuid := auth.uid();
  v_profile uuid := coalesce(p_installer_id, auth.uid());
  v_credited uuid;
  v_refusal text;
begin
  select * into v_opening from project_openings where id = p_opening_id;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  if _flashing_outstanding(p_opening_id) then
    raise exception 'this opening needs flashing submitted before the install is filed';
  end if;

  -- p_installer_id has always been able to name somebody else, and doing so
  -- has always meant "file it as them". From wave Y that IS a credit, so it
  -- answers to the credit rule like every other one — otherwise the rule below
  -- would be one argument away from being no rule at all.
  v_refusal := public.credit_refusal(p_opening_id, nullif(v_profile, v_actor));
  if v_refusal is not null then
    raise exception '%', v_refusal using errcode = '42501';
  end if;

  v_refusal := public.credit_refusal(p_opening_id, nullif(p_credited_to, v_actor));
  if v_refusal is not null then
    raise exception '%', v_refusal using errcode = '42501';
  end if;

  -- Crediting the filer is what NULL already means. Storing it twice would
  -- give the same fact two spellings and every reader a choice to get wrong.
  v_credited := nullif(p_credited_to, v_profile);

  insert into install_events (
    project_opening_id, window_id, window_type_id, installer, installer_id,
    credited_to, started_at, minutes, estimate_minutes, quality_grade,
    difficulty, went_well, went_poorly, obstacles, tools_helped,
    time_vs_estimate, safety_notes, do_again, transcript_raw
  ) values (
    v_opening.id, v_opening.assigned_window_id, v_opening.window_type_id,
    p_installer, v_profile, v_credited, p_started_at, p_minutes,
    p_estimate_minutes, p_quality_grade, p_difficulty, p_went_well, p_went_poorly,
    p_obstacles, p_tools_helped, p_time_vs_estimate, p_safety_notes, p_do_again,
    p_transcript_raw
  )
  returning * into v_event;

  update project_openings
  set status = 'installed', confirmed = true, work_ended_at = now()
  where id = v_opening.id;

  if v_opening.assigned_window_id is not null then
    perform install_window(v_opening.assigned_window_id, p_installer);
  end if;

  -- Task-time follows the FILER, not the credited person: whoever is standing
  -- here is the one who is now between windows. Sessions follow the human.
  if v_profile is not null then
    perform close_open_task_sessions(v_profile);
    insert into task_sessions (profile_id, opening_id, project_id, state)
    values (v_profile, null, v_opening.project_id, 'off_task');
  end if;

  return v_event;
end;

end;
$activity_body_156$::text,false,'0fcdc2f941c880c5971cac2dd63045b95ec1eb0cb2769c5a55c1eca8eaf256cb'::text,'40bd9237c52f9ce0abcc5ec9731fc0533faabc436ee568e32348624a84b47661'::text,'submit_install_event'::text,'p_opening_id uuid, p_installer text, p_minutes integer, p_quality_grade integer, p_difficulty text, p_went_well text, p_went_poorly text, p_obstacles text, p_tools_helped text, p_time_vs_estimate text, p_safety_notes text, p_do_again text, p_transcript_raw text, p_started_at timestamp with time zone, p_installer_id uuid, p_estimate_minutes integer, p_credited_to uuid'::text),
('finish_unit(uuid, uuid, text, integer, text, text, text, text, text, text, text, text, text, uuid, integer, uuid)'::text,$activity_body_157$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('finish_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_minutes int;
  v_started timestamptz;
  v_event install_events;
  v_tiers int;
begin
  -- Close the caller's open session on this unit first so it counts. THE
  -- CALLER'S — crediting somebody else does not reach into their clock, and a
  -- finish filed for Sam still ends the session of whoever is standing here.
  update unit_sessions
  set ended_at = now(), end_reason = 'finish'
  where profile_id = v_uid and ended_at is null and opening_id = p_opening_id;

  -- Session-derived figures for THIS round: sessions since the last
  -- non-voided event ON THIS UNIT (all of them for a first install). The
  -- column is `project_opening_id`; a bare `opening_id` here resolves to the
  -- outer unit_sessions row instead and picks the newest install on the whole
  -- database (2026-09-02).
  select coalesce(sum(least(480,
           greatest(0, floor(extract(epoch from (ended_at - started_at)) / 60)))), 0)::int,
         min(started_at)
  into v_minutes, v_started
  from unit_sessions
  where opening_id = p_opening_id and ended_at is not null
    and started_at > coalesce(
      (select max(created_at) from install_events
       where project_opening_id = p_opening_id and voided_at is null),
      '-infinity'::timestamptz);

  v_event := submit_install_event(
    p_opening_id, p_installer, nullif(v_minutes, 0), p_quality_grade,
    p_difficulty, p_went_well, p_went_poorly, p_obstacles, p_tools_helped,
    p_time_vs_estimate, p_safety_notes, p_do_again, p_transcript_raw,
    v_started, p_installer_id, p_estimate_minutes, p_credited_to);

  -- Finishing resolves the unit's open redo, if any.
  update unit_redos
  set resolved_at = now()
  where opening_id = p_opening_id and resolved_at is null;

  -- The CHAIN — suppressed on multi-tier units (signature tiers > 1) and
  -- never allowed to sink the submit: a refused start (flashing owed on
  -- the next unit) leaves the finish standing.
  select coalesce(jsonb_array_length(signature -> 'tiers'), 1)
  into v_tiers from project_openings where id = p_opening_id;
  if p_next_opening_id is not null and coalesce(v_tiers, 1) <= 1 then
    begin
      perform start_unit_session(p_next_opening_id, 'install');
    exception when others then
      null; -- next starts by hand
    end;
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_event)::install_events);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_157$::text,false,'128071e45e7c88285295cfce2c8a1e7ec1b3e90a99a7d3f5db520e2465545cd8'::text,'6933bff557a6052d932a65064f3cc7b4fa59f39e1c0e434131ea394c9d4e7198'::text,'finish_unit'::text,'p_opening_id uuid, p_next_opening_id uuid, p_installer text, p_quality_grade integer, p_difficulty text, p_went_well text, p_went_poorly text, p_obstacles text, p_tools_helped text, p_time_vs_estimate text, p_safety_notes text, p_do_again text, p_transcript_raw text, p_installer_id uuid, p_estimate_minutes integer, p_credited_to uuid'::text),
('assign_opening_to_installer(uuid, uuid, uuid, integer, text)'::text,$activity_body_158$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  v_opening project_openings;
begin
  -- No JWT is the service role or a migration, not a phone; the key is the
  -- fence there.
  if auth.uid() is not null and not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can hand out work.'
      using errcode = '42501';
  end if;

  -- Which screen this came from, for the history row the trigger writes.
  -- Transaction-local, so it can never leak into the next request.
  perform set_config('app.assignment_via', coalesce(p_via, 'dispatch'), true);

  update project_openings
  set assigned_to = p_profile_id,
      assigned_by = p_actor_id,
      assigned_at = now(),
      sequence = coalesce(p_sequence, sequence)
  where id = p_opening_id
  returning * into v_opening;

  if v_opening is null then
    raise exception 'That window or door is not on this job.' using errcode = 'P0002';
  end if;
  return v_opening;
end;

end;
$activity_body_158$::text,false,'288f35ff2a2d7d7740462ae2a5d9fc152949aaf4e3fdb7059fa604e1e22e8461'::text,'8eba9e6ee4459fb093ce7cb5234aab8aae92844c3d942ebfde3efa80e0b5718a'::text,'assign_opening_to_installer'::text,'p_opening_id uuid, p_profile_id uuid, p_actor_id uuid, p_sequence integer, p_via text'::text),
('_file_group_toolbox_signin(uuid, uuid)'::text,$activity_body_159$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_file_group_toolbox_signin','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_day date := (now() at time zone 'America/Denver')::date;
  v_talk uuid;
begin
  -- Already covered for today — by their own signature, or by an earlier
  -- group sign-in this morning. Never a second row: the gate is satisfied,
  -- and a duplicate would make the compliance list say two people signed.
  if exists (
    select 1 from toolbox_completions tc
     where tc.profile_id = p_profile_id
       and (tc.signed_at at time zone 'America/Denver')::date = v_day
  ) then
    perform public._work_activity_operation_exit(__work_activity_root_id); return;
  end if;

  -- Today's talk, if there is one. A company that has not published one yet
  -- still gets a dated record of the attestation, with no talk attached —
  -- talk_id is nullable and always has been.
  select st.id into v_talk
    from safety_talks st
   where st.talk_date = v_day
   order by st.created_at desc
   limit 1;

  insert into toolbox_completions
    (talk_id, profile_id, signed_at, typed_name, signed_by, signed_via)
  values
    (v_talk, p_profile_id, now(), null, p_by, 'group');
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_159$::text,false,'167489f6cba67ca8f9937863b26c0a2cb02dca8e60d87e4ecba9c4b60a0a5465'::text,'2324cb57c68a748cfd36c866f6edee1880a6a5fe84db8d699dedb2ba1b5cc8ae'::text,'_file_group_toolbox_signin'::text,'p_profile_id uuid, p_by uuid'::text),
('clock_in_for(uuid, uuid, uuid, text, text, boolean, boolean)'::text,$activity_body_160$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_in_for','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_person profiles;
  v_project projects;
  v_open time_shifts;
  v_shift time_shifts;
  v_mode text;
  v_outcome text := 'clocked_in';
  v_moved_from text;
begin
  -- ---- who is asking ------------------------------------------------------
  if v_actor is null then
    raise exception 'Sign in before clocking anybody in.' using hint = 'crew-clock';
  end if;
  -- A builder/GC login is pinned to 'installer' (20260950000000), so the rank
  -- check below already refuses it. Said out loud anyway: this function is
  -- SECURITY DEFINER and writes straight past every policy on time_shifts, so
  -- the wall has to stand in the body, not only on the table.
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501', hint = 'crew-clock';
  end if;
  if not _is_supervisor(v_actor) then
    raise exception 'Only a supervisor or above can clock somebody else in.' using hint = 'crew-clock';
  end if;
  if not coalesce(p_talk_attested, false) then
    raise exception 'Give today''s toolbox talk first, then tick the box to say you did.' using hint = 'crew-clock';
  end if;

  -- ---- who is being clocked in -------------------------------------------
  select * into v_person from profiles where id = p_profile_id;
  if not found then
    raise exception 'That person is not on the crew list.' using hint = 'crew-clock';
  end if;
  if not coalesce(v_person.active, false) then
    raise exception 'They are not an active crew member.' using hint = 'crew-clock';
  end if;
  if coalesce(v_person.is_partner, false) then
    raise exception 'That is a builder login, not a crew member.' using hint = 'crew-clock';
  end if;

  -- ---- the job ------------------------------------------------------------
  select * into v_project from projects where id = p_project_id;
  if not found or v_project.deleted_at is not null then
    raise exception 'That job is not there any more.' using hint = 'crew-clock';
  end if;
  if v_project.status is distinct from 'active' then
    raise exception '% is not an active job, so nobody can put time on it.', v_project.job_code
      using hint = 'crew-clock';
  end if;

  -- ---- the cost code ------------------------------------------------------
  if p_cost_code_id is null then
    raise exception 'Pick a cost code before clocking anybody in.' using hint = 'crew-clock';
  end if;
  if not exists (
    select 1 from cost_codes cc where cc.id = p_cost_code_id and cc.active
  ) then
    raise exception 'That cost code is not in use any more.' using hint = 'crew-clock';
  end if;
  -- The same rule resolveClockCostCodes plays by on the phone (20260973000000):
  -- a job with its own subset allows only those codes, a job without one allows
  -- the whole active library, and the general catch-all is allowed either way
  -- so nobody is ever left with nothing valid to charge to.
  if exists (
        select 1 from project_cost_codes pcc where pcc.project_id = p_project_id
      )
     and not exists (
        select 1 from project_cost_codes pcc
         where pcc.project_id = p_project_id and pcc.cost_code_id = p_cost_code_id
      )
     and not exists (
        select 1 from cost_codes cc where cc.id = p_cost_code_id and cc.is_general
      )
  then
    raise exception 'That cost code is not one % uses.', v_project.job_code using hint = 'crew-clock';
  end if;

  -- ---- the mode -----------------------------------------------------------
  v_mode := case when p_mode in ('data', 'tracking') then p_mode else null end;
  if v_mode is not null and not (v_mode = any (v_project.allowed_modes)) then
    raise exception '% is not set up for % work.', v_project.job_code, v_mode
      using hint = 'crew-clock';
  end if;

  -- ---- are they already on the clock? -------------------------------------
  select * into v_open
    from time_shifts ts
   where ts.profile_id = p_profile_id
     and ts.status = 'open'
     and ts.clock_out_at is null
   order by ts.clock_in_at desc
   limit 1;

  if found then
    if v_open.project_id is not distinct from p_project_id then
      -- Already exactly where this call wanted them. Opening a second punch
      -- would split one day into two and double nothing but the paperwork.
      return public._work_activity_finish(__work_activity_root_id,((p_profile_id, 'already_on_this_job')::crew_clock_result)::crew_clock_result);
    end if;
    select pj.job_code into v_moved_from from projects pj where pj.id = v_open.project_id;
    if not coalesce(p_move_if_elsewhere, false) then
      raise exception 'Already on %. Tick "Move anyone already on another job here" to bring them over.',
        coalesce(v_moved_from, 'another job') using hint = 'crew-clock';
    end if;
    v_outcome := 'moved_from_other_job';
  end if;

  select p.display_name into v_actor_name from profiles p where p.id = v_actor;
  v_actor_name := coalesce(v_actor_name, 'a supervisor');

  -- ---- the safety talk ----------------------------------------------------
  -- Files a group sign-in for anybody not already covered today, which is what
  -- makes the gate below pass honestly rather than being bypassed.
  perform public._file_group_toolbox_signin(p_profile_id, v_actor);

  -- ---- close whatever was running ----------------------------------------
  -- The shared close every clock_in overload calls (20260945000000): a
  -- believable punch is closed at __work_activity_arrival and marked auto-closed; one that ran
  -- past the cap is put into needs_finish rather than given a made-up end.
  perform _close_dangling_shift(p_profile_id);

  if v_open.id is not null then
    -- Say who ended it, and log it, for the same reason the new punch does:
    -- a move is a clock-out somebody else performed.
    update time_shifts ts
       set clocked_out_by = v_actor
     where ts.id = v_open.id
       and ts.clock_out_at is not null
       and ts.clocked_out_by is null;

    insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
    select v_open.id, v_actor, 'clock_out', null, ts.clock_out_at::text,
           'clocked out by ' || v_actor_name || ' from the roster, moving them to '
             || v_project.job_code
      from time_shifts ts
     where ts.id = v_open.id
       and ts.clock_out_at is not null;
  end if;

  -- ---- the punch ----------------------------------------------------------
  insert into time_shifts
    (profile_id, project_id, cost_code_id, note, job_mode, clocked_in_by)
  values
    (p_profile_id, p_project_id, p_cost_code_id,
     nullif(btrim(p_note), ''), v_mode, v_actor)
  returning * into v_shift;

  -- ---- the audit trail, and with it the worker's own notice ---------------
  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (v_shift.id, v_actor, 'clock_in', null, v_shift.clock_in_at::text,
          'clocked in by ' || v_actor_name || ' from the roster');

  return public._work_activity_finish(__work_activity_root_id,((p_profile_id, v_outcome)::crew_clock_result)::crew_clock_result);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_160$::text,false,'75d08ea8fa7cfba157670aa75eb6d22d912a61a736b98fbfb449ef4f49dd3f39'::text,'d1fee42e7d70feaa48c33839400849f91e8ebfdd768447bf6684e5fb534b31ad'::text,'clock_in_for'::text,'p_profile_id uuid, p_project_id uuid, p_cost_code_id uuid, p_note text, p_mode text, p_talk_attested boolean, p_move_if_elsewhere boolean'::text),
('clock_out_for(uuid)'::text,$activity_body_161$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_out_for','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_open time_shifts;
  v_shift time_shifts;
begin
  if v_actor is null then
    raise exception 'Sign in before clocking anybody out.' using hint = 'crew-clock';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501', hint = 'crew-clock';
  end if;
  if not _is_supervisor(v_actor) then
    raise exception 'Only a supervisor or above can clock somebody else out.' using hint = 'crew-clock';
  end if;

  select * into v_open
    from time_shifts ts
   where ts.profile_id = p_profile_id
     and ts.clock_out_at is null
     and ts.status in ('open', 'needs_finish')
   order by ts.clock_in_at desc
   limit 1;

  if not found then
    -- Not an error and not a refusal: a bulk call sweeps up whoever is on the
    -- clock, and "they were already off" is a perfectly good thing to report.
    return public._work_activity_finish(__work_activity_root_id,((p_profile_id, 'already_out')::crew_clock_result)::crew_clock_result);
  end if;

  if v_open.status = 'needs_finish' then
    -- The app already refused to guess an end for this one. Stamping now()
    -- here would be that same guess, made by somebody who was not there.
    raise exception 'Their punch ran too long to guess an end for. Set the real finish time on "Still on the clock".'
      using hint = 'crew-clock';
  end if;

  select p.display_name into v_actor_name from profiles p where p.id = v_actor;
  v_actor_name := coalesce(v_actor_name, 'a supervisor');

  update time_shifts ts
     set clock_out_at = now(),
         break_seconds = ts.break_seconds + case
           when ts.break_started_at is not null
             then greatest(0, floor(extract(epoch from (now() - ts.break_started_at)))::int)
           else 0
         end,
         break_started_at = null,
         break_type = null,
         signed_at = now(),
         status = 'submitted',
         clocked_out_by = v_actor
   where ts.id = v_open.id
  returning * into v_shift;

  insert into time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (v_shift.id, v_actor, 'clock_out', null, v_shift.clock_out_at::text,
          'clocked out by ' || v_actor_name || ' from the roster');

  return public._work_activity_finish(__work_activity_root_id,((p_profile_id, 'clocked_out')::crew_clock_result)::crew_clock_result);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_161$::text,false,'b16a08189bc4307d7cf90722e149ee8cbae1d28c3395fa3fa8089cebaf76e162'::text,'4a6998e216099c1b8df1e32829826c9e8d8357454d6f223e07b23df62024a371'::text,'clock_out_for'::text,'p_profile_id uuid'::text),
('clock_in_many(uuid[], uuid, uuid, text, text, boolean, boolean)'::text,$activity_body_162$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_in_many','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_hint text;
begin
  -- The whole-call refusals are checked ONCE, up front, and thrown rather than
  -- returned: "you are not allowed to do this" and "you have not said you gave
  -- the talk" are facts about the request, not fourteen separate outcomes.
  if auth.uid() is null then
    raise exception 'Sign in before clocking anybody in.' using hint = 'crew-clock';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501', hint = 'crew-clock';
  end if;
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or above can clock somebody else in.' using hint = 'crew-clock';
  end if;
  if not coalesce(p_talk_attested, false) then
    raise exception 'Give today''s toolbox talk first, then tick the box to say you did.' using hint = 'crew-clock';
  end if;

  for v_id in
    select distinct u from unnest(coalesce(p_profile_ids, '{}'::uuid[])) as u
  loop
    begin
      return next public.clock_in_for(
        v_id, p_project_id, p_cost_code_id, p_note, p_mode,
        p_talk_attested, p_move_if_elsewhere);
    exception when others then
      -- Only a refusal this file WROTE is repeated to a supervisor. Everything
      -- else caught here is an accident — a check constraint, a trigger, a
      -- deadlock — and sqlerrm for those is raw Postgres wording, which is the
      -- one thing an installer-facing app must never put on a screen. It is
      -- logged instead, where whoever is fixing it can read it.
      get stacked diagnostics v_hint = pg_exception_hint;
      if v_hint is distinct from 'crew-clock' then
        raise warning 'clock_in_many: unexpected error for %: % (%)',
          v_id, sqlerrm, sqlstate;
        return next (
          v_id,
          'refused:Something went wrong for this person. Try again, or clock them in from their own phone.'
        )::crew_clock_result;
      else
        return next (v_id, 'refused:' || sqlerrm)::crew_clock_result;
      end if;
    end;
  end loop;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_162$::text,false,'cf97143288c44d7833bbca72d8cf49c9acbf913b48c122ffe3c56536d4a6a672'::text,'65cd6a34c9cc84cbaac84f1d0855a700bf427f648ce4b09957c85b9a23494eac'::text,'clock_in_many'::text,'p_profile_ids uuid[], p_project_id uuid, p_cost_code_id uuid, p_note text, p_mode text, p_talk_attested boolean, p_move_if_elsewhere boolean'::text),
('clock_out_many(uuid[])'::text,$activity_body_163$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_out_many','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_hint text;
begin
  if auth.uid() is null then
    raise exception 'Sign in before clocking anybody out.' using hint = 'crew-clock';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501', hint = 'crew-clock';
  end if;
  if not _is_supervisor(auth.uid()) then
    raise exception 'Only a supervisor or above can clock somebody else out.' using hint = 'crew-clock';
  end if;

  for v_id in
    select distinct u from unnest(coalesce(p_profile_ids, '{}'::uuid[])) as u
  loop
    begin
      return next public.clock_out_for(v_id);
    exception when others then
      -- Same rule as clock_in_many: our own sentence, or one generic line.
      get stacked diagnostics v_hint = pg_exception_hint;
      if v_hint is distinct from 'crew-clock' then
        raise warning 'clock_out_many: unexpected error for %: % (%)',
          v_id, sqlerrm, sqlstate;
        return next (
          v_id,
          'refused:Something went wrong for this person. Try again, or clock them out from their own phone.'
        )::crew_clock_result;
      else
        return next (v_id, 'refused:' || sqlerrm)::crew_clock_result;
      end if;
    end;
  end loop;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_163$::text,false,'d3397d93fa705654bcfe9192413934b7a93a901aa3b82a3b9c8f832ce43e94d2'::text,'98962d1caa2d56ac1e67c7dca053053654259b93a9ef8dab0bc7b9783f33199d'::text,'clock_out_many'::text,'p_profile_ids uuid[]'::text),
('reassign_package(uuid, uuid, text, text)'::text,$activity_body_164$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('reassign_package','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row packages;
  v_code text;
  v_mark uuid;
  v_old_marks text;
  v_old_job text;
  v_new_job text;
  v_issue uuid;
  v_before jsonb;
  v_movement uuid;
begin
  -- Warehouse work is crew work (ADR-0007): signed in, and not a builder
  -- login, is the whole door.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;

  select p.* into v_row from packages p where p.id = p_package;
  if not found then
    raise exception 'package not found';
  end if;
  if v_row.status = 'blank' then
    raise exception 'that sticker is not on a package yet — tag it first';
  end if;

  v_code := upper(trim(coalesce(p_mark, '')));
  if p_project is null then
    -- Back to the Boneyard: company stock no job owns has no window number,
    -- because a window number is a position on one job's plans.
    v_code := '';
  else
    if not exists (select 1 from projects where id = p_project and deleted_at is null) then
      raise exception 'job not found';
    end if;
    if v_code = '' then
      raise exception 'pick the window this package becomes part of';
    end if;
    if length(v_code) > 12 then
      raise exception 'a window number is 1 to 12 characters';
    end if;
  end if;

  select string_agg(pm2.mark_code, ', ' order by pm2.mark_code) into v_old_marks
  from package_marks pm
  join project_marks pm2 on pm2.id = pm.mark_id
  where pm.package_id = p_package;

  -- Nothing to do: same job, same single window. No movement line for a
  -- non-event — the history stays a history of things that happened.
  if v_row.project_id is not distinct from p_project
     and coalesce(v_old_marks, '') = v_code then
    return public._work_activity_finish(__work_activity_root_id,(null)::uuid);
  end if;

  v_before := jsonb_build_object(
    'project_id', v_row.project_id,
    'pending_job_name', v_row.pending_job_name,
    'pending_issue_id', v_row.pending_issue_id,
    'marks', coalesce((
      select jsonb_agg(pm2.mark_code order by pm2.mark_code)
      from package_marks pm
      join project_marks pm2 on pm2.id = pm.mark_id
      where pm.package_id = p_package
    ), '[]'::jsonb)
  );
  v_issue := v_row.pending_issue_id;

  if p_project is not null then
    -- A window not on the schedule yet is added in the same step (the tag
    -- screen's "Add window N" button, folded in — a door that sends you to
    -- another screen to add the window first is the friction this removes).
    insert into project_marks (project_id, mark_code)
    values (p_project, v_code)
    on conflict (project_id, mark_code) do nothing;
    select id into v_mark
    from project_marks
    where project_id = p_project and mark_code = v_code;
  end if;

  update packages
  set project_id = p_project,
      pending_job_name = null,
      pending_issue_id = null
  where id = p_package;

  delete from package_marks where package_id = p_package;
  if v_mark is not null then
    insert into package_marks (package_id, mark_id)
    values (p_package, v_mark)
    on conflict do nothing;
  end if;

  select job_code into v_old_job from projects where id = v_row.project_id;
  select job_code into v_new_job from projects where id = p_project;

  insert into movements (package_id, event, project_id, actor, reason, before)
  values (
    p_package, 'assigned', p_project, auth.uid()::text,
    'moved from '
      || coalesce(v_old_job, nullif(v_row.pending_job_name, ''), 'the Boneyard')
      || case when v_old_marks is null then '' else ' window ' || v_old_marks end
      || ' to '
      || coalesce(v_new_job, 'the Boneyard')
      || case when v_code = '' then '' else ' window ' || v_code end
      || case when nullif(trim(coalesce(p_reason, '')), '') is null then ''
              else ' — ' || trim(p_reason) end,
    v_before
  )
  returning id into v_movement;

  -- A missing_job issue resolves when its last waiting package files —
  -- byte-for-byte the rule assign_package_to_job and file_pending_packages
  -- follow.
  if v_issue is not null and not exists (
    select 1 from packages
    where pending_issue_id = v_issue and project_id is null
  ) then
    update issues
       set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
     where id = v_issue and status = 'open';
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_movement)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_164$::text,false,'80a40fe6c39edae514ba2ea1bbbea50b08a44500a76ce5ab6aa911c0b18ced3c'::text,'0dd9575fd1a3ce347024dfb1f4814acd6ab859e381f1df81b4c997120d32421d'::text,'reassign_package'::text,'p_package uuid, p_project uuid, p_mark text, p_reason text'::text),
('undo_movement(uuid)'::text,$activity_body_165$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('undo_movement','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_m movements;
  v_p packages;
  v_mine boolean;
  v_before jsonb;
  v_mark_code text;
  v_mark uuid;
  v_new uuid;
  v_status text;
  v_container uuid;
  v_location uuid;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;

  select m.* into v_m from movements m where m.id = p_movement;
  if not found then
    raise exception 'that history line no longer exists';
  end if;
  if v_m.undoes is not null then
    raise exception 'that line is itself an undo — nothing to undo';
  end if;
  if exists (select 1 from movements where undoes = p_movement) then
    raise exception 'that was already undone';
  end if;
  if v_m.package_id is null then
    raise exception 'only a package''s own history can be undone here';
  end if;

  -- The person who did it may undo it the same day. A foreman may undo any
  -- line at any time. Client mirror: lib/warehouse/undo.ts (keep in step).
  v_mine := v_m.actor = auth.uid()::text
            and v_m.created_at > now() - interval '24 hours';
  if not v_mine and not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only the person who did this can undo it today. A foreman can undo it any time.'
      using errcode = '42501';
  end if;

  select p.* into v_p from packages p where p.id = v_m.package_id;
  if not found then
    raise exception 'that package is gone';
  end if;

  v_before := v_m.before;

  if v_m.event = 'assigned' then
    if v_before is null then
      raise exception 'this job change was recorded before undo existed — move it back by hand';
    end if;
    update packages
    set project_id = nullif(v_before->>'project_id', '')::uuid,
        pending_job_name = v_before->>'pending_job_name',
        pending_issue_id = nullif(v_before->>'pending_issue_id', '')::uuid
    where id = v_p.id;
    delete from package_marks where package_id = v_p.id;
    if nullif(v_before->>'project_id', '') is not null then
      for v_mark_code in select jsonb_array_elements_text(coalesce(v_before->'marks', '[]'::jsonb))
      loop
        insert into project_marks (project_id, mark_code)
        values ((v_before->>'project_id')::uuid, v_mark_code)
        on conflict (project_id, mark_code) do nothing;
        select id into v_mark from project_marks
        where project_id = (v_before->>'project_id')::uuid and mark_code = v_mark_code;
        insert into package_marks (package_id, mark_id)
        values (v_p.id, v_mark)
        on conflict do nothing;
      end loop;
    end if;

  elsif v_m.event = 'stored' then
    -- Only the most recent placement can be walked back: if the package has
    -- moved again since, this line is not what put it where it is.
    if v_p.status <> 'stored' or v_p.container_id is distinct from v_m.to_container_id then
      raise exception 'this package has moved since — undo the newer line first';
    end if;
    if v_before is not null then
      v_status := coalesce(v_before->>'status', 'received');
      v_container := nullif(v_before->>'container_id', '')::uuid;
      v_location := nullif(v_before->>'location_id', '')::uuid;
    elsif v_m.from_container_id is not null then
      v_status := 'stored'; v_container := v_m.from_container_id; v_location := null;
    elsif v_m.from_location_id is not null then
      v_status := 'stored'; v_container := null; v_location := v_m.from_location_id;
    else
      v_status := 'received'; v_container := null; v_location := null;
    end if;
    update packages
    set status = v_status, container_id = v_container, location_id = v_location, area = null
    where id = v_p.id;

  elsif v_m.event = 'checked_out' then
    if v_p.status <> 'checked_out' then
      raise exception 'this package is not checked out any more — nothing to undo';
    end if;
    if v_m.from_container_id is not null then
      v_status := 'stored'; v_container := v_m.from_container_id; v_location := null;
    elsif v_m.from_location_id is not null then
      v_status := 'stored'; v_container := null; v_location := v_m.from_location_id;
    else
      v_status := 'received'; v_container := null; v_location := null;
    end if;
    update packages
    set status = v_status, container_id = v_container, location_id = v_location, area = null
    where id = v_p.id;

  else
    raise exception 'a "%" line can''t be undone yet — fix it by hand', v_m.event;
  end if;

  select p.* into v_p from packages p where p.id = v_p.id;

  insert into movements (
    package_id, event, project_id, actor, reason, undoes,
    from_container_id, to_container_id, from_location_id, to_location_id
  )
  values (
    v_p.id, 'override', v_p.project_id, auth.uid()::text,
    'undone: ' || coalesce(v_m.reason, v_m.event),
    p_movement,
    v_m.to_container_id, v_m.from_container_id,
    v_m.to_location_id, v_m.from_location_id
  )
  returning id into v_new;

  return public._work_activity_finish(__work_activity_root_id,(v_new)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_165$::text,false,'498511bd43575cb41da655260a360452d661b04f715ed611d2328b94cfb85c20'::text,'5ee5fda880393d0fcf83cde210c00e4820f0d20400df82ccd48eadcfbb49047e'::text,'undo_movement'::text,'p_movement uuid'::text),
('copy_unit(uuid, text, integer, boolean)'::text,$activity_body_166$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('copy_unit','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_code text;
  v_mark uuid;
  v_src record;
  v_row packages;
  v_n int := 0;
  i int;
begin
  -- Warehouse work is crew work (ADR-0007): signed in, and not a builder
  -- login, is the whole door.
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if p_times is null or p_times < 1 or p_times > 20 then
    raise exception 'copy a unit 1 to 20 times at once';
  end if;

  v_code := upper(trim(coalesce(p_mark, '')));
  select id into v_mark from project_marks
  where project_id = p_project and mark_code = v_code;
  if v_mark is null then
    raise exception 'window % is not on this job''s schedule', v_code;
  end if;

  -- One representative per part slot: the unit's shape, not its twins.
  for v_src in
    select distinct on (p.part_index, coalesce(p.part_type, ''), coalesce(p.piece_count, -1))
           p.category, p.part_index, p.part_total, p.part_type, p.piece_count, p.mfr_mark
    from packages p
    join package_marks pm on pm.package_id = p.id
    where pm.mark_id = v_mark and p.status <> 'blank'
    order by p.part_index, coalesce(p.part_type, ''), coalesce(p.piece_count, -1), p.created_at
  loop
    for i in 1..p_times loop
      insert into packages
        (status, project_id, category, part_index, part_total, part_type,
         piece_count, mfr_mark, tracking, short_code, bound_at, bound_by)
      values
        ('minted', p_project, v_src.category, v_src.part_index, v_src.part_total,
         v_src.part_type, v_src.piece_count, v_src.mfr_mark,
         case when p_pooled then 'pooled' else 'serial' end,
         issue_package_short_code(), now(), auth.uid()::text)
      returning * into v_row;
      insert into package_marks (package_id, mark_id) values (v_row.id, v_mark)
      on conflict do nothing;
      insert into movements (package_id, event, project_id, actor, reason)
      values (v_row.id, 'preissued', p_project, auth.uid()::text,
              'copy ' || i || ' of ' || p_times || ' of window ' || v_code
              || case when p_pooled then ' — rides on the original''s sticker' else '' end);
      v_n := v_n + 1;
    end loop;
  end loop;

  if v_n = 0 then
    raise exception 'window % has no packages to copy yet', v_code;
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_n)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_166$::text,false,'dbd2802494c98178dd1195836b36431b3291b2a01ae7e9a0fa9dd20f50974768'::text,'4e83491fd176b168cefdcbba77d052bc198b4936b25d8282dbda2dd3cf9062bb'::text,'copy_unit'::text,'p_project uuid, p_mark text, p_times integer, p_pooled boolean'::text),
('job_bay_box(uuid)'::text,$activity_body_167$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('job_bay_box','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_code text;
begin
  select id into v_id from storage_containers
  where project_id = p_project and kind = 'bay' and active
  limit 1;
  if v_id is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_id)::uuid);
  end if;
  select job_code into v_code from projects where id = p_project;
  if v_code is null then
    raise exception 'that job does not exist';
  end if;
  insert into storage_containers (name, kind, project_id, notes)
  values (v_code || ' bay', 'bay', p_project, 'This job''s own bay: what is set aside for it waits here.')
  returning id into v_id;
  return public._work_activity_finish(__work_activity_root_id,(v_id)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_167$::text,false,'d4ce7533174776b7487ffdb307c4cb0163082f91c14cc7888f4d029d60d1723f'::text,'09b24daec8073f895ae4e2707c30391aa1a096736fd1e138ebfe64eb801bcc60'::text,'job_bay_box'::text,'p_project uuid'::text),
('create_placeholder_job(text)'::text,$activity_body_168$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('create_placeholder_job','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_name text := trim(coalesce(p_name, ''));
  v_base text;
  v_code text;
  v_n int := 1;
  v_row projects;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if v_name = '' or length(v_name) > 80 then
    raise exception 'a job name is 1 to 80 characters';
  end if;

  -- A job by this name already exists (typed the same way twice at two
  -- trucks): hand that one back rather than make a twin.
  select * into v_row from projects
  where deleted_at is null and lower(name) = lower(v_name)
  order by created_at limit 1;
  if found then
    return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
  end if;

  -- NEW-<first letters of the name>, numbered when that is taken. The
  -- office renames it from the job page; the code is a handle, not a name.
  v_base := 'NEW-' || left(upper(regexp_replace(v_name, '[^A-Za-z0-9]+', '', 'g')), 8);
  if v_base = 'NEW-' then
    v_base := 'NEW-JOB';
  end if;
  v_code := v_base;
  while exists (select 1 from projects where job_code = v_code) loop
    v_n := v_n + 1;
    v_code := v_base || '-' || v_n;
  end loop;

  insert into projects (job_code, name, notes)
  values (v_code, v_name, 'Made at the truck on ' || to_char(now(), 'YYYY-MM-DD') || ' for material that arrived before the office built the job. Rename the code and fill in the details.')
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_168$::text,false,'17769c0fc557e4e783c578622e1b48cd128dad60ae751387588bdccae0a430b1'::text,'38b687c728df2d6b069a3122473aef14635b86588aabe5b8dfd6f2f077c06246'::text,'create_placeholder_job'::text,'p_name text'::text),
('finalize_job_materials(uuid)'::text,$activity_body_169$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('finalize_job_materials','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
  v_left int;
  v_line text;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can finalize a job''s material.'
      using errcode = '42501';
  end if;

  select * into v_row from projects where id = p_project and deleted_at is null;
  if not found then
    raise exception 'that job does not exist';
  end if;
  if v_row.materials_finalized_at is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
  end if;

  select count(*) into v_left
  from packages
  where project_id = p_project and status in ('received', 'stored');
  if v_left > 0 then
    v_line := public.job_leftovers_line(p_project);
    raise exception '% package% still in the warehouse (%). Send them to the job site or move them to the Boneyard first.',
      v_left, case when v_left = 1 then ' is' else 's are' end, v_line;
  end if;

  update projects
  set materials_finalized_at = now(), materials_finalized_by = auth.uid()
  where id = p_project
  returning * into v_row;

  -- The job's bay has nothing in it (checked above); it goes quiet with the
  -- job. A fresh one is made if anything is ever set aside for it again.
  update storage_containers
  set active = false
  where project_id = p_project and kind = 'bay' and active;

  insert into movements (project_id, event, actor, reason)
  values (p_project, 'finalized', auth.uid()::text, 'unit movement finalized');

  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_169$::text,false,'e480420a864d8fcbc9c53b62673c921a7446cf55210d114db89762375fa5d323'::text,'ed27d6163c9cf62587a3f52db52c150993d45bc99d8e64419797a57b3b68c556'::text,'finalize_job_materials'::text,'p_project uuid'::text),
('reopen_job_materials(uuid)'::text,$activity_body_170$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('reopen_job_materials','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row projects;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  if not public.is_foreman_plus(auth.uid()) then
    raise exception 'Only a foreman or above can reopen a job''s material.'
      using errcode = '42501';
  end if;

  update projects
  set materials_finalized_at = null, materials_finalized_by = null
  where id = p_project and deleted_at is null
  returning * into v_row;
  if not found then
    raise exception 'that job does not exist';
  end if;

  insert into movements (project_id, event, actor, reason)
  values (p_project, 'reopened', auth.uid()::text, 'material reopened in the warehouse');

  return public._work_activity_finish(__work_activity_root_id,(v_row)::projects);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_170$::text,false,'8677f896538b35478c146e8efdd739a338434e6d5837f5a7ad8af2f53d659df3'::text,'3d84b6f532fca7c1a4d4626958e55efedcf0d7d564e865d2975b7f3443f23abd'::text,'reopen_job_materials'::text,'p_project uuid'::text),
('boneyard_job_leftovers(uuid)'::text,$activity_body_171$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('boneyard_job_leftovers','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_id uuid;
  v_n int := 0;
begin
  if auth.uid() is null then
    raise exception 'sign in first';
  end if;
  if public.is_partner_user() then
    raise exception 'Only a crew member can do warehouse work.'
      using errcode = '42501';
  end if;
  for v_id in
    select id from packages
    where project_id = p_project and status in ('received', 'stored')
  loop
    perform public.reassign_package(v_id, null, null, 'left over when the job''s material was finalized');
    v_n := v_n + 1;
  end loop;
  return public._work_activity_finish(__work_activity_root_id,(v_n)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_171$::text,false,'ba4dd80e3f94ee91536011f5e019065f6ed2bf44ac9388ba2ac27f2761cecab3'::text,'2ad514e6e366671be0f762f9091ad9cde42657d43356251fe2ab911bf25fc8cb'::text,'boneyard_job_leftovers'::text,'p_project uuid'::text),
('workflow_lock_writes()'::text,$activity_body_172$
begin
 if tg_table_schema='public' then perform pg_catalog.pg_advisory_xact_lock(7712,0);end if;
 begin
 perform pg_advisory_xact_lock(639024,1); return null;
end;

