$activity_body_172$::text,false,'928d72be48c829c9b40af31a62357c1fe44164722b30f14e55bf50783f44fd5e'::text,'c1279879ec5fe31fffccea5e163a92a21b1ae6875ebc32c29aaf2503e350738f'::text,'workflow_lock_writes'::text,''::text),
('workflow_create_plan(uuid, text, uuid[], uuid[])'::text,$activity_body_173$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('workflow_create_plan','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare project uuid; graph jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 if p_id is null or nullif(trim(p_name),'') is null or coalesce(cardinality(p_assignments),0) not between 1 and 40
 or coalesce(cardinality(p_trips),0) not between 1 and 20 then
  raise exception 'Choose work and travel drafts for one job.';
 end if;
 -- Caller supplies a UUID so retries after a lost response do not make copies.
 if exists(select 1 from public.workflow_plans where id=p_id) then
  if (select name from public.workflow_plans where id=p_id)=trim(p_name)
   and (select array_agg(assignment_id order by assignment_id) from public.workflow_plan_assignments where plan_id=p_id)=(select array_agg(x order by x) from unnest(p_assignments) x)
   and (select array_agg(trip_id order by trip_id) from public.workflow_plan_trips where plan_id=p_id)=(select array_agg(x order by x) from unnest(p_trips) x)
  then return public._work_activity_finish(__work_activity_root_id,(p_id)::uuid); end if;
  raise exception 'This request was already used for another plan.';
 end if;
 select a.project_id into project from public.schedule_assignments a where a.id=p_assignments[1];
 if project is null or (select count(*) from public.schedule_assignments where id=any(p_assignments) and project_id=project and kind='install' and status='draft')<>cardinality(p_assignments)
 or (select count(*) from public.trips where id=any(p_trips) and project_id=project and status='draft')<>cardinality(p_trips) then
  raise exception 'Choose existing unpublished work and trips for the same job.';
 end if;
 insert into public.workflow_plans(id,project_id,name,created_by) values(p_id,project,trim(p_name),auth.uid());
 insert into public.workflow_plan_assignments select p_id,x from unnest(p_assignments) x;
 insert into public.workflow_plan_trips select p_id,x from unnest(p_trips) x;
 graph:=public.workflow_snapshot(p_id);
 update public.workflow_plans set draft=graph,source_snapshot=graph where id=p_id;
 return public._work_activity_finish(__work_activity_root_id,(p_id)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_173$::text,false,'e3b40ee922429ccd10ef9889e5fc4894ecab045822cd31e089ec9f8aa136d46f'::text,'7a82827e019510bab7bb659c8f187f9d116a861427ecef9c9eb2339221fc1007'::text,'workflow_create_plan'::text,'p_id uuid, p_name text, p_assignments uuid[], p_trips uuid[]'::text),
('workflow_save_draft(uuid, bigint, jsonb)'::text,$activity_body_174$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('workflow_save_draft','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare plan public.workflow_plans; a jsonb; original jsonb; section jsonb; old_section jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 select * into strict plan from public.workflow_plans where id=p_plan for update;
 if plan.state<>'active' or plan.revision<>p_expected then raise exception 'The plan changed. Reload it before saving.' using errcode='40001'; end if;
 if jsonb_typeof(p_draft) is distinct from 'object' or pg_column_size(p_draft)>1048576 then raise exception 'That draft is not valid.'; end if;
 if (p_draft - array['assignments','trips']) is distinct from (plan.draft - array['assignments','trips'])
 or jsonb_array_length(p_draft->'assignments') is distinct from jsonb_array_length(plan.draft->'assignments')
 or jsonb_array_length(p_draft->'trips') is distinct from jsonb_array_length(plan.draft->'trips') then
  raise exception 'Keep the linked work, trips, and vehicle records in this plan.';
 end if;
 for a in select value from jsonb_array_elements(p_draft->'assignments') loop
  if jsonb_typeof(a->'members') is distinct from 'array' or (a->>'start_date')::date is null or (a->>'end_date')::date is null or (a->>'start_date')::date>(a->>'end_date')::date then raise exception 'Work needs valid dates and a crew list.'; end if;
  if a->>'end_time' is not null and ((a->>'start_time') is null or (a->>'end_time')::time <= (a->>'start_time')::time) then raise exception 'End time must be later than start time on the same day.'; end if;
  select value into original from jsonb_array_elements(plan.draft->'assignments') where value->>'id'=a->>'id';
  if original is null or (a-array['start_date','end_date','start_time','end_time','note','members']) is distinct from (original-array['start_date','end_date','start_time','end_time','note','members']) then raise exception 'The work identity cannot be changed.'; end if;
 end loop;
 for section in select value from jsonb_array_elements(p_draft->'trips') loop
  if jsonb_typeof(section->'crew') is distinct from 'array' or (section->'trip'->>'start_date')::date is null or (section->'trip'->>'end_date')::date is null or (section->'trip'->>'start_date')::date>(section->'trip'->>'end_date')::date then raise exception 'Travel needs valid dates and a crew list.'; end if;
  select value into old_section from jsonb_array_elements(plan.draft->'trips') where value->'trip'->>'id'=section->'trip'->>'id';
  if old_section is null or (section-array['trip','crew']) is distinct from (old_section-array['trip','crew'])
   or ((section->'trip')-array['name','destination','start_date','end_date','timezone','notes']) is distinct from ((old_section->'trip')-array['name','destination','start_date','end_date','timezone','notes']) then
   raise exception 'Keep the existing travel details and files. Only plan fields and crew can change here.';
  end if;
 end loop;
 -- Duplicate parent IDs must not replace another parent in a same-length list.
 if (select count(distinct value->>'id') from jsonb_array_elements(p_draft->'assignments'))<>jsonb_array_length(p_draft->'assignments')
 or (select count(distinct value->'trip'->>'id') from jsonb_array_elements(p_draft->'trips'))<>jsonb_array_length(p_draft->'trips') then raise exception 'A linked record appears twice.'; end if;
 if p_draft=plan.draft then return public._work_activity_finish(__work_activity_root_id,(plan.revision)::bigint); end if;
 update public.workflow_plans set draft=p_draft,revision=revision+1,updated_at=now() where id=p_plan returning revision into plan.revision;
 return public._work_activity_finish(__work_activity_root_id,(plan.revision)::bigint);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_174$::text,false,'f2fc57e87284ac5dcef614023d8a18dea0a603a7ef49784a60e5ca8758db0f4c'::text,'ad7d9f576bc27218cf9e1aa6797f7f718cff3b692b6096305dfcc87b16a29e40'::text,'workflow_save_draft'::text,'p_plan uuid, p_expected bigint, p_draft jsonb'::text),
('workflow_publish_plan(uuid, bigint, uuid, text, boolean, boolean)'::text,$activity_body_175$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('workflow_publish_plan','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare p public.workflow_plans; prior public.workflow_publish_requests; fingerprint text; conflicts jsonb; a jsonb; pack jsonb; member jsonb; old_members uuid[]; new_members uuid[]; result jsonb;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 if p_request is null or p_expected is null or p_review_token is null or p_cancel is null or p_allow_crew_conflicts is null then raise exception 'Review this plan before publishing.'; end if;
 fingerprint:=md5(jsonb_build_array(p_plan,p_expected,p_review_token,p_allow_crew_conflicts,p_cancel)::text);
 select * into prior from public.workflow_publish_requests where request_id=p_request;
 if found then
  if prior.fingerprint<>fingerprint then raise exception 'This publish request was already used for different changes.'; end if;
  return public._work_activity_finish(__work_activity_root_id,(prior.result)::jsonb);
 end if;
 select * into strict p from public.workflow_plans where id=p_plan for update;
 if p.state<>'active' or p.revision<>p_expected then raise exception 'The plan changed. Reload and review it again.' using errcode='40001'; end if;
 if not p_cancel and p.published_revision=p.revision then raise exception 'There are no unpublished changes.'; end if;
 conflicts:=public.workflow_conflicts(p_plan);
 if md5(p.draft::text||conflicts::text)<>p_review_token then raise exception 'Bookings changed since your review. Review the conflicts again.' using errcode='40001'; end if;
 if public.workflow_snapshot(p_plan)<>p.source_snapshot then raise exception 'A linked source changed outside this plan. Reconcile it before publishing.' using errcode='40001'; end if;
 if not p_cancel and exists(select 1 from jsonb_array_elements(conflicts) c where c->>'kind'='vehicle') then raise exception 'Resolve the vehicle double-booking before publishing.'; end if;
 if not p_cancel and jsonb_array_length(conflicts)>0 and not p_allow_crew_conflicts then raise exception 'Review and acknowledge the crew conflicts before publishing.'; end if;
 select array_agg(distinct id) into old_members from (
  select m.profile_id as id from public.schedule_assignment_members m join public.workflow_plan_assignments l on l.assignment_id=m.assignment_id where l.plan_id=p_plan
  union select m.profile_id from public.trip_crew m join public.workflow_plan_trips l on l.trip_id=m.trip_id where l.plan_id=p_plan
 ) x;
 if p_cancel then
  update public.schedule_assignments set status='canceled',updated_at=now() where id in(select assignment_id from public.workflow_plan_assignments where plan_id=p_plan);
  update public.trips set status='draft',updated_at=now() where id in(select trip_id from public.workflow_plan_trips where plan_id=p_plan);
  update public.workflow_plans set state='canceled',revision=revision+1 where id=p_plan returning * into p;
 else
  for a in select value from jsonb_array_elements(p.draft->'assignments') loop
   if (a->>'start_date')::date>(a->>'end_date')::date or jsonb_array_length(a->'members')=0 then raise exception 'Each work block needs valid dates and crew.'; end if;
   update public.schedule_assignments set start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date,
    start_time=(a->>'start_time')::time,end_time=(a->>'end_time')::time,note=a->>'note',status='published',published_at=now(),updated_at=now() where id=(a->>'id')::uuid;
   delete from public.schedule_assignment_members where assignment_id=(a->>'id')::uuid;
   for member in select value from jsonb_array_elements(a->'members') loop
    if not exists(select 1 from public.profiles where id=(member->>'profile_id')::uuid and not is_partner and active) then raise exception 'Choose active internal crew members.'; end if;
    insert into public.schedule_assignment_members(assignment_id,profile_id,role) values((a->>'id')::uuid,(member->>'profile_id')::uuid,member->>'role');
   end loop;
   update public.vehicle_project_assignments set start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date where assignment_id=(a->>'id')::uuid;
  end loop;
  for pack in select value from jsonb_array_elements(p.draft->'trips') loop
   a:=pack->'trip';
   if nullif(trim(a->>'name'),'') is null or (a->>'start_date')::date>(a->>'end_date')::date or jsonb_array_length(pack->'crew')=0 then raise exception 'Each trip needs a name, valid dates and crew.'; end if;
   if nullif(a->>'timezone','') is not null and not exists(select 1 from pg_timezone_names where name=a->>'timezone') then raise exception 'Choose a valid trip time zone.'; end if;
   update public.trips set name=a->>'name',destination=a->>'destination',start_date=(a->>'start_date')::date,end_date=(a->>'end_date')::date,
    timezone=nullif(a->>'timezone',''),notes=a->>'notes',status='published',published_at=now(),updated_at=now() where id=(a->>'id')::uuid;
   delete from public.trip_crew where trip_id=(a->>'id')::uuid;
   for member in select value from jsonb_array_elements(pack->'crew') loop
    if not exists(select 1 from public.profiles where id=(member->>'profile_id')::uuid and not is_partner and active) then raise exception 'Choose active internal crew members.'; end if;
    insert into public.trip_crew(trip_id,profile_id,role) values((a->>'id')::uuid,(member->>'profile_id')::uuid,coalesce(member->>'role','crew'));
   end loop;
  end loop;
 end if;
 -- Immutable audit, materialized instructions and the durable notification
 -- queue commit together. A network retry returns this result without replay.
 update public.workflow_plans set published_revision=revision,source_snapshot=public.workflow_snapshot(p_plan),
  draft=public.workflow_snapshot(p_plan),updated_at=now() where id=p_plan returning * into p;
 insert into public.workflow_plan_revisions(plan_id,revision,action,snapshot,actor) values(p_plan,p.revision,case when p_cancel then 'cancel' else 'publish' end,p.draft,auth.uid());
 insert into public.schedule_events(assignment_id,actor,kind,payload)
  select assignment_id,auth.uid(),case when p_cancel then 'removed' else 'published' end,
   jsonb_build_object('plan_id',p_plan,'revision',p.revision) from public.workflow_plan_assignments where plan_id=p_plan;
 select array_agg(distinct id) into new_members from (
  select m.profile_id as id from public.schedule_assignment_members m join public.workflow_plan_assignments l on l.assignment_id=m.assignment_id where l.plan_id=p_plan
  union select m.profile_id from public.trip_crew m join public.workflow_plan_trips l on l.trip_id=m.trip_id where l.plan_id=p_plan
 ) x;
 insert into public.workflow_notice_outbox(plan_id,revision,profile_id)
  select p_plan,p.revision,id from (select distinct unnest(coalesce(old_members,'{}'::uuid[])||coalesce(new_members,'{}'::uuid[])) id) x;
 result:=jsonb_build_object('plan_id',p_plan,'revision',p.revision,'state',p.state,'notifications','pending');
 insert into public.workflow_publish_requests values(p_request,p_plan,fingerprint,result,now());
 return public._work_activity_finish(__work_activity_root_id,(result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_175$::text,false,'fa07964525f9cfa6f5800e0476537778efeb5e4b66800c7810d3044d452d6021'::text,'aba03be701ace1e7685b38cd73a293651a533eafe1f01767dc2e43e96a9a3c7c'::text,'workflow_publish_plan'::text,'p_plan uuid, p_expected bigint, p_request uuid, p_review_token text, p_allow_crew_conflicts boolean, p_cancel boolean'::text),
('workflow_discard_plan(uuid, bigint)'::text,$activity_body_176$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('workflow_discard_plan','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare p public.workflow_plans;
begin
 perform public.workflow_require_manager(); perform pg_advisory_xact_lock(639024,1);
 select * into strict p from public.workflow_plans where id=p_plan for update;
 if p.revision<>p_expected or p.published_revision is not null then raise exception 'Only an unpublished plan can be disconnected.'; end if;
 delete from public.workflow_plans where id=p_plan;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_176$::text,false,'36815e7037957e583a4bf4c06c47c1076b988af3ffad308c2408e53b4b84fed2'::text,'a1e49873749fad03d12121048ed5dc668c8d6746cdcc38936bc89a7185d05c9b'::text,'workflow_discard_plan'::text,'p_plan uuid, p_expected bigint'::text),
('schedule_remove_day(uuid, date, timestamp with time zone)'::text,$activity_body_177$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare
  a public.schedule_assignments%rowtype;
  right_id uuid;
begin
  if auth.uid() is null or public.is_partner_user() or not public.travel_is_supervisor()
     or not exists (select 1 from public.profiles where id=auth.uid() and active) then
    raise exception 'Only an active owner or supervisor can remove scheduled days.';
  end if;
  if p_day is null or p_expected_updated_at is null then
    raise exception 'Choose a day and reload the assignment before removing it.';
  end if;
  -- Match connected publication's lock order, including membership/vehicle edits.
  perform pg_advisory_xact_lock(639024,1);
  select * into a from public.schedule_assignments where id=p_assignment_id for update;
  -- A retry after a lost response must not remove any additional days.
  if not found then return; end if;
  if exists (select 1 from public.workflow_plan_assignments where assignment_id=a.id) then
    raise exception 'Open the connected plan to change its work dates.';
  end if;
  if p_day < a.start_date or p_day > a.end_date then return; end if;
  if a.updated_at is distinct from p_expected_updated_at then
    raise exception 'This assignment changed. Close and reopen it before removing a day.';
  end if;
  if a.kind is distinct from 'install' then
    raise exception 'Change delivery dates from the delivery schedule.';
  end if;
  if a.start_date = a.end_date then
    delete from public.schedule_assignments where id=a.id;
  elsif p_day = a.start_date then
    update public.schedule_assignments set start_date=p_day+1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=p_day+1,end_date=a.end_date where assignment_id=a.id;
  elsif p_day = a.end_date then
    update public.schedule_assignments set end_date=p_day-1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=a.start_date,end_date=p_day-1 where assignment_id=a.id;
  else
    right_id := gen_random_uuid();
    insert into public.schedule_assignments
      (id,project_id,start_date,end_date,start_time,end_time,status,color,note,created_by,published_at,created_at,kind,created_via)
    values (right_id,a.project_id,p_day+1,a.end_date,a.start_time,a.end_time,a.status,a.color,a.note,a.created_by,a.published_at,a.created_at,a.kind,a.created_via);
    insert into public.schedule_assignment_members (assignment_id,profile_id,role,created_at)
      select right_id,profile_id,role,created_at from public.schedule_assignment_members where assignment_id=a.id;
    insert into public.vehicle_project_assignments (vehicle_id,project_id,assigned_at,note,assignment_id,start_date,end_date)
      select vehicle_id,project_id,assigned_at,note,right_id,p_day+1,a.end_date
      from public.vehicle_project_assignments where assignment_id=a.id;
    update public.schedule_assignments set end_date=p_day-1,updated_at=clock_timestamp() where id=a.id;
    update public.vehicle_project_assignments set start_date=a.start_date,end_date=p_day-1 where assignment_id=a.id;
  end if;
  insert into public.schedule_events (assignment_id,actor,kind,payload)
    values (a.id,auth.uid(),'removed',jsonb_build_object('scope','day','day',p_day,
      'previous_start_date',a.start_date,'previous_end_date',a.end_date,'remaining_assignment_id',right_id));
end;

end;
$activity_body_177$::text,false,'7d35c18c0e7bbe6c379566a0dc671d93227c668b73d9499864453c4324241762'::text,'c2c2a79e47a71ffc2c3d22401fa28dbbac3f3779da3d9e52b23f51d4351eb88c'::text,'schedule_remove_day'::text,'p_assignment_id uuid, p_day date, p_expected_updated_at timestamp with time zone'::text),
('custom_work_command(uuid, text, jsonb)'::text,$activity_body_178$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('custom_work_command','{}'::jsonb,p_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  uid uuid:=auth.uid(); c public.custom_work_commands; u public.custom_work_units;
  s public.custom_work_sessions; sh public.time_shifts; oldj jsonb; outid uuid;
  jid uuid; oid uuid; at_time timestamptz; typ public.custom_work_types;
  expected uuid; target uuid; f jsonb; finish_time timestamptz;
  v_obs jsonb; v_obs_present boolean; v_obs_is_null boolean; v_expected_fact_rev numeric;
  v_old_w numeric; v_old_h numeric; v_old_src text; v_old_area text;
  v_new_w numeric; v_new_h numeric; v_new_src text; v_new_area text;
  v_event_kind text; v_width_in numeric; v_height_in numeric; v_m_unit text; v_m_source text; v_m_ref text; v_area text;
  v_estimated boolean; v_obs_actor uuid; v_reason text; v_raw_obs jsonb; v_protected boolean;
  v_origin_project uuid; v_origin_opening uuid; v_origin_kind text; v_origin_author uuid; v_origin_is_test boolean;
  v_legacy_source text; v_legacy_area text; v_norm_source text; v_norm_area text; v_origin_live_job uuid;
  v_cur_rev_num bigint; v_cur_fact_prior public.work_unit_fact_revisions;
  v_applied_intent jsonb; v_before_snapshot jsonb;
begin
  if not public.custom_work_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid work request.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  -- Shares the lock with legacy-session inserts, preventing two surfaces/devices accruing together.
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  select * into c from public.custom_work_commands where id=p_id;
  if found then
    if c.profile_id<>uid or c.payload<>jsonb_build_object('action',p_action,'data',p_data) then raise exception 'This retry belongs to a different request.'; end if;
    return public._work_activity_finish(__work_activity_root_id,(c.result_id)::uuid);
  end if;
  if p_action='type' then
    if not public._is_lead(uid) or public.is_test_profile(uid) then raise exception 'Only foremen and above can manage shared types.'; end if;
    target:=(p_data->>'id')::uuid;
    select * into typ from public.custom_work_types where id=target for update;
    if coalesce(typ.revision,0)<>coalesce((p_data->>'revision')::int,-1) then raise exception 'This type changed. Refresh before saving.'; end if;
    oldj:=to_jsonb(typ);
    insert into public.custom_work_types(id,label,archived,revision) values(target,btrim(p_data->>'label'),coalesce((p_data->>'archived')::boolean,false),coalesce(typ.revision,0)+1)
    on conflict(id) do update set label=excluded.label,archived=excluded.archived,revision=excluded.revision;
    outid:=target;
  elsif p_action in ('unit','link') then
    target:=(p_data->>'id')::uuid;
    select * into u from public.custom_work_units where id=target for update;
    -- Refresh active-actor status after the row wait (B4): another session
    -- could have retired/revoked this account while we waited for the lock.
    if not public.custom_work_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
    jid:=nullif(p_data->>'project_id','')::uuid;
    oid:=nullif(p_data->>'opening_id','')::uuid;
    -- Current/destination context precedes operational CAS too: a hidden-job
    -- caller must not distinguish a correct unit revision from a guessed one.
    -- This applies to all unit/link edits; nondimensional author/lead role
    -- compatibility is preserved below, subject to actual source visibility.
    if (u.project_id is not null and not public._ai_job_visible(u.project_id,uid))
      or (jid is not null and not public._ai_job_visible(jid,uid)) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if oid is not null and not exists(select 1 from project_openings where id=oid and project_id=jid and removed_at is null) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if u.opening_id is not null and not exists(select 1 from project_openings where id=u.opening_id and project_id=u.project_id and removed_at is null) then
      raise exception 'Unit source is unavailable.' using errcode='42501';
    end if;
    if u.id is not null and u.created_by<>uid and not public._is_lead(uid) then raise exception 'Only the author or a foreman can edit this unit.'; end if;
    if u.id is not null and coalesce(u.revision,0)<>coalesce((p_data->>'revision')::int,-1) then raise exception 'Unit details changed. Refresh before saving.'; end if;
    -- Retained evidence belongs to a previous physical unit. Ordinary creates
    -- cannot silently adopt it; restoration needs explicit reconciliation.
    if u.id is null and (exists(select 1 from public.work_unit_fact_current where unit_id=target)
      or exists(select 1 from public.work_unit_fact_revisions where unit_id=target)) then
      raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
    end if;
    if u.id is null and coalesce((p_data->>'revision')::int,-1)<>0 then raise exception 'Unit details changed. Refresh before saving.'; end if;
    if u.project_id is not null and jid is distinct from u.project_id and not public._is_lead(uid) then raise exception 'Ask a foreman to move a record already assigned to a job.'; end if;
    if u.id is not null and (jid is distinct from u.project_id or oid is distinct from u.opening_id) and length(btrim(coalesce(p_data->>'reason','')))<3 then raise exception 'Add a short reason for assigning or linking this record.'; end if;

    -- Unit dimension observation (20261108300000). f is validated against
    -- the ORIGINAL caller shape first (B8), before any server-derived value
    -- can merge over -- and thereby hide -- an invalid supplied type.
    f:=coalesce(p_data->'facts','{}');
    perform public.validate_custom_work_facts(f);
    v_old_w:=nullif(u.facts->>'width_in','')::numeric;
    v_old_h:=nullif(u.facts->>'height_in','')::numeric;
    v_old_src:=u.facts->>'measurement_source';
    v_old_area:=u.facts->>'area_source';
    v_cur_fact_prior:=null; v_cur_rev_num:=0;
    if u.id is not null then
      select r.* into v_cur_fact_prior from public.work_unit_fact_revisions r
        join public.work_unit_fact_current cu on cu.current_revision_id=r.id
        where cu.unit_id=u.id;
      if v_cur_fact_prior.id is not null then
        if v_cur_fact_prior.unit_incarnation_epoch is distinct from public._work_unit_fact_peek_epoch('unit_incarnation',target) then
          raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
        end if;
        v_cur_rev_num:=v_cur_fact_prior.revision;
      end if;
    end if;
    v_obs_present:=p_data ? 'dimension_observation';
    v_obs:=p_data->'dimension_observation';
    v_obs_is_null:=v_obs_present and jsonb_typeof(v_obs)='null';
    v_event_kind:=null; v_width_in:=null; v_height_in:=null; v_m_unit:=null; v_m_source:=null; v_m_ref:=null; v_area:=null;
    v_estimated:=null; v_obs_actor:=null; v_reason:=null; v_raw_obs:=null; v_origin_project:=null; v_origin_opening:=null;
    v_applied_intent:=null; v_before_snapshot:=null;
    v_origin_kind:='none'; v_origin_author:=null; v_origin_is_test:=null;
    v_legacy_source:=null; v_legacy_area:=null;
    if v_obs_present and jsonb_typeof(v_obs) not in ('object','null') then
      raise exception 'Invalid dimension observation.';
    end if;
    if v_obs_present then
      -- Strict type check before extraction (B8): a numeric STRING like "1"
      -- must refuse, not silently coerce.
      if jsonb_typeof(p_data->'expected_fact_revision') is distinct from 'number' then
        raise exception 'A valid expected fact revision is required with a new observation or reset.';
      end if;
      v_expected_fact_rev:=(p_data->>'expected_fact_revision')::numeric;
      if v_expected_fact_rev<>trunc(v_expected_fact_rev) or v_expected_fact_rev<0 or v_expected_fact_rev>9007199254740991 then
        raise exception 'A valid expected fact revision is required with a new observation or reset.';
      end if;
    end if;
    if v_obs_is_null then
      if jsonb_typeof(p_data->'dimension_observation_reason') is distinct from 'string' then
        raise exception 'Add a short reason for clearing this observation.';
      end if;
      v_reason:=btrim(p_data->>'dimension_observation_reason');
      if length(v_reason) not between 3 and 500 then raise exception 'Add a short reason for clearing this observation.'; end if;
      v_event_kind:='cleared';
      f:=f-'width_in'-'height_in'-'measurement_source'-'area_source';
    elsif v_obs_present then
      select n.width_in,n.height_in,n.m_unit,n.m_source,n.m_ref into v_width_in,v_height_in,v_m_unit,v_m_source,v_m_ref
        from public._work_unit_normalize_observation(v_obs) n;
      -- Server mapping, exact per contract (B3): measured->Measured,
      -- plans->From plans, estimated->Estimated.
      v_area:=case v_m_source when 'measured' then 'Measured' when 'plans' then 'From plans' when 'estimated' then 'Estimated' end;
      v_estimated:=(v_m_source='estimated');
      v_obs_actor:=uid;
      v_event_kind:='observation';
      v_raw_obs:=jsonb_build_object('width',v_obs->'width','height',v_obs->'height','unit',v_m_unit,'source',v_m_source,'sourceReference',v_m_ref);
      -- f's own width_in/height_in/measurement_source/area_source, if
      -- present, are already known valid-typed by the pre-merge validation
      -- above (B8), so this comparison is safe rather than coercive.
      if f ? 'width_in' and (f->>'width_in')::numeric is distinct from v_width_in then raise exception 'Supplied width does not match the observation.'; end if;
      if f ? 'height_in' and (f->>'height_in')::numeric is distinct from v_height_in then raise exception 'Supplied height does not match the observation.'; end if;
      if f ? 'measurement_source' and f->>'measurement_source' is distinct from v_m_source then raise exception 'Supplied measurement source does not match the observation.'; end if;
      if f ? 'area_source' and f->>'area_source' is distinct from v_area then raise exception 'Supplied area source does not match the observation.'; end if;
      f:=f || jsonb_build_object('width_in',v_width_in,'height_in',v_height_in,'measurement_source',v_m_source,'area_source',v_area);
      if f ? 'unknown_fields' then
        -- Only deliberately clear a VALID string marker naming width_in/
        -- height_in (B8); anything else -- including an invalid entry --
        -- passes through unchanged for the final validator to judge.
        f:=jsonb_set(f,'{unknown_fields}',(select coalesce(jsonb_agg(x),'[]'::jsonb) from jsonb_array_elements(f->'unknown_fields') x
          where not (jsonb_typeof(x)='string' and x#>>'{}' in ('width_in','height_in'))));
      end if;
    end if;
    v_new_w:=nullif(f->>'width_in','')::numeric; v_new_h:=nullif(f->>'height_in','')::numeric;
    v_new_src:=f->>'measurement_source'; v_new_area:=f->>'area_source';
    -- Protects area_source alongside measurement_source/width/height (B3),
    -- and -- unlike the earlier draft -- applies to a brand-new unit's
    -- first legacy save too, not only an existing row (B2): an empty
    -- legacy create stays silent, but a legacy create with real dimensions
    -- is a genuine new assertion, not historical backfill.
    if v_event_kind is null and (v_new_w,v_new_h,v_new_src,v_new_area) is distinct from (v_old_w,v_old_h,v_old_src,v_old_area) then
      if v_new_w is not null and v_new_h is not null then v_event_kind:='legacy_observation'; else v_event_kind:='incomplete'; end if;
      -- Complete server intent from the FINAL validated flat facts (B2) --
      -- never left null while the unit itself carries real dimensions.
      v_width_in:=v_new_w; v_height_in:=v_new_h;
      v_norm_source:=public._work_unit_fact_legacy_source(v_new_src);
      v_norm_area:=public._work_unit_fact_legacy_source(v_new_area);
      -- Unknown or contradictory labels never become trusted provenance.
      if (v_new_src is null or v_norm_source is not null)
        and (v_new_area is null or v_norm_area is not null)
        and (v_norm_source is null or v_norm_area is null or v_norm_source=v_norm_area) then
        v_m_source:=coalesce(v_norm_source,v_norm_area);
      end if;
      v_estimated:=case when v_norm_source='estimated' or v_norm_area='estimated' then true
        when v_m_source is not null then false else null end;
    end if;
    if v_event_kind is null and u.id is not null and (jid is distinct from u.project_id or oid is distinct from u.opening_id)
        and v_cur_fact_prior.id is not null then
      v_event_kind:='relink';
      v_width_in:=v_cur_fact_prior.width_in; v_height_in:=v_cur_fact_prior.height_in;
      v_m_unit:=v_cur_fact_prior.measurement_unit; v_m_source:=v_cur_fact_prior.measurement_source; v_m_ref:=v_cur_fact_prior.source_reference;
      v_estimated:=v_cur_fact_prior.estimated; v_obs_actor:=v_cur_fact_prior.observation_actor_id; v_raw_obs:=v_cur_fact_prior.raw_observation;
      -- Origin is carried forward UNCHANGED through a pure relink (B1) --
      -- never reset to the new destination job.
      v_origin_project:=v_cur_fact_prior.origin_project_id; v_origin_opening:=v_cur_fact_prior.origin_opening_id;
      v_origin_kind:=v_cur_fact_prior.origin_kind; v_origin_author:=v_cur_fact_prior.origin_author_id;
      v_origin_is_test:=v_cur_fact_prior.origin_is_test;
    end if;
    if v_event_kind is not null and v_event_kind not in ('relink','cleared')
      and (v_new_w is not null or v_new_h is not null or v_new_src is not null or v_new_area is not null) then
      -- A genuinely fresh assertion (new/legacy/incomplete) establishes its
      -- own origin at the current binding; 'relink' already set it above
      -- from the predecessor, and 'cleared' has no observation to attribute.
      v_origin_project:=jid; v_origin_opening:=oid;
      v_origin_kind:=case when jid is null then 'unassigned' else 'job' end;
      v_origin_author:=coalesce(u.created_by,uid);
      v_origin_is_test:=public.is_test_profile(v_origin_author);
    end if;
    -- Every recorded event is protected, including a relink of a legacy/
    -- incomplete (not-yet-raw) prior observation (B4): a relink only ever
    -- reaches this point when v_cur_fact_prior.id is not null, so there is
    -- always something real being administered.
    v_protected:=v_event_kind is not null;
    if v_protected then
      -- All actors, including authors and new creators, pass source checks.
      -- Prior origin is required even for replacement/reset: before_snapshot
      -- preserves that evidence. No source IDs are exposed on a refusal.
      if (u.id is not null and not public._work_unit_fact_context_visible(uid,
          case when u.project_id is null then 'unassigned' else 'job' end,
          u.project_id,u.opening_id,u.created_by,public.is_test_profile(u.created_by),false))
        or not public._work_unit_fact_context_visible(uid,
          case when jid is null then 'unassigned' else 'job' end,
          jid,oid,coalesce(u.created_by,uid),public.is_test_profile(coalesce(u.created_by,uid)),false)
        or (v_cur_fact_prior.id is not null and not public._work_unit_fact_context_visible(uid,
          v_cur_fact_prior.origin_kind,v_cur_fact_prior.origin_project_id,v_cur_fact_prior.origin_opening_id,
          v_cur_fact_prior.origin_author_id,v_cur_fact_prior.origin_is_test,true)) then
        raise exception 'Unit source is unavailable.' using errcode='42501';
      end if;
      select project_id into v_origin_live_job from public.project_openings
        where id=v_cur_fact_prior.origin_opening_id and removed_at is null;
      if not public._work_unit_fact_can_edit_dimensions(uid,coalesce(u.created_by,uid),
          array[u.project_id,jid,v_cur_fact_prior.origin_project_id,v_origin_live_job]) then
        raise exception 'Only the author or an authorized foreman, supervisor or owner can change this unit''s dimensions.' using errcode='42501';
      end if;
    end if;
    -- Do not disclose even a private fact-revision mismatch before source
    -- authorization. Input types above are caller-owned, revision is evidence.
    if v_obs_present and v_expected_fact_rev::bigint<>v_cur_rev_num then
      raise exception 'Unit observation changed. Refresh before saving.';
    end if;
    v_legacy_source:=v_new_src; v_legacy_area:=v_new_area;

    perform public.validate_custom_work_facts(f);

    -- Absent row: FOR UPDATE locked nothing, so two concurrent creators can
    -- both reach here (B5). Decide via a real INSERT conflict rather than
    -- a blind UPSERT -- the loser refuses cleanly instead of silently
    -- overwriting the winner's row, author, and private fact.
    if u.id is null then
      insert into public.custom_work_units(id,project_id,opening_id,created_by,label,type_label,facts,revision)
      values(target,jid,oid,uid,btrim(p_data->>'label'),coalesce(nullif(btrim(p_data->>'type_label'),''),'Unknown'),f,1)
      on conflict(id) do nothing;
      if not found then raise exception 'Unit details changed. Refresh before saving.'; end if;
      -- Recheck after the INSERT wait too: a competing create/delete could
      -- have left retained evidence after our initial absent-row check.
      if exists(select 1 from public.work_unit_fact_current where unit_id=target)
        or exists(select 1 from public.work_unit_fact_revisions where unit_id=target) then
        raise exception 'Unit identity requires reconciliation before reuse.' using errcode='23514';
      end if;
      oldj:=null;
    else
      oldj:=to_jsonb(u);
      update public.custom_work_units set project_id=jid,opening_id=oid,label=btrim(p_data->>'label'),
        type_label=coalesce(nullif(btrim(p_data->>'type_label'),''),'Unknown'),facts=f,revision=u.revision+1,updated_at=now()
        where id=target;
    end if;
    update public.custom_work_units set legacy_time_present=exists(select 1 from unit_sessions where opening_id=oid) or exists(select 1 from task_sessions where opening_id=oid) where id=target;
    -- Attribution moves the observation, never the underlying payroll shift.
    update public.custom_work_sessions set project_id=jid,review_required=review_required or exists(select 1 from time_shifts t where t.id=shift_id and (t.project_id is distinct from jid or t.status in ('needs_finish','rejected','voided'))),revision=revision+1 where unit_id=target and project_id is distinct from jid;
    outid:=target;
    if v_event_kind is not null then
      -- jsonb_strip_nulls: a key assigned the PL/pgSQL `null` scalar must
      -- not become a stored JSON null (B2) -- jsonb_build_object always
      -- encodes a SQL NULL argument as JSON null, and the helper's
      -- raw_observation column CHECK only accepts SQL NULL or an object.
      -- Stripping the key entirely keeps `->` extraction returning true
      -- SQL NULL on the other side.
      v_applied_intent:=jsonb_strip_nulls(jsonb_build_object('event_kind',v_event_kind,'width_in',v_width_in,'height_in',v_height_in,
        'measurement_unit',v_m_unit,'measurement_source',v_m_source,'source_reference',v_m_ref,
        'raw_observation',v_raw_obs,'estimated',v_estimated,'observation_actor_id',v_obs_actor,'reason',v_reason,
        'origin_project_id',v_origin_project,'origin_opening_id',v_origin_opening,
        'origin_kind',v_origin_kind,'origin_author_id',v_origin_author,'origin_is_test',v_origin_is_test,
        'legacy_measurement_source',v_legacy_source,'legacy_area_source',v_legacy_area));
      v_before_snapshot:=jsonb_strip_nulls(jsonb_build_object('width_in',v_old_w,'height_in',v_old_h,'measurement_source',v_old_src,'area_source',v_old_area,
        'raw_observation',case when v_cur_fact_prior.id is not null then v_cur_fact_prior.raw_observation else null end));
    end if;
  elsif p_action in ('start','stop') then
    at_time:=coalesce((p_data->>'at')::timestamptz,now());
    if at_time>now()+interval '2 minutes' or at_time<now()-interval '7 days' then raise exception 'This work time needs a foreman review. Check the device clock.'; end if;
    expected:=nullif(p_data->>'expected_session_id','')::uuid;
    select * into s from public.custom_work_sessions where profile_id=uid and ended_at is null for update;
    if s.id is null and expected is not null then
      select * into s from public.custom_work_sessions where id=expected and profile_id=uid and ended_at is not null and end_reason in ('clock_out','stop') for update;
      if s.id is not null and (at_time<s.started_at or at_time>s.ended_at) then s.id:=null; end if;
    end if;
    if s.id is distinct from expected then raise exception 'Your current work changed. Sync and review before retrying.'; end if;
    if s.id is not null and at_time<s.started_at then raise exception 'The finish cannot be before the start.'; end if;
    if p_action='start' then
      select * into sh from public.time_shifts where id=(p_data->>'shift_id')::uuid and profile_id=uid for update;
      if sh.id is null or sh.status not in ('open','submitted','approved') or sh.clock_in_at>at_time or (sh.clock_out_at is not null and sh.clock_out_at<=at_time) or (sh.break_started_at is not null and sh.break_started_at<=at_time) then raise exception 'Clock in or resume your job clock before starting work.'; end if;
      -- The job clock already enforces its safety step; do not ask a second time.
      if now()-sh.clock_in_at>interval '16 hours' and sh.clock_out_at is null then raise exception 'Finish the older job clock before starting new work.'; end if;
      target:=nullif(p_data->>'unit_id','')::uuid;
      jid:=sh.project_id;
      -- Both kinds of start wait for today's toolbox signature, right after the
      -- open-shift check above (20261031000000): a UNIT start (a unit_id) meets
      -- the same gate every other unit-start RPC passes; PREP TIME (no unit_id;
      -- kind 'idle') meets its own, in its own sentence — the owner's answer of
      -- 2026-09-24. The two lines are the only change to this branch.
      if target is not null then
        perform public._unit_work_gate(uid);
        select * into u from public.custom_work_units where id=target for update;
        if u.id is null or (u.project_id is null and u.created_by<>uid and not public._is_lead(uid)) then raise exception 'That custom unit is unavailable.'; end if;
        if u.project_id is not null and u.project_id is distinct from sh.project_id then raise exception 'Switch your job clock to this unit''s job first.'; end if;
        jid:=u.project_id;
      else
        perform public._prep_time_gate(uid);
        if length(btrim(coalesce(p_data->>'description','')))=0 then raise exception 'Describe your idle time.'; end if;
      end if;
      if jid is not null and not exists(select 1 from projects where id=jid and deleted_at is null) then raise exception 'That job is unavailable.'; end if;
      -- Never rewrite a newer activity based on a stale/offline start.
      if exists(select 1 from public.custom_work_sessions where profile_id=uid and id is distinct from s.id and coalesce(ended_at,'infinity')>at_time) or exists(select 1 from public.unit_sessions where profile_id=uid and (started_at>at_time or (ended_at is not null and ended_at>at_time))) or exists(select 1 from public.task_sessions where profile_id=uid and (started_at>at_time or (ended_at is not null and ended_at>at_time))) then raise exception 'This overlaps recorded work. Ask a foreman to review the timeline.'; end if;
      if at_time<now()-interval '2 minutes' and exists(select 1 from opening_phases where started_by=uid and status='active' and paused_at is null) then raise exception 'A flashing timer is now running. Ask a foreman to reconcile the older work.'; end if;
      update public.task_sessions set ended_at=at_time where profile_id=uid and ended_at is null;
      update public.unit_sessions set ended_at=at_time,end_reason='handoff' where profile_id=uid and ended_at is null;
      update public.opening_phases set paused_at=at_time where started_by=uid and status='active' and paused_at is null;
    end if;
    if s.id is not null then
      oldj:=to_jsonb(s);
      update public.custom_work_sessions set ended_at=at_time,end_reason=case when p_action='start' then 'switch' else 'stop' end,
        outcome=nullif(p_data->>'outcome',''),description=coalesce(p_data->>'finish_note',description),delay_reason=coalesce(p_data->>'delay_reason',delay_reason),revision=revision+1 where id=s.id;
      insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value) select project_id,uid,id,'stop',oldj,to_jsonb(x) from public.custom_work_sessions x where id=s.id;
    end if;
    if p_action='start' then
      -- A later visit reopens completion; the worker can mark the whole install done again.
      update public.custom_work_units set facts=jsonb_set(facts,'{installation_complete}','"No"'),revision=revision+1,updated_at=now() where id=target and facts->>'installation_complete'='Yes';
      if found then
        insert into custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason) select jid,uid,id,'reopen',to_jsonb(u),to_jsonb(x),'New work visit' from custom_work_units x where id=target;
      end if;
      outid:=(p_data->>'id')::uuid;
      insert into public.custom_work_sessions(id,profile_id,shift_id,project_id,unit_id,kind,participation,stage,description,started_at,ended_at,end_reason,shift_status,review_required)
      values(outid,uid,sh.id,jid,target,case when target is null then 'idle' else 'unit' end,coalesce(p_data->>'participation','install'),case when target is null then 'Idle time' else coalesce(p_data->>'stage','Installing') end,coalesce(p_data->>'description',''),at_time,sh.clock_out_at,case when sh.clock_out_at is not null then 'clock_out' end,sh.status,jid is distinct from sh.project_id or (sh.clock_out_at is not null and coalesce(sh.break_seconds,0)>0));
      oldj:=null;
    else outid:=s.id; jid:=s.project_id;
    end if;
  elsif p_action='session' then
    select * into s from public.custom_work_sessions where id=(p_data->>'id')::uuid for update;
    if s.id is null or (s.profile_id<>uid and not public._is_lead(uid)) then raise exception 'Only the worker or a foreman can correct this record.'; end if;
    if s.project_id is not null and not exists(select 1 from projects where id=s.project_id and deleted_at is null) then raise exception 'That job is unavailable.'; end if;
    if s.revision<>coalesce((p_data->>'revision')::int,-1) then raise exception 'This record changed. Refresh before saving.'; end if;
    if length(btrim(coalesce(p_data->>'reason','')))<3 then raise exception 'Add a correction reason.'; end if;
    if s.kind='idle' and length(btrim(coalesce(p_data->>'description',s.description)))=0 then raise exception 'Describe your idle time.'; end if;
    oldj:=to_jsonb(s); jid:=s.project_id; outid:=s.id;
    if coalesce((p_data->>'review_time')::boolean,false) or p_data ? 'started_at' or p_data ? 'ended_at' then
      if not public._is_lead(uid) then raise exception 'Only foremen and above can correct captured times.'; end if;
      if s.ended_at is null then raise exception 'Stop the activity before correcting its time.'; end if;
      select * into sh from time_shifts where id=s.shift_id for update;
      at_time:=coalesce((p_data->>'started_at')::timestamptz,s.started_at);
      finish_time:=coalesce((p_data->>'ended_at')::timestamptz,s.ended_at);
      if sh.status not in ('submitted','approved') or sh.clock_out_at is null or s.project_id is distinct from sh.project_id or s.project_id is null
        or at_time<sh.clock_in_at or finish_time>sh.clock_out_at or finish_time<at_time or finish_time-at_time>interval '16 hours' then
        raise exception 'First resolve the job, timecard, or shift bounds. Captured time must fit its closed job clock.';
      end if;
      if exists(select 1 from custom_work_sessions x where x.profile_id=s.profile_id and x.id<>s.id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time)
        or exists(select 1 from unit_sessions x where x.profile_id=s.profile_id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time)
        or exists(select 1 from task_sessions x where x.profile_id=s.profile_id and x.started_at<finish_time and coalesce(x.ended_at,'infinity')>at_time) then
        raise exception 'The corrected interval overlaps other recorded work.';
      end if;
      if extract(epoch from finish_time-at_time)+(select coalesce(sum(extract(epoch from ended_at-started_at)),0) from custom_work_sessions where shift_id=s.shift_id and id<>s.id)
        >extract(epoch from sh.clock_out_at-sh.clock_in_at)-coalesce(sh.break_seconds,0)+1 then
        raise exception 'Captured activity exceeds the worked shift time after breaks. Review the other intervals too.';
      end if;
      update public.custom_work_sessions set started_at=at_time,ended_at=finish_time,review_required=false,end_reason='reviewed' where id=s.id;
    end if;
    update public.custom_work_sessions set description=coalesce(p_data->>'description',description),outcome=nullif(p_data->>'outcome',''),delay_reason=coalesce(p_data->>'delay_reason',delay_reason),revision=revision+1 where id=s.id;
  else raise exception 'Unknown work action.';
  end if;
  -- Audit values live behind the same job/author boundary as the records.
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason)
  values(jid,uid,coalesce(outid,p_id),p_action,oldj,
    case when p_action in ('unit','link') then (select to_jsonb(x) from public.custom_work_units x where id=outid)
      when p_action='type' then (select to_jsonb(x) from public.custom_work_types x where id=outid)
      else (select to_jsonb(x) from public.custom_work_sessions x where id=outid) end,coalesce(p_data->>'reason',''));
  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,jsonb_build_object('action',p_action,'data',p_data),outid);
  if p_action in ('unit','link') and v_event_kind is not null then
    perform public._work_record_unit_fact(p_id,v_applied_intent,v_before_snapshot,outid);
  end if;
  return public._work_activity_finish(__work_activity_root_id,(outid)::uuid);
end; 
 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_178$::text,false,'0ba57efca2176e2ae077feeaaf6bb88110fd76b4e7b1df78ad450afae678afd6'::text,'96723429413c73f8a2f3959df925807c5f36f0cd088ae21cca850a5b7dd5aed4'::text,'custom_work_command'::text,'p_id uuid, p_action text, p_data jsonb'::text),
('edit_shift_with_description(uuid, uuid, uuid, timestamp with time zone, timestamp with time zone, integer, text, text)'::text,$activity_body_179$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('edit_shift_with_description','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_shift time_shifts; v_old_note text; v_description text := nullif(btrim(p_description),'');
begin
  if length(v_description)>4000 then raise exception 'Keep the description under 4,000 characters.'; end if;
  v_shift := public.edit_shift(p_shift_id,p_project_id,p_cost_code_id,p_clock_in_at,p_clock_out_at,p_break_seconds,p_note);
  v_old_note := v_shift.note;
  if v_old_note is distinct from v_description then
    update time_shifts set note=v_description where id=p_shift_id returning * into v_shift;
    insert into time_shift_edits(shift_id,edited_by,field,old_value,new_value,reason)
      values(p_shift_id,auth.uid(),'note',v_old_note,v_description,btrim(p_note));
  end if;
  return public._work_activity_finish(__work_activity_root_id,(v_shift)::time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_179$::text,false,'24e1c6a38861d46294f40a0421645c06f779b82cd6bbfe08b3d80f690fad0076'::text,'9217489a3ab858ed0a738ea685bc351e29575332f95321b42d14b83dfffe13ef'::text,'edit_shift_with_description'::text,'p_shift_id uuid, p_project_id uuid, p_cost_code_id uuid, p_clock_in_at timestamp with time zone, p_clock_out_at timestamp with time zone, p_break_seconds integer, p_note text, p_description text'::text),
('approve_timecard_week(uuid, timestamp with time zone, timestamp with time zone, jsonb)'::text,$activity_body_180$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('approve_timecard_week','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v_count int; v_rows jsonb;
begin
  if not public.can_approve_timecard(p_profile_id) then
    raise exception 'Foremen may approve installer and foreman time; supervisor time requires a supervisor.';
  end if;
  if p_start is null or p_end is null or p_end-p_start not between interval '167 hours' and interval '169 hours' then
    raise exception 'Select one full week to approve.';
  end if;
  if p_expected is null or jsonb_typeof(p_expected)<>'array' then
    raise exception 'Refresh this timecard before approving.';
  end if;
  -- Serialize concurrent approvals, then snapshot locked rows. New punches
  -- arriving later remain submitted and show that another review is needed.
  perform 1 from profiles where id=p_profile_id for no key update;
  perform 1 from time_shifts where profile_id=p_profile_id and clock_in_at>=p_start
    and clock_in_at<p_end order by id for update;
  select coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) into v_rows from time_shifts s
    where profile_id=p_profile_id and clock_in_at>=p_start and clock_in_at<p_end and status<>'voided';
  if jsonb_array_length(v_rows)=0 then raise exception 'There are no entries in this week.'; end if;
  if exists (select 1 from jsonb_to_recordset(v_rows) as s(status text,clock_out_at timestamptz)
    where status not in ('submitted','approved') or clock_out_at is null) then
    raise exception 'Finish or correct the open, unfinished, or rejected entries before approving this week.';
  end if;
  if jsonb_array_length(p_expected)<>jsonb_array_length(v_rows)
    or (select count(distinct id) from jsonb_to_recordset(p_expected) as e(id uuid))<>jsonb_array_length(v_rows)
    or exists (
      select 1
      from jsonb_to_recordset(v_rows) as s(id uuid,project_id uuid,cost_code_id uuid,clock_in_at timestamptz,clock_out_at timestamptz,break_seconds int,note text,edited_at timestamptz)
      full join jsonb_to_recordset(p_expected) as e(id uuid,project_id uuid,cost_code_id uuid,clock_in_at timestamptz,clock_out_at timestamptz,break_seconds int,note text,edited_at timestamptz) on e.id=s.id
      where s.id is null or e.id is null or row(s.project_id,s.cost_code_id,s.clock_in_at,s.clock_out_at,s.break_seconds,s.note,s.edited_at)
        is distinct from row(e.project_id,e.cost_code_id,e.clock_in_at,e.clock_out_at,e.break_seconds,e.note,e.edited_at)
    ) then raise exception 'This timecard changed. Refresh it and review the week again.';
  end if;
  update time_shifts set status='approved',approved_by=auth.uid(),approved_at=now()
    where profile_id=p_profile_id and status='submitted'
      and id in (select (entry->>'id')::uuid from jsonb_array_elements(v_rows) as entry);
  get diagnostics v_count=row_count;
  return public._work_activity_finish(__work_activity_root_id,(v_count)::int);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_180$::text,false,'52c5b3112708bad9ae4960e010e322252109c9a73f67da3592cfbedb9e690cf7'::text,'c5ef67cfa7ccf95b82e73cf4da30496ff14487be9827675ad1e3d489b75b3f51'::text,'approve_timecard_week'::text,'p_profile_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_expected jsonb'::text),
('service_notify_lodging(uuid)'::text,$activity_body_181$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('service_notify_lodging','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare v service_visits; recipients uuid[]; message_id uuid; job text;
begin
  select * into v from service_visits where id=target for update;
  if not coalesce((v.details->>'lodging')::boolean,false) or v.lodging_message_id is not null then perform public._work_activity_operation_exit(__work_activity_root_id); return; end if;
  select array_agg(p.id) into recipients from service_job_supervisors s join profiles p on p.id=s.profile_id
    where s.project_id=v.project_id and not p.is_partner and p.retired_at is null and p.access_revoked_at is null and p.role in ('supervisor','owner');
  if coalesce(cardinality(recipients),0)=0 then
    select array_agg(id) into recipients from profiles where not is_partner and retired_at is null and access_revoked_at is null and role='supervisor';
  end if;
  if coalesce(cardinality(recipients),0)=0 then perform public._work_activity_operation_exit(__work_activity_root_id); return; end if;
  select job_code||' · '||name into job from projects where id=v.project_id;
  message_id:=gen_random_uuid();
  insert into project_messages(id,project_id,author_id,body,mentions) values(message_id,v.project_id,auth.uid(),
    'Lodging needed for service: '||job||E'\nCrew: '||coalesce(nullif(v.details->>'crew_names',''),'See service visit')||E'\nDate: '||coalesce(nullif(v.details->>'scheduled_date',''),'Confirm with requester')||E'\nhttps://app.forgewd.com/service?visit='||v.id,recipients);
  update service_visits set lodging_message_id=message_id where id=v.id;
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_181$::text,false,'09a5696f61cc63b42013dc2bb8d5ea4f4b86c091b9eb04d544e4aa4f2cc4eb75'::text,'d52551c9a503627bc8dc9b6ecc9799a084278e8fc06769209d587e279b9329ee'::text,'service_notify_lodging'::text,'target uuid'::text),
('service_command(uuid, text, jsonb)'::text,$activity_body_182$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('service_command','{}'::jsonb,p_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare uid uuid:=auth.uid(); c service_commands; v service_visits; u service_visit_units;
  s service_time_sessions; sh time_shifts; m service_media; oldj jsonb; afterj jsonb;
  target uuid; jid uuid; result uuid; at_time timestamptz; boundary timestamptz; expected uuid; v_details jsonb; recipient uuid; total numeric;
begin
  if not public.service_internal() then raise exception 'An active Forge crew login is required.' using errcode='42501'; end if;
  if p_id is null or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>100000 then raise exception 'Invalid service request.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7482));
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  select * into c from service_commands where id=p_id;
  if found then
    if c.profile_id<>uid or c.payload<>jsonb_build_object('action',p_action,'data',p_data) then raise exception 'This retry belongs to another request.'; end if;
    return public._work_activity_finish(__work_activity_root_id,(c.result_id)::uuid);
  end if;
  target:=nullif(p_data->>'visit_id','')::uuid;
  if target is not null then
    select * into v from service_visits where id=target for update;
    if not found or not public.service_job_access(v.project_id) then raise exception 'That service visit is unavailable.' using errcode='42501'; end if;
    jid:=v.project_id;
  else jid:=(p_data->>'project_id')::uuid;
  end if;
  if not public.service_job_access(jid) then raise exception 'That job is unavailable.' using errcode='42501'; end if;
  if p_action not in ('visit','supervisor') and v.id is null then raise exception 'Choose a service visit.'; end if;
  if p_action='supervisor' then
    if not public.service_supervisor() then raise exception 'Only a supervisor can assign the job supervisor.' using errcode='42501'; end if;
    recipient:=nullif(p_data->>'profile_id','')::uuid;
    if recipient is not null and not exists(select 1 from profiles where id=recipient and not is_partner and retired_at is null and access_revoked_at is null and role in ('supervisor','owner')) then raise exception 'Choose an active supervisor or owner.'; end if;
    select to_jsonb(x) into oldj from service_job_supervisors x where project_id=jid;
    insert into service_job_supervisors(project_id,profile_id) values(jid,recipient) on conflict(project_id) do update set profile_id=excluded.profile_id;
    result:=jid; afterj:=jsonb_build_object('profile_id',recipient);
  elsif p_action='visit' then
    v_details:=coalesce(p_data->'details','{}'); perform service_validate_details(v_details);
    if v.id is null then
      result:=(p_data->>'id')::uuid;
      if nullif(p_data->>'previous_visit_id','') is not null and not exists(select 1 from service_visits where id=(p_data->>'previous_visit_id')::uuid and project_id=jid) then raise exception 'The earlier visit belongs to another job.'; end if;
      insert into service_visits(id,project_id,created_by,previous_visit_id,details) values(result,jid,uid,nullif(p_data->>'previous_visit_id','')::uuid,v_details);
      target:=result;
    else
      if v.created_by is distinct from uid and not public._is_lead(uid) then raise exception 'The visit creator or a foreman can edit trip details.' using errcode='42501'; end if;
      if v.revision is distinct from (p_data->>'revision')::int then raise exception 'This visit changed. Refresh before saving.'; end if;
      oldj:=to_jsonb(v); result:=v.id;
      update service_visits x set details=p_data->'details',revision=x.revision+1,reviewed_at=null,reviewed_by=null,updated_at=now() where x.id=v.id;
    end if;
    perform service_notify_lodging(result);
    select to_jsonb(x) into afterj from service_visits x where id=result;
  elsif p_action='unit' then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    select * into u from service_visit_units where id=(p_data->>'id')::uuid for update;
    if found then
      if u.visit_id<>v.id or (u.created_by is distinct from uid and v.created_by is distinct from uid and not public._is_lead(uid)) then raise exception 'This unit is not editable from this visit.' using errcode='42501'; end if;
      if u.revision is distinct from (p_data->>'revision')::int then raise exception 'This unit changed. Refresh before saving.'; end if;
      oldj:=to_jsonb(u);
    end if;
    if nullif(p_data->>'work_unit_id','') is not null and not exists(select 1 from custom_work_units where id=(p_data->>'work_unit_id')::uuid and project_id=jid) then raise exception 'That saved unit belongs to another job.'; end if;
    if nullif(p_data->>'opening_id','') is not null and not exists(select 1 from project_openings where id=(p_data->>'opening_id')::uuid and project_id=jid and removed_at is null) then raise exception 'That mapped unit is unavailable.'; end if;
    if nullif(p_data->>'window_id','') is not null and not exists(select 1 from windows where id=(p_data->>'window_id')::uuid and project_id=jid) then raise exception 'That warehouse unit belongs to another job.'; end if;
    if nullif(p_data->>'legacy_case_id','') is not null and not exists(select 1 from service_cases where id=(p_data->>'legacy_case_id')::uuid and project_id=jid) then raise exception 'That earlier case belongs to another job.'; end if;
    perform validate_custom_work_facts(coalesce(p_data->'facts','{}'));
    result:=(p_data->>'id')::uuid;
    insert into service_visit_units(id,visit_id,project_id,created_by,work_unit_id,opening_id,window_id,legacy_case_id,label,type_label,facts,issue,fail_point,cause,repair,verification,prevention,next_steps,memo_text,evidence_exception,outcome)
    values(result,v.id,jid,uid,nullif(p_data->>'work_unit_id','')::uuid,nullif(p_data->>'opening_id','')::uuid,nullif(p_data->>'window_id','')::uuid,nullif(p_data->>'legacy_case_id','')::uuid,
      p_data->>'label',coalesce(p_data->>'type_label','Unknown'),coalesce(p_data->'facts','{}'),p_data->>'issue',coalesce(p_data->>'fail_point',''),coalesce(p_data->>'cause','pending'),coalesce(p_data->>'repair',''),coalesce(p_data->>'verification',''),coalesce(p_data->>'prevention',''),coalesce(p_data->>'next_steps',''),coalesce(p_data->>'memo_text',''),coalesce(p_data->>'evidence_exception',''),coalesce(p_data->>'outcome','open'))
    on conflict(id) do update set work_unit_id=excluded.work_unit_id,opening_id=excluded.opening_id,window_id=excluded.window_id,legacy_case_id=excluded.legacy_case_id,
      label=excluded.label,type_label=excluded.type_label,facts=excluded.facts,issue=excluded.issue,fail_point=excluded.fail_point,cause=excluded.cause,repair=excluded.repair,verification=excluded.verification,prevention=excluded.prevention,next_steps=excluded.next_steps,memo_text=excluded.memo_text,evidence_exception=excluded.evidence_exception,outcome=excluded.outcome,revision=service_visit_units.revision+1,updated_at=now();
    select to_jsonb(x) into afterj from service_visit_units x where id=result;
  elsif p_action in ('start','stop') then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    at_time:=coalesce((p_data->>'at')::timestamptz,now());
    if at_time>now()+interval '2 minutes' or at_time<now()-interval '7 days' then raise exception 'Check the device time; a foreman must review older work.'; end if;
    expected:=nullif(p_data->>'expected_session_id','')::uuid;
    select * into s from service_time_sessions where profile_id=uid and ended_at is null for update;
    -- An offline stop can arrive after the payroll clock already closed it. It may shorten,
    -- never extend, that automatic boundary. Other edits still require reconciliation.
    if s.id is null and expected is not null then
      select * into s from service_time_sessions where id=expected and profile_id=uid and visit_id=v.id
        and end_reason in ('clock_out','break','offline_boundary') for update;
      if s.id is not null then at_time:=least(at_time,s.ended_at); end if;
    end if;
    if s.id is distinct from expected then raise exception 'Your timer changed. Refresh before continuing.'; end if;
    if s.id is not null and (s.visit_id<>v.id or at_time<s.started_at) then raise exception 'Stop your other service visit first.'; end if;
    if p_action='start' then
      if v.status<>'active' then raise exception 'Start a new visit for a return trip.'; end if;
      select * into sh from time_shifts where id=(p_data->>'shift_id')::uuid and profile_id=uid for update;
      boundary:=coalesce(sh.clock_out_at,sh.break_started_at);
      if sh.id is null or sh.project_id is distinct from jid or sh.status not in ('open','submitted','approved') or at_time<sh.clock_in_at
        or (boundary is not null and at_time>=boundary) or (boundary is null and now()-sh.clock_in_at>interval '16 hours') then raise exception 'Clock into this job and finish any break before starting service.'; end if;
      if nullif(p_data->>'unit_id','') is not null and not exists(select 1 from service_visit_units where id=(p_data->>'unit_id')::uuid and visit_id=v.id) then raise exception 'Choose a unit on this service visit.'; end if;
      if p_data->>'kind' in ('idle','travel') and length(btrim(coalesce(p_data->>'description','')))=0 then raise exception 'Describe the travel or idle time.'; end if;
      if exists(select 1 from service_time_sessions where profile_id=uid and id is distinct from s.id and coalesce(ended_at,'infinity')>at_time)
        or exists(select 1 from custom_work_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time))
        or exists(select 1 from unit_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time))
        or exists(select 1 from task_sessions where profile_id=uid and (started_at>at_time or ended_at>at_time)) then raise exception 'This overlaps newer work. Refresh and review the timeline.'; end if;
      if at_time<now()-interval '2 minutes' and exists(select 1 from opening_phases where started_by=uid and status='active' and paused_at is null) then raise exception 'Review the existing flashing timer first.'; end if;
      update custom_work_sessions set ended_at=at_time,end_reason='service',revision=revision+1 where profile_id=uid and ended_at is null;
      update unit_sessions set ended_at=at_time,end_reason='handoff' where profile_id=uid and ended_at is null;
      update task_sessions set ended_at=at_time where profile_id=uid and ended_at is null;
      update opening_phases set paused_at=at_time where started_by=uid and status='active' and paused_at is null;
    end if;
    if s.id is not null then
      oldj:=to_jsonb(s);
      update service_time_sessions set ended_at=at_time,end_reason=case when p_action='start' then 'switch' else 'stop' end,description=coalesce(p_data->>'finish_note',description) where id=s.id;
    end if;
    if p_action='start' then
      result:=(p_data->>'id')::uuid;
      insert into service_time_sessions(id,visit_id,project_id,unit_id,shift_id,profile_id,kind,stage,description,started_at,ended_at,end_reason,review_required)
      values(result,v.id,jid,nullif(p_data->>'unit_id','')::uuid,sh.id,uid,p_data->>'kind',coalesce(p_data->>'stage','Diagnosis'),coalesce(p_data->>'description',''),at_time,boundary,case when boundary is not null then 'offline_boundary' end,boundary is not null);
    else result:=s.id; end if;
    select to_jsonb(x) into afterj from service_time_sessions x where id=result;
  elsif p_action='review_time' then
    if not public.service_supervisor() then raise exception 'Only a supervisor or owner can reconcile service time.' using errcode='42501'; end if;
    select * into s from service_time_sessions where id=(p_data->>'id')::uuid and visit_id=v.id for update;
    if s.id is null or s.ended_at is null then raise exception 'Stop this timer before reviewing it.'; end if;
    if s.started_at is distinct from (p_data->>'expected_start')::timestamptz or s.ended_at is distinct from (p_data->>'expected_end')::timestamptz then raise exception 'This time record changed. Refresh before saving.'; end if;
    if p_data->>'reason' is null or length(btrim(p_data->>'reason'))=0 then raise exception 'Explain the time correction.'; end if;
    select * into sh from time_shifts where id=s.shift_id for update;
    if sh.status not in ('open','submitted','approved') or sh.project_id is distinct from s.project_id then raise exception 'Correct the payroll shift and job before reconciling service time.'; end if;
    if (p_data->>'started_at')::timestamptz<sh.clock_in_at or (p_data->>'ended_at')::timestamptz>coalesce(sh.clock_out_at,now())
      or (p_data->>'started_at')::timestamptz>=(p_data->>'ended_at')::timestamptz or p_data->>'started_at' is null or p_data->>'ended_at' is null then raise exception 'Service time must fit inside the paid shift.'; end if;
    if exists(select 1 from service_time_sessions x where x.id<>s.id and x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from custom_work_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from unit_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz)
      or exists(select 1 from task_sessions x where x.profile_id=s.profile_id and x.started_at<(p_data->>'ended_at')::timestamptz and coalesce(x.ended_at,now())>(p_data->>'started_at')::timestamptz) then raise exception 'This overlaps another recorded activity.'; end if;
    oldj:=to_jsonb(s); result:=s.id;
    update service_time_sessions set started_at=(p_data->>'started_at')::timestamptz,ended_at=(p_data->>'ended_at')::timestamptz,review_required=false where id=s.id;
    if (select coalesce(sum(extract(epoch from coalesce(ended_at,now())-started_at)),0) from service_time_sessions where shift_id=sh.id)
       +(select coalesce(sum(extract(epoch from coalesce(ended_at,now())-started_at)),0) from custom_work_sessions where shift_id=sh.id)
       >extract(epoch from coalesce(sh.clock_out_at,now())-sh.clock_in_at)-sh.break_seconds then raise exception 'Tracked work exceeds paid time after breaks. Reconcile the intervals first.'; end if;
    select to_jsonb(x)||jsonb_build_object('review_reason',p_data->>'reason') into afterj from service_time_sessions x where id=result;
  elsif p_action in ('finish','review','notify') then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    if p_action='notify' then perform service_notify_lodging(v.id);
    else
      if v.created_by is distinct from uid and not public._is_lead(uid) then raise exception 'The visit creator or a foreman can finish the visit.' using errcode='42501'; end if;
      if v.revision is distinct from (p_data->>'revision')::int then raise exception 'This visit changed. Refresh before continuing.'; end if;
      if exists(select 1 from service_time_sessions where visit_id=v.id and ended_at is null) then raise exception 'Each worker must stop their service timer before finishing the visit.'; end if;
      if not exists(select 1 from service_visit_units where visit_id=v.id) then raise exception 'Add the serviced unit first.'; end if;
      if p_action='finish' then
        oldj:=to_jsonb(v);
        update service_visits set status='completed',completed_at=now(),revision=revision+1,updated_at=now(),reviewed_at=null,reviewed_by=null where id=v.id;
      else
        if not public.service_supervisor() then raise exception 'Only a supervisor or owner can approve billing.' using errcode='42501'; end if;
        if v.status<>'completed' then raise exception 'Finish the visit before billing review.'; end if;
        if exists(select 1 from service_visit_units where visit_id=v.id and (cause='pending' or btrim(fail_point)='' or btrim(repair)='' or btrim(verification)='' or outcome='open' or btrim(memo_text)='')) then raise exception 'Complete the unit explanation, responsibility and result first.'; end if;
        if exists(select 1 from service_time_sessions row_time join time_shifts t on t.id=row_time.shift_id where row_time.visit_id=v.id and (row_time.review_required or t.status in ('voided','rejected','needs_finish') or t.project_id is distinct from row_time.project_id)) then raise exception 'Reconcile flagged labor before billing review.'; end if;
        if exists(select 1 from service_visit_units row_unit where row_unit.visit_id=v.id and btrim(row_unit.evidence_exception)='' and (select count(distinct kind) from service_media row_media where row_media.unit_id=row_unit.id and kind in ('before','after','voice','video'))<4) then raise exception 'Attach the unit evidence or explain what is missing.'; end if;
        v_details:=p_data->'allocation';
        if jsonb_typeof(v_details) is distinct from 'object' or jsonb_typeof(v_details->'manufacturer') is distinct from 'number' or jsonb_typeof(v_details->'customer') is distinct from 'number' or jsonb_typeof(v_details->'installer') is distinct from 'number'
          or (v_details->>'manufacturer')::numeric<0 or (v_details->>'customer')::numeric<0 or (v_details->>'installer')::numeric<0
          or coalesce(v_details->>'reason','')='' or length(v_details->>'reason')>2000 then raise exception 'Explain how shared costs are split and enter all three percentages.'; end if;
        total:=(v_details->>'manufacturer')::numeric+(v_details->>'customer')::numeric+(v_details->>'installer')::numeric;
        if total<>100 then raise exception 'Shared cost percentages must total 100.'; end if;
        oldj:=to_jsonb(v);
        update service_visits set allocation=v_details,reviewed_at=now(),reviewed_by=uid,revision=revision+1,updated_at=now() where id=v.id;
      end if;
    end if;
    result:=v.id; select to_jsonb(x) into afterj from service_visits x where id=result;
  elsif p_action='media' then
    if v.id is null then raise exception 'Choose a service visit.'; end if;
    if nullif(p_data->>'unit_id','') is not null and not exists(select 1 from service_visit_units where id=(p_data->>'unit_id')::uuid and visit_id=v.id) then raise exception 'Choose a unit on this visit.'; end if;
    result:=(p_data->>'id')::uuid;
    if split_part(p_data->>'storage_path','/',1)<>uid::text or split_part(p_data->>'storage_path','/',2)<>v.id::text or split_part(split_part(p_data->>'storage_path','/',3),'.',1)<>result::text
      or not exists(select 1 from storage.objects where bucket_id='service-media' and name=p_data->>'storage_path') then raise exception 'Upload the original file before attaching it.'; end if;
    insert into service_media(id,visit_id,project_id,unit_id,created_by,kind,storage_path,filename,content_type,bytes,caption)
    values(result,v.id,jid,nullif(p_data->>'unit_id','')::uuid,uid,p_data->>'kind',p_data->>'storage_path',p_data->>'filename',p_data->>'content_type',(p_data->>'bytes')::bigint,coalesce(p_data->>'caption',''));
    select to_jsonb(x) into afterj from service_media x where id=result;
  elsif p_action='transcript' then
    select * into m from service_media where id=(p_data->>'id')::uuid for update;
    if m.id is null or m.visit_id<>v.id or (m.created_by is distinct from uid and not public._is_lead(uid)) then raise exception 'This memo is not editable.' using errcode='42501'; end if;
    if m.revision is distinct from (p_data->>'revision')::int then raise exception 'This transcript changed. Refresh first.'; end if;
    oldj:=to_jsonb(m); result:=m.id;
    update service_media set transcript=p_data->>'transcript',revision=revision+1 where id=m.id;
    select to_jsonb(x) into afterj from service_media x where id=result;
  else raise exception 'Unknown service action.';
  end if;
  if p_action in ('unit','start','stop','media','transcript','review_time') then
    update service_visits set reviewed_at=null,reviewed_by=null,revision=revision+1,updated_at=now() where id=target;
  end if;
  insert into service_commands(id,profile_id,payload,result_id) values(p_id,uid,jsonb_build_object('action',p_action,'data',p_data),result);
  insert into service_audit(project_id,visit_id,actor_id,action,entity_id,before_value,after_value) values(jid,target,uid,p_action,result,oldj,afterj);
  return public._work_activity_finish(__work_activity_root_id,(result)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_182$::text,false,'26f10cbbf12e91381b55ca755504ebd416e133b11e9daaec20c99280e9b45401'::text,'8cbbf73e7491089c5181d2f1e58dfac6d4c233dcb8834ef0396b2c6ca7ed4ee7'::text,'service_command'::text,'p_id uuid, p_action text, p_data jsonb'::text),
('record_crew_work(uuid, jsonb)'::text,$activity_body_183$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('record_crew_work','{}'::jsonb,p_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands;
  unit_data jsonb; unit_id uuid; job_id uuid; people uuid[]; work_day date;
  result_id uuid; existing public.custom_work_units; person uuid;
  record_payload jsonb:=jsonb_build_object('action','crew_record','data',p_data);
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can record work for the crew.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid crew record.'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>record_payload then raise exception 'This retry belongs to a different request.'; end if;
    return public._work_activity_finish(__work_activity_root_id,(receipt.result_id)::uuid);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));
  unit_data:=p_data->'unit';
  if jsonb_typeof(unit_data) is distinct from 'object' then raise exception 'Choose or build a unit.'; end if;
  unit_id:=(unit_data->>'id')::uuid;
  job_id:=(unit_data->>'project_id')::uuid;
  if unit_id is null or job_id is null then raise exception 'Choose a job and a unit.'; end if;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  select * into existing from public.custom_work_units where id=unit_id for update;
  if existing.id is not null and (existing.project_id is distinct from job_id or existing.opening_id is distinct from nullif(unit_data->>'opening_id','')::uuid) then
    raise exception 'Use Unit details to move or link an existing unit before recording crew work.';
  end if;
  if length(btrim(coalesce(unit_data->>'label','')))=0 then raise exception 'Enter a unit number or name.'; end if;
  if existing.id is null and exists(select 1 from public.custom_work_units where project_id=job_id and lower(btrim(label))=lower(btrim(unit_data->>'label'))) then
    raise exception 'A unit with this name already exists. Select it, or include the building/floor for a different unit.';
  end if;
  if existing.id is null and nullif(unit_data->>'opening_id','') is null and exists(select 1 from public.project_openings where project_id=job_id and removed_at is null and lower(btrim(opening_code))=lower(btrim(unit_data->>'label'))) then
    raise exception 'This unit is already on the map. Select the map unit instead of creating a duplicate.';
  end if;
  if jsonb_typeof(p_data->'people') is distinct from 'array' or jsonb_array_length(p_data->'people') not between 1 and 100 then raise exception 'Select the people who did or will do this work.'; end if;
  select array_agg(distinct value::uuid) into people from jsonb_array_elements_text(p_data->'people');
  foreach person in array people loop
    if person is null or not exists(
      select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
        and is_test=public.is_test_profile(uid)
    ) or not public._ai_job_visible(job_id,person) then
      raise exception 'Choose Forge crew members with current access to this job.';
    end if;
  end loop;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null or work_day<date '2000-01-01' or work_day>date '2100-12-31' then raise exception 'Choose a valid work date.'; end if;
  if p_data->>'outcome' is null or p_data->>'outcome' not in ('assigned','partial','finished') then raise exception 'Choose assigned, partial or stage complete.'; end if;
  if p_data->>'outcome'<>'assigned' and work_day>(now() at time zone 'America/Denver')::date then raise exception 'Completed work cannot have a future date.'; end if;
  if p_data->>'stage' is null or p_data->>'stage' not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then raise exception 'Choose the work stage.'; end if;
  if length(coalesce(p_data->>'description',''))>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if coalesce((p_data->>'whole_complete')::boolean,false) then
    if p_data->>'stage'<>'Installing' or p_data->>'outcome'<>'finished' then raise exception 'Whole installation completion requires the Installing stage to be finished.'; end if;
    unit_data:=jsonb_set(unit_data,'{facts}',coalesce(unit_data->'facts','{}') || '{"installation_complete":"Yes"}'::jsonb);
  end if;
  result_id:=public.custom_work_command(p_id,'unit',unit_data);
  if p_data->>'outcome'<>'assigned' then
    update public.custom_work_units set untimed_work_present=true where id=result_id;
  end if;
  insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
  values(p_id,job_id,result_id,uid,work_day,p_data->>'stage',p_data->>'outcome',coalesce((p_data->>'whole_complete')::boolean,false),coalesce(p_data->>'description',''));
  insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(people);
  update public.custom_work_commands set payload=record_payload where id=p_id;
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,after_value,reason)
  values(job_id,uid,result_id,'crew_record',jsonb_build_object('record_id',p_id,'people',people,'work_date',work_day,'stage',p_data->>'stage','outcome',p_data->>'outcome','description',coalesce(p_data->>'description','')),'Foreman crew record; no payroll changes');
  return public._work_activity_finish(__work_activity_root_id,(result_id)::uuid);
end; 
 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_183$::text,false,'9b0234499b660df4e812b77c833b3b616fc8843586ca538413b516d8721be586'::text,'086ca94746195b76858ce13c6290df1610fd7314d4b182e47e1ba5786d9e3aa3'::text,'record_crew_work'::text,'p_id uuid, p_data jsonb'::text),
('_ai_one_unit_owner()'::text,$activity_body_184$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare o project_openings;
begin
  if new.opening_id is null or new.assigned_to is null then return new; end if;
  select * into o from project_openings where id = new.opening_id for update;
  if o.assigned_to is null then
    perform set_config('app.assignment_via', 'map', true);
    update project_openings set assigned_to = new.assigned_to, assigned_by = coalesce(auth.uid(), new.assigned_to), assigned_at = now() where id = o.id;
  elsif o.assigned_to <> new.assigned_to then
    raise exception 'This unit and its map unit are assigned to different people. Ask a foreman to reassign one of them first.';
  end if;
  new.assigned_to := null; new.assigned_at := null;
  return new;
end;

end;
$activity_body_184$::text,false,'dcd91566fa72cdf7e04ccb2293c90ea00553ee7bcbcf178645c199142ac0f61b'::text,'c93892bb03c20318e2a1813853d5cb73300386f2031522b33ff57bc4c02bc4fb'::text,'_ai_one_unit_owner'::text,''::text),
('_ai_field_apply(uuid, text)'::text,$activity_body_185$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_ai_field_apply','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  uid uuid := auth.uid(); a ai_field_actions; r ai_field_requests; d jsonb; jid uuid; res jsonb; st jsonb; snap jsonb;
  u custom_work_units; o project_openings; sh time_shifts; s custom_work_sessions; matches jsonb; people uuid[]; msg uuid;
  at_time timestamptz; can_edit boolean; proposed jsonb; additions jsonb := '{}'; conflicts jsonb := '{}'; plan jsonb;
  k text; v jsonb; newfacts jsonb; unknowns jsonb; stage text; part text; assignee uuid; others jsonb; from_confirm boolean := p_choice is not null;
  outid uuid; label_norm text; prev jsonb;
begin
  select * into a from ai_field_actions where id = p_action and profile_id = uid for update;
  if not found then raise exception 'This action is unavailable.' using errcode = '42501'; end if;
  if a.status <> 'waiting' then return public._work_activity_finish(__work_activity_root_id,(a.result)::jsonb); end if;
  prev := a.result;
  select * into r from ai_field_requests where id = a.request_id;
  d := a.data; snap := r.clock_snapshot;
  jid := nullif(d->>'project_id', '')::uuid;
  if jid is not null and not public._ai_job_visible(jid, uid) then raise exception 'That job is unavailable.'; end if;
  if from_confirm and (prev->>'expires_at')::timestamptz < now() then
    res := public._ai_stale('This choice expired. Ask Forge AI again.');
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text, 7281));
  if jid is not null then perform pg_advisory_xact_lock(hashtextextended(jid::text, 7285)); end if;

  if res is not null then
    null;
  elsif a.action = 'create_job' then
    if public.is_test_profile(uid) then raise exception 'This is a test login. It can only use the automation sandbox job, not create a real one.' using errcode = '42501'; end if;
    if length(btrim(coalesce(d->>'name', ''))) not between 2 and 80 or length(btrim(coalesce(d->>'location', ''))) not between 3 and 300 then
      raise exception 'A new job needs its name and site address or location.';
    end if;
    -- One creator at a time, so two phones naming the same site see each other.
    perform pg_advisory_xact_lock(7592);
    select coalesce(jsonb_agg(x order by x->>'name', x->>'id'), '[]') into matches from (
      select jsonb_build_object('id', p.id, 'name', p.name, 'job_code', p.job_code, 'location', p.address) x from projects p
      where public._ai_job_visible(p.id, uid) and (
        (length(public._ai_norm(p.name)) >= 3 and length(public._ai_norm(d->>'name')) >= 3 and
          (public._ai_norm(p.name) like '%' || public._ai_norm(d->>'name') || '%' or public._ai_norm(d->>'name') like '%' || public._ai_norm(p.name) || '%'))
        or (length(public._ai_norm(p.address)) >= 6 and public._ai_norm(p.address) = public._ai_norm(d->>'location'))
        or exists (select 1 from regexp_split_to_table(lower(p.name), '[^a-z0-9]+') w1 join regexp_split_to_table(lower(d->>'name'), '[^a-z0-9]+') w2 on w1 = w2
                   where length(w1) >= 4 and w1 not in ('residence','house','home','project','remodel','street','road','avenue','drive','lane','windows','doors','window','door','building','court')))
      order by p.name, p.id limit 5) m;
    if p_choice like 'use_existing:%' then
      if not exists (select 1 from jsonb_array_elements(prev->'matches') m where m->>'id' = substr(p_choice, 14)) or not public._ai_job_visible(substr(p_choice, 14)::uuid, uid) then
        res := public._ai_stale('That job is no longer available. Ask again.');
      else
        jid := substr(p_choice, 14)::uuid;
        res := jsonb_build_object('status', 'done', 'outcome', 'used_existing', 'project_id', jid, 'name', (select name from projects where id = jid), 'created', false);
      end if;
    elsif jsonb_array_length(matches) > 0 and (p_choice is distinct from 'create_new' or matches <> prev->'matches') then
      -- First sight, or the similar jobs changed since the person chose: show the
      -- current list and ask again rather than create beside one they never saw.
      res := public._ai_waiting(jsonb_build_object('reason', 'similar_job', 'message', 'A similar job already exists. Do you still want to create this project?',
        'proposed', jsonb_build_object('name', btrim(d->>'name'), 'location', btrim(d->>'location')), 'matches', matches,
        'options', (select jsonb_agg(jsonb_build_object('id', 'use_existing:' || (m->>'id'), 'label', 'Use ' || (m->>'name'))) from jsonb_array_elements(matches) m)
          || jsonb_build_array(jsonb_build_object('id', 'create_new', 'label', 'Create a separate new job'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
    else
      jid := gen_random_uuid();
      insert into projects(id, job_code, name, address)
      values (jid, 'FIELD-' || upper(substr(md5(jid::text), 1, 6)), btrim(d->>'name'), btrim(d->>'location'));
      -- Born Not ready, like every job nobody in the office has set up yet.
      insert into project_pipeline(project_id, ready_state, updated_at, updated_by) values (jid, 'not_ready', now(), uid)
      on conflict (project_id) do update set ready_state = 'not_ready', updated_at = now(), updated_by = uid;
      -- D26: the job's supervisors, else every supervisor, else the owners. Login
      -- access decides, not whether they are on site today.
      select array_agg(p.id) into people from service_job_supervisors js join profiles p on p.id = js.profile_id
        where js.project_id = jid and not coalesce(p.is_partner, false) and p.retired_at is null and p.access_revoked_at is null and p.role in ('supervisor','owner');
      if coalesce(cardinality(people), 0) = 0 then
        select array_agg(id) into people from profiles where role = 'supervisor' and not coalesce(is_partner, false) and retired_at is null and access_revoked_at is null and not public.is_test_profile(id);
      end if;
      if coalesce(cardinality(people), 0) = 0 then
        select array_agg(id) into people from profiles where role = 'owner' and not coalesce(is_partner, false) and retired_at is null and access_revoked_at is null and not public.is_test_profile(id);
      end if;
      msg := gen_random_uuid();
      insert into project_messages(id, project_id, author_id, body, mentions) values (msg, jid, uid,
        'New field job created in Forge AI by ' || coalesce((select display_name from profiles where id = uid), 'a crew member') || ': ' || btrim(d->>'name')
        || E'\nLocation: ' || btrim(d->>'location')
        || E'\nNeeds office setup: customer, schedule, readiness and a supervisor. Crew can record work on it now.'
        || E'\nhttps://app.forgewd.com/projects/' || jid, coalesce(people, '{}'));
      insert into ai_field_jobs(project_id, created_by, action_id, notice_message_id, notified) values (jid, uid, a.id, msg, coalesce(people, '{}'));
      res := jsonb_build_object('status', 'done', 'outcome', 'created', 'project_id', jid, 'name', btrim(d->>'name'), 'location', btrim(d->>'location'),
        'job_code', 'FIELD-' || upper(substr(md5(jid::text), 1, 6)), 'created', true, 'ready_state', 'not_ready',
        'supervisor_notice', jsonb_build_object('message_id', msg, 'recipients', coalesce(cardinality(people), 0), 'channel', 'job chat mention'));
    end if;

  elsif a.action = 'save_unit' then
    if jid is null then raise exception 'Choose the job first.'; end if;
    proposed := coalesce(d->'facts', '{}');
    perform public.validate_custom_work_facts(proposed);
    if length(btrim(coalesce(d->>'label', ''))) not between 1 and 120 then raise exception 'Give the unit its number or name.'; end if;
    label_norm := lower(btrim(d->>'label'));
    -- Resolve identity first: a stated id, then a map unit, then a same-named
    -- record. "Start unit four" never makes a second unit four.
    if nullif(d->>'unit_id', '') is not null then
      select * into u from custom_work_units where id = (d->>'unit_id')::uuid for update;
      if u.id is null or u.project_id is distinct from jid then raise exception 'That unit is not on this job.'; end if;
      select * into o from project_openings where id = u.opening_id;
    elsif nullif(d->>'opening_id', '') is not null then
      select * into o from project_openings where id = (d->>'opening_id')::uuid and project_id = jid and removed_at is null;
      if o.id is null then raise exception 'That map unit is not on this job.'; end if;
      select * into u from custom_work_units where opening_id = o.id for update;
    else
      select * into u from custom_work_units where project_id = jid and lower(btrim(label)) = label_norm for update;
      select * into o from project_openings where project_id = jid and removed_at is null and lower(btrim(opening_code)) = label_norm limit 1;
      if u.id is null and o.id is not null then
        select * into u from custom_work_units where opening_id = o.id for update;
      elsif u.id is not null and o.id is not null and u.opening_id is distinct from o.id then
        raise exception 'Two different records use this unit name. Open the job''s unit list and choose the right one.';
      end if;
    end if;
    if u.id is null then
      -- New record. A map unit starts from what the plans say; a spoken value that
      -- disagrees with the plans is shown, never silently chosen.
      plan := case when o.id is not null then public._ai_plan_facts(o.id) else '{}'::jsonb end;
      for k, v in select * from jsonb_each(proposed) loop
        if plan ? k and k in ('width_in','height_in','location') and v is distinct from plan->k
           and (jsonb_typeof(v) <> 'string' or lower(btrim(v #>> '{}')) <> lower(btrim(plan->>k))) then
          conflicts := conflicts || jsonb_build_object(k, jsonb_build_object('plans', plan->k, 'said', v));
        end if;
      end loop;
      if plan ? 'type_label' and nullif(btrim(d->>'type_label'), '') is not null and lower(btrim(d->>'type_label')) <> lower(plan->>'type_label') then
        conflicts := conflicts || jsonb_build_object('type_label', jsonb_build_object('plans', plan->'type_label', 'said', btrim(d->>'type_label')));
      end if;
      if from_confirm and prev->'plan' is distinct from plan then
        res := public._ai_stale('The plans for this unit changed since you chose. Ask again.');
      elsif conflicts <> '{}' and p_choice is null then
        res := public._ai_waiting(jsonb_build_object('reason', 'plan_conflict', 'message', 'The plans say something different for unit ' || o.opening_code || '. Which should the field record use?',
          'plan', plan, 'differences', conflicts, 'map_code', o.opening_code,
          'options', jsonb_build_array(jsonb_build_object('id', 'use_plans', 'label', 'Use the plans'), jsonb_build_object('id', 'use_said', 'label', 'Use what I said (plans stay unchanged)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
      else
        newfacts := public._ai_plan_seed(plan) || case when p_choice = 'use_plans' then proposed - (select coalesce(array_agg(key), '{}') from jsonb_object_keys(conflicts) key) else proposed end;
        outid := public.custom_work_command(md5(a.id::text || ':unit')::uuid, 'unit', jsonb_build_object('id', a.id, 'revision', 0, 'project_id', jid,
          'opening_id', o.id, 'label', coalesce(o.opening_code, btrim(d->>'label')),
          'type_label', coalesce(case when p_choice = 'use_plans' then plan->>'type_label' end, nullif(btrim(d->>'type_label'), ''), plan->>'type_label', 'Unknown'),
          'facts', newfacts, 'reason', 'Field capture through Forge AI'));
        select * into u from custom_work_units where id = outid;
        res := jsonb_build_object('status', 'done', 'outcome', case when o.id is not null then 'created_from_map' else 'created' end, 'unit', public._ai_unit_json(u), 'project_id', jid,
          'from_plans', nullif(plan, '{}'::jsonb));
      end if;
    else
      can_edit := u.created_by = uid or public._is_lead(uid);
      -- A confirmation answers the record as it was shown. If anyone changed the
      -- unit since, the person has not seen what they would be overwriting.
      if from_confirm and (prev->'unit'->>'revision')::int is distinct from u.revision then
        res := public._ai_stale('Unit ' || u.label || ' changed since you saw this. Nothing was changed; ask again to see the latest details.');
      elsif nullif(d->>'unit_id', '') is not null and lower(btrim(d->>'label')) <> lower(btrim(u.label)) and p_choice is null then
        res := public._ai_waiting(jsonb_build_object('reason', 'identity', 'message', 'You named unit ' || btrim(d->>'label') || ', but the selected record is unit ' || u.label || '. Which is it?',
          'unit', public._ai_unit_json(u), 'options', jsonb_build_array(jsonb_build_object('id', 'keep_original', 'label', 'It is unit ' || u.label), jsonb_build_object('id', 'cancel', 'label', 'Neither — cancel'))));
      else
        for k, v in select * from jsonb_each(proposed) loop
          if k = 'unknown_fields' then continue; end if;
          if not (u.facts ? k) then additions := additions || jsonb_build_object(k, v);
          elsif (jsonb_typeof(v) = 'string' and lower(btrim(v #>> '{}')) is distinct from lower(btrim(u.facts ->> k))) or (jsonb_typeof(v) <> 'string' and v is distinct from u.facts -> k) then
            conflicts := conflicts || jsonb_build_object(k, jsonb_build_object('stored', u.facts -> k, 'said', v));
          end if;
        end loop;
        if nullif(btrim(d->>'type_label'), '') is not null and lower(btrim(d->>'type_label')) <> lower(u.type_label) then
          if u.type_label = 'Unknown' then additions := additions || jsonb_build_object('type_label', btrim(d->>'type_label'));
          else conflicts := conflicts || jsonb_build_object('type_label', jsonb_build_object('stored', u.type_label, 'said', btrim(d->>'type_label'))); end if;
        end if;
        if conflicts <> '{}' and p_choice is null then
          -- D18: say what the record says and what was said; nothing is overwritten.
          res := public._ai_waiting(jsonb_build_object('reason', 'fact_conflict', 'message', 'Unit ' || u.label || ' already has different details. Keep what is saved, or correct the record?',
            'unit', public._ai_unit_json(u), 'differences', conflicts, 'additions', additions, 'can_edit', can_edit,
            'options', jsonb_build_array(jsonb_build_object('id', 'keep_original', 'label', 'Keep the saved details (I misspoke)'))
              || case when can_edit then jsonb_build_array(jsonb_build_object('id', 'correct_record', 'label', 'Correct the unit record')) else '[]'::jsonb end
              || jsonb_build_array(jsonb_build_object('id', 'send_for_review', 'label', 'Keep saved details and send my observation for review'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif p_choice = 'correct_record' and not can_edit then
          raise exception 'Only the unit''s author or a foreman can correct this record. Send it for review instead.';
        elsif p_choice = 'send_for_review' or (not can_edit and (additions <> '{}' or conflicts <> '{}')) then
          -- The saved record stays as it is; the observation waits in the unit's
          -- history for a foreman. Checked before "unchanged" so a review of
          -- differences alone is never dropped.
          insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
          values (jid, uid, u.id, 'ai_observation', jsonb_build_object('type', u.type_label, 'facts', u.facts, 'revision', u.revision),
            jsonb_build_object('additions', additions, 'differences', conflicts, 'request_id', r.id),
            'Crew observation through Forge AI; not applied to the record');
          res := jsonb_build_object('status', 'done', 'outcome', 'sent_for_review', 'unit', public._ai_unit_json(u), 'project_id', jid,
            'observation', jsonb_build_object('additions', additions, 'differences', conflicts),
            'message', 'Saved as an observation for a foreman to review. The unit record is unchanged.');
        else
          newfacts := u.facts || (additions - 'type_label') || case when p_choice = 'correct_record' then (select coalesce(jsonb_object_agg(key, value->'said'), '{}') from jsonb_each(conflicts) where key <> 'type_label') else '{}' end;
          select coalesce(jsonb_agg(distinct x), '[]') into unknowns from (
            select jsonb_array_elements_text(coalesce(u.facts->'unknown_fields', '[]')) x union select jsonb_array_elements_text(coalesce(proposed->'unknown_fields', '[]'))) z
            where not (newfacts ? x) and not (x = 'type_label' and coalesce(additions->>'type_label', u.type_label) <> 'Unknown');
          newfacts := (newfacts - 'unknown_fields') || case when jsonb_array_length(unknowns) > 0 then jsonb_build_object('unknown_fields', unknowns) else '{}' end;
          -- Same facts and the same set of unanswered questions (order aside) is no change.
          if additions = '{}' and (p_choice is distinct from 'correct_record' or conflicts = '{}') and (newfacts - 'unknown_fields') = (u.facts - 'unknown_fields')
             and unknowns = (select coalesce(jsonb_agg(distinct x), '[]') from jsonb_array_elements_text(coalesce(u.facts->'unknown_fields', '[]')) x) then
            res := jsonb_build_object('status', 'done', 'outcome', 'unchanged', 'unit', public._ai_unit_json(u), 'project_id', jid,
              'kept_original', case when p_choice = 'keep_original' then conflicts end);
          else
            outid := public.custom_work_command(md5(a.id::text || ':unit')::uuid, 'unit', jsonb_build_object('id', u.id, 'revision', u.revision, 'project_id', u.project_id,
              'opening_id', u.opening_id, 'label', u.label,
              'type_label', case when p_choice = 'correct_record' and conflicts ? 'type_label' then conflicts->'type_label'->>'said' else coalesce(additions->>'type_label', u.type_label) end,
              'facts', newfacts, 'reason', case when p_choice = 'correct_record' then 'Crew correction through Forge AI' else 'Details added through Forge AI' end));
            select * into u from custom_work_units where id = outid;
            res := jsonb_build_object('status', 'done', 'outcome', case when p_choice = 'correct_record' then 'corrected' else 'details_added' end,
              'unit', public._ai_unit_json(u), 'project_id', jid, 'kept_original', case when p_choice = 'keep_original' then conflicts end);
          end if;
        end if;
      end if;
    end if;

  elsif a.action in ('start_unit','start_idle','stop_work') then
    st := public._ai_clock_state(uid);
    if not from_confirm then
      -- Never act on an old or delayed request, on a phone still sending a clock
      -- change, or on timing that moved at ANY point after the phone last read
      -- it before Send — in transit, on arrival or while the model worked, and
      -- even if it moved back.
      if r.sent_at < now() - interval '5 minutes' or r.received_at < now() - interval '5 minutes' then
        res := public._ai_stale('This request was sent more than five minutes ago, so no timer was changed. Ask again if you still want this.');
      elsif coalesce((snap->>'client_pending_sync')::boolean, false) then
        res := public._ai_stale('Your phone is still sending a job-clock change. Wait until it syncs, then ask again.');
      elsif coalesce((snap->>'changed_after_send')::boolean, true) or (st->>'epoch')::bigint <> (snap->>'epoch')::bigint then
        res := public._ai_stale('Your job clock or a timer changed after you sent this, so I did not change anything. Check the clock and ask again.');
      end if;
    elsif p_choice in ('end_break_and_start','join_helper') and (st->>'epoch')::bigint is distinct from (prev->>'epoch')::bigint then
      res := public._ai_stale('Your clock or timers changed since this question. Nothing was started; ask again.');
    elsif p_choice = 'start_now' and (st->'session' is distinct from prev->'work_session' or st->'work' is distinct from prev->'work') then
      -- Clocking in is the expected change; any other timer that started since is
      -- not ours to stop.
      res := public._ai_stale('Another timer started since this question. It was left running; ask again if you want to switch.');
    end if;
    if res is null then
      select * into sh from time_shifts where id = nullif(st->'shift'->>'id', '')::uuid for update;
      select * into s from custom_work_sessions where profile_id = uid and ended_at is null for update;
      if a.action = 'stop_work' then
        if s.id is null then res := jsonb_build_object('status', 'done', 'outcome', 'already_stopped');
        else
          if d->>'outcome' not in ('finished','partial','blocked','rework') then raise exception 'Was this stage finished, partial, blocked or rework?'; end if;
          outid := public.custom_work_command(md5(a.id::text || ':stop')::uuid, 'stop', jsonb_build_object('expected_session_id', s.id, 'at', now(),
            'outcome', d->>'outcome', 'finish_note', coalesce(nullif(btrim(d->>'note'), ''), s.description)));
          jid := s.project_id;
          res := jsonb_build_object('status', 'done', 'outcome', 'stopped', 'session_id', outid, 'stage', s.stage, 'stage_outcome', d->>'outcome',
            'unit', (select label from custom_work_units where id = s.unit_id), 'stopped_at', now(), 'job_clock_still_running', sh.id is not null,
            'helpers_still_working', (select count(*) from custom_work_sessions where unit_id = s.unit_id and ended_at is null and profile_id <> uid),
            'qc', 'not_approved');
        end if;
      else
        stage := coalesce(nullif(d->>'stage', ''), 'Installing');
        part := case when p_choice = 'join_helper' then 'helper' else coalesce(nullif(d->>'participation', ''), 'install') end;
        if a.action = 'start_idle' then
          if length(btrim(coalesce(d->>'description', ''))) not between 1 and 4000 then raise exception 'Describe the idle time.'; end if;
          jid := coalesce(jid, (sh.project_id));
        else
          if stage not in ('Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') or part not in ('install','helper') then raise exception 'Choose a work stage.'; end if;
          select * into u from custom_work_units where id = nullif(d->>'unit_id', '')::uuid for update;
          if u.id is null or u.project_id is distinct from jid then raise exception 'Choose a unit on this job first.'; end if;
          if lower(btrim(u.type_label)) = 'unknown' then raise exception 'Say what type of unit this is before starting its timer.'; end if;
          -- The map owner is the owner; lock it so dispatch cannot hand it out mid-claim.
          if u.opening_id is not null then select * into o from project_openings where id = u.opening_id for update; end if;
          if (u.facts->>'installation_complete' = 'Yes' or o.status = 'installed') and stage <> 'Rework' then
            raise exception 'Unit % is already finished. Rework starts only as the Rework stage.', u.label;
          end if;
          assignee := case when u.opening_id is not null then o.assigned_to else u.assigned_to end;
          select coalesce(jsonb_agg(pr.display_name order by pr.display_name), '[]') into others from (
            select w.profile_id from custom_work_sessions w where w.unit_id = u.id and w.ended_at is null and w.profile_id <> uid
            union select us.profile_id from unit_sessions us where u.opening_id is not null and us.opening_id = u.opening_id and us.ended_at is null and us.profile_id <> uid) x
            join profiles pr on pr.id = x.profile_id;
        end if;
        if a.action = 'start_unit' and s.id is not null and s.unit_id is not distinct from u.id and s.stage = stage and s.participation = part then
          -- Repeating a start never restarts the timer.
          res := jsonb_build_object('status', 'running', 'outcome', 'already_running', 'session_id', s.id, 'unit', public._ai_unit_json(u), 'started_at', s.started_at, 'stage', s.stage);
        elsif a.action = 'start_unit' and part = 'install' and ((assignee is not null and assignee <> uid) or (assignee is null and jsonb_array_length(others) > 0)) then
          -- D25: occupied work is never silently taken; the person may help instead.
          res := public._ai_waiting(jsonb_build_object('reason', 'claimed', 'message', 'Unit ' || u.label || ' is ' ||
              case when assignee is not null then 'assigned to ' || coalesce((select display_name from profiles where id = assignee), 'someone else') else 'being worked by ' || (select string_agg(x, ', ') from jsonb_array_elements_text(others) x) end
              || '. Join as a helper with your own time?', 'unit', public._ai_unit_json(u), 'working_now', others, 'epoch', (st->>'epoch')::bigint,
            'options', jsonb_build_array(jsonb_build_object('id', 'join_helper', 'label', 'Join as a helper'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif sh.id is null or sh.status <> 'open' then
          res := public._ai_waiting(jsonb_build_object('reason', 'needs_clock', 'message', 'You are not clocked in. Use the job clock to clock in' ||
              coalesce(' to ' || (select name from projects where id = jid), '') || ', then tap Start now.',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'stage', stage, 'work_session', st->'session', 'work', st->'work',
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now (after clocking in)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif jid is not null and sh.project_id is distinct from jid then
          res := public._ai_waiting(jsonb_build_object('reason', 'wrong_job', 'message', 'Use the job clock to switch from ' || coalesce((select name from projects where id = sh.project_id), 'your current job') || ' to ' || (select name from projects where id = jid) || ', then tap Start now. Your time so far stays on ' || coalesce((select name from projects where id = sh.project_id), 'that job') || '.',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'current_job', (select name from projects where id = sh.project_id), 'stage', stage,
            'work_session', st->'session', 'work', st->'work',
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now (after switching jobs)'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        elsif sh.break_started_at is not null and p_choice is distinct from 'end_break_and_start' then
          res := public._ai_waiting(jsonb_build_object('reason', 'on_break', 'message', 'End your break and start ' || coalesce('unit ' || u.label, 'idle time') || '?',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'stage', stage, 'epoch', (st->>'epoch')::bigint,
            'options', jsonb_build_array(jsonb_build_object('id', 'end_break_and_start', 'label', 'End break and start ' || coalesce('unit ' || u.label, 'idle time')), jsonb_build_object('id', 'cancel', 'label', 'Stay on break'))));
        elsif not from_confirm and not coalesce((snap->>'send_time_eligible')::boolean, false) then
          -- Nothing changed, but the phone's clock puts Send before this shift or
          -- before the last change it had seen: the send time cannot be trusted,
          -- so the person decides to start now rather than we guess a time.
          res := public._ai_waiting(jsonb_build_object('reason', 'confirm_time', 'message', 'This phone''s clock does not match the server, so the time you sent this cannot be used. Start ' || coalesce('unit ' || u.label, 'idle time') || ' now?',
            'unit', case when u.id is not null then public._ai_unit_json(u) end, 'project_id', jid, 'stage', stage, 'work_session', st->'session', 'work', st->'work', 'device_sent_at', r.sent_at,
            'options', jsonb_build_array(jsonb_build_object('id', 'start_now', 'label', 'Start now'), jsonb_build_object('id', 'cancel', 'label', 'Cancel'))));
        else
          if p_choice = 'end_break_and_start' then
            perform public.end_break(sh.id);
            select * into sh from time_shifts where id = sh.id;
          end if;
          -- D16: the send time, only for an unchanged request sent on this open
          -- shift. A resume, a switch or a later tap starts now, never backdated.
          at_time := case when not from_confirm then r.sent_at else now() end;
          if s.id is not null and at_time < s.started_at then
            -- The running timer began after the words were said; the epoch should
            -- already have refused this, and it is never restamped to "now".
            raise exception 'Your current timer started after this request was sent. Ask again.';
          end if;
          outid := public.custom_work_command(md5(a.id::text || ':start')::uuid, 'start', jsonb_build_object('id', md5(a.id::text || ':session')::uuid,
            'unit_id', u.id, 'shift_id', sh.id, 'project_id', jid, 'expected_session_id', s.id, 'stage', stage, 'participation', part,
            'description', case when a.action = 'start_idle' then btrim(d->>'description') else '' end, 'at', at_time));
          if a.action = 'start_unit' and part = 'install' and assignee is null then
            if u.opening_id is not null then
              perform set_config('app.assignment_via', 'map', true);
              update project_openings set assigned_to = uid, assigned_by = uid, assigned_at = now() where id = u.opening_id and assigned_to is null;
            else
              update custom_work_units set assigned_to = uid, assigned_at = now(), revision = revision + 1, updated_at = now() where id = u.id and assigned_to is null;
            end if;
            insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
            values (jid, uid, u.id, 'claim', jsonb_build_object('assigned_to', null), jsonb_build_object('assigned_to', uid, 'map_opening', u.opening_id), 'Claimed through Forge AI');
          end if;
          if u.id is not null then select * into u from custom_work_units where id = u.id; end if;
          res := jsonb_build_object('status', 'running', 'outcome', 'started', 'session_id', outid, 'unit', case when u.id is not null then public._ai_unit_json(u) end,
            'project_id', jid, 'stage', case when a.action = 'start_idle' then 'Idle time' else stage end, 'participation', part, 'started_at', at_time,
            'start_time_basis', case when not from_confirm then 'request_sent' else 'tapped_start' end, 'device_sent_at', r.sent_at,
            'previous_timer_ended', s.id is not null, 'break_ended', p_choice = 'end_break_and_start',
            'claimed', a.action = 'start_unit' and part = 'install' and assignee is null);
        end if;
      end if;
    end if;

  elsif a.action = 'release_unit' then
    select * into u from custom_work_units where id = nullif(d->>'unit_id', '')::uuid for update;
    if u.id is null or u.project_id is distinct from jid then raise exception 'Choose a unit on this job first.'; end if;
    if u.opening_id is not null then select * into o from project_openings where id = u.opening_id for update; assignee := o.assigned_to; else assignee := u.assigned_to; end if;
    if assignee is null then res := jsonb_build_object('status', 'done', 'outcome', 'not_assigned', 'unit', public._ai_unit_json(u));
    elsif assignee <> uid and not public._is_lead(uid) then raise exception 'Only the assigned installer or a foreman can release this unit.';
    elsif exists (select 1 from custom_work_sessions where unit_id = u.id and profile_id = uid and ended_at is null) then raise exception 'Stop your timer on this unit before releasing it.';
    else
      if u.opening_id is not null then
        update project_openings set assigned_to = null, assigned_by = null, assigned_at = null where id = u.opening_id;
      else
        update custom_work_units set assigned_to = null, assigned_at = null, revision = revision + 1, updated_at = now() where id = u.id;
      end if;
      insert into custom_work_history(project_id, actor_id, entity_id, action, before_value, after_value, reason)
      values (jid, uid, u.id, 'release', jsonb_build_object('assigned_to', assignee), jsonb_build_object('assigned_to', null), 'Released through Forge AI');
      select * into u from custom_work_units where id = u.id;
      res := jsonb_build_object('status', 'done', 'outcome', 'released', 'unit', public._ai_unit_json(u),
        'helpers_still_working', (select count(*) from custom_work_sessions where unit_id = u.id and ended_at is null));
    end if;

  elsif a.action = 'crew_record' then
    if not public._is_lead(uid) then raise exception 'Only an active foreman, supervisor or owner can record work for the crew.' using errcode = '42501'; end if;
    if jid is null then raise exception 'Choose the job first.'; end if;
    if nullif(d->>'unit_id', '') is not null then
      select * into u from custom_work_units where id = (d->>'unit_id')::uuid;
      if u.id is null or u.project_id is distinct from jid then raise exception 'That unit is not on this job.'; end if;
    else
      select * into u from custom_work_units where project_id = jid and lower(btrim(label)) = lower(btrim(d->>'label'));
      if u.id is null then
        select * into o from project_openings where project_id = jid and removed_at is null and lower(btrim(opening_code)) = lower(btrim(d->>'label')) limit 1;
        if o.id is not null then select * into u from custom_work_units where opening_id = o.id; end if;
      end if;
    end if;
    plan := case when u.id is null and o.id is not null then public._ai_plan_facts(o.id) else '{}'::jsonb end;
    -- Existing facts go through unchanged: a crew record never corrects a unit.
    outid := public.record_crew_work(md5(a.id::text || ':crew')::uuid, jsonb_build_object(
      'unit', case when u.id is not null then jsonb_build_object('id', u.id, 'revision', u.revision, 'project_id', u.project_id, 'opening_id', u.opening_id, 'label', u.label, 'type_label', u.type_label, 'facts', u.facts)
               else jsonb_build_object('id', a.id, 'revision', 0, 'project_id', jid, 'opening_id', o.id, 'label', coalesce(o.opening_code, btrim(d->>'label')),
                 'type_label', coalesce(plan->>'type_label', nullif(btrim(d->>'type_label'), ''), 'Unknown'), 'facts', public._ai_plan_seed(plan), 'reason', 'Crew record through Forge AI') end,
      'people', d->'people', 'work_date', d->>'work_date', 'stage', d->>'stage', 'outcome', d->>'outcome', 'description', coalesce(d->>'description', ''), 'whole_complete', false));
    res := jsonb_build_object('status', 'done', 'outcome', 'crew_recorded', 'record_id', md5(a.id::text || ':crew')::uuid, 'unit', (select public._ai_unit_json(x) from custom_work_units x where id = outid),
      'people', (select jsonb_agg(display_name order by display_name) from profiles where id::text in (select jsonb_array_elements_text(d->'people'))),
      'work_date', d->>'work_date', 'stage', d->>'stage', 'stage_outcome', d->>'outcome', 'payroll_changed', false);
  else
    raise exception 'Unsupported field action.';
  end if;

  res := res || jsonb_build_object('action_id', a.id, 'action', a.action, 'request_id', a.request_id);
  update ai_field_actions set project_id = coalesce(jid, project_id), result = res, choice = coalesce(p_choice, choice),
    status = case res->>'status' when 'needs_choice' then 'waiting' when 'stale' then 'stale' else 'done' end,
    resolved_at = case when res->>'status' = 'needs_choice' then null else now() end
  where id = a.id;
  return public._work_activity_finish(__work_activity_root_id,(res)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_185$::text,false,'b4ff00ef820e022cd93e54017f5183474101c220ce6c789d12b15fe2ec6f0828'::text,'4e6a675b841ccb92ebf17a817296685c86f3658d72e0aae55c36d8f8ae476000'::text,'_ai_field_apply'::text,'p_action uuid, p_choice text'::text),
('ai_field_command(uuid, text, text, jsonb)'::text,$activity_body_186$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('ai_field_command','{}'::jsonb,p_request);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare uid uuid := public._ai_field_actor(); r ai_field_requests; aid uuid; a ai_field_actions;
begin
  select * into r from ai_field_requests where id = p_request;
  if r.id is null or r.profile_id <> uid then raise exception 'This request belongs to another account.' using errcode = '42501'; end if;
  if r.finished_at is not null then raise exception 'This request is finished. Send a new message.'; end if;
  if p_data is null or jsonb_typeof(p_data) <> 'object' or octet_length(p_data::text) > 40000 then raise exception 'Invalid action details.'; end if;
  if p_key is null or length(p_key) not between 1 and 300 then raise exception 'Invalid action key.'; end if;
  aid := md5(p_request::text || ':' || p_key)::uuid;
  perform pg_advisory_xact_lock(hashtextextended(aid::text, 7593));
  select * into a from ai_field_actions where id = aid;
  if found then
    -- Same action retried: the saved receipt. Different details under the same
    -- key: refuse, and show what was already done.
    if a.action <> p_action or a.data <> p_data then
      return public._work_activity_finish(__work_activity_root_id,(a.result || jsonb_build_object('replay', 'changed', 'message', 'This request already did something different. Send a new message to change it.'))::jsonb);
    end if;
    return public._work_activity_finish(__work_activity_root_id,(a.result || jsonb_build_object('replay', 'same'))::jsonb);
  end if;
  -- A stop or idle start names no job; file it under the running shift/timer so
  -- the receipt sits behind the same job boundary (and sandbox fence).
  insert into ai_field_actions(id, request_id, profile_id, project_id, action, action_key, data)
  values (aid, p_request, uid, coalesce(nullif(p_data->>'project_id', '')::uuid,
    case when p_action = 'stop_work' then (select project_id from custom_work_sessions where profile_id = uid and ended_at is null)
         when p_action = 'start_idle' then (select project_id from time_shifts where profile_id = uid and status = 'open' and clock_out_at is null order by clock_in_at desc limit 1) end),
    p_action, p_key, p_data);
  return public._work_activity_finish(__work_activity_root_id,(public._ai_field_apply(aid, null))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_186$::text,false,'42654e187269e76a57efba72912e7e38ae81d4889b8c11d948c9cea61323521f'::text,'fb5fb1c8090236e6ee828387d3e3ad14ee96ff29cbcebfaeb8fcd22e3cdef0bb'::text,'ai_field_command'::text,'p_request uuid, p_key text, p_action text, p_data jsonb'::text),
('ai_field_resolve(uuid, text, text)'::text,$activity_body_187$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('ai_field_resolve','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare uid uuid := public._ai_field_actor(); a ai_field_actions;
begin
  perform pg_advisory_xact_lock(hashtextextended(p_action::text, 7593));
  select * into a from ai_field_actions where id = p_action;
  if a.id is null or a.profile_id <> uid then raise exception 'This choice belongs to another account.' using errcode = '42501'; end if;
  if a.status <> 'waiting' then return public._work_activity_finish(__work_activity_root_id,(a.result)::jsonb); end if;
  if p_preview_hash is distinct from a.result->>'preview_hash' then raise exception 'This choice changed. Review the latest card before choosing.'; end if;
  if not exists (select 1 from jsonb_array_elements(a.result->'options') x where x->>'id' = p_choice) then raise exception 'Choose one of the options shown.'; end if;
  if p_choice = 'cancel' then
    update ai_field_actions set status = 'cancelled', choice = 'cancel', resolved_at = now(),
      result = result - 'options' - 'preview_hash' || jsonb_build_object('status', 'cancelled') where id = a.id;
    return public._work_activity_finish(__work_activity_root_id,((select result from ai_field_actions where id = a.id))::jsonb);
  end if;
  return public._work_activity_finish(__work_activity_root_id,(public._ai_field_apply(a.id, p_choice))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_187$::text,false,'9067b76cde79b832ca09dc3cd27e279150f824d5bb660a573bc63ab5ea3ca389'::text,'e782885f2846f62ce6794346f576522c66c04481fd1c02331bb2464d3275bca0'::text,'ai_field_resolve'::text,'p_action uuid, p_choice text, p_preview_hash text'::text),
('_flag_shift_for_review(uuid, text, text)'::text,$activity_body_188$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_flag_shift_for_review','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
begin
  update public.time_shifts
     set review_reason = coalesce(review_reason, p_reason)
   where id = p_shift_id;
  insert into public.time_shift_edits (shift_id, edited_by, field, old_value, new_value, reason)
  values (p_shift_id, auth.uid(), 'review_reason', null, p_reason, p_sentence);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_188$::text,false,'c32e53fee3019dcb0b90a59e7df11d164dfaec03b28553fb14964296617dbb3d'::text,'6c9267c4aee8970cc3ceaa671c0b34105a1750a4637264296a8343ac22429d17'::text,'_flag_shift_for_review'::text,'p_shift_id uuid, p_reason text, p_sentence text'::text),
('clock_in(uuid, uuid, text, double precision, double precision, text, text, uuid, timestamp with time zone, timestamp with time zone, integer)'::text,$activity_body_189$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_in','{}'::jsonb,p_client_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 perform public._work_activity_clock_replay_guard(p_client_id,'clock_in',null);

declare
  v_uid uuid := auth.uid();
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_had_open boolean;
  v_setup_admitted boolean;
  v_previous_end timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before clocking in.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This clock-in is missing its id. Update the app and try again.';
  end if;

  -- One person, one clock-in at a time, until this transaction ends. Two
  -- devices sending clock-ins together — or one tap resent neck and neck
  -- with itself — would otherwise both read the timeline below before either
  -- had written to it, and the second would not see the first's shift.
  perform pg_advisory_xact_lock(hashtextextended('clock_in:' || v_uid::text, 0));

  -- The same tap arriving twice: answer with the shift it already made.
  select ts.* into v_shift
    from public.time_clock_actions a
    join public.time_shifts ts on ts.id = a.shift_id
   where a.client_id = p_client_id and a.profile_id = v_uid;
  if v_shift.id is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;
  -- A queued punch that went through the older client_id overload before the
  -- app updated, then retried through this one.
  select * into v_shift from public.time_shifts
   where client_id = p_client_id and profile_id = v_uid;
  if v_shift.id is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;

  v_setup_admitted:=public._work_activity_claim_clock_setup(p_project_id,p_cost_code_id,p_photo,p_lat,p_lng,p_note,p_mode,p_client_id,p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
  if not public._toolbox_gate_open(v_uid) and not v_setup_admitted then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  -- A shift still open when this one arrives is closed at ARRIVAL by the
  -- dangling-shift guard. Starting the new one at an earlier tap time would
  -- overlap the two and pay the gap twice, so the new one starts at arrival
  -- too, and says why.
  select exists (
    select 1 from public.time_shifts
     where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) into v_had_open;
  if exists(select 1 from public.time_shifts where profile_id=auth.uid() and status<>'voided' and greatest(clock_in_at,clock_out_at,last_punch_at,break_started_at)>__work_activity_arrival) then raise exception 'Existing clock times need foreman review before a new shift can start.';end if;
  perform public._close_dangling_shift(v_uid);

  if v_had_open then
    v_pick := (__work_activity_arrival, false, 'previous_shift_open')::public.clock_time_pick;
  else
    v_pick := public._clock_pick_time_at(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, null,__work_activity_arrival);
    -- The end of this person's timeline: the latest moment any shift that
    -- still counts reached (a voided one has left every total; a completed
    -- or approved one has not). A trusted tap before it would start this
    -- shift inside the previous one and pay the overlap twice — the stale
    -- device whose earlier clock-in arrives after another phone or the
    -- office closed the day. Arrival instead, marked, with the tap kept in
    -- the ledger for the review. An untrusted tap is already arrival time.
    select max(greatest(clock_in_at, clock_out_at)) into v_previous_end
      from public.time_shifts
     where profile_id = v_uid and status <> 'voided';
    if v_pick.used_tap and v_previous_end is not null and v_pick.pay_at < v_previous_end then
      v_pick := (__work_activity_arrival, false, 'overlaps_previous_shift')::public.clock_time_pick;
    end if;
  end if;

  insert into public.time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng,
     note, job_mode, client_id, clock_in_at, last_punch_at, review_reason)
  values
    (v_uid, p_project_id, p_cost_code_id, p_photo, p_lat, p_lng,
     nullif(btrim(p_note), ''),
     case when p_mode in ('data', 'tracking') then p_mode else null end,
     p_client_id, v_pick.pay_at, v_pick.pay_at, v_pick.reason)
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'clock_in', 'clocked_in', p_tapped_at, __work_activity_arrival,
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, __work_activity_arrival, v_previous_end));
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_189$::text,false,'f567f8e3617861e22c6cded1b27e11f7de6f7b7654db1120b5e4ce0e74a1a42d'::text,'ad7268b517980f7a4fc9f8cf7949bda734b127ccd2ee7eeec04119bffaf1c7e5'::text,'clock_in'::text,'p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision, p_note text, p_mode text, p_client_id uuid, p_tapped_at timestamp with time zone, p_clock_checked_at timestamp with time zone, p_clock_skew_ms integer'::text),
('clock_out(uuid, text, boolean, boolean, integer, double precision, double precision, text, uuid, timestamp with time zone, timestamp with time zone, integer)'::text,$activity_body_190$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('clock_out','{}'::jsonb,p_client_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 perform public._work_activity_clock_replay_guard(p_client_id,'clock_out',p_shift_id);

declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before clocking out.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This clock-out is missing its id. Update the app and try again.';
  end if;

  -- Already applied: the original result, and not one column moved.
  if exists (select 1 from public.time_clock_actions where client_id = p_client_id and profile_id = v_uid) then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;
  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    raise exception 'This shift was already clocked out. Nothing was changed.';
  end if;

  -- Not before the shift's last punch: the clock-in, the break still running,
  -- or the end of a break already finished (last_punch_at — the break columns
  -- are cleared when a break ends, and were once all this looked at).
  v_not_before := greatest(v_open.clock_in_at, v_open.break_started_at, v_open.last_punch_at);
  v_pick := public._clock_pick_time_at(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before,__work_activity_arrival);
  if v_pick.pay_at is null then
    v_shift:=public._work_activity_clock_review(p_shift_id,p_client_id,'clock_out',p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;


  update public.time_shifts ts
  set clock_out_at = v_pick.pay_at,
      last_punch_at = v_pick.pay_at,
      clock_out_photo = coalesce(p_photo, ts.clock_out_photo),
      injured = p_injured,
      injury_note = case when p_injured then nullif(trim(coalesce(p_injury_note, '')), '') else null end,
      time_confirmed = p_time_confirmed,
      break_seconds = coalesce(p_break_seconds,
        ts.break_seconds + case
          when ts.break_started_at is not null
            then greatest(0, floor(extract(epoch from (v_pick.pay_at - ts.break_started_at)))::int)
          else 0
        end),
      break_started_at = null,
      break_type = null,
      clock_out_lat = coalesce(p_lat, ts.clock_out_lat),
      clock_out_lng = coalesce(p_lng, ts.clock_out_lng),
      signed_at = __work_activity_arrival,
      status = 'submitted',
      review_reason = coalesce(ts.review_reason, v_pick.reason)
  where ts.id = v_open.id
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'clock_out', 'clocked_out', p_tapped_at, __work_activity_arrival,
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, __work_activity_arrival, v_not_before));
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_190$::text,false,'a60a58072a07e0b78e1f62656c4c39705443e8ffcb48b65c862f28a3c5db4df6'::text,'2ddaca78ba00333dde9100492716df17f279c6ab1fc99d3b17ce20f77c0bb636'::text,'clock_out'::text,'p_shift_id uuid, p_photo text, p_injured boolean, p_time_confirmed boolean, p_break_seconds integer, p_lat double precision, p_lng double precision, p_injury_note text, p_client_id uuid, p_tapped_at timestamp with time zone, p_clock_checked_at timestamp with time zone, p_clock_skew_ms integer'::text),
('start_break(uuid, text, uuid, timestamp with time zone, timestamp with time zone, integer)'::text,$activity_body_191$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('start_break','{}'::jsonb,p_client_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 perform public._work_activity_clock_replay_guard(p_client_id,'break_start',p_shift_id);

declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_outcome text;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before starting a break.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This break is missing its id. Update the app and try again.';
  end if;

  if exists (select 1 from public.time_clock_actions where client_id = p_client_id and profile_id = v_uid) then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;
  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    raise exception 'This shift is already clocked out, so a break can''t start on it.';
  end if;

  if v_open.break_started_at is not null then
    -- Already on a break: the earlier start stands, as it always has.
    v_shift := v_open;
    v_outcome := 'already_on_break';
    v_pick := (__work_activity_arrival, false, null)::public.clock_time_pick;
  else
    -- Not before the clock-in, nor before a break this shift already finished
    -- (last_punch_at): a second break tapped inside the first would deduct
    -- that time twice.
    v_not_before := greatest(v_open.clock_in_at, v_open.last_punch_at);
    v_pick := public._clock_pick_time_at(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before,__work_activity_arrival);
  if v_pick.pay_at is null then
    v_shift:=public._work_activity_clock_review(p_shift_id,p_client_id,'break_start',p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
    return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
  end if;

    update public.time_shifts ts
       set break_started_at = v_pick.pay_at,
           last_punch_at = v_pick.pay_at,
           break_type = coalesce(ts.break_type, case when p_break_type in ('lunch', 'rest', 'other') then p_break_type else 'other' end),
           review_reason = coalesce(ts.review_reason, v_pick.reason)
     where ts.id = v_open.id
    returning * into v_shift;
    v_outcome := 'started';

    -- Going on a break pauses every phase clock you have running (20260811010000).
    update public.opening_phases
       set paused_at = coalesce(paused_at, __work_activity_arrival)
     where status = 'active' and started_by = v_uid;
  end if;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'break_start', v_outcome, p_tapped_at, __work_activity_arrival,
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, __work_activity_arrival, v_not_before));
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_shift)::public.time_shifts);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_191$::text,false,'3664fe81ef27ea6eeb692001339cad2f9a4c17b4405196cc33d337bc4e2e3b3a'::text,'02f00615f0264ad7f3b0b21a949df2c5e8a9257b9b66f714ef866df913d84cbc'::text,'start_break'::text,'p_shift_id uuid, p_break_type text, p_client_id uuid, p_tapped_at timestamp with time zone, p_clock_checked_at timestamp with time zone, p_clock_skew_ms integer'::text),
('end_break(uuid, uuid, timestamp with time zone, timestamp with time zone, integer)'::text,$activity_body_192$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('end_break','{}'::jsonb,p_client_id);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 perform public._work_activity_clock_replay_guard(p_client_id,'break_end',p_shift_id);

declare
  v_uid uuid := auth.uid();
  v_open public.time_shifts;
  v_shift public.time_shifts;
  v_pick public.clock_time_pick;
  v_prior text;
  v_not_before timestamptz;
begin
  if v_uid is null then
    raise exception 'Sign in before ending a break.';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This break end is missing its id. Update the app and try again.';
  end if;

  select a.outcome into v_prior from public.time_clock_actions a
   where a.client_id = p_client_id and a.profile_id = v_uid;
  if v_prior is not null then
    select * into v_shift from public.time_shifts where id = p_shift_id and profile_id = v_uid;
    if v_shift.id is null then raise exception 'no open shift %', p_shift_id; end if;
    return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('outcome', v_prior, 'shift', to_jsonb(v_shift)))::jsonb);
  end if;

  select * into v_open from public.time_shifts
   where id = p_shift_id and profile_id = v_uid
   for update;
  if v_open.id is null then
    raise exception 'no open shift %', p_shift_id;
  end if;

  if v_open.status <> 'open' or v_open.clock_out_at is not null then
    insert into public.time_clock_actions
      (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at, clock_checked_at, clock_skew_ms)
    values
      (p_client_id, v_open.id, v_uid, 'break_end', 'shift_closed', p_tapped_at, __work_activity_arrival, p_clock_checked_at, p_clock_skew_ms);
    return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('outcome', 'shift_closed', 'shift', to_jsonb(v_open)))::jsonb);
  end if;

  if v_open.break_started_at is null then
    -- K0.4: nothing to end. Refuse, keep the refusal, mark the shift.
    insert into public.time_clock_actions
      (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at, clock_checked_at, clock_skew_ms, review_reason)
    values
      (p_client_id, v_open.id, v_uid, 'break_end', 'no_break_running', p_tapped_at, __work_activity_arrival, p_clock_checked_at, p_clock_skew_ms, 'break_end_without_break');
    perform public._flag_shift_for_review(v_open.id, 'break_end_without_break',
      public._clock_review_sentence('break_end_without_break', p_tapped_at, __work_activity_arrival, null));
    select * into v_shift from public.time_shifts where id = v_open.id;
    return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('outcome', 'no_break_running', 'shift', to_jsonb(v_shift)))::jsonb);
  end if;

  -- Not before the break it is ending (which is also the shift's last punch).
  v_not_before := greatest(v_open.break_started_at, v_open.last_punch_at);
  v_pick := public._clock_pick_time_at(p_tapped_at, p_clock_checked_at, p_clock_skew_ms, v_not_before,__work_activity_arrival);
  if v_pick.pay_at is null then
    v_shift:=public._work_activity_clock_review(p_shift_id,p_client_id,'break_end',p_tapped_at,p_clock_checked_at,p_clock_skew_ms);
    return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('outcome','requires_review','shift',to_jsonb(v_shift)))::jsonb);
  end if;


  update public.time_shifts ts
     set break_seconds = ts.break_seconds
           + greatest(0, extract(epoch from (v_pick.pay_at - ts.break_started_at))::int),
         break_started_at = null,
         break_type = null,
         last_punch_at = v_pick.pay_at,
         review_reason = coalesce(ts.review_reason, v_pick.reason)
   where ts.id = v_open.id
  returning * into v_shift;

  insert into public.time_clock_actions
    (client_id, shift_id, profile_id, action, outcome, tapped_at, arrived_at,
     clock_checked_at, clock_skew_ms, used_tap_time, review_reason)
  values
    (p_client_id, v_shift.id, v_uid, 'break_end', 'ended', p_tapped_at, __work_activity_arrival,
     p_clock_checked_at, p_clock_skew_ms, v_pick.used_tap, v_pick.reason);

  if v_pick.reason is not null then
    perform public._flag_shift_for_review(v_shift.id, v_pick.reason,
      public._clock_review_sentence(v_pick.reason, p_tapped_at, __work_activity_arrival, v_not_before));
  end if;

  return public._work_activity_finish(__work_activity_root_id,(jsonb_build_object('outcome', 'ended', 'shift', to_jsonb(v_shift)))::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_192$::text,false,'3cf4a8b2c8bf1c4fb75104e4b83738ebe8e81550dd5de0b66cb0fd792072ce8c'::text,'470a0539693065c6cbd7ff51d8033fd74500570db13cdc2b990719a0eb2f7fc4'::text,'end_break'::text,'p_shift_id uuid, p_client_id uuid, p_tapped_at timestamp with time zone, p_clock_checked_at timestamp with time zone, p_clock_skew_ms integer'::text),
('set_my_ui_design(text)'::text,$activity_body_193$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_my_ui_design','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v text := lower(coalesce(trim(p_design), ''));
begin
  if auth.uid() is null then
    raise exception 'sign in before choosing a design' using errcode = '42501';
  end if;

  if v not in ('classic', 'new') then
    raise exception 'design must be classic or new' using errcode = '22023';
  end if;

  update public.profiles
     set ui_design = v, updated_at = now()
   where id = auth.uid();
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_193$::text,false,'132f03112d817cc50d97171dcfaa5ead7401e465b4c5f428e1aeb42e2fe53088'::text,'0874e9122f7f0251e239cc91702509151e48c739b752a3bc92f1bb317c29ce38'::text,'set_my_ui_design'::text,'p_design text'::text),
('set_new_design_switch(text, boolean)'::text,$activity_body_194$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_new_design_switch','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row company_settings;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can turn a new design on or off for everyone.'
      using errcode = '42501';
  end if;
  if p_enabled is null then
    raise exception 'Say whether the new design is on or off.' using errcode = '22023';
  end if;

  if p_release = 'r1' then
    update company_settings
       set new_design_r1_enabled = p_enabled,
           updated_at = now(),
           updated_by = auth.uid()
     where id = 1
    returning * into v_row;
  else
    raise exception 'Unknown release "%". The only new design so far is r1.', p_release
      using errcode = '22023';
  end if;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::company_settings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_194$::text,false,'355437437b6df30543d75f1c2e7bcb47dbe91be598028ca9bb0c3e83bc8c176c'::text,'a01c304c2da0fa5118d2d9a4b7b7f0fff78084118722a9594e982e26875f896a'::text,'set_new_design_switch'::text,'p_release text, p_enabled boolean'::text),
('set_paid_time_rule_date(date)'::text,$activity_body_195$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_paid_time_rule_date','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row company_settings;
begin
  if public.my_role_rank() < 3 then
    raise exception 'Only an owner can set when paid time starts at Start day.'
      using errcode = '42501';
  end if;
  -- A past date would switch the rule on retroactively for today's shifts
  -- already punched under the old timing — nothing is recalculated, but the
  -- day would then run under two rules. Today or later only; null turns it off.
  if p_on is not null and p_on < (now() at time zone 'America/Denver')::date then
    raise exception 'Pick today or a later day — the rule cannot start in the past.'
      using errcode = '22023';
  end if;

  update company_settings
     set paid_time_from_start_day_on = p_on,
         updated_at = now(),
         updated_by = auth.uid()
   where id = 1
  returning * into v_row;

  return public._work_activity_finish(__work_activity_root_id,(v_row)::company_settings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_195$::text,false,'834b134b0f313841f9fef1fbc92c75fe28f0debdc1a11473f14fba6d3fc2dae6'::text,'b77e80103c068ae6a2c7b67a3c8813d527b71c5da0e38944893b4f34f9bc58cc'::text,'set_paid_time_rule_date'::text,'p_on date'::text),
('sign_toolbox_talk(uuid, uuid, uuid, text, text, text, text, timestamp with time zone)'::text,$activity_body_196$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('sign_toolbox_talk','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_uid uuid := auth.uid();
  v_now timestamptz := now();
  v_name text := nullif(btrim(coalesce(p_typed_name, '')), '');
  v_folder text;
  v_row public.toolbox_completions;
  v_talk uuid;
  v_talk_day date;
  v_day date;
  v_at timestamptz;
  v_note text;
begin
  if v_uid is null then
    raise exception 'Sign in to send your toolbox talk signature.' using errcode = '42501';
  end if;
  if public.is_partner_user() then
    raise exception 'Not available for your account.' using errcode = '42501';
  end if;
  -- Nobody files a signature for somebody else, whoever is signed in on the
  -- phone that happens to send it.
  if p_profile_id is distinct from v_uid then
    raise exception 'This toolbox talk signature belongs to someone else on this phone. Sign in as the person who signed it to send it.'
      using errcode = '42501';
  end if;
  if p_client_id is null then
    raise exception 'This toolbox talk signature is missing its id. Sign today''s talk again.' using errcode = '22023';
  end if;
  if v_name is null then
    raise exception 'Type your name to sign the toolbox talk.' using errcode = '22023';
  end if;
  -- The files live under the signer's own folder in toolbox-records, the
  -- folder a test login may write (20261027020000). A record pointing
  -- anywhere else would be pointing at somebody else's signature.
  v_folder := v_uid::text || '/';
  if (p_signature_path is not null and left(p_signature_path, length(v_folder)) <> v_folder)
     or (p_pdf_path is not null and left(p_pdf_path, length(v_folder)) <> v_folder) then
    raise exception 'A toolbox talk signature can only point at files in the signer''s own folder.'
      using errcode = '22023';
  end if;

  -- One signature at a time per person, until this transaction ends: the same
  -- signature sent twice at once must find the first, not race it.
  perform pg_advisory_xact_lock(hashtextextended('toolbox_sign:' || v_uid::text, 0));

  select * into v_row from public.toolbox_completions
   where profile_id = v_uid and client_id = p_client_id;
  if v_row.id is not null then
    return public._work_activity_finish(__work_activity_root_id,(v_row)::public.toolbox_completions);
  end if;

  -- A lead can re-point a day's talk after the phone kept it (assignTalk
  -- deletes an unsigned instance). The person signed what the phone showed
  -- them; the snapshot says what that was.
  select st.id, st.talk_date into v_talk, v_talk_day from public.safety_talks st where st.id = p_talk_id;

  if p_signed_at is null then
    v_at := v_now;
  elsif p_signed_at > v_now + interval '2 minutes' then
    v_at := v_now;
    v_note := 'phone_clock_ahead';
  elsif p_signed_at < v_now - interval '24 hours' then
    v_at := p_signed_at;
    v_note := 'arrived_late';
  else
    v_at := least(p_signed_at, v_now);
  end if;

  -- The day this signature will count for — the day clock_in's gate reads —
  -- must be its talk's own day (see A TALK IS SIGNED FOR ITS OWN DAY above).
  v_day := (v_at at time zone 'America/Denver')::date;
  if v_talk is not null and v_talk_day is distinct from v_day
     and exists (select 1 from public.safety_talks st where st.talk_date = v_day) then
    raise exception 'This signature is for the toolbox talk of %, but it would count for %. Sign that day''s own talk.',
      to_char(v_talk_day, 'FMMonth FMDD'), to_char(v_day, 'FMMonth FMDD')
      using errcode = '22023';
  end if;

  insert into public.toolbox_completions
    (talk_id, profile_id, signed_at, typed_name, signature_path, talk_snapshot, pdf_path,
     signed_via, signed_by, client_id, phone_signed_at, signed_at_note)
  values
    (v_talk, v_uid, v_at, v_name, p_signature_path, p_talk_snapshot, p_pdf_path,
     'self', null, p_client_id, p_signed_at, v_note)
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::public.toolbox_completions);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_196$::text,false,'eff0c4ffab9fcc407d4eb67de94b0138f12104a76f754c7e18f4105f00901285'::text,'4cf25d17391eceee14bbcd235c2678b21748f74cd53fc138a30fc1a35d6c1ca4'::text,'sign_toolbox_talk'::text,'p_client_id uuid, p_profile_id uuid, p_talk_id uuid, p_typed_name text, p_signature_path text, p_pdf_path text, p_talk_snapshot text, p_signed_at timestamp with time zone'::text),
('record_qc_decision(uuid, uuid, text, text)'::text,$activity_body_197$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('record_qc_decision','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid();
  v_existing public.qc_decision_events;
  v_inserted uuid;
  v_at timestamptz := clock_timestamp();
  v_note text := nullif(btrim(p_note), '');
begin
  if p_decision_id is null or p_opening_id is null then
    raise exception 'A QC decision and opening are required.' using errcode = '22023';
  end if;
  if p_status not in ('passed', 'callback') or p_status is null then
    raise exception 'Choose Pass or Callback.' using errcode = '22023';
  end if;
  if length(coalesce(v_note, '')) > 4000 then
    raise exception 'Keep the QC note under 4,000 characters.' using errcode = '22023';
  end if;
  if v_actor is null or not public.qc_actor_can_review() then
    raise exception 'Only an active foreman, supervisor or owner can review QC.' using errcode = '42501';
  end if;

  -- A repeated request is a no-op, even if the opening was reviewed again
  -- afterward. A reused ID with different contents is never accepted.
  select * into v_existing from public.qc_decision_events where id = p_decision_id;
  if found then
    if v_existing.project_opening_id is distinct from p_opening_id
       or v_existing.status is distinct from p_status
       or v_existing.note is distinct from v_note
       or v_existing.reviewer_id is distinct from v_actor
       or v_existing.source <> 'review' then
      raise exception 'This QC request ID was already used for another decision.' using errcode = '23505';
    end if;
    return public._work_activity_finish(__work_activity_root_id,(v_existing.id)::uuid);
  end if;

  perform 1 from public.project_openings o
  where o.id = p_opening_id and o.status = 'installed' and o.removed_at is null
  for update;
  if not found then
    raise exception 'This installed unit is unavailable for QC.' using errcode = '22023';
  end if;

  -- Claim the request ID before touching the current QC row. Concurrent
  -- retries wait on the opening lock or unique key and then become no-ops.
  insert into public.qc_decision_events
    (id, project_opening_id, status, note, reviewer_id, decided_at, source)
  values (p_decision_id, p_opening_id, p_status, v_note, v_actor, v_at, 'review')
  on conflict (id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    select * into v_existing from public.qc_decision_events where id = p_decision_id;
    if v_existing.project_opening_id is distinct from p_opening_id
       or v_existing.status is distinct from p_status
       or v_existing.note is distinct from v_note
       or v_existing.reviewer_id is distinct from v_actor
       or v_existing.source <> 'review' then
      raise exception 'This QC request ID was already used for another decision.' using errcode = '23505';
    end if;
    return public._work_activity_finish(__work_activity_root_id,(v_existing.id)::uuid);
  end if;

  -- Keep the direct-write compatibility trigger from also archiving this RPC
  -- decision; the explicit event above carries its stable request UUID.
  perform set_config('app.qc_rpc', '1', true);
  insert into public.qc_checks(project_opening_id, status, note, checked_by, checked_at)
  values (p_opening_id, p_status, v_note, v_actor, v_at)
  on conflict (project_opening_id) do update
    set status = excluded.status, note = excluded.note,
        checked_by = excluded.checked_by, checked_at = excluded.checked_at;

  -- The QC projection, history, and pending-point resolution commit together.
  -- Existing points rules intentionally do not reopen already-settled rows.
  perform public.resolve_install_points(
    p_opening_id::text,
    case when p_status = 'passed' then 'confirmed' else 'void' end
  );

  return public._work_activity_finish(__work_activity_root_id,(p_decision_id)::uuid);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_197$::text,false,'9bf3da06c5fee5a8bd0a0f436dcc0a81df9fde73d8bbb731c2ef35b9ab12ddbf'::text,'9f2817a41202431b77101e649627b34a6448fd4167c7a2ad438de4a55b862a1d'::text,'record_qc_decision'::text,'p_decision_id uuid, p_opening_id uuid, p_status text, p_note text'::text),
('record_stage_contributors(uuid, jsonb)'::text,$activity_body_198$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('record_stage_contributors','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands;
  v_unit_id uuid; v_opening_id uuid; opening public.project_openings; unit_row public.custom_work_units;
  job_id uuid; v_stage text; work_day date; outcome text; description text;
  people uuid[]; person uuid; existing_people uuid[]; new_people uuid[];
  plan jsonb; norm_payload jsonb;
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can record crew contributors.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid contributor record.'; end if;

  v_unit_id:=nullif(p_data->>'unit_id','')::uuid;
  v_opening_id:=nullif(p_data->>'opening_id','')::uuid;
  if (v_unit_id is not null)=(v_opening_id is not null) then raise exception 'Choose exactly one saved unit or mapped opening.'; end if;

  v_stage:=p_data->>'stage';
  if v_stage is null or v_stage not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then
    raise exception 'Choose the work stage.';
  end if;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null or work_day<date '2000-01-01' or work_day>(now() at time zone 'America/Denver')::date then
    raise exception 'Choose a valid work date, not in the future.';
  end if;
  outcome:=p_data->>'outcome';
  if outcome is null or outcome not in ('partial','finished') then raise exception 'Choose partial or stage complete.'; end if;
  description:=coalesce(p_data->>'description','');
  if length(description)>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if jsonb_typeof(p_data->'people') is distinct from 'array' or jsonb_array_length(p_data->'people') not between 1 and 100 then
    raise exception 'Select the people who worked.';
  end if;
  select array_agg(distinct value::uuid order by value::uuid) into people from jsonb_array_elements_text(p_data->'people');

  -- Normalized fingerprint: sorted/deduped people, so a resend of this exact
  -- request id with the same people in a different order still matches.
  norm_payload:=jsonb_build_object('action','stage_contributors','data',p_data||jsonb_build_object('people',to_jsonb(people)));

  -- Same namespace as custom_work_command/record_crew_work's own receipt
  -- lock (7282): every route keyed by a custom_work_commands id must
  -- serialize against every other, or two different actions sharing one
  -- request id could both pass the "not found yet" check at once.
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>norm_payload then raise exception 'This retry belongs to a different request.'; end if;
    return public._work_activity_finish(__work_activity_root_id,(receipt.result_id)::uuid);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));

  -- Resolve the job server-side from the reference; the caller never names it.
  if v_unit_id is not null then
    select project_id into job_id from public.custom_work_units where id=v_unit_id;
    if job_id is null then raise exception 'Choose a saved unit on a job.'; end if;
  else
    select * into opening from public.project_openings where id=v_opening_id and removed_at is null;
    if opening.id is null then raise exception 'This opening is not available.'; end if;
    job_id:=opening.project_id;
  end if;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  perform pg_advisory_xact_lock(hashtextextended(coalesce(v_unit_id,v_opening_id)::text,7296));

  if v_unit_id is not null then
    select * into unit_row from public.custom_work_units where id=v_unit_id for update;
    if unit_row.id is null then raise exception 'Choose a saved unit on a job.'; end if;
  else
    select * into unit_row from public.custom_work_units where opening_id=opening.id for update;
    if unit_row.id is null then
      plan:=public._ai_plan_facts(opening.id);
      insert into public.custom_work_units(id,project_id,opening_id,created_by,label,type_label,facts)
      values(gen_random_uuid(),job_id,opening.id,uid,opening.opening_code,coalesce(plan->>'type_label','Unknown'),public._ai_plan_seed(plan))
      on conflict (opening_id) where opening_id is not null do nothing;
      select * into unit_row from public.custom_work_units where opening_id=opening.id for update;
      if unit_row.id is null then raise exception 'Could not create a unit for this opening.'; end if;
    end if;
  end if;

  -- Revalidate identity under the lock (Astra review): the job/opening
  -- checked above was read before this transaction held the unit row. A
  -- concurrent move or removal between that read and this lock is refused,
  -- never silently trusted from a moment earlier. Applies to both the
  -- existing-unit and the just-resolved-opening path, and to an existing
  -- unit's linked opening being removed concurrently.
  if unit_row.project_id is distinct from job_id then
    raise exception 'This unit moved to a different job. Refresh and try again.';
  end if;
  if unit_row.opening_id is not null and not exists(
    select 1 from public.project_openings where id=unit_row.opening_id and removed_at is null and project_id=job_id
  ) then
    raise exception 'This opening is not available.';
  end if;

  foreach person in array people loop
    if person is null or not exists(
      select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null
        and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
        and is_test=public.is_test_profile(uid)
    ) or not public._ai_job_visible(job_id,person) then
      raise exception 'Choose Forge crew members with current access to this job.';
    end if;
  end loop;

  -- The unit and project locks are held before checking historical sources;
  -- a saved digest or an accessible current job grants no access to old jobs.
  if not public._stage_contributor_sources_visible(unit_row.id,v_stage,work_day) then
    raise exception 'Some earlier records for this work are unavailable. Ask a supervisor to review them.' using errcode='42501';
  end if;

  -- Semantic dedupe against every EFFECTIVE report for this exact tuple, not
  -- merely this request: same/fresh id, reordered or overlapping submissions
  -- all land on the same "who is actually new" answer.
  select coalesce(array_agg(distinct p.profile_id),'{}') into existing_people
  from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
  where r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day and p.voided_at is null and r.outcome in ('partial','finished');
  select coalesce(array_agg(x),'{}') into new_people from unnest(people) x where not (x=any(existing_people));

  if array_length(new_people,1) is not null then
    update public.custom_work_units set untimed_work_present=true where id=unit_row.id;
    insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
    values(p_id,job_id,unit_row.id,uid,work_day,v_stage,outcome,false,description);
    insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(new_people);
    insert into public.custom_work_history(project_id,actor_id,entity_id,action,after_value,reason)
    values(job_id,uid,unit_row.id,'stage_contributors',
      jsonb_build_object('record_id',p_id,'people',new_people,'requested',people,'work_date',work_day,'stage',v_stage,'outcome',outcome),
      'Foreman contributor record; no payroll changes');
  end if;

  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,norm_payload,unit_row.id);
  return public._work_activity_finish(__work_activity_root_id,(unit_row.id)::uuid);
end; 
 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_198$::text,false,'413648e9bd6338b95076bed3b6e7e17c0a15fb2ec43548cf7bb86f24d65e296a'::text,'cfe78c20dca24a17bb6267e587f90f636105ea2a684b2339495cdf9dec49efd5'::text,'record_stage_contributors'::text,'p_id uuid, p_data jsonb'::text),
('correct_stage_contributors(uuid, jsonb)'::text,$activity_body_199$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('correct_stage_contributors','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  uid uuid:=auth.uid(); receipt public.custom_work_commands; unit_row public.custom_work_units;
  job_id uuid; v_stage text; work_day date; reason text; expected text; current_digest text;
  remove_ids uuid[]; add_ids uuid[]; person uuid; voided_ids uuid[]:='{}'; added_ids uuid[]:='{}';
  outcome text; description text; existing_people uuid[]; norm_payload jsonb;
begin
  if not public.custom_work_internal() or not public._is_lead(uid) then
    raise exception 'Only an active foreman, supervisor or owner can correct crew contributors.' using errcode='42501';
  end if;
  if p_id is null or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'Invalid correction.'; end if;

  reason:=btrim(coalesce(p_data->>'reason',''));
  if length(reason) not between 1 and 500 then raise exception 'Enter a short reason for this correction.'; end if;
  v_stage:=p_data->>'stage';
  if v_stage is null or v_stage not in ('RO checked','Installing','Preparation','Flashing','Setting frame','Glazing','Hardware','Detail work','Rework') then
    raise exception 'Choose the work stage.';
  end if;
  work_day:=(p_data->>'work_date')::date;
  if work_day is null then raise exception 'Choose the work date being corrected.'; end if;
  expected:=p_data->>'expected_digest';
  if expected is null then raise exception 'This correction needs the summary you reviewed.'; end if;
  if jsonb_typeof(p_data->'remove')<>'array' then remove_ids:='{}'; else
    select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into remove_ids from jsonb_array_elements_text(p_data->'remove');
  end if;
  if jsonb_typeof(p_data->'add')<>'array' then add_ids:='{}'; else
    select coalesce(array_agg(distinct value::uuid order by value::uuid),'{}') into add_ids from jsonb_array_elements_text(p_data->'add');
  end if;
  if coalesce(array_length(remove_ids,1),0)>100 or coalesce(array_length(add_ids,1),0)>100 then
    raise exception 'Correct up to 100 people at a time.';
  end if;
  if coalesce(array_length(remove_ids,1),0)=0 and coalesce(array_length(add_ids,1),0)=0 then
    raise exception 'Choose who to remove or add.';
  end if;
  outcome:=p_data->>'outcome';
  description:=coalesce(p_data->>'description','');
  if length(description)>4000 then raise exception 'Keep the description under 4000 characters.'; end if;
  if array_length(add_ids,1) is not null then
    if outcome is null or outcome not in ('partial','finished') then
      raise exception 'Choose partial or stage complete for the people being added.';
    end if;
    -- Same finite range as record_stage_contributors; a removal-only
    -- correction skips this so it can still clean up old invalid evidence.
    if work_day<date '2000-01-01' or work_day>(now() at time zone 'America/Denver')::date then
      raise exception 'Choose a valid work date, not in the future.';
    end if;
  end if;

  -- Normalized fingerprint: the (already sorted/deduped) remove/add arrays,
  -- so a resend of this exact request id matches regardless of input order.
  norm_payload:=jsonb_build_object('action','correct_stage_contributors','data',
    p_data||jsonb_build_object('remove',to_jsonb(remove_ids),'add',to_jsonb(add_ids)));
  -- Same shared receipt namespace as every other custom_work_commands route
  -- (crew_record/stage_contributors/custom_work_command): every route keyed
  -- by a request id must serialize against every other.
  perform pg_advisory_xact_lock(hashtextextended(p_id::text,7282));
  select * into receipt from public.custom_work_commands where id=p_id;
  if found then
    if receipt.profile_id<>uid or receipt.payload<>norm_payload then raise exception 'This retry belongs to a different request.'; end if;
    return public._work_activity_finish(__work_activity_root_id,(receipt.result_id)::uuid);
  end if;
  perform pg_advisory_xact_lock(hashtextextended(uid::text,7281));

  select u.* into unit_row from public.custom_work_units u where u.id=(p_data->>'unit_id')::uuid;
  if unit_row.id is null or unit_row.project_id is null then raise exception 'Choose a saved unit on a job.'; end if;
  job_id:=unit_row.project_id;
  if not exists(select 1 from public.projects where id=job_id and deleted_at is null) or not public._ai_job_visible(job_id,uid) then
    raise exception 'This job is unavailable.';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(job_id::text,7285));
  perform pg_advisory_xact_lock(hashtextextended(unit_row.id::text,7296));
  select * into unit_row from public.custom_work_units where id=unit_row.id for update;

  -- Revalidate identity under the lock (Astra review): job_id above was read
  -- before this transaction held the unit row. Re-derive authority from what
  -- is actually locked, and refuse rather than trust a moment-old read.
  if unit_row.project_id is distinct from job_id then
    raise exception 'This unit moved to a different job. Refresh and try again.';
  end if;
  if unit_row.opening_id is not null and not exists(
    select 1 from public.project_openings where id=unit_row.opening_id and removed_at is null and project_id=job_id
  ) then
    raise exception 'This opening is not available.';
  end if;

  if not public._stage_contributor_sources_visible(unit_row.id,v_stage,work_day) then
    raise exception 'Some earlier records for this work are unavailable. Ask a supervisor to review them.' using errcode='42501';
  end if;

  -- Recomputed under the mutation locks: a tuple that moved between
  -- loading the summary and submitting the correction is refused, not guessed.
  current_digest:=public._stage_contributor_digest(unit_row.id,v_stage,work_day);
  if current_digest is distinct from expected then
    raise exception 'This contributor summary changed since you loaded it. Review it again before correcting.' using errcode='40001';
  end if;

  if array_length(remove_ids,1) is not null then
    foreach person in array remove_ids loop
      with voided as (
        update public.crew_work_record_people p set voided_at=now(),voided_by=uid,void_reason=reason
        from public.crew_work_records r
        where r.id=p.record_id and r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day
          and r.outcome in ('partial','finished') and p.profile_id=person and p.voided_at is null
        returning p.record_id
      )
      select voided_ids||coalesce(array_agg(record_id),'{}') into voided_ids from voided;
    end loop;
  end if;

  if array_length(add_ids,1) is not null then
    select coalesce(array_agg(distinct p.profile_id),'{}') into existing_people
    from public.crew_work_record_people p join public.crew_work_records r on r.id=p.record_id
    where r.unit_id=unit_row.id and r.stage=v_stage and r.work_date=work_day and p.voided_at is null and r.outcome in ('partial','finished');
    foreach person in array add_ids loop
      if person=any(existing_people) then continue; end if;
      if not exists(
        select 1 from public.profiles where id=person and retired_at is null and access_revoked_at is null
          and not coalesce(is_partner,false) and role in ('installer','foreman','supervisor','owner')
          and is_test=public.is_test_profile(uid)
      ) or not public._ai_job_visible(job_id,person) then
        raise exception 'Choose Forge crew members with current access to this job.';
      end if;
      added_ids:=added_ids||person;
    end loop;
    if array_length(added_ids,1) is not null then
      update public.custom_work_units set untimed_work_present=true where id=unit_row.id;
      insert into public.crew_work_records(id,project_id,unit_id,filed_by,work_date,stage,outcome,whole_complete,description)
      values(p_id,job_id,unit_row.id,uid,work_day,v_stage,outcome,false,description);
      insert into public.crew_work_record_people(record_id,profile_id) select p_id,unnest(added_ids);
    end if;
  end if;

  -- request_id is recorded even remove-only, so every correction — whether
  -- or not it also added a replacement report — traces to the exact request.
  insert into public.custom_work_history(project_id,actor_id,entity_id,action,before_value,after_value,reason)
  values(job_id,uid,unit_row.id,'stage_contributor_correction',
    jsonb_build_object('request_id',p_id,'stage',v_stage,'work_date',work_day,'voided_source_records',voided_ids,'digest_before',current_digest),
    jsonb_build_object('request_id',p_id,'removed',remove_ids,'added',added_ids,'new_record_id',case when array_length(added_ids,1) is not null then p_id end,
      'digest_after',public._stage_contributor_digest(unit_row.id,v_stage,work_day)),
    reason);

  insert into public.custom_work_commands(id,profile_id,payload,result_id) values(p_id,uid,norm_payload,unit_row.id);
  return public._work_activity_finish(__work_activity_root_id,(unit_row.id)::uuid);
end; 
 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_199$::text,false,'a24c2e8367ecc845b24c52ca42c48b18099ae3d8d682730c287e61203d7e9682'::text,'c9a1c07120d351bca7206a2633e771e2193fc39dfcfbadadac53fd48d09b33f7'::text,'correct_stage_contributors'::text,'p_id uuid, p_data jsonb'::text),
('set_values_scheduler_enabled(boolean)'::text,$activity_body_200$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('set_values_scheduler_enabled','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_row public.company_settings;
begin
  if not public._values_is_owner(auth.uid()) then
    raise exception 'Only an owner can turn the monthly values-review scheduler on or off.'
      using errcode = '42501';
  end if;
  if p_enabled is null then
    raise exception 'Say whether the scheduler is on or off.' using errcode = '22023';
  end if;
  update public.company_settings
     set values_scheduler_enabled = p_enabled, updated_at = now(), updated_by = auth.uid()
   where id = 1
  returning * into v_row;
  return public._work_activity_finish(__work_activity_root_id,(v_row)::public.company_settings);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_200$::text,false,'be9241f43b2050f08f4aad7a522a9756abb150eed2e0647579b6cfd7040045be'::text,'aca196c78ef098a8b806968bfddf4e446742d0e2eaa7b29f8bffd7a1adeabb21'::text,'set_values_scheduler_enabled'::text,'p_enabled boolean'::text),
('work_propose_activity_draft(uuid, text, bigint, text, text, text, boolean, jsonb)'::text,$activity_body_201$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('work_propose_activity_draft','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid(); v_payload jsonb; v_hash text; v_existing jsonb;
  v_cur_rev bigint; v_cur_latest uuid; v_new_rev bigint; v_new_id uuid; v_body jsonb; v_result jsonb;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'Sign-in required.'; end if;
  perform pg_advisory_xact_lock(7710, 0);
  if p_command_id is null then
    raise exception using errcode = '23514', message = 'A command id is required.';
  end if;
  if public.is_test_profile(v_actor) or not public._work_config_is_supervisor(v_actor) then
    raise exception using errcode = '42501', message = 'Only an owner or supervisor may draft company configuration.';
  end if;
  if p_code is null or p_code !~ '^[a-z][a-z0-9_]{0,79}$' then
    raise exception using errcode = '23514', message = 'Invalid activity code.';
  end if;
  if p_scope is null or p_scope not in ('general', 'specific') then
    raise exception using errcode = '23514', message = 'Invalid activity scope.';
  end if;
  if p_label_en is null or p_label_es is null or length(btrim(p_label_en)) not between 1 and 120 or length(btrim(p_label_es)) not between 1 and 120 then
    raise exception using errcode = '23514', message = 'Invalid activity label.';
  end if;
  if p_machine_selection is null then
    raise exception using errcode = '23514', message = 'Machine selection must be a boolean.';
  end if;
  perform public._work_config_validate_typed_fields(p_typed_fields);
  if p_expected_revision is null or p_expected_revision not between 0 and 9007199254740990 then
    raise exception using errcode = '23514', message = 'A valid expected draft revision is required.';
  end if;
  v_payload := jsonb_build_object('code', p_code, 'expectedRevision', p_expected_revision, 'scope', p_scope,
    'labelEn', p_label_en, 'labelEs', p_label_es, 'machineSelection', p_machine_selection, 'typedFields', p_typed_fields);
  v_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');
  v_existing := public._work_config_replay(p_command_id, v_actor, 'propose_activity_draft', v_hash, v_payload);
  if v_existing is not null then return public._work_activity_finish(__work_activity_root_id,(v_existing)::jsonb); end if;
  select revision, latest_draft_id into v_cur_rev, v_cur_latest
    from public.work_configuration_draft_pointers
   where kind = 'activity' and code = p_code for update;
  if not found then v_cur_rev := 0; v_cur_latest := null; end if;
  if v_cur_rev <> p_expected_revision then
    raise exception using errcode = '23514', message = 'Draft revision changed; reload and retry.';
  end if;
  v_new_rev := v_cur_rev + 1;
  v_body := jsonb_build_object('scope', p_scope, 'labelEn', p_label_en, 'labelEs', p_label_es,
    'machineSelection', p_machine_selection, 'typedFields', p_typed_fields);
  insert into public.work_configuration_draft_revisions(kind, code, revision, body, proposed_by, predecessor_id)
    values ('activity', p_code, v_new_rev, v_body, v_actor, v_cur_latest) returning id into v_new_id;
  insert into public.work_configuration_draft_pointers(kind, code, revision, latest_draft_id)
    values ('activity', p_code, v_new_rev, v_new_id)
    on conflict (kind, code) do update set revision = v_new_rev, latest_draft_id = v_new_id, updated_at = now();
  v_result := jsonb_build_object('protocolVersion', 1, 'kind', 'activity', 'code', p_code,
    'revision', v_new_rev, 'draftId', v_new_id);
  perform public._work_config_store_receipt(p_command_id, v_actor, 'propose_activity_draft', v_payload, v_hash, v_result);
  return public._work_activity_finish(__work_activity_root_id,(v_result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_201$::text,false,'cf159f060cd319541b53ff287b46e6bc17e1cc601af1b740a193578bc5724c8e'::text,'8080e8e77c90a231e2f8b46357d22fe7df11c043ffab7ad927f3d4871961592c'::text,'work_propose_activity_draft'::text,'p_command_id uuid, p_code text, p_expected_revision bigint, p_scope text, p_label_en text, p_label_es text, p_machine_selection boolean, p_typed_fields jsonb'::text),
('work_propose_menu_draft(uuid, text, bigint, text, text, jsonb)'::text,$activity_body_202$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('work_propose_menu_draft','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid(); v_payload jsonb; v_hash text; v_existing jsonb;
  v_cur_rev bigint; v_cur_latest uuid; v_new_rev bigint; v_new_id uuid; v_body jsonb; v_result jsonb;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'Sign-in required.'; end if;
  perform pg_advisory_xact_lock(7710, 0);
  if p_command_id is null then
    raise exception using errcode = '23514', message = 'A command id is required.';
  end if;
  if public.is_test_profile(v_actor) or not public._work_config_is_supervisor(v_actor) then
    raise exception using errcode = '42501', message = 'Only an owner or supervisor may draft company configuration.';
  end if;
  if p_code is null or p_code !~ '^[a-z][a-z0-9_]{0,79}$' then
    raise exception using errcode = '23514', message = 'Invalid menu code.';
  end if;
  if p_label_en is null or p_label_es is null or length(btrim(p_label_en)) not between 1 and 120 or length(btrim(p_label_es)) not between 1 and 120 then
    raise exception using errcode = '23514', message = 'Invalid menu label.';
  end if;
  perform public._work_config_validate_menu_draft_items(p_items);
  if p_expected_revision is null or p_expected_revision not between 0 and 9007199254740990 then
    raise exception using errcode = '23514', message = 'A valid expected draft revision is required.';
  end if;
  v_payload := jsonb_build_object('code', p_code, 'expectedRevision', p_expected_revision,
    'labelEn', p_label_en, 'labelEs', p_label_es, 'items', p_items);
  v_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');
  v_existing := public._work_config_replay(p_command_id, v_actor, 'propose_menu_draft', v_hash, v_payload);
  if v_existing is not null then return public._work_activity_finish(__work_activity_root_id,(v_existing)::jsonb); end if;
  select revision, latest_draft_id into v_cur_rev, v_cur_latest
    from public.work_configuration_draft_pointers
   where kind = 'menu' and code = p_code for update;
  if not found then v_cur_rev := 0; v_cur_latest := null; end if;
  if v_cur_rev <> p_expected_revision then
    raise exception using errcode = '23514', message = 'Draft revision changed; reload and retry.';
  end if;
  v_new_rev := v_cur_rev + 1;
  v_body := jsonb_build_object('labelEn', p_label_en, 'labelEs', p_label_es, 'items', p_items);
  insert into public.work_configuration_draft_revisions(kind, code, revision, body, proposed_by, predecessor_id)
    values ('menu', p_code, v_new_rev, v_body, v_actor, v_cur_latest) returning id into v_new_id;
  insert into public.work_configuration_draft_pointers(kind, code, revision, latest_draft_id)
    values ('menu', p_code, v_new_rev, v_new_id)
    on conflict (kind, code) do update set revision = v_new_rev, latest_draft_id = v_new_id, updated_at = now();
  v_result := jsonb_build_object('protocolVersion', 1, 'kind', 'menu', 'code', p_code,
    'revision', v_new_rev, 'draftId', v_new_id);
  perform public._work_config_store_receipt(p_command_id, v_actor, 'propose_menu_draft', v_payload, v_hash, v_result);
  return public._work_activity_finish(__work_activity_root_id,(v_result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_202$::text,false,'4d2332ab6b6f4169134b7e98ff34440309ea94ee590891b07eaa5dfd0b4b9ba9'::text,'e129ee56a2c3c0df729d8312a2c3736170729c77459c9c3a316a8db8b1c0be41'::text,'work_propose_menu_draft'::text,'p_command_id uuid, p_code text, p_expected_revision bigint, p_label_en text, p_label_es text, p_items jsonb'::text),
('work_publish_activity_version(uuid, text, integer, text, text, text, boolean, jsonb, timestamp with time zone)'::text,$activity_body_203$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('work_publish_activity_version','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid(); v_payload jsonb; v_hash text; v_existing jsonb;
  v_published_at timestamptz; v_effective_from timestamptz;
  v_def_id uuid; v_max_ver integer; v_new_ver integer; v_version_id uuid; v_result jsonb;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'Sign-in required.'; end if;
  perform pg_advisory_xact_lock(7710, 0);
  if p_command_id is null then
    raise exception using errcode = '23514', message = 'A command id is required.';
  end if;
  if public.is_test_profile(v_actor) or not public._work_config_is_owner(v_actor) then
    raise exception using errcode = '42501', message = 'Only an owner may publish company configuration.';
  end if;
  if p_code is null or p_code !~ '^[a-z][a-z0-9_]{0,79}$' then
    raise exception using errcode = '23514', message = 'Invalid activity code.';
  end if;
  if p_scope is null or p_scope not in ('general', 'specific') then
    raise exception using errcode = '23514', message = 'Invalid activity scope.';
  end if;
  if p_label_en is null or p_label_es is null or length(btrim(p_label_en)) not between 1 and 120 or length(btrim(p_label_es)) not between 1 and 120 then
    raise exception using errcode = '23514', message = 'Invalid activity label.';
  end if;
  if p_machine_selection is null then
    raise exception using errcode = '23514', message = 'Machine selection must be a boolean.';
  end if;
  perform public._work_config_validate_typed_fields(p_typed_fields);
  if p_expected_latest_version is null or p_expected_latest_version not between 0 and 2147483646 then
    raise exception using errcode = '23514', message = 'A valid expected published version is required.';
  end if;
  v_payload := jsonb_build_object('code', p_code, 'expectedLatestVersion', p_expected_latest_version, 'scope', p_scope,
    'labelEn', p_label_en, 'labelEs', p_label_es, 'machineSelection', p_machine_selection, 'typedFields', p_typed_fields, 'effectiveFrom', p_effective_from);
  v_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');
  v_existing := public._work_config_replay(p_command_id, v_actor, 'publish_activity_version', v_hash, v_payload);
  if v_existing is not null then return public._work_activity_finish(__work_activity_root_id,(v_existing)::jsonb); end if;
  v_published_at := clock_timestamp();
  v_effective_from := coalesce(p_effective_from, v_published_at);
  if not isfinite(v_effective_from) or v_effective_from < v_published_at then
    raise exception using errcode = '23514', message = 'Effective time must be finite and no earlier than publication.';
  end if;
  if exists(select 1 from public.work_activity_definitions where code = p_code and retired_at is not null) then
    raise exception using errcode = '23514', message = 'A retired activity cannot be republished.';
  end if;
  select d.id, (select max(v.version) from public.work_activity_definition_versions v where v.definition_id = d.id)
    into v_def_id, v_max_ver
    from public.work_activity_definitions d where d.code = p_code for update;
  if not found then
    if p_expected_latest_version <> 0 then
      raise exception using errcode = '23514', message = 'Activity definition does not exist yet.';
    end if;
    insert into public.work_activity_definitions(code, created_by) values (p_code, v_actor) returning id into v_def_id;
    v_max_ver := 0;
  else
    if coalesce(v_max_ver, 0) <> p_expected_latest_version then
      raise exception using errcode = '23514', message = 'Activity version changed; reload and retry.';
    end if;
  end if;
  v_new_ver := coalesce(v_max_ver, 0) + 1;
  insert into public.work_activity_definition_versions(
    definition_id, version, scope, label_en, label_es, machine_selection, typed_fields, published_by, published_at, effective_from)
    values (v_def_id, v_new_ver, p_scope, p_label_en, p_label_es, p_machine_selection, p_typed_fields, v_actor, v_published_at, v_effective_from)
    returning id into v_version_id;
  v_result := jsonb_build_object('protocolVersion', 1, 'code', p_code, 'version', v_new_ver, 'versionId', v_version_id,
    'publishedAt', v_published_at, 'effectiveFrom', v_effective_from);
  perform public._work_config_store_receipt(p_command_id, v_actor, 'publish_activity_version', v_payload, v_hash, v_result);
  return public._work_activity_finish(__work_activity_root_id,(v_result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
