('work_grant_job_capability(uuid, uuid, uuid, text)'::text,$activity_body_208$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('work_grant_job_capability','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid(); v_payload jsonb; v_hash text; v_existing jsonb;
  v_granted_at timestamptz; v_grant_id uuid; v_result jsonb;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'Sign-in required.'; end if;
  perform pg_advisory_xact_lock(7710, 0);
  if p_command_id is null then
    raise exception using errcode = '23514', message = 'A command id is required.';
  end if;
  if not public._work_config_is_supervisor(v_actor) then
    raise exception using errcode = '42501', message = 'Only an owner or supervisor may grant job capabilities.';
  end if;
  if p_capability is null or p_capability not in ('menu_select', 'dimensions_edit', 'final_qc') then
    raise exception using errcode = '23514', message = 'Invalid capability.';
  end if;
  if p_profile_id = v_actor then
    raise exception using errcode = '42501', message = 'A capability cannot be granted to yourself.';
  end if;
  if not public._ai_job_visible(p_project_id, v_actor) then
    raise exception using errcode = '23514', message = 'That job is unavailable.';
  end if;
  if not public._work_config_is_foreman(p_profile_id)
      or not public._ai_job_visible(p_project_id, p_profile_id) then
    raise exception using errcode = '23514', message = 'Only an active foreman may receive this grant.';
  end if;
  v_payload := jsonb_build_object('projectId', p_project_id, 'profileId', p_profile_id, 'capability', p_capability);
  v_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');
  v_existing := public._work_config_replay(p_command_id, v_actor, 'grant_job_capability', v_hash, v_payload);
  if v_existing is not null then return public._work_activity_finish(__work_activity_root_id,(v_existing)::jsonb); end if;
  insert into public.work_job_management_grants(project_id, profile_id, capability, granted_by)
    values (p_project_id, p_profile_id, p_capability, v_actor)
    returning granted_at, id into v_granted_at, v_grant_id;
  v_result := jsonb_build_object('protocolVersion', 1, 'projectId', p_project_id, 'profileId', p_profile_id,
    'capability', p_capability, 'grantedAt', v_granted_at, 'grantId', v_grant_id);
  perform public._work_config_store_receipt(p_command_id, v_actor, 'grant_job_capability', v_payload, v_hash, v_result);
  return public._work_activity_finish(__work_activity_root_id,(v_result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_208$::text,false,'af211ed8a50e25013881f84a79f77288a64cc1223aa091f75aece52bdac3abbc'::text,'30dd551dab87de09b153c350102efbd2f172b0efca2dbece63d69c4ce963f94c'::text,'work_grant_job_capability'::text,'p_command_id uuid, p_project_id uuid, p_profile_id uuid, p_capability text'::text),
('work_revoke_job_capability(uuid, uuid, uuid, text, uuid)'::text,$activity_body_209$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('work_revoke_job_capability','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid(); v_payload jsonb; v_hash text; v_existing jsonb; v_id uuid; v_result jsonb;
begin
  if v_actor is null then raise exception using errcode = '42501', message = 'Sign-in required.'; end if;
  perform pg_advisory_xact_lock(7710, 0);
  if p_command_id is null then
    raise exception using errcode = '23514', message = 'A command id is required.';
  end if;
  if not public._work_config_is_supervisor(v_actor) then
    raise exception using errcode = '42501', message = 'Only an owner or supervisor may revoke job capabilities.';
  end if;
  if p_capability is null or p_capability not in ('menu_select', 'dimensions_edit', 'final_qc') then
    raise exception using errcode = '23514', message = 'Invalid capability.';
  end if;
  if not public._ai_job_visible(p_project_id, v_actor) then
    raise exception using errcode = '23514', message = 'That job is unavailable.';
  end if;
  if p_expected_grant_id is null then
    raise exception using errcode = '23514', message = 'An expected grant id is required.';
  end if;
  v_payload := jsonb_build_object('projectId', p_project_id, 'profileId', p_profile_id, 'capability', p_capability, 'expectedGrantId', p_expected_grant_id);
  v_hash := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');
  v_existing := public._work_config_replay(p_command_id, v_actor, 'revoke_job_capability', v_hash, v_payload);
  if v_existing is not null then return public._work_activity_finish(__work_activity_root_id,(v_existing)::jsonb); end if;
  update public.work_job_management_grants set revoked_at = now(), revoked_by = v_actor
   where id = p_expected_grant_id and project_id = p_project_id and profile_id = p_profile_id and capability = p_capability and revoked_at is null
   returning id into v_id;
  if v_id is null then
    raise exception using errcode = '23514', message = 'No active grant to revoke.';
  end if;
  v_result := jsonb_build_object('protocolVersion', 1, 'projectId', p_project_id, 'profileId', p_profile_id,
    'capability', p_capability, 'revokedAt', now());
  perform public._work_config_store_receipt(p_command_id, v_actor, 'revoke_job_capability', v_payload, v_hash, v_result);
  return public._work_activity_finish(__work_activity_root_id,(v_result)::jsonb);
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_209$::text,false,'1a916d84bc9d797eaa194f5fb5156f62db1a2f38ba12ac8f82ec1f808b4a4c8c'::text,'78d05226682bd6fce5c41f5e8b5ba76f512e488fc4c5c81d036a559c4f87ffa9'::text,'work_revoke_job_capability'::text,'p_command_id uuid, p_project_id uuid, p_profile_id uuid, p_capability text, p_expected_grant_id uuid'::text),
('_work_unit_fact_bump_epoch()'::text,$activity_body_210$
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);

declare v_kind text; v_id uuid;
begin
  if TG_TABLE_NAME = 'custom_work_units' then v_kind := 'unit_binding';
  elsif TG_TABLE_NAME = 'project_openings' then v_kind := 'opening';
  elsif TG_TABLE_NAME = 'projects' then v_kind := 'project';
  else
    if TG_OP = 'DELETE' then return old; else return new; end if;
  end if;
  if TG_OP = 'DELETE' then v_id := old.id; else v_id := new.id; end if;
  if TG_OP = 'INSERT' then
    -- A brand-new identity that was never tracked before is not itself a
    -- "change" -- it stays at the 0 baseline until its first real update
    -- or delete. Only a REINSERTION of a previously-tracked id (a genuine
    -- physical reincarnation after purge) advances an existing row.
    update public.work_unit_fact_context_epochs set epoch = epoch + 1, updated_at = now()
     where scope_kind = v_kind and scope_id = v_id;
  else
    insert into public.work_unit_fact_context_epochs(scope_kind, scope_id, epoch)
      values (v_kind, v_id, 1)
    on conflict (scope_kind, scope_id) do update
      set epoch = public.work_unit_fact_context_epochs.epoch + 1, updated_at = now();
  end if;
  -- Physical lifetime is distinct from ordinary relinks. Never reset the
  -- retained token when a source row is deleted or reinserted.
  if TG_TABLE_NAME = 'custom_work_units' and TG_OP in ('INSERT','DELETE') then
    if TG_OP = 'INSERT' then
      update public.work_unit_fact_context_epochs set epoch = epoch + 1, updated_at = now()
        where scope_kind = 'unit_incarnation' and scope_id = v_id;
    else
      insert into public.work_unit_fact_context_epochs(scope_kind, scope_id, epoch)
        values ('unit_incarnation', v_id, 1)
      on conflict (scope_kind, scope_id) do update
        set epoch = public.work_unit_fact_context_epochs.epoch + 1, updated_at = now();
    end if;
  end if;
  if TG_OP = 'DELETE' then return old; else return new; end if;
end;

end;
$activity_body_210$::text,false,'beaca8f387aae5596ab6ccbd25ac9fd1c2cd2b0d8462e5e33d1d78d7d19ad7f4'::text,'b3e480ef16942be1a6e44fcb90a712d37e141ab1105427dcc126071212b30214'::text,'_work_unit_fact_bump_epoch'::text,''::text),
('_work_record_unit_fact(uuid, jsonb, jsonb, uuid)'::text,$activity_body_211$
declare __work_activity_root_id uuid;__work_activity_arrival timestamptz;
begin
 perform pg_catalog.pg_advisory_xact_lock(7712,0);
  __work_activity_root_id:=public._work_activity_operation_enter('_work_record_unit_fact','{}'::jsonb,null);
 __work_activity_arrival:=(public._work_activity_operation()).arrival_at;
 
declare
  v_actor uuid := auth.uid();
  v_command public.custom_work_commands;
  v_unit public.custom_work_units;
  v_cur public.work_unit_fact_current;
  v_new_rev integer;
  v_new_id uuid;
begin
  if v_actor is null then
    raise exception using errcode = '42501', message = 'Sign-in required.';
  end if;
  select * into v_command from public.custom_work_commands where id = p_command_id;
  if v_command.id is null or v_command.profile_id is distinct from v_actor then
    raise exception using errcode = '42501', message = 'Unit fact recording requires the actual saved command receipt.';
  end if;
  select * into v_unit from public.custom_work_units where id = p_unit_id;
  if v_unit.id is null or v_command.result_id is distinct from v_unit.id
      or coalesce(v_command.payload->>'action','') not in ('unit','link')
      or (v_command.payload->'data'->>'id')::uuid is distinct from v_unit.id then
    raise exception using errcode = '23514', message = 'Unit fact recording does not match the saved canonical unit.';
  end if;
  if p_applied_unit_intent is null or jsonb_typeof(p_applied_unit_intent) <> 'object'
      or coalesce(p_applied_unit_intent->>'event_kind','') not in ('observation','legacy_observation','incomplete','cleared','relink') then
    raise exception using errcode = '23514', message = 'Unit fact recording received an invalid applied intent.';
  end if;
  if (p_applied_unit_intent->>'width_in')::numeric is distinct from (v_unit.facts->>'width_in')::numeric
    or (p_applied_unit_intent->>'height_in')::numeric is distinct from (v_unit.facts->>'height_in')::numeric
    or p_applied_unit_intent->>'legacy_measurement_source' is distinct from v_unit.facts->>'measurement_source'
    or p_applied_unit_intent->>'legacy_area_source' is distinct from v_unit.facts->>'area_source' then
    raise exception using errcode = '23514', message = 'Unit fact intent does not match the applied canonical facts.';
  end if;
  select * into v_cur from public.work_unit_fact_current where unit_id = p_unit_id;
  v_new_rev := coalesce(v_cur.current_revision, 0) + 1;
  insert into public.work_unit_fact_revisions(
    unit_id, revision, predecessor_id, command_id, actor_id, observation_actor_id, event_kind,
    project_id, opening_id, origin_project_id, origin_opening_id, origin_kind, origin_author_id, origin_is_test,
    legacy_measurement_source, legacy_area_source, unit_incarnation_epoch,
    width_in, height_in, measurement_unit, measurement_source, source_reference,
    raw_observation, estimated, unit_binding_epoch, opening_context_epoch, project_context_epoch,
    applied_intent, before_snapshot, reason
  ) values (
    p_unit_id, v_new_rev, v_cur.current_revision_id,
    p_command_id, v_actor,
    nullif(p_applied_unit_intent->>'observation_actor_id','')::uuid,
    p_applied_unit_intent->>'event_kind',
    v_unit.project_id, v_unit.opening_id,
    nullif(p_applied_unit_intent->>'origin_project_id','')::uuid,
    nullif(p_applied_unit_intent->>'origin_opening_id','')::uuid,
    p_applied_unit_intent->>'origin_kind', (p_applied_unit_intent->>'origin_author_id')::uuid,
    (p_applied_unit_intent->>'origin_is_test')::boolean,
    p_applied_unit_intent->>'legacy_measurement_source', p_applied_unit_intent->>'legacy_area_source',
    public._work_unit_fact_peek_epoch('unit_incarnation', p_unit_id),
    nullif(p_applied_unit_intent->>'width_in','')::numeric, nullif(p_applied_unit_intent->>'height_in','')::numeric,
    p_applied_unit_intent->>'measurement_unit', p_applied_unit_intent->>'measurement_source',
    p_applied_unit_intent->>'source_reference',
    p_applied_unit_intent->'raw_observation',
    nullif(p_applied_unit_intent->>'estimated','')::boolean,
    public._work_unit_fact_peek_epoch('unit_binding', p_unit_id),
    case when v_unit.opening_id is not null then public._work_unit_fact_peek_epoch('opening', v_unit.opening_id) end,
    case when v_unit.project_id is not null then public._work_unit_fact_peek_epoch('project', v_unit.project_id) end,
    p_applied_unit_intent, p_before, p_applied_unit_intent->>'reason'
  ) returning id into v_new_id;
  insert into public.work_unit_fact_current(unit_id, current_revision_id, current_revision)
    values (p_unit_id, v_new_id, v_new_rev)
  on conflict (unit_id) do update
    set current_revision_id = excluded.current_revision_id, current_revision = excluded.current_revision, updated_at = now();
end;

 perform public._work_activity_operation_exit(__work_activity_root_id);
end;
$activity_body_211$::text,false,'6b121440ab32cfd5f465da1eff16f44a770dbfac0cec049f30d0a7df6d6ed5be'::text,'c4fe3b7c6b85a02b630ae98012acf0707656f60ebf94886c7308ea90eac8049e'::text,'_work_record_unit_fact'::text,'p_command_id uuid, p_applied_unit_intent jsonb, p_before jsonb, p_unit_id uuid'::text)
-- ENTRY_VALUES_END
 ) v(identity,body,convert_invoker,old_sha,new_sha,routine_name,arguments) loop
  select p.oid into function_oid from pg_proc p where p.pronamespace='public'::regnamespace and p.proname=item->>'name' and pg_get_function_identity_arguments(p.oid)=item->>'arguments';
  if function_oid is null then raise exception using errcode='23514',message='Installed activity entry identity is unavailable.';end if;
  select pg_get_functiondef(function_oid),proacl,proowner into definition,original_acl,original_owner from pg_proc where oid=function_oid;
  delimiter:=(regexp_match(definition,E'AS (\\$[^$]*\\$)'))[1];
  if delimiter is null or position(delimiter in item->>'body')>0 then raise exception 'Cannot preserve installed function delimiter.';end if;
  start_at:=position('AS '||delimiter in definition)+3+length(delimiter);
  definition:=left(definition,start_at-1)||(item->>'body')||delimiter||E';\n';
  if (item->>'convertInvokerPayroll')::boolean then
    definition:=replace(definition,'LANGUAGE plpgsql',E'LANGUAGE plpgsql\n SECURITY DEFINER');
  end if;
  execute definition;
  if (item->>'convertInvokerPayroll')::boolean then execute format('alter function %s set search_path=public,pg_temp',function_oid::regprocedure);end if;
  if (select proacl is distinct from original_acl or proowner is distinct from original_owner from pg_proc where oid=function_oid)
    or not exists(select 1 from pg_proc p where p.oid=function_oid and p.pronamespace='public'::regnamespace and p.proname=item->>'name' and pg_get_function_identity_arguments(p.oid)=item->>'arguments')
    or (select encode(sha256(convert_to(prosrc,'UTF8')),'hex') from pg_proc where oid=function_oid) is distinct from item->>'newBodySha256' then
    raise exception using errcode='23514',message='Activity entry replacement did not preserve its identity and ACL.';
  end if;
 end loop;
end;
