","table":"work_activity_definitions","function":"_work_activity_no_truncate","type":34},{"name":"z_work_activity_authority","table":"work_activity_definitions","function":"_work_activity_authority_changed","type":29},{"name":"000_work_activity_gate","table":"work_capture_menus","function":"_work_activity_parent_gate","type":30},{"name":"000_work_activity_no_truncate","table":"work_capture_menus","function":"_work_activity_no_truncate","type":34},{"name":"z_work_activity_authority","table":"work_capture_menus","function":"_work_activity_authority_changed","type":29},{"name":"000_work_activity_gate","table":"work_job_management_grants","function":"_work_activity_parent_gate","type":30},{"name":"000_work_activity_no_truncate","table":"work_job_management_grants","function":"_work_activity_no_truncate","type":34},{"name":"z_work_activity_authority","table":"work_job_management_grants","function":"_work_activity_authority_changed","type":29},{"name":"000_work_activity_gate","table":"work_job_menu_selections","function":"_work_activity_parent_gate","type":30},{"name":"000_work_activity_no_truncate","table":"work_job_menu_selections","function":"_work_activity_no_truncate","type":34},{"name":"z_work_activity_authority","table":"work_job_menu_selections","function":"_work_activity_authority_changed","type":29},{"name":"000_work_activity_gate","table":"work_setup_sessions","function":"_work_activity_statement_begin","type":30},{"name":"000_work_activity_no_truncate","table":"work_setup_sessions","function":"_work_activity_no_truncate","type":34},{"name":"000_work_activity_row","table":"work_setup_sessions","function":"_work_activity_row_before","type":31},{"name":"zz_work_activity_row","table":"work_setup_sessions","function":"_work_activity_row_event","type":29},{"name":"zzz_work_activity_statement","table":"work_setup_sessions","function":"_work_activity_statement_end","type":28},{"name":"zzz_work_activity_shift","table":"time_shifts","function":"_work_activity_shift_life