-- Held candidate: integration/provider/review gates remain.


do $review_metadata$ declare probe_result record; begin
 for probe_result in (-- Read-only metadata fragment. Run ONLY inside the coordinator's exact-source,
-- forced-ROLLBACK candidate assembly. No production clock/employee/QC writes.
with private_tables(name) as (values
 ('work_activity_source_history'),('work_unit_review_commands'),
 ('work_unit_dimension_verifications'),('work_unit_review_events'),
 ('work_unit_review_current'),('work_unit_review_defects'),('work_unit_review_defect_events')),
 relations as (select c.* from pg_class c join pg_namespace n on n.oid=c.relnamespace
 join private_tables p on p.name=c.relname where n.nspname='public'),
 checks as (
 select 'unit_review_source_contract' check_name,public._work_unit_review_coverage() passed
 union all select 'unit_review_private_rls',count(*)=7 and bool_and(relrowsecurity) from relations
 union all select 'unit_review_no_raw_client_service_privileges',not exists(
 select 1 from relations c cross join (values('anon'),('authenticated'),('service_role')) r(name)
 cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) p(name)
 where has_table_privilege(r.name,c.oid,p.name))
 union all select 'unit_review_no_cascade_source_fks',not exists(
 select 1 from pg_constraint k join relations r on r.oid=k.conrelid where k.contype='f' and (k.confdeltype not in ('a','r') or not exists(select 1 from relations target where target.oid=k.confrelid)))
 union all select 'unit_review_public_rpc_acl',bool_and(
 has_function_privilege('authenticated',p.oid,'EXECUTE') and not has_function_privilege('anon',p.oid,'EXECUTE')
 and not has_function_privilege('service_role',p.oid,'EXECUTE') and p.prosecdef)
 from pg_proc p where p.oid in ('public.work_unit_review_read(uuid)'::regprocedure,
 'public.work_unit_review_command(uuid,integer,jsonb)'::regprocedure,'public.work_unit_review_command_receipt(uuid)'::regprocedure)
 union all select 'unit_review_census_retention',position('work_unit_review_events.original_identities' in p.prosrc)>0
 and position('work_activity_source_history.original_identities' in p.prosrc)>0
 from pg_proc p where p.oid='public.person_record_counts(uuid)'::regprocedure
 union all select 'unit_review_capture_remains_off',not capture_enabled from public.work_activity_authority_generation where singleton
) select check_name,passed from checks order by check_name) loop
  perform pg_temp.dry_run_check('provider/'||probe_result.check_name,probe_result.passed,'Exact private review metadata');
 end loop; end; $review_metadata$;
-- Real authenticated caller, sandbox-bound read, and missing identities only.
-- No accepted review, defect, verification, employee or payroll write is made.
do $review_provider$
declare actor uuid; job uuid; unit_id uuid; missing_unit uuid:=gen_random_uuid();
 missing_command uuid:=gen_random_uuid(); missing_fact uuid:=gen_random_uuid();
 v jsonb; payload jsonb; before_commands bigint; before_events bigint;
begin
 perform pg_temp.dry_run_as_system();
 actor:=pg_temp.dry_run_pick_real('owner'); job:=pg_temp.dry_run_sandbox_job();
 select id into unit_id from public.custom_work_units where project_id=job order by id limit 1;
 if exists(select 1 from public.custom_work_units where id=missing_unit)
 or exists(select 1 from public.work_unit_review_commands where command_id=missing_command) then
 raise exception 'dry run: missing synthetic review identity unexpectedly exists';end if;
 select count(*) into before_commands from public.work_unit_review_commands;
 select count(*) into before_events from public.work_unit_review_events;
 perform pg_temp.dry_run_act_as(actor);
 perform pg_temp.dry_run_check('provider/reviewActualCaller',current_user='authenticated' and auth.uid()=actor,'Actual owner login context');
 v:=public.work_unit_review_read(coalesce(unit_id,missing_unit));
 perform pg_temp.dry_run_check('provider/reviewSandboxRead',(v->>'protocolVersion')::integer=1
 and ((v->>'availability'='unavailable' and v->'review'='null'::jsonb)
 or (v->>'availability'='available' and coalesce((v#>>'{review,qc,qcAccepted}')::boolean,false)=false)),
 'Existing legacy sandbox work cannot acquire accepted QC from a read');
 v:=public.work_unit_review_read(missing_unit);
 perform pg_temp.dry_run_check('provider/reviewMissingUnitHidden',v->>'availability'='unavailable' and v->'review'='null'::jsonb,'No identity, digest or counts for absent unit');
 v:=public.work_unit_review_command_receipt(missing_command);
 perform pg_temp.dry_run_check('provider/reviewMissingReceiptHidden',v=jsonb_build_object('protocolVersion',1,'availability','unavailable','receipt',null),'Missing receipt is not non-delivery proof');
 payload:=jsonb_build_object('action','submit','basis',jsonb_build_object(
 'unitId',missing_unit,'unitRevision',0,'factId',missing_fact,'factRevision',1,
 'scopeToken','ur1:'||repeat('0',64),'reviewRevision',0,'submissionId',null,'generation',0),'data',jsonb_build_object('note',null));
 perform pg_temp.dry_run_expect_error('provider/reviewMissingUnitCommandRefused',
 format('select public.work_unit_review_command(%L::uuid,1,%L::jsonb)',missing_command,payload::text),'Unit review is unavailable.');
 perform pg_temp.dry_run_as_system();
 perform pg_temp.dry_run_check('provider/reviewNoDecisionWritten',
 (select count(*) from public.work_unit_review_commands)=before_commands
 and (select count(*) from public.work_unit_review_events)=before_events,
 'Read-only checks and a refused missing-unit command preserve review records');
end; $review_provider$;

do $review_diagnostic$ declare probe_result record; begin
 if not public._work_unit_review_coverage() then
  for probe_result in (-- READ-ONLY catalog diagnostic for exact held 0844 source.
-- No application rows, operational identities or function bodies are returned.
